-- Record deletion successor (C81 foundation).
--
-- Adds the root-independent v2 deletion authorization surface beside the
-- frozen v1 ledger/witness contract. Version 1 rows keep every original
-- constraint verbatim; version 2 rows never carry ledger, witness, or retry
-- facts. V2 gate and preview writes are confined to the restricted issuer
-- functions; application roles receive no direct DML on those tables.

-- Replace the exact predecessor record-ID checks by inspecting their actual
-- catalog identities. Do not infer autogenerated names or remove a different
-- check merely because it references a record column.
do $$
declare
  target record;
  relation_oid oid;
  attribute_number smallint;
  predecessor_expression text;
  predecessor_names text[];
begin
  for target in
    select * from (values
      ('records', 'record_id', false),
      ('evidence_capture_intents', 'record_id', false),
      ('record_search_documents', 'record_id', false),
      ('record_search_rebuild_jobs', 'resume_after_record_id', true),
      ('record_activity_projection', 'record_id', true),
      ('record_activity_subjects', 'record_id', true),
      ('record_activity_revision_intervals', 'record_id', false),
      ('record_export_jobs', 'record_id', true),
      ('record_origins', 'source_record_id', true)
    ) as expected(table_name, column_name, nullable)
  loop
    select c.oid, a.attnum into strict relation_oid, attribute_number
    from pg_catalog.pg_class c
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    join pg_catalog.pg_attribute a on a.attrelid = c.oid
    where n.nspname = 'public' and c.relname = target.table_name
      and c.relkind = 'r' and a.attname = target.column_name
      and a.atttypid = 'pg_catalog.text'::pg_catalog.regtype
      and a.attnum > 0 and not a.attisdropped
      and a.attnotnull = (not target.nullable);

    predecessor_expression := pg_catalog.format('(%I ~ %L::text)',
      target.column_name, '^rec_[a-z0-9]{1,64}$');
    if target.nullable then
      predecessor_expression := pg_catalog.format('((%I IS NULL) OR %s)',
        target.column_name, predecessor_expression);
    end if;

    select pg_catalog.array_agg(c.conname order by c.conname) into predecessor_names
    from pg_catalog.pg_constraint c
    where c.conrelid = relation_oid and c.contype = 'c'
      and c.conkey = array[attribute_number]::smallint[]
      and c.convalidated and c.conislocal and not c.connoinherit
      and pg_catalog.pg_get_expr(c.conbin, c.conrelid) = predecessor_expression;
    if coalesce(pg_catalog.cardinality(predecessor_names), 0) <> 1
      or (select pg_catalog.count(*) from pg_catalog.pg_constraint c
          where c.conrelid = relation_oid and c.contype = 'c'
            and attribute_number = any(c.conkey)
            and pg_catalog.strpos(pg_catalog.pg_get_expr(c.conbin, c.conrelid),
              '^rec_[a-z0-9]{1,64}$') > 0) <> 1 then
      raise exception 'unexpected predecessor record identity check on public.%.%',
        target.table_name, target.column_name;
    end if;

    execute pg_catalog.format('alter table public.%I drop constraint %I',
      target.table_name, predecessor_names[1]);
    execute pg_catalog.format(
      'alter table public.%I add constraint %I check (%I ~ %L)',
      target.table_name, 'record_identity_m1_check', target.column_name,
      '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$');
  end loop;
end
$$;

-- v2 reservations: same preview binding facts as v1 minus the witness tuple.
alter table public.deletion_reservations
  add column deletion_contract_version bigint not null default 1
    check (deletion_contract_version in (1, 2));

alter table public.deletion_reservations
  drop constraint deletion_reservations_preview_or_recovery_check;

alter table public.deletion_reservations
  add constraint deletion_reservations_preview_or_recovery_check
    check (
      (deletion_contract_version = 1
        and ((not recovery_replayed
            and actor_scope_digest is not null
            and preview_binding_digest is not null
            and preview_current_revision_id is not null
            and preview_lock_version is not null
            and preview_authorization_epoch is not null
            and preview_content_delivery_epoch is not null
            and preview_dependency_graph_digest is not null
            and preview_backup_inventory_digest is not null
            and preview_processor_inventory_digest is not null
            and adapter_readiness_digest is not null
            and adapter_preview_digest is not null
            and preview_witness_sequence is not null
            and preview_witness_entry_hash is not null)
          or (recovery_replayed
            and state in ('committed', 'not_committed')
            and actor_scope_digest is null
            and preview_binding_digest is null
            and preview_current_revision_id is null
            and preview_lock_version is null
            and preview_authorization_epoch is null
            and preview_content_delivery_epoch is null
            and preview_dependency_graph_digest is null
            and preview_backup_inventory_digest is null
            and preview_processor_inventory_digest is null
            and adapter_readiness_digest is null
            and adapter_preview_digest is null
            and preview_witness_sequence is null
            and preview_witness_entry_hash is null
            and owner_id = ''
            and owner_generation = 0
            and owner_expires_at is null
            and completed_at is not null)))
      or (deletion_contract_version = 2
        and not recovery_replayed
        and actor_scope_digest is not null
        and preview_binding_digest is not null
        and preview_current_revision_id is not null
        and preview_lock_version is not null
        and preview_authorization_epoch is not null
        and preview_content_delivery_epoch is not null
        and adapter_readiness_digest is not null
        and adapter_preview_digest is not null
        and preview_witness_sequence is null
        and preview_witness_entry_hash is null)
    );

-- v2 operations: online_purging/online_purged only, no ledger/witness/retry.
alter table public.record_purge_operations
  drop constraint record_purge_operations_deletion_contract_version_check;

alter table public.record_purge_operations
  add constraint record_purge_operations_deletion_contract_version_check
    check (deletion_contract_version in (1, 2));

alter table public.record_purge_operations
  drop constraint record_purge_operations_ledger_state_check;

alter table public.record_purge_operations
  add constraint record_purge_operations_ledger_state_check
    check (
      (deletion_contract_version = 1
        and ((operation_state in ('provisional_fenced', 'ledger_commit_unknown')
            and ledger_entry_type is null and witness_proof_digest is null)
          or (operation_state = 'witness_pending'
            and ledger_entry_type = 'delete_commit' and witness_proof_digest is null)
          or (operation_state in ('delete_requested', 'fence_propagating',
                'read_fenced', 'online_purging', 'online_purged', 'retry_required')
            and ledger_entry_type = 'delete_commit' and witness_proof_digest is not null)
          or (operation_state = 'release_pending'
            and ((ledger_entry_type is null and witness_proof_digest is null)
              or ledger_entry_type = 'attempt_not_committed'))
          or (operation_state = 'not_committed'
            and ledger_entry_type = 'attempt_not_committed'
            and witness_proof_digest is not null)))
      or (deletion_contract_version = 2
        and operation_state in ('online_purging', 'online_purged')
        and ledger_sequence is null
        and ledger_entry_hash is null
        and ledger_entry_type is null
        and witness_proof_digest is null
        and retry_from is null
        and release_epoch = 0)
    );

create or replace function record_platform_internal.enforce_record_purge_operation_contract_version()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog
as $$
declare
  v_reservation_version bigint;
begin
  if tg_op = 'UPDATE' and new.deletion_contract_version is distinct from old.deletion_contract_version then
    raise exception using
      errcode = '55000',
      message = 'record purge operation contract version is immutable';
  end if;
  select reservation.deletion_contract_version
    into v_reservation_version
  from public.deletion_reservations as reservation
  where reservation.reservation_id = new.reservation_id;
  if v_reservation_version is distinct from new.deletion_contract_version then
    raise exception using
      errcode = '55000',
      message = 'record purge operation contract version does not match its reservation';
  end if;
  return new;
end
$$;

revoke all on function record_platform_internal.enforce_record_purge_operation_contract_version() from public;

create trigger record_purge_operations_contract_version_guard
  before insert or update of deletion_contract_version, reservation_id
  on public.record_purge_operations
  for each row execute function record_platform_internal.enforce_record_purge_operation_contract_version();

-- Trash lifecycle. trashed_at is written only on first entry and cleared on
-- restore by the lifecycle writer; it never creates a content revision.
alter table public.records
  drop constraint records_lifecycle_check;

alter table public.records
  add constraint records_lifecycle_check
    check (lifecycle in ('active', 'archived', 'trashed'));

alter table public.records
  add column trashed_at timestamptz;

alter table public.records
  add constraint records_trashed_at_check
    check ((lifecycle = 'trashed') = (trashed_at is not null));

alter table public.record_search_documents
  drop constraint record_search_documents_lifecycle_check;

alter table public.record_search_documents
  add constraint record_search_documents_lifecycle_check
    check (lifecycle in ('active', 'archived', 'trashed'));

-- Immutable, root-independent deletion gate. No root FK: the gate and its
-- canonical authorization evidence outlive the record root.
create table public.record_deletion_gates (
  operation_id text primary key check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  project_id text not null default 'default' check (project_id = 'default'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  expected_lifecycle text not null check (expected_lifecycle in ('active', 'trashed')),
  expected_revision_id text not null check (expected_revision_id ~ '^rrv_[a-z0-9]{1,64}$'),
  expected_lock_version bigint not null check (expected_lock_version > 0),
  expected_authorization_epoch bigint not null check (expected_authorization_epoch > 0),
  fence_epoch bigint not null check (fence_epoch > 0),
  actor_id text not null check (actor_id ~ '^usr_[a-z0-9]{1,64}$'),
  actor_scope_digest bytea not null check (octet_length(actor_scope_digest) = 32),
  request_fingerprint bytea not null check (octet_length(request_fingerprint) = 32),
  binding_digest bytea not null check (octet_length(binding_digest) = 32),
  authorization_evidence bytea not null
    check (octet_length(authorization_evidence) between 1 and 65536),
  issued_at timestamptz not null default transaction_timestamp(),
  unique (project_id, record_id),
  foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict
);

-- Executed preview bindings. No root FK; operation_id binds once on execute.
create table public.record_deletion_previews (
  deletion_token_commitment bytea primary key
    check (octet_length(deletion_token_commitment) = 32),
  reservation_id text not null unique check (reservation_id ~ '^drs_[a-z0-9]{1,64}$'),
  project_id text not null default 'default' check (project_id = 'default'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  expected_lifecycle text not null check (expected_lifecycle in ('active', 'trashed')),
  expected_revision_id text not null check (expected_revision_id ~ '^rrv_[a-z0-9]{1,64}$'),
  expected_lock_version bigint not null check (expected_lock_version > 0),
  expected_authorization_epoch bigint not null check (expected_authorization_epoch > 0),
  content_delivery_epoch bigint not null check (content_delivery_epoch >= 0),
  dependency_graph_digest bytea not null check (octet_length(dependency_graph_digest) = 32),
  processor_inventory_digest bytea not null check (octet_length(processor_inventory_digest) = 32),
  obligation_inventory_digest bytea not null check (octet_length(obligation_inventory_digest) = 32),
  adapter_readiness_digest bytea not null check (octet_length(adapter_readiness_digest) = 32),
  adapter_preview_digest bytea not null check (octet_length(adapter_preview_digest) = 32),
  backup_inventory_digest bytea check (octet_length(backup_inventory_digest) = 32),
  actor_id text not null check (actor_id ~ '^usr_[a-z0-9]{1,64}$'),
  actor_scope_digest bytea not null check (octet_length(actor_scope_digest) = 32),
  request_fingerprint bytea not null check (octet_length(request_fingerprint) = 32),
  binding_digest bytea not null check (octet_length(binding_digest) = 32),
  authorization_evidence bytea not null
    check (octet_length(authorization_evidence) between 1 and 65536),
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  operation_id text unique check (operation_id is null or operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  check (expires_at > created_at),
  foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict
);

create index idx_record_deletion_previews_record
  on public.record_deletion_previews(project_id, record_id, expires_at);

create or replace function record_platform_internal.enforce_record_deletion_gate()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog
as $$
declare
  v_contract_version bigint;
begin
  if tg_op <> 'INSERT' then
    raise exception using
      errcode = '55000',
      message = 'record deletion gate is immutable';
  end if;
  select operation.deletion_contract_version
    into v_contract_version
  from public.record_purge_operations as operation
  where operation.operation_id = new.operation_id;
  if v_contract_version is distinct from 2 then
    raise exception using
      errcode = '55000',
      message = 'record deletion gate requires a version 2 purge operation';
  end if;
  return new;
end
$$;

revoke all on function record_platform_internal.enforce_record_deletion_gate() from public;

create trigger record_deletion_gates_guard
  before insert or update or delete on public.record_deletion_gates
  for each row execute function record_platform_internal.enforce_record_deletion_gate();

create or replace function record_platform_internal.enforce_record_deletion_preview()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog
as $$
begin
  if tg_op <> 'UPDATE' then
    raise exception using errcode = '55000', message = 'record deletion preview is immutable';
  end if;
  if old.operation_id is not null
    or new.operation_id is null
    or (to_jsonb(new) - 'operation_id') is distinct from (to_jsonb(old) - 'operation_id') then
    raise exception using
      errcode = '55000',
      message = 'record deletion preview binding is immutable except its single operation binding';
  end if;
  return new;
end
$$;

revoke all on function record_platform_internal.enforce_record_deletion_preview() from public;

create trigger record_deletion_previews_guard
  before update or delete on public.record_deletion_previews
  for each row execute function record_platform_internal.enforce_record_deletion_preview();

-- v2 operations may carry an origin tombstone instead of a ledger sequence.
alter table public.record_origin_tombstones
  alter column ledger_sequence drop not null;

alter table public.record_origin_tombstones
  add column operation_id text
    check (operation_id is null or operation_id ~ '^rpo_[a-z0-9]{1,64}$');

alter table public.record_origin_tombstones
  add constraint record_origin_tombstones_operation_fk
    foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict;

alter table public.record_origin_tombstones
  add constraint record_origin_tombstones_source_check
    check ((ledger_sequence is null) <> (operation_id is null));

-- Two additional adapter receipts, shaped like the existing adapter receipts.
create table public.record_markdown_client_purge_receipts (
  operation_id text primary key check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  adapter_name text not null default 'record_markdown_client'
    check (adapter_name = 'record_markdown_client'),
  removed_surface_digest bytea not null
    check (octet_length(removed_surface_digest) = 32),
  receipt_digest bytea not null check (octet_length(receipt_digest) = 32),
  removed_row_count bigint not null check (removed_row_count >= 0),
  verified_absent_at timestamptz not null,
  created_at timestamptz not null default now(),
  foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict
);

create table public.record_comparison_purge_receipts (
  operation_id text primary key check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  adapter_name text not null default 'record_comparison'
    check (adapter_name = 'record_comparison'),
  removed_surface_digest bytea not null
    check (octet_length(removed_surface_digest) = 32),
  receipt_digest bytea not null check (octet_length(receipt_digest) = 32),
  removed_row_count bigint not null check (removed_row_count >= 0),
  verified_absent_at timestamptz not null,
  created_at timestamptz not null default now(),
  foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict
);

-- Comparison provenance index. Only the destination result is a foreign key;
-- sources are immutable provenance strings that survive source purge.
create table public.comparison_result_dependencies (
  result_snapshot_id text not null check (result_snapshot_id ~ '^evs_[a-z0-9]{1,64}$'),
  source_record_id text not null check (source_record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  source_revision_id text
    check (source_revision_id is null or source_revision_id ~ '^rrv_[a-z0-9]{1,64}$'),
  source_snapshot_id text
    check (source_snapshot_id is null or source_snapshot_id ~ '^evs_[a-z0-9]{1,64}$'),
  project_id text not null default 'default' check (project_id = 'default'),
  created_at timestamptz not null default now(),
  constraint comparison_result_dependencies_identity_key
    unique nulls not distinct
      (result_snapshot_id, source_record_id, source_revision_id, source_snapshot_id),
  constraint comparison_result_dependencies_result_fk
    foreign key (result_snapshot_id) references public.evidence_snapshots(snapshot_id)
    deferrable initially deferred
);

create index idx_comparison_result_dependencies_source
  on public.comparison_result_dependencies(source_record_id, result_snapshot_id);

-- Per-result index completion facts; readiness inspects the actual result
-- set against these rows, never a single global completion flag.
create table public.comparison_result_dependency_index_completions (
  result_snapshot_id text primary key check (result_snapshot_id ~ '^evs_[a-z0-9]{1,64}$'),
  payload_digest bytea not null check (octet_length(payload_digest) = 32),
  project_id text not null default 'default' check (project_id = 'default'),
  indexed_at timestamptz not null default now(),
  constraint comparison_result_dependency_index_completions_result_fk
    foreign key (result_snapshot_id) references public.evidence_snapshots(snapshot_id)
    deferrable initially deferred
);

create or replace function public.record_text_set_is_canonical(text[])
returns boolean
language sql
immutable
strict
security invoker
set search_path = pg_catalog
as $$
  select pg_catalog.array_ndims($1) = 1
    and pg_catalog.array_lower($1, 1) = 1
    and pg_catalog.cardinality($1) between 1 and 64
    and $1 = array(
      select distinct item collate "C"
      from pg_catalog.unnest($1) as items(item)
      order by item collate "C"
    )
    and not exists (
      select 1 from pg_catalog.unnest($1) as items(item)
      where item is null or item !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    )
$$;

revoke all on function public.record_text_set_is_canonical(text[]) from public;

-- Controlled client metadata. The server stores reported ownership only,
-- never browser content, and these rows are not proof of all browser copies.
create table public.browser_record_cleanup_targets (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  project_id text not null default 'default' check (project_id = 'default'),
  registered_at timestamptz not null default now(),
  primary key (user_id, browser_id, record_id)
);

create index idx_browser_record_cleanup_targets_record
  on public.browser_record_cleanup_targets(project_id, record_id, user_id, browser_id);

create table public.browser_record_cleanup_events (
  cursor bigint generated always as identity primary key,
  operation_id text not null check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  project_id text not null default 'default' check (project_id = 'default'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  cleanup_epoch bigint not null check (cleanup_epoch > 0),
  scopes text[] not null
    check (pg_catalog.cardinality(scopes) between 1 and 4
      and scopes <@ array['markdown_draft_buffer', 'markdown_workspace',
        'comparison_workbench', 'comparison_save_attempt']::text[]),
  created_at timestamptz not null default now(),
  constraint browser_record_cleanup_events_operation_record_key
    unique (operation_id, record_id),
  constraint browser_record_cleanup_events_identity_key
    unique (cursor, operation_id, record_id, cleanup_epoch),
  foreign key (operation_id) references public.record_purge_operations(operation_id)
    on delete restrict
);

create index idx_browser_record_cleanup_events_record
  on public.browser_record_cleanup_events(project_id, record_id, cursor);

create table public.browser_record_cleanup_receipts (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  event_cursor bigint not null check (event_cursor > 0),
  operation_id text not null check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  cleanup_epoch bigint not null check (cleanup_epoch > 0),
  acked_at timestamptz not null default now(),
  primary key (user_id, browser_id, event_cursor),
  constraint browser_record_cleanup_receipts_event_fk
    foreign key (event_cursor, operation_id, record_id, cleanup_epoch)
    references public.browser_record_cleanup_events(cursor, operation_id, record_id, cleanup_epoch)
    on delete restrict,
  constraint browser_record_cleanup_receipts_target_fk
    foreign key (user_id, browser_id, record_id)
    references public.browser_record_cleanup_targets(user_id, browser_id, record_id)
    on delete restrict
);

create or replace function record_platform_internal.enforce_browser_record_cleanup_immutable()
returns trigger
language plpgsql
security invoker
set search_path = pg_catalog
as $$
begin
  raise exception using
    errcode = '55000',
    message = 'browser record cleanup events and receipts are immutable';
end
$$;

revoke all on function record_platform_internal.enforce_browser_record_cleanup_immutable() from public;

create trigger browser_record_cleanup_events_guard
  before update or delete on public.browser_record_cleanup_events
  for each row execute function record_platform_internal.enforce_browser_record_cleanup_immutable();

create trigger browser_record_cleanup_receipts_guard
  before update or delete on public.browser_record_cleanup_receipts
  for each row execute function record_platform_internal.enforce_browser_record_cleanup_immutable();

-- The gate, not a best-effort post-commit notification, owns the cleanup event.
-- Targets and acknowledgements deliberately survive removal of the record root.
create function record_platform_internal.record_deletion_gate_cleanup_event()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
begin
  insert into public.browser_record_cleanup_events (
    operation_id, project_id, record_id, cleanup_epoch, scopes
  ) values (
    new.operation_id, new.project_id, new.record_id, new.fence_epoch,
    array['markdown_draft_buffer', 'markdown_workspace',
      'comparison_workbench', 'comparison_save_attempt']::text[]
  );
  return new;
end
$$;

revoke all on function record_platform_internal.record_deletion_gate_cleanup_event() from public;

create trigger record_deletion_gates_cleanup_event
  after insert on public.record_deletion_gates
  for each row execute function record_platform_internal.record_deletion_gate_cleanup_event();

create table public.markdown_client_draft_buffers (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  project_id text not null default 'default' check (project_id = 'default'),
  session_generation bigint not null check (session_generation > 0),
  cleanup_generation bigint not null check (cleanup_generation >= 0),
  registered_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, browser_id, record_id),
  check (updated_at >= registered_at)
);

create index idx_markdown_client_draft_buffers_record
  on public.markdown_client_draft_buffers(project_id, record_id);

create table public.markdown_client_workspaces (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  project_id text not null default 'default' check (project_id = 'default'),
  session_generation bigint not null check (session_generation > 0),
  cleanup_generation bigint not null check (cleanup_generation >= 0),
  registered_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, browser_id, record_id),
  check (updated_at >= registered_at)
);

create index idx_markdown_client_workspaces_record
  on public.markdown_client_workspaces(project_id, record_id);

create table public.comparison_client_workbenches (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  workbench_digest bytea not null check (octet_length(workbench_digest) = 32),
  project_id text not null default 'default' check (project_id = 'default'),
  destination_record_id text
    check (destination_record_id is null or destination_record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  source_record_ids text[] not null
    check (public.record_text_set_is_canonical(source_record_ids)),
  generation bigint not null check (generation > 0),
  registered_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, browser_id, workbench_digest),
  check (updated_at >= registered_at)
);

create index idx_comparison_client_workbenches_sources
  on public.comparison_client_workbenches using gin (source_record_ids);

create table public.comparison_client_save_attempts (
  user_id text not null check (user_id ~ '^usr_[a-z0-9]{1,64}$'),
  browser_id text not null check (browser_id ~ '^[a-z0-9_-]{1,128}$'),
  save_digest bytea not null check (octet_length(save_digest) = 32),
  project_id text not null default 'default' check (project_id = 'default'),
  destination_record_id text
    check (destination_record_id is null or destination_record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  source_record_ids text[] not null
    check (public.record_text_set_is_canonical(source_record_ids)),
  idempotency_key text not null check (idempotency_key ~ '^[A-Za-z0-9._~-]{1,200}$'),
  generation bigint not null check (generation > 0),
  registered_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, browser_id, save_digest),
  unique (user_id, browser_id, idempotency_key),
  check (updated_at >= registered_at)
);

create index idx_comparison_client_save_attempts_sources
  on public.comparison_client_save_attempts using gin (source_record_ids);

-- Source retirement is irreversible inside APP, while W2 outside this recovery
-- unit preserves prepares and final terminals across APP rollback.
create table public.source_authority_admission (
  singleton boolean primary key default true check (singleton),
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  witness_domain_id text not null check (witness_domain_id ~ '^rd-[0-9a-f]{64}$'),
  witness_system_identifier text not null check (witness_system_identifier ~ '^[1-9][0-9]{0,19}$'),
  witness_database_oid oid not null,
  witness_database_name text not null check (witness_database_name ~ '^[a-z][a-z0-9_]{0,62}$'),
  witness_identity_epoch bigint not null check (witness_identity_epoch > 0),
  generation bigint not null check (generation > 0),
  mode text not null check (mode in ('closed', 'ready_closed', 'active')),
  recovery_id text,
  coverage_seal bytea check (octet_length(coverage_seal) = 32),
  credential_manifest_digest bytea check (octet_length(credential_manifest_digest) = 32),
  namespace_handoff_digest bytea check (octet_length(namespace_handoff_digest) = 32),
  check (mode <> 'ready_closed' or (recovery_id is not null and coverage_seal is not null))
);
create table public.source_application_principals (
  principal name not null,
  generation bigint not null check (generation > 0),
  purpose text not null check (purpose in ('runtime', 'admin', 'worker', 'migrator', 'authority')),
  credential_commitment bytea check (octet_length(credential_commitment) = 32),
  primary key (generation, purpose),
  unique (generation, principal)
);
create table public.source_retirement_barriers (
  project_id text not null check (project_id = 'default'),
  source_kind text not null check (source_kind in ('vps', 'monitoring_instance', 'target')),
  source_id text not null,
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  retirement_id text not null unique check (retirement_id ~ '^[a-z0-9_-]{1,128}$'),
  origin_generation bigint not null check (origin_generation > 0),
  request_fingerprint bytea not null check (octet_length(request_fingerprint) = 32),
  actor_id text not null check (actor_id ~ '^usr_[a-z0-9]{1,64}$'),
  expected_source_revision bytea not null,
  last_live bytea not null check (octet_length(last_live) between 1 and 4096),
  final_floor bytea not null check (octet_length(final_floor) between 1 and 4096),
  barrier_digest bytea not null unique check (octet_length(barrier_digest) = 32),
  committed_at timestamptz not null default now(),
  primary key (project_id, source_kind, source_id),
  check ((source_kind = 'vps' and source_id ~ '^vps_[0-9a-f]{16}$')
    or (source_kind = 'monitoring_instance' and source_id ~ '^mi_[0-9a-f]{16}$')
    or (source_kind = 'target' and source_id ~ '^tg_[0-9a-f]{16}$'))
);
create table public.source_retirement_outbox (
  retirement_id text primary key references public.source_retirement_barriers(retirement_id) on delete restrict,
  barrier_digest bytea not null check (octet_length(barrier_digest) = 32)
);
create table public.source_retirement_pins (
  project_id text not null check (project_id = 'default'),
  source_kind text not null check (source_kind in ('vps', 'monitoring_instance', 'target')),
  source_id text not null,
  installed_generation bigint not null check (installed_generation > 0),
  retirement_id text not null,
  origin_generation bigint not null check (origin_generation > 0),
  barrier_digest bytea not null check (octet_length(barrier_digest) = 32),
  canonical_terminal bytea not null check (octet_length(canonical_terminal) between 1 and 65536),
  terminal_hash bytea not null check (octet_length(terminal_hash) = 32),
  terminal_sequence bigint not null check (terminal_sequence > 0),
  primary key (project_id, source_kind, source_id, installed_generation),
  unique (retirement_id, installed_generation)
);
create function record_platform_internal.source_prepare_set_is_canonical(text[])
returns boolean language sql immutable strict set search_path = pg_catalog
as $$
  select array_ndims($1) = 1 and array_lower($1, 1) = 1 and cardinality($1) > 0
    and $1 = array(select distinct item collate "C" from unnest($1) as items(item)
      order by item collate "C")
    and not exists (select 1 from unnest($1) as items(item)
      where item is null or item !~ '^[a-z0-9_-]{1,128}$')
$$;
revoke all on function record_platform_internal.source_prepare_set_is_canonical(text[]) from public;

create table public.source_retirement_coverage_unknown (
  project_id text not null check (project_id = 'default'),
  source_kind text not null check (source_kind in ('vps', 'monitoring_instance', 'target')),
  source_id text not null,
  recovery_id text not null check (recovery_id ~ '^[a-z0-9_-]{1,128}$'),
  installed_generation bigint not null check (installed_generation > 0),
  prepare_ids text[] not null check (cardinality(prepare_ids) > 0
    and record_platform_internal.source_prepare_set_is_canonical(prepare_ids)),
  primary key (project_id, source_kind, source_id)
);
create function record_platform_internal.reject_source_retirement_mutation()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
begin
  raise exception using errcode = '55000', message = 'source retirement evidence is immutable';
  return null;
end
$$;
create trigger source_application_principals_immutable
before update or delete or truncate on public.source_application_principals
for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger source_retirement_barriers_immutable
before update or delete or truncate on public.source_retirement_barriers
for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger source_retirement_outbox_immutable
before update or delete or truncate on public.source_retirement_outbox
for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger source_retirement_pins_immutable
before update or delete or truncate on public.source_retirement_pins
for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger source_retirement_coverage_unknown_immutable
before update or delete or truncate on public.source_retirement_coverage_unknown
for each statement execute function record_platform_internal.reject_source_retirement_mutation();

-- This lock must precede graph and all business locks. Recovery takes UPDATE
-- on the same singleton before draining/closing LOGINs. No external I/O here.
create function public.source_application_admit()
returns bigint language plpgsql security definer set search_path = pg_catalog
as $$
declare s public.source_authority_admission;
begin
  if current_setting('transaction_read_only') = 'on' then
    -- Read-only observations confer no mutation capability. Their callers must
    -- end this snapshot before external verification and recheck before writes.
    select * into s from public.source_authority_admission where singleton;
  else
    select * into s from public.source_authority_admission where singleton for share;
  end if;
  perform record_platform_internal.record_birth_launch_admit(s);
  if s.singleton is null then
    return 0;
  end if;
  if s.mode <> 'active' or not exists (select 1 from public.source_application_principals p
    where p.principal = session_user and p.generation = s.generation
      and p.purpose in ('runtime', 'admin', 'worker')) then
    raise exception using errcode = '42501', message = 'source application admission is closed or stale';
  end if;
  return s.generation;
end
$$;

revoke all on table public.source_authority_admission, public.source_application_principals,
  public.source_retirement_barriers, public.source_retirement_outbox,
  public.source_retirement_pins, public.source_retirement_coverage_unknown from public;
revoke all on function record_platform_internal.reject_source_retirement_mutation(),
  public.source_application_admit() from public;

create function record_platform_internal.source_retirement_field(bytea)
returns bytea language sql immutable strict parallel safe set search_path = pg_catalog
as $$ select int4send(octet_length($1)) || $1 $$;

-- Called only after admission and graph acquisition. A source CAS binds the
-- management revision, not transient observation counters.
create function record_platform_internal.source_retirement_revision(text, text)
returns bytea language plpgsql security definer set search_path = pg_catalog
as $$
declare p_kind alias for $1; p_id alias for $2; body bytea;
begin
  if p_kind = 'vps' then
    select convert_to(jsonb_build_array(vps_id, extract(epoch from updated_at), lifecycle_status)::text, 'UTF8')
      into strict body from public.vps_assets where vps_id = p_id for update;
  elsif p_kind = 'monitoring_instance' then
    select convert_to(jsonb_build_array(monitoring_instance_id, extract(epoch from metadata_updated_at), control_revision, lifecycle_status)::text, 'UTF8')
      into strict body from public.monitoring_instances where monitoring_instance_id = p_id for update;
  elsif p_kind = 'target' then
    select convert_to(jsonb_build_array(target_id, extract(epoch from updated_at), control_revision, run_status)::text, 'UTF8')
      into strict body from public.targets where target_id = p_id for update;
  else
    raise exception using errcode = '22023', message = 'invalid source kind';
  end if;
  return record_platform_internal.digest(convert_to('HOUFENG-SOURCE-REVISION-V2', 'UTF8')
    || record_platform_internal.source_retirement_field(convert_to(p_kind, 'UTF8')) || body, 'sha256');
end
$$;

create function public.source_retirement_preview(text, text, text)
returns table (generation bigint, deployment_id text, source_revision bytea, group_ids text[])
language plpgsql security definer set search_path = pg_catalog
as $$
declare p_actor alias for $1; p_kind alias for $2; p_id alias for $3;
  s public.source_authority_admission; role_value text; revision bytea;
begin
  perform public.source_application_admit();
  select * into strict s from public.source_authority_admission where singleton;
  if not exists (select 1 from public.source_application_principals p where p.principal = session_user
    and p.generation = s.generation and p.purpose = 'admin') then
    raise exception using errcode = '42501', message = 'source retirement requires current admin principal';
  end if;
  perform pg_advisory_xact_lock(1213154899, 1);
  lock table public.users, public.record_access_groups, public.record_access_group_members in share mode;
  select role into strict role_value from public.users where user_id = p_actor and disabled_at is null;
  if role_value <> 'admin' then
    raise exception using errcode = '42501', message = 'source retirement actor is not a current project administrator';
  end if;
  if exists (select 1 from public.source_retirement_barriers b where
    (b.project_id, b.source_kind, b.source_id) = ('default', p_kind, p_id))
    or exists (select 1 from public.source_retirement_coverage_unknown u where
    (u.project_id, u.source_kind, u.source_id) = ('default', p_kind, p_id)) then
    raise exception using errcode = '55000', message = 'source is retiring or coverage unknown';
  end if;
  revision := record_platform_internal.source_retirement_revision(p_kind, p_id);
  return query select s.generation, s.deployment_id, revision,
    array(select m.group_id from public.record_access_group_members m
      join public.record_access_groups g on g.group_id = m.group_id
      where m.user_id = p_actor and g.project_id = 'default' order by m.group_id collate "C");
end
$$;

create function public.source_retirement_commit(bigint, text, text, text, text, text,
  bytea, bytea, bytea, bytea)
returns public.source_retirement_barriers
language plpgsql security definer set search_path = pg_catalog
as $$
declare p_generation alias for $1; p_deployment alias for $2; p_retirement alias for $3;
  p_kind alias for $4; p_source alias for $5; p_actor alias for $6; p_revision alias for $7;
  p_fingerprint alias for $8; p_last_live alias for $9; p_floor alias for $10;
  s public.source_authority_admission; b public.source_retirement_barriers;
  current_revision bytea; role_value text; canonical bytea;
begin
  perform public.source_application_admit();
  select * into strict s from public.source_authority_admission where singleton;
  if s.generation <> p_generation or s.deployment_id <> p_deployment or not exists (
    select 1 from public.source_application_principals p where p.principal = session_user
      and p.generation = s.generation and p.purpose = 'admin') then
    raise exception using errcode = '42501', message = 'source retirement generation or principal changed';
  end if;
  perform pg_advisory_xact_lock(1213154899, 1);
  lock table public.users, public.record_access_groups, public.record_access_group_members in share mode;
  select role into strict role_value from public.users where user_id = p_actor and disabled_at is null;
  if role_value <> 'admin' then
    raise exception using errcode = '42501', message = 'source retirement actor authorization changed';
  end if;
  select * into b from public.source_retirement_barriers where retirement_id = p_retirement;
  if found then
    if (b.deployment_id, b.source_kind, b.source_id, b.actor_id, b.expected_source_revision,
        b.request_fingerprint, b.last_live, b.final_floor, b.origin_generation)
      is distinct from (p_deployment, p_kind, p_source, p_actor, p_revision,
        p_fingerprint, p_last_live, p_floor, p_generation) then
      raise exception using errcode = '23505', message = 'source retirement barrier replay mismatch';
    end if;
    return b;
  end if;
  if exists (select 1 from public.source_retirement_coverage_unknown u where
    (u.project_id, u.source_kind, u.source_id) = ('default', p_kind, p_source)) then
    raise exception using errcode = '55000', message = 'source retirement coverage unknown';
  end if;
  current_revision := record_platform_internal.source_retirement_revision(p_kind, p_source);
  if current_revision is distinct from p_revision then
    raise exception using errcode = '40001', message = 'source retirement original CAS is stale';
  end if;
  canonical := convert_to('HOUFENG-SOURCE-BARRIER-V2', 'UTF8') || int8send(p_generation)
    || record_platform_internal.source_retirement_field(convert_to(p_deployment, 'UTF8'))
    || record_platform_internal.source_retirement_field(convert_to('default', 'UTF8'))
    || record_platform_internal.source_retirement_field(convert_to(p_retirement, 'UTF8'))
    || record_platform_internal.source_retirement_field(convert_to(p_kind, 'UTF8'))
    || record_platform_internal.source_retirement_field(convert_to(p_source, 'UTF8'))
    || record_platform_internal.source_retirement_field(convert_to(p_actor, 'UTF8'))
    || record_platform_internal.source_retirement_field(p_revision)
    || record_platform_internal.source_retirement_field(p_fingerprint)
    || record_platform_internal.source_retirement_field(p_last_live)
    || record_platform_internal.source_retirement_field(p_floor);
  insert into public.source_retirement_barriers(project_id, source_kind, source_id,
    deployment_id, retirement_id, origin_generation, request_fingerprint, actor_id,
    expected_source_revision, last_live, final_floor, barrier_digest)
  values ('default', p_kind, p_source, p_deployment, p_retirement, p_generation, p_fingerprint,
    p_actor, p_revision, p_last_live, p_floor, record_platform_internal.digest(canonical, 'sha256'))
  returning * into b;
  insert into public.source_retirement_outbox(retirement_id, barrier_digest)
    values (p_retirement, b.barrier_digest);
  return b;
end
$$;

create function public.source_retirement_install_pin(bigint, text, bigint, bytea, bytea, bytea, bigint)
returns void language plpgsql security definer set search_path = pg_catalog
as $$
declare p_generation alias for $1; p_retirement alias for $2; p_origin_generation alias for $3;
  p_barrier alias for $4; p_canonical alias for $5; p_hash alias for $6; p_sequence alias for $7;
  s public.source_authority_admission; b public.source_retirement_barriers;
  old public.source_retirement_pins;
begin
  perform public.source_application_admit();
  select * into strict s from public.source_authority_admission where singleton;
  if s.generation <> p_generation or not exists (select 1 from public.source_application_principals p
    where p.principal = session_user and p.generation = s.generation and p.purpose = 'admin') then
    raise exception using errcode = '42501', message = 'source pin installation generation or principal changed';
  end if;
  perform pg_advisory_xact_lock(1213154899, 1);
  select * into strict b from public.source_retirement_barriers where retirement_id = p_retirement;
  if b.barrier_digest is distinct from p_barrier or b.origin_generation <> p_origin_generation
    or b.deployment_id <> s.deployment_id
    or record_platform_internal.digest(p_canonical, 'sha256') is distinct from p_hash then
    raise exception using errcode = '55000', message = 'source pin does not match committed barrier';
  end if;
  select * into old from public.source_retirement_pins
    where retirement_id = p_retirement and installed_generation = p_generation;
  if found then
    if (old.origin_generation, old.barrier_digest, old.canonical_terminal, old.terminal_hash, old.terminal_sequence)
      is distinct from (p_origin_generation, p_barrier, p_canonical, p_hash, p_sequence) then
      raise exception using errcode = '23505', message = 'source pin exact replay mismatch';
    end if;
    return;
  end if;
  insert into public.source_retirement_pins(project_id, source_kind, source_id, installed_generation,
    retirement_id, origin_generation, barrier_digest, canonical_terminal, terminal_hash, terminal_sequence)
  values (b.project_id, b.source_kind, b.source_id, p_generation, p_retirement,
    p_origin_generation, p_barrier, p_canonical, p_hash, p_sequence);
end
$$;
revoke all on function record_platform_internal.source_retirement_field(bytea),
  record_platform_internal.source_retirement_revision(text, text),
  public.source_retirement_preview(text, text, text),
  public.source_retirement_commit(bigint, text, text, text, text, text, bytea, bytea, bytea, bytea),
  public.source_retirement_install_pin(bigint, text, bigint, bytea, bytea, bytea, bigint) from public;

-- Maintenance callers receive only the protected admission projection. The
-- authority heartbeat principal does not receive generic APP table access.
create function public.source_maintenance_status()
returns setof public.source_authority_admission
language plpgsql stable security definer set search_path = pg_catalog
as $$
declare s public.source_authority_admission; bootstrap boolean;
begin
  select oid = 10 and rolsuper into bootstrap from pg_roles where rolname = session_user;
  if current_setting('role') <> 'none' then
    raise exception using errcode = '42501', message = 'source maintenance requires direct login';
  end if;
  select * into s from public.source_authority_admission where singleton;
  if not found then
    return;
  end if;
  if not coalesce(bootstrap, false) and not exists (
    select 1 from public.source_application_principals p join pg_roles r on r.rolname = p.principal
    where p.generation = s.generation and p.principal = session_user
      and p.purpose in ('runtime', 'admin', 'worker', 'migrator', 'authority')
      and r.rolcanlogin and not r.rolsuper and not r.rolcreaterole and not r.rolcreatedb
      and not r.rolreplication and not r.rolbypassrls and not r.rolinherit
      and not exists (select 1 from pg_auth_members m where m.member = r.oid or m.roleid = r.oid)
  ) then
    raise exception using errcode = '42501', message = 'source maintenance principal is stale or unbound';
  end if;
  return next s;
end
$$;

-- The external guard/W2 check covers the whole heartbeat. This effect-time
-- APP check additionally rejects a closed or stale local authority projection.
create function record_platform_internal.source_membership_effect_guard()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
declare s public.source_authority_admission;
begin
  if session_user = 'houfeng_records_authority' or exists (
    select 1 from public.source_application_principals
    where principal = session_user and purpose = 'authority'
  ) then
    select * into s from public.source_authority_admission where singleton;
    if found and (s.mode <> 'active' or new.deployment_id <> s.deployment_id or not exists (
      select 1 from public.source_application_principals p where p.principal = session_user
        and p.purpose = 'authority' and p.generation = s.generation
    )) then
      raise exception using errcode = '42501', message = 'source authority heartbeat admission is closed or stale';
    end if;
  end if;
  return new;
end
$$;
create trigger source_membership_effect_guard
before insert or update on public.deployment_membership
for each row execute function record_platform_internal.source_membership_effect_guard();
revoke all on function public.source_maintenance_status(),
  record_platform_internal.source_membership_effect_guard() from public;

-- A logical namespace survives cold handoff. Physical incarnations and anchors
-- are append-only; admission is the only mutable pointer to a physical tree.
create table public.local_blob_namespaces (
  namespace_id uuid primary key,
  root_path text not null unique check (root_path like '/%' and length(root_path) <= 4096),
  current_incarnation_id uuid not null,
  admission_state text not null check (admission_state in ('closed', 'active')),
  provision_request_id uuid not null unique,
  provision_command bytea not null check (octet_length(provision_command) between 1 and 16384),
  source_recovery_id text,
  created_at timestamptz not null default clock_timestamp(),
  admitted_at timestamptz,
  check ((admission_state = 'active') = (admitted_at is not null))
);

create table public.local_blob_namespace_incarnations (
  namespace_id uuid not null references public.local_blob_namespaces(namespace_id) on delete restrict,
  incarnation_id uuid not null,
  boot_id uuid not null,
  filesystem_device bigint not null check (filesystem_device >= 0),
  root_inode bigint not null check (root_inode > 0),
  digest_inode bigint not null check (digest_inode > 0),
  locks_inode bigint not null check (locks_inode > 0),
  marker_inode bigint not null check (marker_inode > 0),
  owner_uid bigint not null check (owner_uid >= 0),
  owner_gid bigint not null check (owner_gid >= 0),
  marker_digest bytea not null check (octet_length(marker_digest) = 32),
  marker_nonce uuid not null,
  created_at timestamptz not null default clock_timestamp(),
  primary key (namespace_id, incarnation_id),
  unique (boot_id, filesystem_device, root_inode),
  unique (boot_id, filesystem_device, marker_inode)
);
alter table public.local_blob_namespaces add constraint local_blob_namespaces_current_incarnation_fk
  foreign key (namespace_id, current_incarnation_id)
  references public.local_blob_namespace_incarnations(namespace_id, incarnation_id)
  deferrable initially deferred;

create table public.local_blob_key_anchors (
  namespace_id uuid not null,
  incarnation_id uuid not null,
  canonical_key text not null check (canonical_key ~ '^sha256/[0-9a-f]{64}$'),
  filesystem_device bigint not null check (filesystem_device >= 0),
  lock_inode bigint not null check (lock_inode > 0),
  lock_nonce uuid not null,
  created_at timestamptz not null default clock_timestamp(),
  primary key (namespace_id, incarnation_id, canonical_key),
  unique (namespace_id, incarnation_id, lock_inode),
  foreign key (namespace_id, incarnation_id)
    references public.local_blob_namespace_incarnations(namespace_id, incarnation_id) on delete restrict
);

-- No root, draft, upload, job, publication or artifact FK: physical responsibility
-- must remain discoverable after the original business owner has disappeared.
create table public.record_write_obligations (
  obligation_id text primary key check (obligation_id ~ '^rwo_[0-9a-f]{32}$'),
  writer_instance uuid not null,
  request_seq bigint not null check (request_seq > 0),
  writer_principal name not null,
  project_id text not null check (project_id = 'default'),
  origin_kind text not null check (origin_kind in ('upload', 'processor_preview', 'import_attachment', 'export_artifact', 'import_archive')),
  origin_id text not null check (origin_id ~ '^[a-z0-9_-]{1,128}$'),
  origin_generation bigint not null check (origin_generation > 0),
  origin_owner_id text,
  origin_owner_generation bigint,
  origin_owner_expires_at timestamptz,
  plan_digest bytea check (octet_length(plan_digest) = 32),
  archive_digest bytea check (octet_length(archive_digest) = 32),
  namespace_id uuid,
  incarnation_id uuid,
  backend_kind text not null check (backend_kind in ('local', 's3')),
  canonical_key text not null check (canonical_key ~ '^sha256/[0-9a-f]{64}$'),
  sha256_digest bytea not null check (octet_length(sha256_digest) = 32),
  size_bytes bigint not null check (size_bytes > 0),
  publication_id text check (publication_id ~ '^bpi_[a-z0-9]{1,64}$'),
  record_id text check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  record_epoch bigint check (record_epoch >= 0),
  operation_id text references public.record_purge_operations(operation_id) on delete restrict,
  registration_command bytea not null check (octet_length(registration_command) between 1 and 65536),
  temporary_key text,
  dispatch_id uuid,
  dispatched_at timestamptz,
  temporary_device bigint check (temporary_device >= 0),
  temporary_inode bigint check (temporary_inode > 0),
  temporary_created_at timestamptz,
  object_version text check (length(object_version) between 1 and 1024),
  outcome text not null default 'registered'
    check (outcome in ('registered', 'materialized', 'failed', 'local_excluded', 'remote_unknown')),
  returned_at timestamptz,
  return_command bytea,
  handed_off_at timestamptz,
  published_at timestamptz,
  cleanup_owner_id text check (cleanup_owner_id ~ '^[a-z0-9_-]{1,128}$'),
  cleanup_generation bigint not null default 0 check (cleanup_generation >= 0),
  cleanup_expires_at timestamptz,
  cleanup_dispatch_id uuid,
  cleanup_outcome text check (cleanup_outcome in ('deleted', 'already_absent', 'retained_referenced')),
  cleanup_receipt bytea check (octet_length(cleanup_receipt) = 32),
  cleanup_completed_at timestamptz,
  quota_settlement_id text not null unique check (quota_settlement_id ~ '^rwo_[0-9a-f]{32}$'),
  quota_settled_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  unique (writer_instance, request_seq),
  check (canonical_key = 'sha256/' || encode(sha256_digest, 'hex')),
  check ((record_id is null) = (record_epoch is null)),
  check ((origin_owner_id is null and origin_owner_generation is null and origin_owner_expires_at is null)
    or (origin_owner_id is not null and origin_owner_generation > 0 and origin_owner_expires_at is not null)),
  check ((backend_kind = 'local' and namespace_id is not null and incarnation_id is not null
      and temporary_key = 'sha256/.blob-tmp-' || obligation_id)
    or (backend_kind = 's3' and namespace_id is null and incarnation_id is null and temporary_key is null)),
  check ((dispatch_id is null) = (dispatched_at is null)),
  check ((temporary_device is null and temporary_inode is null and temporary_created_at is null)
    or (backend_kind = 'local' and dispatched_at is not null and temporary_device is not null
      and temporary_inode is not null and temporary_created_at is not null)),
  check (outcome <> 'local_excluded' or (backend_kind = 'local' and dispatched_at is null)),
  check (outcome not in ('materialized', 'failed', 'remote_unknown') or dispatched_at is not null),
  check (outcome <> 'materialized' or (object_version is not null and returned_at is not null)),
  check (outcome <> 'remote_unknown' or backend_kind = 's3'),
  check ((returned_at is null) = (return_command is null)),
  check (object_version is null or dispatched_at is not null),
  check ((cleanup_owner_id is null and cleanup_generation = 0 and cleanup_expires_at is null)
    or (cleanup_owner_id is not null and cleanup_generation > 0 and cleanup_expires_at is not null)),
  check ((cleanup_outcome is null and cleanup_receipt is null and cleanup_completed_at is null)
    or (cleanup_outcome is not null and cleanup_receipt is not null and cleanup_completed_at is not null)),
  check (quota_settled_at is null or cleanup_outcome in ('deleted', 'already_absent')),
  foreign key (namespace_id, incarnation_id)
    references public.local_blob_namespace_incarnations(namespace_id, incarnation_id) on delete restrict
);
create index idx_record_write_obligations_key
  on public.record_write_obligations(backend_kind, namespace_id, canonical_key, obligation_id);
create index idx_record_write_obligations_origin
  on public.record_write_obligations(origin_kind, origin_id, origin_generation);
create index idx_record_write_obligations_pending
  on public.record_write_obligations(namespace_id, canonical_key, created_at)
  where cleanup_completed_at is null;

create table public.record_write_obligation_targets (
  obligation_id text not null references public.record_write_obligations(obligation_id) on delete restrict,
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  attachment_id text check (attachment_id ~ '^att_[a-z0-9]{1,64}$'),
  plan_digest bytea not null check (octet_length(plan_digest) = 32),
  record_epoch bigint check (record_epoch >= 0),
  bound_at timestamptz,
  handed_off_at timestamptz,
  primary key (obligation_id, record_id),
  check ((record_epoch is null) = (bound_at is null))
);

-- NULL means legacy/unadopted, never the current namespace by default.
alter table public.blob_objects add column namespace_id uuid references public.local_blob_namespaces(namespace_id);
alter table public.attachment_upload_parts
  add column namespace_id uuid references public.local_blob_namespaces(namespace_id),
  add column obligation_id text references public.record_write_obligations(obligation_id);
alter table public.blob_publication_intents
  add column namespace_id uuid references public.local_blob_namespaces(namespace_id),
  add column obligation_id text references public.record_write_obligations(obligation_id);
alter table public.blob_gc_deletions
  add column namespace_id uuid references public.local_blob_namespaces(namespace_id),
  add column operation_id text references public.record_purge_operations(operation_id);
alter table public.record_export_artifacts
  add column object_version_id text check (length(object_version_id) between 1 and 1024),
  add column namespace_id uuid references public.local_blob_namespaces(namespace_id),
  add column obligation_id text references public.record_write_obligations(obligation_id);
alter table public.record_import_artifacts
  add column namespace_id uuid references public.local_blob_namespaces(namespace_id),
  add column obligation_id text references public.record_write_obligations(obligation_id);

-- Local cleanup may retain shared bytes without claiming physical absence.
do $$
declare constraint_name text;
begin
  for constraint_name in select c.conname from pg_constraint c
    where c.conrelid='public.blob_publication_intents'::regclass and c.contype='c'
      and c.conkey @> array[(select a.attnum from pg_attribute a where a.attrelid=c.conrelid and a.attname='completion_outcome')]
  loop execute format('alter table public.blob_publication_intents drop constraint %I',constraint_name); end loop;
end $$;
alter table public.blob_publication_intents
  add constraint blob_publication_completion_outcome check (completion_outcome is null or completion_outcome in ('consumed','deleted','already_absent')
    or (completion_outcome='retained_referenced' and backend_kind='local' and namespace_id is not null)),
  add constraint blob_publication_object_state check ((publication_state='prepared' and object_version is null)
    or (publication_state='published' and object_version is not null) or publication_state in ('cleanup_claimed','retry_wait')
    or (publication_state='completed' and (completion_outcome in ('already_absent','retained_referenced') or object_version is not null))),
  add constraint blob_publication_completion_facts check ((publication_state='completed')=
    (completion_outcome is not null and receipt_digest is not null and completed_at is not null)),
  add constraint blob_publication_completion_owner check (publication_state<>'completed'
    or (completion_outcome='consumed' and cleanup_owner_id='')
    or (completion_outcome in ('deleted','already_absent','retained_referenced') and cleanup_owner_id<>''));

create function record_platform_internal.local_blob_immutable_identity()
returns trigger language plpgsql set search_path = pg_catalog
as $$
begin
  raise exception using errcode = '55000', message = 'local blob physical identity is immutable';
end
$$;
create trigger local_blob_incarnation_immutable before update or delete
  on public.local_blob_namespace_incarnations for each row
  execute function record_platform_internal.local_blob_immutable_identity();
create trigger local_blob_anchor_immutable before update or delete
  on public.local_blob_key_anchors for each row
  execute function record_platform_internal.local_blob_immutable_identity();

create function record_platform_internal.record_write_obligation_identity_guard()
returns trigger language plpgsql set search_path = pg_catalog
as $$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '55000', message = 'write responsibility cannot be deleted';
  end if;
  if row(new.obligation_id, new.writer_instance, new.request_seq, new.writer_principal,
      new.project_id, new.origin_kind, new.origin_id, new.origin_generation,
      new.origin_owner_id, new.origin_owner_generation, new.origin_owner_expires_at,
      new.plan_digest, new.archive_digest, new.namespace_id, new.incarnation_id,
      new.backend_kind, new.canonical_key, new.sha256_digest, new.size_bytes,
      new.publication_id, new.registration_command, new.temporary_key,
      new.quota_settlement_id, new.created_at)
    is distinct from row(old.obligation_id, old.writer_instance, old.request_seq, old.writer_principal,
      old.project_id, old.origin_kind, old.origin_id, old.origin_generation,
      old.origin_owner_id, old.origin_owner_generation, old.origin_owner_expires_at,
      old.plan_digest, old.archive_digest, old.namespace_id, old.incarnation_id,
      old.backend_kind, old.canonical_key, old.sha256_digest, old.size_bytes,
      old.publication_id, old.registration_command, old.temporary_key,
      old.quota_settlement_id, old.created_at)
    or (old.object_version is not null and new.object_version is distinct from old.object_version)
    or (old.record_id is not null and row(new.record_id, new.record_epoch) is distinct from row(old.record_id, old.record_epoch))
    or (old.dispatch_id is not null and row(new.dispatch_id, new.dispatched_at) is distinct from row(old.dispatch_id, old.dispatched_at))
    or (old.temporary_inode is not null and row(new.temporary_device, new.temporary_inode, new.temporary_created_at)
      is distinct from row(old.temporary_device, old.temporary_inode, old.temporary_created_at))
    or (old.operation_id is not null and new.operation_id is distinct from old.operation_id)
    or (old.cleanup_completed_at is not null and row(new.cleanup_outcome, new.cleanup_receipt, new.cleanup_completed_at)
      is distinct from row(old.cleanup_outcome, old.cleanup_receipt, old.cleanup_completed_at))
    or (old.quota_settled_at is not null and new.quota_settled_at is distinct from old.quota_settled_at) then
    raise exception using errcode = '55000', message = 'write responsibility identity conflict';
  end if;
  return new;
end
$$;
create trigger record_write_obligation_identity_guard before update or delete
  on public.record_write_obligations for each row
  execute function record_platform_internal.record_write_obligation_identity_guard();

-- UPDATE privilege is also required by SELECT FOR UPDATE. Keep the lock
-- capability, but permit actual mutations only with table-owner authority.
create function record_platform_internal.record_attachment_publication_guard()
returns trigger language plpgsql set search_path = pg_catalog
as $$
begin
  if not pg_has_role(current_user, (select relowner from pg_catalog.pg_class where oid = tg_relid), 'USAGE') then
    raise exception using errcode = '42501', message = 'attachment publication requires constrained command authority';
  end if;
  return new;
end
$$;
create trigger record_attachment_publication_guard before insert or update on public.record_attachments
  for each row execute function record_platform_internal.record_attachment_publication_guard();
revoke all on function record_platform_internal.record_attachment_publication_guard() from public;

create function record_platform_internal.blob_gc_operation_identity_guard()
returns trigger language plpgsql set search_path = pg_catalog
as $$
declare protected_old boolean := false; protected_new boolean := false;
begin
  -- This trigger is deliberately INVOKER. Only table-owner authority used by
  -- constrained SECURITY DEFINER commands or trusted database maintenance may mutate local evidence.
  -- Neither a caller-controlled setting nor a V1 tag can confer that authority.
  if tg_op <> 'INSERT' then
    protected_old := old.local_contract_version = 2 or old.operation_id is not null
      or old.namespace_id is not null or old.incarnation_id is not null
      or old.cleanup_dispatch_id is not null or old.inventory_digest is not null
      or old.final_identity_bound or old.final_was_present is not null
      or old.final_device is not null or old.final_inode is not null
      or old.completion_command is not null;
  end if;
  if tg_op <> 'DELETE' then
    protected_new := new.local_contract_version = 2 or new.operation_id is not null
      or new.namespace_id is not null or new.incarnation_id is not null
      or new.cleanup_dispatch_id is not null or new.inventory_digest is not null
      or new.final_identity_bound or new.final_was_present is not null
      or new.final_device is not null or new.final_inode is not null
      or new.completion_command is not null;
  end if;
  if (protected_old or protected_new) and not pg_has_role(current_user,
    (select relowner from pg_catalog.pg_class where oid = tg_relid), 'USAGE') then
    raise exception using errcode = '42501', message = 'local cleanup requires constrained command authority';
  end if;
  if tg_op = 'UPDATE' and row(new.operation_id, new.namespace_id) is distinct from row(old.operation_id, old.namespace_id) then
    raise exception using errcode = '55000', message = 'blob cleanup authority identity is immutable';
  end if;
  if tg_op <> 'DELETE' and new.local_contract_version=1 and new.operation_id is not null
    and (new.purge_mode<>'permanent' or new.backend_kind<>'s3' or new.namespace_id is not null
      or new.incarnation_id is not null or new.cleanup_dispatch_id is not null or new.inventory_digest is not null
      or new.final_identity_bound or new.final_was_present is not null or new.final_device is not null
      or new.final_inode is not null or new.completion_command is not null) then
    raise exception using errcode='55000',message='invalid V1 attachment cleanup identity';
  end if;
  if tg_op='UPDATE' and old.local_contract_version=1 and old.operation_id is not null
    and row(new.deletion_id,new.project_id,new.purge_mode,new.blob_key,new.sha256_digest,new.object_version,
      new.size_bytes,new.backend_kind,new.blob_created_at,new.local_contract_version,new.namespace_id,
      new.incarnation_id,new.cleanup_dispatch_id,new.inventory_digest,new.final_identity_bound,new.final_was_present,
      new.final_device,new.final_inode,new.completion_command,new.created_at)
    is distinct from row(old.deletion_id,old.project_id,old.purge_mode,old.blob_key,old.sha256_digest,old.object_version,
      old.size_bytes,old.backend_kind,old.blob_created_at,old.local_contract_version,old.namespace_id,
      old.incarnation_id,old.cleanup_dispatch_id,old.inventory_digest,old.final_identity_bound,old.final_was_present,
      old.final_device,old.final_inode,old.completion_command,old.created_at) then
    raise exception using errcode='55000',message='V1 attachment cleanup object is immutable';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end
$$;
create trigger blob_gc_operation_identity_guard before insert or update or delete on public.blob_gc_deletions
  for each row execute function record_platform_internal.blob_gc_operation_identity_guard();
revoke all on function record_platform_internal.local_blob_immutable_identity(),
  record_platform_internal.record_write_obligation_identity_guard(),
  record_platform_internal.blob_gc_operation_identity_guard() from public;

-- EXECUTE grants distinguish runtime/admin/worker. This additional check rejects
-- SET ROLE, inherited access and privileged LOGINs even when EXECUTE is present.
create function record_platform_internal.local_blob_direct_login()
returns void language plpgsql security definer set search_path = pg_catalog
as $$
begin
  if current_setting('role') <> 'none' or not exists (
    select 1 from pg_roles r where r.rolname = session_user and r.rolcanlogin
      and not r.rolsuper and not r.rolcreaterole and not r.rolcreatedb
      and not r.rolreplication and not r.rolbypassrls and not r.rolinherit
      and not exists (select 1 from pg_auth_members m where m.member = r.oid or m.roleid = r.oid)
  ) then
    raise exception using errcode = '42501', message = 'local blob command requires constrained direct LOGIN';
  end if;
end
$$;

-- Comparison input writers acquire this only at their transaction prefix,
-- after source/graph/namespace admission and before record or actor rows.
create function record_platform_internal.record_comparison_writer_fence()
returns void language plpgsql security definer set search_path = pg_catalog
as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'comparison writer requires read committed isolation';
  end if;
  perform pg_advisory_xact_lock_shared(1213154899, 81);
end
$$;

-- NULL identifies a predecessor row whose owner has not yet been observed
-- under the current route protocol. This is not a root foreign key or drain
-- evidence; the immutable route survives removal of the subject and root.
alter table public.record_outbox add column record_id text
  check (record_id is null or record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$');

create function record_platform_internal.record_outbox_route_immutable()
returns trigger language plpgsql set search_path = pg_catalog
as $$
begin
  if old.record_id is not null and new.record_id is distinct from old.record_id then
    raise exception using errcode = '55000', message = 'outbox record route is immutable';
  end if;
  return new;
end
$$;
create trigger record_outbox_route_immutable before update on public.record_outbox
for each row execute function record_platform_internal.record_outbox_route_immutable();
revoke all on function record_platform_internal.record_outbox_route_immutable() from public;

-- This closed command only locks existing rows. Neither an absent row nor a
-- successful call authorizes a write or establishes a route, gate, or rank.
create function public.record_mutation_rows_lock(bytea)
returns void language plpgsql security definer set search_path = pg_catalog
as $$
declare
  input_json json;
  command jsonb;
  fields text[];
  family text;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'record row locks require read committed isolation';
  end if;
  if not exists (select 1 from pg_locks l
    where l.pid = pg_backend_pid() and l.locktype = 'advisory' and l.granted
      and l.classid = 1213154899::oid and l.objid = 81::oid and l.objsubid = 2
      and l.mode in ('ShareLock', 'ExclusiveLock')) then
    raise exception using errcode = '42501', message = 'comparison fence must be held before record row locks';
  end if;
  -- An observed lock could be session scoped. Pin the same fence to this
  -- transaction without waiting or trying to upgrade a shared holder.
  if not pg_try_advisory_xact_lock_shared(1213154899, 81) then
    raise exception using errcode = '55000', message = 'comparison transaction fence unavailable';
  end if;
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode = '22023', message = 'invalid record row lock command size';
  end if;
  -- jsonb discards duplicate object keys; check the original json first.
  input_json := convert_from($1, 'UTF8')::json;
  if json_typeof(input_json) is distinct from 'object'
    or (select count(*) from json_each(input_json)) <>
      (select count(distinct field.key) from json_each(input_json) field) then
    raise exception using errcode = '22023', message = 'invalid record row lock command object';
  end if;
  command := input_json::jsonb;
  family := command->>'family';
  fields := case family
    when 'gate' then array['family', 'project_id', 'record_id']
    when 'outbox_gate' then array['family', 'project_id', 'record_id']
    when 'deletion_fence' then array['family', 'project_id', 'record_id']
    when 'reservation' then array['family', 'project_id', 'record_id', 'reservation_id']
    when 'membership' then array['family', 'group_id', 'user_id']
    when 'revision' then array['family', 'record_id', 'revision_id']
    when 'revision_participant' then array['family', 'revision_id', 'user_id']
    when 'evidence_intent' then array['family', 'intent_id']
    when 'evidence_payload' then array['family', 'payload_digest']
    when 'evidence_snapshot' then array['family', 'snapshot_id']
    when 'evidence_lineage' then array['family', 'snapshot_id']
    when 'comparison_dependencies' then array['family', 'result_snapshot_id']
    when 'comparison_completion' then array['family', 'result_snapshot_id']
    when 'export_job' then array['family', 'project_id', 'export_job_id']
    when 'write_obligation' then array['family', 'obligation_id']
    when 'outbox' then array['family', 'outbox_row_id']
    when 'search_subject' then array['family', 'generation', 'record_id', 'subject_kind', 'source_id', 'relation_role']
    else null
  end;
  if fields is null or (select count(*) from json_each(input_json)) <> cardinality(fields)
    or exists (select 1 from json_each(input_json) field
      where not (field.key = any(fields)) or case when field.key in ('generation', 'outbox_row_id') then
        json_typeof(field.value) <> 'number' or field.value::text !~ '^[1-9][0-9]*$'
          or field.value::text::numeric > 9223372036854775807::numeric
      else json_typeof(field.value) <> 'string' end) then
    raise exception using errcode = '22023', message = 'invalid record row lock command fields';
  end if;
  if (family in ('gate','outbox_gate','deletion_fence','reservation','export_job') and command->>'project_id' <> 'default')
    or (family = 'evidence_payload' and command->>'payload_digest' !~ '^[0-9a-f]{64}$')
    or (family = 'export_job' and command->>'export_job_id' !~ '^rej_[a-z0-9]{1,64}$')
    or (family = 'write_obligation' and command->>'obligation_id' !~ '^rwo_[0-9a-f]{32}$') then
    raise exception using errcode = '22023', message = 'invalid record row lock identity';
  end if;

  case family
    when 'gate' then
      perform 1 from public.record_deletion_gates g
        where g.project_id = command->>'project_id' and g.record_id = command->>'record_id'
        order by g.project_id collate "C", g.record_id collate "C" for update;
    when 'outbox_gate' then
      begin
        perform 1 from public.record_deletion_gates g
          where g.project_id = command->>'project_id' and g.record_id = command->>'record_id' for share nowait;
      exception when lock_not_available then
        raise exception using errcode = '40001', message = 'outbox gate changed; restart transaction';
      end;
    when 'deletion_fence' then
      perform 1 from public.deletion_fence_leases f
        where f.project_id = command->>'project_id' and f.object_kind = 'record' and f.object_id = command->>'record_id'
        order by f.project_id collate "C", f.object_id collate "C" for update;
    when 'reservation' then
      perform 1 from public.deletion_reservations r
        where r.project_id = command->>'project_id' and r.object_kind = 'record' and r.object_id = command->>'record_id'
          and r.reservation_id = command->>'reservation_id'
        order by r.reservation_id collate "C" for update;
    when 'membership' then
      perform 1 from public.record_access_group_members m
        join public.record_access_groups g on g.group_id = m.group_id
        where g.project_id = 'default' and m.group_id = command->>'group_id' and m.user_id = command->>'user_id'
        order by m.group_id collate "C", m.user_id collate "C" for update of m;
    when 'revision' then
      perform 1 from public.record_revisions r
        where r.project_id = 'default' and r.record_id = command->>'record_id' and r.revision_id = command->>'revision_id'
        order by r.revision_id collate "C" for update;
    when 'revision_participant' then
      perform 1 from public.record_revision_participants p
        where p.revision_id = command->>'revision_id' and p.participant_id = command->>'user_id'
        order by p.revision_id collate "C", p.ordinal for update;
    when 'evidence_intent' then
      perform 1 from public.evidence_capture_intents i where i.intent_id = command->>'intent_id'
        order by i.intent_id collate "C" for update;
    when 'evidence_payload' then
      perform 1 from public.evidence_payloads p where p.payload_digest = decode(command->>'payload_digest', 'hex')
        order by p.payload_digest for update;
    when 'evidence_snapshot' then
      perform 1 from public.evidence_snapshots s where s.snapshot_id = command->>'snapshot_id'
        order by s.snapshot_id collate "C" for update;
    when 'evidence_lineage' then
      perform 1 from public.evidence_copy_lineage l where l.snapshot_id = command->>'snapshot_id'
        order by l.snapshot_id collate "C" for update;
    when 'comparison_dependencies' then
      perform 1 from public.comparison_result_dependencies d
        where d.project_id = 'default' and d.result_snapshot_id = command->>'result_snapshot_id'
        order by d.result_snapshot_id collate "C", d.source_record_id collate "C",
          d.source_revision_id collate "C" nulls first, d.source_snapshot_id collate "C" nulls first for update;
    when 'comparison_completion' then
      perform 1 from public.comparison_result_dependency_index_completions c
        where c.project_id = 'default' and c.result_snapshot_id = command->>'result_snapshot_id'
        order by c.result_snapshot_id collate "C" for update;
    when 'export_job' then
      perform 1 from public.record_export_jobs j where j.project_id=command->>'project_id'
        and j.export_job_id=command->>'export_job_id' for update;
    when 'write_obligation' then
      perform 1 from public.record_write_obligations o where o.obligation_id = command->>'obligation_id'
        order by o.obligation_id collate "C" for update;
    when 'outbox' then
      begin
        perform 1 from public.record_outbox o
          where o.outbox_row_id = (command->>'outbox_row_id')::bigint for update nowait;
      exception when lock_not_available then
        raise exception using errcode = '40001', message = 'outbox row changed; restart transaction';
      end;
    when 'search_subject' then
      perform 1 from public.record_search_subjects s
        join public.record_search_documents d on d.generation = s.generation and d.record_id = s.record_id
        where d.project_id = 'default' and s.generation = (command->>'generation')::bigint
          and s.record_id = command->>'record_id' and s.subject_kind = command->>'subject_kind'
          and s.source_id = command->>'source_id' and s.relation_role = command->>'relation_role'
        order by s.generation, s.record_id collate "C", s.subject_kind collate "C",
          s.source_id collate "C", s.relation_role collate "C" for update of s;
  end case;
end
$$;
revoke all on function record_platform_internal.record_comparison_writer_fence(),
  public.record_mutation_rows_lock(bytea) from public;

-- Fixed outbox transitions derive the route from the actual subject and own
-- every database lock they need. The discriminator is private; public callers
-- can only invoke one named transition. In particular, an observed Go lock is
-- never accepted as authority for these commands.
create function record_platform_internal.record_outbox_transition(bytea, text)
returns setof public.record_outbox language plpgsql security definer set search_path = pg_catalog
as $$
declare
  raw json;
  v jsonb;
  fields text[] := array['project_id','event_kind','subject_kind','subject_id',
    'source_version','authorization_epoch','record_fence_epoch','record_id'];
  numeric_fields constant text[] := array['source_version','authorization_epoch','record_fence_epoch',
    'expires_after_us','outbox_row_id','owner_generation','attempt_count','delay_us'];
  reservation_ids text[] := array[]::text[];
  reservation_id text;
  epoch bigint;
  lease_expiry timestamptz;
  owner_expiry timestamptz;
  event_expiry timestamptz;
  next_attempt timestamptz;
  tick timestamptz;
  route text;
  gate public.record_deletion_gates;
  admission public.source_authority_admission;
  source_present boolean;
  current_row public.record_outbox;
  terminal boolean := $2 in ('sent','cancel','cleanup');
  notification boolean;
  blocked boolean := false;
begin
  if $2 = 'enqueue' then
    fields := fields || array['expires_after_us'];
  elsif $2 in ('claim','retry','sent','cancel','cleanup') then
    fields := fields || array['outbox_row_id','status','owner_id','owner_generation',
      'owner_expires_at','attempt_count','next_attempt_at','event_expires_at','new_owner_id','delay_us'];
  else
    raise exception using errcode = '22023', message = 'invalid outbox transition';
  end if;
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'outbox commands require read committed isolation';
  end if;
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode = '22023', message = 'invalid outbox command size';
  end if;
  begin
    raw := convert_from($1, 'UTF8')::json;
  exception when data_exception then
    raise exception using errcode = '22023', message = 'invalid outbox command';
  end;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw)) <> cardinality(fields)
    or (select count(distinct f.key) from json_each(raw) f) <> cardinality(fields)
    or exists (select 1 from json_each(raw) f where not (f.key = any(fields)) or
      case when f.key = any(numeric_fields) then
        case when json_typeof(f.value) <> 'number' or f.value::text !~ '^(0|[1-9][0-9]*)$' then true
          else f.value::text::numeric > 9223372036854775807::numeric end
      when f.key = 'owner_expires_at' then json_typeof(f.value) not in ('string','null')
      else json_typeof(f.value) <> 'string' end) then
    raise exception using errcode = '22023', message = 'invalid outbox command fields';
  end if;
  v := raw::jsonb;
  notification := v->>'event_kind' in ('record_owner_changed','record_participant_changed',
    'record_action_assigned','record_action_completed','record_action_cancelled',
    'record_comment_replied','record_comment_mentioned','record_notification_delivery');
  if v->>'project_id' <> 'default' or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'subject_id' !~ '^[a-z0-9_]{1,128}$'
    or not ((v->>'subject_kind' = 'record' and v->>'subject_id' = v->>'record_id'
        and v->>'event_kind' in ('record_created','record_updated','record_deleted','record_owner_changed','record_participant_changed'))
      or (v->>'subject_kind' = 'action' and v->>'event_kind' in ('record_action_created','record_action_updated',
        'record_action_assigned','record_action_completed','record_action_cancelled','record_action_reopened'))
      or (v->>'subject_kind' = 'comment' and v->>'event_kind' in ('record_comment_created','record_comment_edited',
        'record_comment_redacted','record_comment_replied','record_comment_mentioned'))
      or (v->>'subject_kind' = 'delivery' and v->>'subject_id' ~ '^rnd_[a-z0-9]{1,64}$'
        and v->>'event_kind' = 'record_notification_delivery'))
    or notification <> ((v->>'source_version')::bigint > 0)
    or (notification and (v->>'authorization_epoch')::bigint = 0)
    or (not notification and (v->>'record_fence_epoch')::bigint <> 0) then
    raise exception using errcode = '22023', message = 'invalid outbox event identity';
  end if;
  if $2 = 'enqueue' then
    if (v->>'expires_after_us')::bigint not between 1 and 9223372036854775 then
      raise exception using errcode = '22023', message = 'invalid outbox expiry';
    end if;
  else
    if (v->>'outbox_row_id')::bigint <= 0 or v->>'status' not in ('pending','processing','sent','cancelled')
      or (v->>'owner_id' <> '' and v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$')
      or (v->>'new_owner_id' <> '' and v->>'new_owner_id' !~ '^[a-z0-9_-]{1,128}$')
      or (v->>'delay_us')::bigint > 9223372036854775
      or ($2 = 'claim' and (v->>'new_owner_id' = '' or (v->>'delay_us')::bigint = 0))
      or ($2 = 'retry' and (v->>'new_owner_id' <> '' or (v->>'delay_us')::bigint = 0))
      or ($2 in ('sent','cancel','cleanup') and (v->>'new_owner_id' <> '' or (v->>'delay_us')::bigint <> 0))
      or exists (select 1 from jsonb_each_text(v) f where f.key in ('owner_expires_at','next_attempt_at','event_expires_at')
        and f.value is not null and f.value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{0,5}[1-9])?Z$') then
      raise exception using errcode = '22023', message = 'invalid outbox owner identity';
    end if;
    begin
      owner_expiry := (v->>'owner_expires_at')::timestamptz;
      event_expiry := (v->>'event_expires_at')::timestamptz;
      next_attempt := (v->>'next_attempt_at')::timestamptz;
    exception when data_exception then
      raise exception using errcode = '22023', message = 'invalid outbox timestamp';
    end;
  end if;

  -- This function can be called after later Go ranks. Reacquire the actual
  -- source singleton, graph, comparison and record scopes without waiting.
  begin
    select s.* into admission from public.source_authority_admission s where s.singleton for share nowait;
    source_present := found;
    if source_present and (admission.mode <> 'active' or not exists (
      select 1 from public.source_application_principals p where p.principal = session_user
        and p.generation = admission.generation and p.purpose in ('runtime','admin','worker'))) then
      raise exception using errcode = '42501', message = 'source application admission is closed or stale';
    end if;
    perform record_platform_internal.record_birth_launch_admit(admission);
    if not pg_try_advisory_xact_lock_shared(1213154899,1)
      or not pg_try_advisory_xact_lock_shared(1213154899,81) then
      raise exception using errcode = '40001', message = 'outbox admission changed; restart transaction';
    end if;
    if source_present <> exists (select 1 from public.source_authority_admission s where s.singleton) then
      raise exception using errcode = '40001', message = 'outbox source admission changed; restart transaction';
    end if;
    for reservation_id in select r.reservation_id from public.deletion_reservations r
      where r.project_id = 'default' and r.object_kind = 'record' and r.object_id = v->>'record_id'
      order by r.reservation_id collate "C" for update nowait loop
      reservation_ids := array_append(reservation_ids, reservation_id);
    end loop;
    select e.delivery_epoch into epoch from public.content_delivery_epochs e
      where e.project_id = 'default' and e.object_kind = 'record' and e.object_id = v->>'record_id' for update nowait;
    if exists (select 1 from public.deletion_reservations r where r.project_id = 'default'
      and r.object_kind = 'record' and r.object_id = v->>'record_id'
      and not (r.reservation_id = any(reservation_ids))) then
      raise exception using errcode = '40001', message = 'outbox reservation changed; restart transaction';
    end if;
    select l.expires_at into lease_expiry from public.deletion_fence_leases l
      where l.project_id = 'default' and l.object_kind = 'record' and l.object_id = v->>'record_id' for update nowait;
    perform 1 from public.object_content_leases l where l.project_id = 'default'
      and l.object_kind = 'record' and l.object_id = v->>'record_id' for update nowait;
    select g.* into gate from public.record_deletion_gates g
      where g.project_id = 'default' and g.record_id = v->>'record_id' for share nowait;
    blocked := found or coalesce(lease_expiry > clock_timestamp(),false) or exists (
      select 1 from public.deletion_reservations r where r.project_id = 'default' and r.object_kind = 'record'
        and r.object_id = v->>'record_id' and r.state in ('fenced','committed'));
    if epoch is null then
      if not terminal or gate.operation_id is null or gate.fence_epoch < (v->>'record_fence_epoch')::bigint or not exists (
        select 1 from public.record_purge_operations o join public.deletion_reservations r
          on r.reservation_id = o.reservation_id
        where o.operation_id = gate.operation_id and o.deletion_contract_version = 2 and o.project_id = gate.project_id
          and r.deletion_contract_version = 2 and r.project_id = gate.project_id
          and r.object_kind = 'record' and r.object_id = gate.record_id
          and r.fence_epoch = gate.fence_epoch and r.state in ('fenced','committed')) then
        raise exception using errcode = '55000', message = 'outbox record scope unavailable';
      end if;
    elsif epoch < (v->>'record_fence_epoch')::bigint then
      raise exception using errcode = '55000', message = 'outbox record epoch unavailable';
    end if;
    if not terminal and (blocked or (notification and epoch <> (v->>'record_fence_epoch')::bigint)) then
      raise exception using errcode = '55000', message = 'outbox record gate closed';
    end if;
    perform 1 from public.records r where r.project_id = 'default' and r.record_id = v->>'record_id'
      and r.current_revision_id is not null for update nowait;
    if not found and not terminal then
      raise exception using errcode = '55000', message = 'outbox record root unavailable';
    end if;
    case v->>'subject_kind'
      when 'record' then
        select r.record_id into route from public.records r where r.project_id = 'default'
          and r.record_id = v->>'subject_id';
      when 'action' then
        select a.record_id into route from public.record_actions a where a.project_id = 'default'
          and a.action_id = v->>'subject_id' for share nowait;
      when 'comment' then
        select c.record_id into route from public.record_comments c where c.project_id = 'default'
          and c.comment_id = v->>'subject_id' for share nowait;
      when 'delivery' then
        select d.record_id into route from public.record_notification_deliveries d
          join public.record_notifications n on n.record_id = d.record_id and n.notification_id = d.notification_id
          where n.project_id = 'default' and d.delivery_id = v->>'subject_id' for share of d,n nowait;
    end case;
    if route is distinct from v->>'record_id' and (route is not null or not terminal) then
      raise exception using errcode = '40001', message = 'outbox subject route changed; restart transaction';
    end if;
    if $2 <> 'enqueue' then
      select o.* into current_row from public.record_outbox o
        where o.outbox_row_id = (v->>'outbox_row_id')::bigint for update nowait;
      if not found then return; end if;
      if current_row.record_id is not null and current_row.record_id is distinct from v->>'record_id' then
        raise exception using errcode = '40001', message = 'outbox persisted route changed; restart transaction';
      end if;
      if current_row.record_id is null and route is distinct from v->>'record_id' then
        return;
      end if;
    end if;
  exception when lock_not_available then
    raise exception using errcode = '40001', message = 'outbox scope changed; restart transaction';
  end;

  if $2 = 'enqueue' then
    insert into public.record_outbox (project_id,event_kind,subject_kind,subject_id,source_version,
      authorization_epoch,record_fence_epoch,record_id,expires_at)
      values (v->>'project_id',v->>'event_kind',v->>'subject_kind',v->>'subject_id',
        (v->>'source_version')::bigint,(v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,
        route,transaction_timestamp() + ((v->>'expires_after_us')::bigint * interval '1 microsecond'))
      returning * into current_row;
    if current_row.expires_at <= clock_timestamp() then
      raise exception using errcode = '40001', message = 'outbox enqueue expired during write';
    end if;
    return next current_row;
    return;
  end if;
  -- The complete observed tuple is checked only after all locks, with a new
  -- wall-clock reading. Terminal transitions retain the existing owner policy.
  if row(current_row.project_id,current_row.event_kind,current_row.subject_kind,current_row.subject_id,
      current_row.source_version,current_row.authorization_epoch,current_row.record_fence_epoch,
      current_row.status,current_row.owner_id,current_row.owner_generation,current_row.owner_expires_at,
      current_row.attempt_count,current_row.next_attempt_at,current_row.expires_at)
    is distinct from row(v->>'project_id',v->>'event_kind',v->>'subject_kind',v->>'subject_id',
      (v->>'source_version')::bigint,(v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,
      v->>'status',v->>'owner_id',(v->>'owner_generation')::bigint,owner_expiry,
      (v->>'attempt_count')::bigint,next_attempt,event_expiry) then
    return;
  end if;
  -- Once a send is started, only fact-backed finalization/reconciliation or
  -- the deletion-owner drain can dispose of its queue row. A completed prior
  -- retry may still be cancelled by a current pre-start/no-processor path.
  if current_row.subject_kind='delivery' and $2 in ('retry','sent','cancel') and exists(
      select 1 from public.record_notification_deliveries d where d.delivery_id=current_row.subject_id
        and (d.delivery_state='processing' or exists(select 1 from public.record_notification_delivery_starts s
          where s.delivery_id=d.delivery_id and s.attempt_no=d.attempt_count and not exists(
            select 1 from public.record_notification_delivery_completions c
              where c.delivery_id=s.delivery_id and c.attempt_no=s.attempt_no)))) then
    raise exception using errcode='55000',message='started delivery requires atomic completion';
  end if;
  tick := clock_timestamp();
  if $2 = 'claim' then
    if not ((current_row.status = 'pending' and current_row.next_attempt_at <= tick)
      or (current_row.status = 'processing' and current_row.owner_expires_at <= tick))
      or current_row.expires_at <= tick + ((v->>'delay_us')::bigint * interval '1 microsecond')
      or current_row.owner_generation = 9223372036854775807 or current_row.attempt_count = 9223372036854775807 then
      return;
    end if;
    update public.record_outbox set record_id = coalesce(record_id, route), status = 'processing',
      owner_id = v->>'new_owner_id', owner_generation = owner_generation + 1,
      owner_expires_at = tick + ((v->>'delay_us')::bigint * interval '1 microsecond'),
      attempt_count = attempt_count + 1 where outbox_row_id = current_row.outbox_row_id returning * into current_row;
  elsif $2 = 'cleanup' then
    if current_row.status not in ('sent','cancelled') or current_row.expires_at > tick
      or (current_row.owner_expires_at is not null and current_row.owner_expires_at > tick) then return; end if;
    if exists(select 1 from public.record_notification_delivery_completions c
      where c.outbox_row_id=current_row.outbox_row_id and c.owner_generation=current_row.owner_generation
        and c.owner_expires_at>tick) then return; end if;
    delete from public.record_outbox where outbox_row_id = current_row.outbox_row_id;
  else
    if current_row.status <> 'processing' or current_row.owner_id = '' or current_row.owner_generation <= 0
      or current_row.owner_expires_at <= tick then return; end if;
    if $2 = 'retry' then
      if current_row.expires_at <= tick + ((v->>'delay_us')::bigint * interval '1 microsecond') then return; end if;
      update public.record_outbox set record_id = coalesce(record_id, route), status = 'pending', owner_id = '',
        owner_expires_at = null, next_attempt_at = tick + ((v->>'delay_us')::bigint * interval '1 microsecond')
        where outbox_row_id = current_row.outbox_row_id returning * into current_row;
    elsif $2 = 'sent' then
      if current_row.expires_at <= tick then return; end if;
      update public.record_outbox set record_id = coalesce(record_id, route), status = 'sent', owner_id = '',
        owner_expires_at = null, sent_at = tick where outbox_row_id = current_row.outbox_row_id returning * into current_row;
    else
      update public.record_outbox set record_id = coalesce(record_id, route), status = 'cancelled', owner_id = '',
        owner_expires_at = null where outbox_row_id = current_row.outbox_row_id returning * into current_row;
    end if;
  end if;
  -- Triggers and indexes may wait even after all explicit locks were taken.
  -- Roll back the transition if that wait outlived its owner or event fence.
  tick := clock_timestamp();
  if ($2 = 'claim' and (current_row.owner_expires_at <= tick or current_row.expires_at <= tick))
    or ($2 in ('retry','sent','cancel') and owner_expiry <= tick)
    or ($2 = 'sent' and event_expiry <= tick)
    or ($2 = 'retry' and event_expiry <= tick + ((v->>'delay_us')::bigint * interval '1 microsecond')) then
    raise exception using errcode = '40001', message = 'outbox owner expired during transition';
  end if;
  return next current_row;
end
$$;

create function public.record_outbox_enqueue(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'enqueue') $$;
create function public.record_outbox_claim(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'claim') $$;
create function public.record_outbox_retry(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'retry') $$;
create function public.record_outbox_sent(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'sent') $$;
create function public.record_outbox_cancel(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'cancel') $$;
create function public.record_outbox_cleanup(bytea) returns setof public.record_outbox
language sql security definer set search_path = pg_catalog as $$ select * from record_platform_internal.record_outbox_transition($1,'cleanup') $$;
revoke all on function record_platform_internal.record_outbox_transition(bytea,text),
  public.record_outbox_enqueue(bytea), public.record_outbox_claim(bytea), public.record_outbox_retry(bytea),
  public.record_outbox_sent(bytea), public.record_outbox_cancel(bytea), public.record_outbox_cleanup(bytea) from public;

-- No FK to any online content, queue, epoch, operation or root. Existing
-- predecessor inventory, if imported by the migration owner, has a NULL hash;
-- no command in this block creates a capability for such a row.
create table public.record_notification_delivery_starts (
  delivery_id text not null,
  attempt_no integer not null check (attempt_no between 1 and 8),
  attempt_id text not null unique check (attempt_id ~ '^rna_[0-9a-f]{64}$'),
  project_id text not null default 'default' check (project_id = 'default'),
  record_id text not null,
  notification_id text not null,
  recipient_user_id text not null,
  channel text not null check (channel in ('telegram','feishu')),
  binding_id text not null check (binding_id ~ '^[a-z0-9_-]{1,128}$'),
  source_version bigint not null check (source_version > 0),
  authorization_epoch bigint not null check (authorization_epoch > 0),
  record_fence_epoch bigint not null check (record_fence_epoch >= 0),
  started_at timestamptz not null,
  outbox_row_id bigint not null check (outbox_row_id > 0),
  owner_id text not null check (owner_id ~ '^[a-z0-9_-]{1,128}$'),
  owner_generation bigint not null check (owner_generation > 0),
  owner_expires_at timestamptz not null,
  event_expires_at timestamptz not null,
  correlation_digest bytea not null check (octet_length(correlation_digest) = 32),
  reporting_capability_hash bytea check (reporting_capability_hash is null or octet_length(reporting_capability_hash) = 32),
  primary key (delivery_id, attempt_no),
  check (owner_expires_at > started_at and event_expires_at > started_at)
);
create index record_notification_delivery_starts_record_idx
  on public.record_notification_delivery_starts(project_id, record_id, delivery_id, attempt_no);

create table public.record_notification_delivery_facts (
  attempt_id text not null references public.record_notification_delivery_starts(attempt_id) on delete restrict,
  fact_kind text not null check (fact_kind in ('provider_report','drain_observation')),
  evidence_digest bytea not null check (octet_length(evidence_digest) = 32),
  project_id text not null check (project_id = 'default'),
  record_id text not null,
  outcome text not null check (outcome in ('sent','temporary_failure','permanent_failure','unknown_outcome')),
  reason_code text not null check (reason_code in ('provider_sent','provider_temporary_failure',
    'provider_permanent_failure','provider_unknown_outcome','lease_takeover_unknown','deletion_handoff_unknown')),
  reported_at timestamptz not null,
  primary key (attempt_id, fact_kind, evidence_digest),
  check ((fact_kind = 'provider_report' and reason_code = case outcome
      when 'sent' then 'provider_sent' when 'temporary_failure' then 'provider_temporary_failure'
      when 'permanent_failure' then 'provider_permanent_failure' else 'provider_unknown_outcome' end)
    or (fact_kind = 'drain_observation' and outcome = 'unknown_outcome'
      and reason_code in ('lease_takeover_unknown','deletion_handoff_unknown')))
);
create index record_notification_delivery_facts_record_idx
  on public.record_notification_delivery_facts(project_id, record_id, attempt_id);

-- Legacy processing without a start has NULL attempt_id/fact identity. Its
-- deterministic request attempt_id is validated, but is not persisted as a
-- claimed start. No FK to live queue, delivery, root, or notification.
create table public.record_notification_delivery_completions (
  delivery_id text not null,
  attempt_no integer not null check (attempt_no between 1 and 8),
  attempt_id text unique references public.record_notification_delivery_starts(attempt_id) on delete restrict,
  fact_kind text,
  evidence_digest bytea,
  request_evidence_digest bytea check (request_evidence_digest is null or octet_length(request_evidence_digest) = 32),
  project_id text not null check (project_id = 'default'),
  record_id text not null,
  notification_id text not null,
  recipient_user_id text not null,
  channel text not null check (channel in ('telegram','feishu')),
  binding_id text not null,
  source_version bigint not null check (source_version>0),
  authorization_epoch bigint not null check (authorization_epoch>0),
  record_fence_epoch bigint not null check (record_fence_epoch >= 0),
  started_at timestamptz not null,
  outbox_row_id bigint not null check (outbox_row_id > 0),
  event_expires_at timestamptz not null,
  owner_id text not null,
  owner_generation bigint not null check (owner_generation > 0),
  owner_expires_at timestamptz not null,
  disposition text not null check (disposition in ('complete','retry','cancel')),
  retry_after_us bigint not null check (retry_after_us >= 0),
  next_attempt_at timestamptz,
  completed_at timestamptz not null,
  primary key (delivery_id, attempt_no),
  foreign key (attempt_id, fact_kind, evidence_digest)
    references public.record_notification_delivery_facts(attempt_id, fact_kind, evidence_digest) on delete restrict,
  check ((attempt_id is null and fact_kind is null and evidence_digest is null and request_evidence_digest is null)
      or (attempt_id is not null and fact_kind is not null and evidence_digest is not null and octet_length(evidence_digest) = 32)),
  check ((disposition = 'retry' and retry_after_us > 0 and next_attempt_at is not null)
      or (disposition <> 'retry' and retry_after_us = 0 and next_attempt_at is null))
);
create index record_notification_delivery_completions_record_idx
  on public.record_notification_delivery_completions(project_id, record_id, delivery_id, attempt_no);

-- A handoff for every start and every predecessor attempt/processing projection
-- without a start, plus an explicitly proven never-started queue observation.
-- None of these legacy observations creates a sender, start or capability.
create table public.record_notification_delivery_handoffs (
  operation_id text not null,
  delivery_id text not null,
  attempt_no integer not null check (attempt_no between 1 and 8),
  project_id text not null check (project_id = 'default'),
  record_id text not null,
  notification_id text not null,
  record_fence_epoch bigint not null check (record_fence_epoch >= 0),
  attempt_id text references public.record_notification_delivery_starts(attempt_id) on delete restrict,
  start_correlation_digest bytea,
  legacy_observation_digest bytea,
  legacy_observation bytea check (legacy_observation is null or octet_length(legacy_observation) between 1 and 8192),
  legacy_outbox_row_id bigint check (legacy_outbox_row_id is null or legacy_outbox_row_id>0),
  legacy_observation_kind text check (legacy_observation_kind is null or legacy_observation_kind in ('predecessor','not_started')),
  observed_status text not null check (observed_status in ('sent','not_sent','possible_external')),
  observed_at timestamptz not null,
  primary key (operation_id, delivery_id, attempt_no),
  check ((attempt_id is not null and start_correlation_digest is not null and octet_length(start_correlation_digest) = 32
        and legacy_observation_digest is null and legacy_observation is null and legacy_outbox_row_id is null and legacy_observation_kind is null)
      or (attempt_id is null and start_correlation_digest is null and legacy_observation_digest is not null
        and octet_length(legacy_observation_digest) = 32 and legacy_observation is not null and legacy_observation_kind is not null
        and sha256(legacy_observation)=legacy_observation_digest
        and (legacy_observation_kind<>'not_started' or (observed_status='not_sent' and legacy_outbox_row_id is not null))))
);
create index record_notification_delivery_handoffs_record_idx
  on public.record_notification_delivery_handoffs(project_id, record_id, delivery_id, attempt_no);

create function record_platform_internal.record_delivery_retained_immutable()
returns trigger language plpgsql security definer set search_path = pg_catalog as $$
begin
  raise exception using errcode='55000', message='retained delivery evidence is immutable';
end $$;
create trigger record_notification_delivery_starts_immutable before update or delete or truncate
  on public.record_notification_delivery_starts for each statement execute function record_platform_internal.record_delivery_retained_immutable();
create trigger record_notification_delivery_facts_immutable before update or delete or truncate
  on public.record_notification_delivery_facts for each statement execute function record_platform_internal.record_delivery_retained_immutable();
create trigger record_notification_delivery_completions_immutable before update or delete or truncate
  on public.record_notification_delivery_completions for each statement execute function record_platform_internal.record_delivery_retained_immutable();
create trigger record_notification_delivery_handoffs_immutable before update or delete or truncate
  on public.record_notification_delivery_handoffs for each statement execute function record_platform_internal.record_delivery_retained_immutable();
revoke all on public.record_notification_delivery_starts, public.record_notification_delivery_facts,
  public.record_notification_delivery_completions, public.record_notification_delivery_handoffs from public;
revoke all on function record_platform_internal.record_delivery_retained_immutable() from public;

create function record_platform_internal.record_external_delivery_command(bytea, text)
returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare
  raw json; v jsonb; n bigint; attempt_no bigint; f text[] := array[
    'outbox_row_id','owner_id','owner_generation','owner_expires_at','event_expires_at',
    'project_id','event_kind','subject_kind','delivery_id','record_id','notification_id',
    'recipient_user_id','channel','binding_id','source_version','authorization_epoch','record_fence_epoch'];
  numeric_fields constant text[] := array['outbox_row_id','owner_generation','source_version',
    'authorization_epoch','record_fence_epoch','expected_attempt_count','attempt_no','retry_after_us'];
begin
  case $2
    when 'start' then f:=f||array['expected_state','expected_attempt_count'];
    when 'cancel' then f:=f||array['expected_state','expected_attempt_count','reason'];
    when 'report' then f:=f||array['attempt_no','started_at','attempt_id','reporting_capability','outcome'];
    when 'finalize' then f:=f||array['attempt_no','started_at','attempt_id','evidence_digest','retry_after_us'];
    when 'reconcile' then f:=f||array['attempt_no','started_at','attempt_id','retry_after_us'];
    else raise exception using errcode='22023',message='invalid delivery command kind';
  end case;
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode='22023',message='invalid delivery command size';
  end if;
  begin raw:=convert_from($1,'UTF8')::json;
  exception when data_exception then raise exception using errcode='22023',message='invalid delivery command json'; end;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw)) <> cardinality(f)
    or (select count(distinct x.key) from json_each(raw) x) <> cardinality(f)
    or exists(select 1 from json_each(raw) x where not (x.key=any(f)) or
      case when x.key=any(numeric_fields) then case
        when json_typeof(x.value)<>'number' or x.value::text !~ '^(0|[1-9][0-9]*)$' then true
        else x.value::text::numeric>9223372036854775807::numeric end
      else json_typeof(x.value)<>'string' end) then
    raise exception using errcode='22023',message='invalid delivery command fields';
  end if;
  v:=raw::jsonb;
  if $2 in ('start','cancel') then
    n:=(v->>'expected_attempt_count')::bigint;
    if n>7 or v->>'expected_state' not in ('pending','retry_wait') then
      raise exception using errcode='22023',message='invalid delivery expected state'; end if;
    attempt_no:=n+1;
  else attempt_no:=(v->>'attempt_no')::bigint; end if;
  if (v->>'outbox_row_id')::bigint<=0 or (v->>'owner_generation')::bigint<=0
    or (v->>'source_version')::bigint<=0 or (v->>'authorization_epoch')::bigint<=0
    or attempt_no not between 1 and 8 or coalesce((v->>'retry_after_us')::bigint,0)>9223372036854775
    or v->>'project_id'<>'default' or v->>'event_kind'<>'record_notification_delivery'
    or v->>'subject_kind'<>'delivery' or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'delivery_id' !~ '^rnd_[a-z0-9]{1,64}$'
    or v->>'notification_id' !~ '^rnt_[0-9a-f]{64}$'
    or v->>'recipient_user_id' !~ '^usr_[a-z0-9]{1,64}$'
    or v->>'channel' not in ('telegram','feishu') or v->>'binding_id' !~ '^[a-z0-9_-]{1,128}$'
    or ($2='cancel' and v->>'reason' not in ('authorization_revoked','source_stale','binding_unbound','binding_invalid'))
    or ($2='report' and (v->>'reporting_capability' !~ '^[0-9a-f]{64}$'
      or v->>'outcome' not in ('sent','temporary_failure','permanent_failure','unknown_outcome')))
    or ($2='finalize' and v->>'evidence_digest' !~ '^[0-9a-f]{64}$')
    or exists(select 1 from jsonb_each_text(v) x where x.key in ('owner_expires_at','event_expires_at','started_at')
      and x.value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{0,5}[1-9])?Z$') then
    raise exception using errcode='22023',message='invalid delivery command identity';
  end if;
  begin
    perform (v->>'owner_expires_at')::timestamptz, (v->>'event_expires_at')::timestamptz;
    if $2 not in ('start','cancel') then perform (v->>'started_at')::timestamptz; end if;
  exception when data_exception then raise exception using errcode='22023',message='invalid delivery timestamp'; end;
  if $2 not in ('start','cancel') and v->>'attempt_id' is distinct from
    ('rna_'||encode(record_platform_internal.digest(
      record_platform_internal.source_retirement_field(convert_to('houfeng.record-collaboration.notification-delivery-attempt.v1','UTF8'))||
      record_platform_internal.source_retirement_field(convert_to(v->>'delivery_id','UTF8'))||int8send(attempt_no),'sha256'),'hex')) then
    raise exception using errcode='22023',message='invalid delivery attempt id';
  end if;
  return v;
end $$;

-- The canonical digest is independent of database timezone, JSON ordering,
-- and the capability. All text fields are length-prefixed, numeric fields
-- are signed int8 big-endian, and timestamps are Unix microseconds.
create function record_platform_internal.record_external_delivery_correlation(jsonb, bigint, timestamptz)
returns bytea language sql immutable strict set search_path=pg_catalog as $$
  select record_platform_internal.digest(
    record_platform_internal.source_retirement_field(convert_to('houfeng.external-delivery.start.v1','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'project_id','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'record_id','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'delivery_id','UTF8'))||int8send($2)||
    record_platform_internal.source_retirement_field(convert_to($1->>'notification_id','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'recipient_user_id','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'channel','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($1->>'binding_id','UTF8'))||
    int8send(($1->>'source_version')::bigint)||int8send(($1->>'authorization_epoch')::bigint)||
    int8send(($1->>'record_fence_epoch')::bigint)||int8send((extract(epoch from $3)*1000000)::bigint)||
    int8send(($1->>'outbox_row_id')::bigint)||
    record_platform_internal.source_retirement_field(convert_to($1->>'owner_id','UTF8'))||
    int8send(($1->>'owner_generation')::bigint)||
    int8send((extract(epoch from ($1->>'owner_expires_at')::timestamptz)*1000000)::bigint)||
    int8send((extract(epoch from ($1->>'event_expires_at')::timestamptz)*1000000)::bigint),'sha256')
$$;
create function record_platform_internal.record_external_delivery_fact_digest(bytea,text,text,text)
returns bytea language sql immutable strict set search_path=pg_catalog as $$
  select record_platform_internal.digest(
    record_platform_internal.source_retirement_field(convert_to('houfeng.external-delivery.fact.v1','UTF8'))||
    record_platform_internal.source_retirement_field($1)||
    record_platform_internal.source_retirement_field(convert_to($2,'UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($3,'UTF8'))||
    record_platform_internal.source_retirement_field(convert_to($4,'UTF8')),'sha256')
$$;
revoke all on function record_platform_internal.record_external_delivery_command(bytea,text),
  record_platform_internal.record_external_delivery_correlation(jsonb,bigint,timestamptz),
  record_platform_internal.record_external_delivery_fact_digest(bytea,text,text,text) from public;

create table record_platform_internal.record_external_delivery_commit_checks (
  transaction_id xid8 not null,
  backend_pid integer not null,
  outbox_row_id bigint not null,
  phase text not null check (phase in ('start','cancel','finish','retry_closed')),
  project_id text not null,
  event_kind text not null,
  subject_kind text not null,
  delivery_id text not null,
  record_id text not null,
  notification_id text not null,
  recipient_user_id text not null,
  channel text not null,
  binding_id text not null,
  source_version bigint not null,
  authorization_epoch bigint not null,
  record_fence_epoch bigint not null,
  owner_id text not null,
  owner_generation bigint not null,
  owner_expires_at timestamptz not null,
  event_expires_at timestamptz not null,
  attempt_no bigint not null,
  started_at timestamptz not null,
  primary key(transaction_id,backend_pid,outbox_row_id)
);
revoke all on table record_platform_internal.record_external_delivery_commit_checks from public;

create function record_platform_internal.record_external_delivery_commit_trigger()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare o public.record_outbox; c public.record_notification_delivery_completions;
begin
  if new.transaction_id<>pg_current_xact_id() or new.backend_pid<>pg_backend_pid()
    or new.owner_expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  select x.* into o from public.record_outbox x where x.outbox_row_id=new.outbox_row_id for update;
  if not found or row(o.project_id,o.event_kind,o.subject_kind,o.subject_id,o.source_version,o.authorization_epoch,
      o.record_fence_epoch,o.owner_generation,o.expires_at) is distinct from
    row(new.project_id,new.event_kind,new.subject_kind,new.delivery_id,new.source_version,new.authorization_epoch,
      new.record_fence_epoch,new.owner_generation,new.event_expires_at)
    or (o.record_id is not null and o.record_id<>new.record_id) then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  if new.phase in ('start','cancel') then
    if o.status<>'processing' or o.owner_id<>new.owner_id or o.owner_expires_at is distinct from new.owner_expires_at
      or o.expires_at<=clock_timestamp() or not exists(select 1 from public.record_notification_deliveries d
        where d.delivery_id=new.delivery_id and d.record_id=new.record_id and d.notification_id=new.notification_id
          and d.recipient_user_id=new.recipient_user_id and d.channel=new.channel and d.binding_id=new.binding_id
          and d.authorization_epoch=new.authorization_epoch and d.record_fence_epoch=new.record_fence_epoch
          and d.attempt_count=new.attempt_no and d.delivery_state=case when new.phase='start' then 'processing' else 'cancelled' end)
      then raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    if new.phase='start' then
      if not exists(select 1 from public.record_notification_delivery_starts s where s.delivery_id=new.delivery_id
        and s.attempt_no=new.attempt_no and s.record_id=new.record_id and s.notification_id=new.notification_id
        and s.recipient_user_id=new.recipient_user_id and s.channel=new.channel and s.binding_id=new.binding_id
        and s.source_version=new.source_version and s.authorization_epoch=new.authorization_epoch
        and s.record_fence_epoch=new.record_fence_epoch and s.started_at=new.started_at and s.outbox_row_id=new.outbox_row_id
        and s.owner_id=new.owner_id and s.owner_generation=new.owner_generation and s.owner_expires_at=new.owner_expires_at
        and s.event_expires_at=new.event_expires_at) then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    else
      if not exists(select 1 from public.record_notification_delivery_attempts a where a.delivery_id=new.delivery_id
        and a.attempt_no=new.attempt_no and a.record_id=new.record_id and a.notification_id=new.notification_id
        and a.recipient_user_id=new.recipient_user_id and a.authorization_epoch=new.authorization_epoch
        and a.record_fence_epoch=new.record_fence_epoch and a.started_at=new.started_at and a.outcome='cancelled') then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    end if;
  elsif new.phase='retry_closed' then
    if o.status<>'sent' or o.owner_id<>'' or o.owner_expires_at is not null
      or not exists(select 1 from public.record_notification_deliveries d
        where d.delivery_id=new.delivery_id and d.record_id=new.record_id and d.notification_id=new.notification_id
          and d.recipient_user_id=new.recipient_user_id and d.channel=new.channel and d.binding_id=new.binding_id
          and d.authorization_epoch=new.authorization_epoch and d.record_fence_epoch=new.record_fence_epoch
          and d.attempt_count=new.attempt_no and d.delivery_state='unknown_outcome'
          and d.next_attempt_at is null and d.attempt_started_at is null)
      or not exists(select 1 from public.record_notification_delivery_starts s
        join public.record_notification_delivery_completions completed on completed.attempt_id=s.attempt_id
        where s.delivery_id=new.delivery_id and s.attempt_no=new.attempt_no and s.started_at=new.started_at
          and s.outbox_row_id=new.outbox_row_id and completed.disposition='retry')
      or not exists(select 1 from public.record_notification_delivery_starts s
        join public.record_notification_delivery_facts f on f.attempt_id=s.attempt_id
        where s.delivery_id=new.delivery_id and f.fact_kind='drain_observation') then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  else
    select x.* into c from public.record_notification_delivery_completions x
      where x.delivery_id=new.delivery_id and x.attempt_no=new.attempt_no;
    if not found or row(c.project_id,c.record_id,c.notification_id,c.recipient_user_id,c.channel,c.binding_id,
        c.source_version,c.authorization_epoch,c.record_fence_epoch,c.started_at,c.outbox_row_id,c.event_expires_at,
        c.owner_id,c.owner_generation,c.owner_expires_at) is distinct from
      row(new.project_id,new.record_id,new.notification_id,new.recipient_user_id,new.channel,new.binding_id,
        new.source_version,new.authorization_epoch,new.record_fence_epoch,new.started_at,new.outbox_row_id,new.event_expires_at,
        new.owner_id,new.owner_generation,new.owner_expires_at)
      or (c.disposition='retry' and (o.status<>'pending' or o.next_attempt_at is distinct from c.next_attempt_at
        or o.expires_at<=clock_timestamp()))
      or (c.disposition='complete' and o.status<>'sent') or (c.disposition='cancel' and o.status<>'cancelled') then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  end if;
  if new.owner_expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  delete from record_platform_internal.record_external_delivery_commit_checks x
    where x.transaction_id=new.transaction_id and x.backend_pid=new.backend_pid and x.outbox_row_id=new.outbox_row_id;
  return null;
end $$;
create constraint trigger record_external_delivery_commit_check
  after insert on record_platform_internal.record_external_delivery_commit_checks
  deferrable initially deferred for each row execute function record_platform_internal.record_external_delivery_commit_trigger();

create function record_platform_internal.record_external_delivery_queue_commit_check(jsonb,text,bigint,timestamptz)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v alias for $1; phase_arg alias for $2; a alias for $3; started alias for $4;
begin
  if phase_arg not in ('start','cancel','finish','retry_closed') or a not between 1 and 8 or started is null then
    raise exception using errcode='22023',message='invalid delivery commit assertion'; end if;
  insert into record_platform_internal.record_external_delivery_commit_checks(transaction_id,backend_pid,outbox_row_id,phase,
    project_id,event_kind,subject_kind,delivery_id,record_id,notification_id,recipient_user_id,channel,binding_id,
    source_version,authorization_epoch,record_fence_epoch,owner_id,owner_generation,owner_expires_at,event_expires_at,attempt_no,started_at)
  values(pg_current_xact_id(),pg_backend_pid(),(v->>'outbox_row_id')::bigint,phase_arg,
    v->>'project_id',v->>'event_kind',v->>'subject_kind',v->>'delivery_id',v->>'record_id',v->>'notification_id',
    v->>'recipient_user_id',v->>'channel',v->>'binding_id',(v->>'source_version')::bigint,
    (v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,v->>'owner_id',
    (v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz,(v->>'event_expires_at')::timestamptz,a,started)
  on conflict on constraint record_external_delivery_commit_checks_pkey do nothing;
  if not exists(select 1 from record_platform_internal.record_external_delivery_commit_checks x
    where x.transaction_id=pg_current_xact_id() and x.backend_pid=pg_backend_pid()
      and x.outbox_row_id=(v->>'outbox_row_id')::bigint and x.phase=phase_arg
      and row(x.project_id,x.event_kind,x.subject_kind,x.delivery_id,x.record_id,x.notification_id,x.recipient_user_id,
        x.channel,x.binding_id,x.source_version,x.authorization_epoch,x.record_fence_epoch,x.owner_id,x.owner_generation,
        x.owner_expires_at,x.event_expires_at,x.attempt_no,x.started_at) is not distinct from
      row(v->>'project_id',v->>'event_kind',v->>'subject_kind',v->>'delivery_id',v->>'record_id',v->>'notification_id',
        v->>'recipient_user_id',v->>'channel',v->>'binding_id',(v->>'source_version')::bigint,
        (v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,v->>'owner_id',
        (v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz,(v->>'event_expires_at')::timestamptz,a,started)) then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
end $$;
revoke all on function record_platform_internal.record_external_delivery_commit_trigger(),
  record_platform_internal.record_external_delivery_queue_commit_check(jsonb,text,bigint,timestamptz) from public;

-- Lock prefix shared with the current 0081 transition. Missing epoch is
-- accepted only for a matching V2 gate/reservation; that scope is blocked,
-- never open for a start or retry.
create function record_platform_internal.record_external_delivery_scope(jsonb,boolean)
returns boolean language plpgsql security definer set search_path=pg_catalog as $$
declare v alias for $1; ids text[]:='{}'; rid text; epoch bigint; lease_expiry timestamptz;
  gate public.record_deletion_gates; blocked boolean:=false; root_found boolean;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='external delivery requires read committed isolation'; end if;
  perform public.source_application_admit();
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform record_platform_internal.record_comparison_writer_fence();
  begin
    if $2 then
      perform 1 from public.users u where u.user_id=v->>'recipient_user_id' and u.disabled_at is null for share nowait;
      if not found then raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    end if;
    for rid in select r.reservation_id from public.deletion_reservations r
      where r.project_id='default' and r.object_kind='record' and r.object_id=v->>'record_id'
      order by r.reservation_id collate "C" for update nowait loop ids:=array_append(ids,rid); end loop;
    select e.delivery_epoch into epoch from public.content_delivery_epochs e
      where e.project_id='default' and e.object_kind='record' and e.object_id=v->>'record_id' for update nowait;
    if exists(select 1 from public.deletion_reservations r where r.project_id='default'
      and r.object_kind='record' and r.object_id=v->>'record_id' and not (r.reservation_id=any(ids))) then
      raise exception using errcode='40001',message='external delivery route changed; restart transaction'; end if;
    select l.expires_at into lease_expiry from public.deletion_fence_leases l where l.project_id='default'
      and l.object_kind='record' and l.object_id=v->>'record_id' for update nowait;
    perform 1 from public.object_content_leases l where l.project_id='default'
      and l.object_kind='record' and l.object_id=v->>'record_id' for update nowait;
    select g.* into gate from public.record_deletion_gates g where g.project_id='default'
      and g.record_id=v->>'record_id' for share nowait;
    blocked:=found or coalesce(lease_expiry>clock_timestamp(),false) or exists(
      select 1 from public.deletion_reservations r where r.project_id='default' and r.object_kind='record'
        and r.object_id=v->>'record_id' and r.state in ('fenced','committed'));
    if epoch is null then
      if gate.operation_id is null or gate.fence_epoch<(v->>'record_fence_epoch')::bigint or not exists(
        select 1 from public.record_purge_operations o join public.deletion_reservations r on r.reservation_id=o.reservation_id
        where o.operation_id=gate.operation_id and o.deletion_contract_version=2 and o.project_id=gate.project_id
          and r.deletion_contract_version=2 and r.project_id=gate.project_id and r.object_kind='record'
          and r.object_id=gate.record_id and r.fence_epoch=gate.fence_epoch and r.state in ('fenced','committed')) then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
      blocked:=true;
    elsif epoch<(v->>'record_fence_epoch')::bigint then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable';
    elsif epoch<>(v->>'record_fence_epoch')::bigint then blocked:=true; end if;
    perform 1 from public.records r where r.project_id='default' and r.record_id=v->>'record_id'
      and (not $2 or (r.current_revision_id is not null and r.authorization_epoch=(v->>'authorization_epoch')::bigint))
      for update nowait;
    root_found:=found;
    if $2 and (blocked or not root_found) then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  exception when lock_not_available then
    raise exception using errcode='40001',message='external delivery route changed; restart transaction';
  end;
  return blocked;
end $$;

-- Private common row check; the caller already acquired the route prefix and
-- holds the returned outbox lock through its entire transaction.
create function record_platform_internal.record_external_delivery_lock_claim(jsonb)
returns public.record_outbox language plpgsql security definer set search_path=pg_catalog as $$
declare v alias for $1; o public.record_outbox;
begin
  select x.* into o from public.record_outbox x where x.outbox_row_id=(v->>'outbox_row_id')::bigint for update;
  if not found or o.project_id<>v->>'project_id' or o.event_kind<>v->>'event_kind'
    or o.subject_kind<>v->>'subject_kind' or o.subject_id<>v->>'delivery_id'
    or (o.record_id is not null and o.record_id<>v->>'record_id')
    or o.source_version<>(v->>'source_version')::bigint or o.authorization_epoch<>(v->>'authorization_epoch')::bigint
    or o.record_fence_epoch<>(v->>'record_fence_epoch')::bigint
    or o.expires_at<>(v->>'event_expires_at')::timestamptz
    or o.owner_generation<>(v->>'owner_generation')::bigint then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  return o;
end $$;

create function record_platform_internal.record_external_delivery_begin(bytea,boolean)
returns table (attempt_no bigint, started_at timestamptz, reporting_capability bytea)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; o public.record_outbox; d public.record_notification_deliveries; a bigint;
  aid text; tick timestamptz; cap bytea; blocked boolean;
  previous public.record_notification_delivery_starts; conflicted public.record_notification_delivery_starts;
  completed public.record_notification_delivery_completions; seen bigint:=0; providers bigint; retry_fact boolean; dg bytea;
begin
  v:=record_platform_internal.record_external_delivery_command($1,case when $2 then 'start' else 'cancel' end);
  a:=(v->>'expected_attempt_count')::bigint+1;
  aid:='rna_'||encode(record_platform_internal.digest(
    record_platform_internal.source_retirement_field(convert_to('houfeng.record-collaboration.notification-delivery-attempt.v1','UTF8'))||
    record_platform_internal.source_retirement_field(convert_to(v->>'delivery_id','UTF8'))||int8send(a),'sha256'),'hex');
  blocked:=record_platform_internal.record_external_delivery_scope(v,$2);
  o:=record_platform_internal.record_external_delivery_lock_claim(v);
  if o.status<>'processing' or o.owner_id<>v->>'owner_id'
    or o.owner_expires_at is distinct from (v->>'owner_expires_at')::timestamptz
    or o.owner_expires_at<=clock_timestamp() or o.expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  select x.* into d from public.record_notification_deliveries x
    join public.record_notifications n on n.record_id=x.record_id and n.notification_id=x.notification_id
    where x.delivery_id=v->>'delivery_id' and x.record_id=v->>'record_id'
      and x.notification_id=v->>'notification_id' and x.recipient_user_id=v->>'recipient_user_id'
      and x.channel=v->>'channel' and x.binding_id=v->>'binding_id'
      and x.authorization_epoch=(v->>'authorization_epoch')::bigint and x.record_fence_epoch=(v->>'record_fence_epoch')::bigint
      and n.project_id=v->>'project_id' and n.source_version=(v->>'source_version')::bigint
      and x.delivery_state=v->>'expected_state' and x.attempt_count=(v->>'expected_attempt_count')::bigint
      and (x.delivery_state='pending' or x.next_attempt_at<=clock_timestamp()) for update of x;
  if not found then raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  if $2 then
    begin
      perform 1 from public.record_notification_recipients r where r.record_id=d.record_id
        and r.notification_id=d.notification_id and r.recipient_user_id=d.recipient_user_id
        and r.authorization_epoch=d.authorization_epoch and r.record_fence_epoch=d.record_fence_epoch for share nowait;
      if not found then raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    exception when lock_not_available then
      raise exception using errcode='40001',message='external delivery route changed; restart transaction'; end;
  end if;
  if $2 and d.delivery_state='retry_wait' then
    -- A late report can contradict any earlier completed retry. Serialize
    -- every retained start with reporting before granting another send.
    for previous in select x.* from public.record_notification_delivery_starts x
      where x.delivery_id=d.delivery_id order by x.attempt_no for update loop
      seen:=seen+1;
      if previous.attempt_no<>seen or previous.attempt_no>d.attempt_count
        or row(previous.project_id,previous.record_id,previous.notification_id,previous.recipient_user_id,
          previous.channel,previous.binding_id,previous.source_version,previous.authorization_epoch,
          previous.record_fence_epoch,previous.outbox_row_id,previous.event_expires_at) is distinct from
          row(v->>'project_id',d.record_id,d.notification_id,d.recipient_user_id,d.channel,d.binding_id,
            (v->>'source_version')::bigint,d.authorization_epoch,d.record_fence_epoch,o.outbox_row_id,o.expires_at) then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
      select x.* into completed from public.record_notification_delivery_completions x
        where x.delivery_id=d.delivery_id and x.attempt_no=previous.attempt_no;
      if not found or completed.attempt_id is distinct from previous.attempt_id or completed.disposition<>'retry'
        or completed.fact_kind<>'provider_report'
        or (previous.attempt_no=d.attempt_count and completed.next_attempt_at is distinct from d.next_attempt_at)
        or not exists(select 1 from public.record_notification_delivery_facts f where f.attempt_id=previous.attempt_id
          and f.fact_kind=completed.fact_kind and f.evidence_digest=completed.evidence_digest and f.outcome='temporary_failure') then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
      select count(*),coalesce(bool_and(f.outcome='temporary_failure'),false) into providers,retry_fact
        from public.record_notification_delivery_facts f where f.attempt_id=previous.attempt_id and f.fact_kind='provider_report';
      if providers<>1 or not retry_fact or exists(select 1 from public.record_notification_delivery_facts f
        where f.attempt_id=previous.attempt_id and f.fact_kind='drain_observation') then conflicted:=previous; end if;
    end loop;
    if seen<>d.attempt_count or seen=0 then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    if conflicted.attempt_id is not null then
      dg:=record_platform_internal.record_external_delivery_fact_digest(conflicted.correlation_digest,
        'drain_observation','unknown_outcome','lease_takeover_unknown');
      insert into public.record_notification_delivery_facts(attempt_id,fact_kind,evidence_digest,project_id,record_id,outcome,reason_code,reported_at)
        values(conflicted.attempt_id,'drain_observation',dg,conflicted.project_id,conflicted.record_id,
          'unknown_outcome','lease_takeover_unknown',clock_timestamp())
        on conflict on constraint record_notification_delivery_facts_pkey do nothing;
      tick:=clock_timestamp();
      update public.record_notification_deliveries set delivery_state='unknown_outcome',next_attempt_at=null,
        attempt_started_at=null,reason_code='lease_takeover_unknown',updated_at=tick where delivery_id=d.delivery_id;
      update public.record_outbox set status='sent',owner_id='',owner_expires_at=null,sent_at=tick
        where outbox_row_id=o.outbox_row_id;
      if o.owner_expires_at<=clock_timestamp() then
        raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
      perform record_platform_internal.record_external_delivery_queue_commit_check(v,'retry_closed',d.attempt_count,previous.started_at);
      -- NULL capability is an explicit terminal result, never a send permit.
      return query select d.attempt_count::bigint,previous.started_at,null::bytea;
      return;
    end if;
  end if;
  if exists(select 1 from public.record_notification_delivery_starts s where
      (s.delivery_id=d.delivery_id and s.attempt_no=a) or s.attempt_id=aid)
    or exists(select 1 from public.record_notification_delivery_attempts x where
      (x.delivery_id=d.delivery_id and x.attempt_no=a) or x.attempt_id=aid) then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  tick:=clock_timestamp();
  if o.owner_expires_at<=tick or o.expires_at<=tick then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  if $2 then
    cap:=record_platform_internal.gen_random_bytes(32);
    insert into public.record_notification_delivery_starts(delivery_id,attempt_no,attempt_id,project_id,record_id,
      notification_id,recipient_user_id,channel,binding_id,source_version,authorization_epoch,record_fence_epoch,
      started_at,outbox_row_id,owner_id,owner_generation,owner_expires_at,event_expires_at,correlation_digest,reporting_capability_hash)
    values(d.delivery_id,a,aid,'default',d.record_id,d.notification_id,d.recipient_user_id,d.channel,d.binding_id,
      (v->>'source_version')::bigint,d.authorization_epoch,d.record_fence_epoch,tick,o.outbox_row_id,o.owner_id,
      o.owner_generation,o.owner_expires_at,o.expires_at,record_platform_internal.record_external_delivery_correlation(v,a,tick),
      record_platform_internal.digest(cap,'sha256'));
    update public.record_notification_deliveries set delivery_state='processing',attempt_count=a,attempt_started_at=tick,
      next_attempt_at=null,reason_code='',updated_at=tick where delivery_id=d.delivery_id;
  else
    insert into public.record_notification_delivery_attempts(attempt_id,record_id,delivery_id,notification_id,
      recipient_user_id,attempt_no,outcome,reason_code,authorization_epoch,record_fence_epoch,started_at,completed_at)
    values(aid,d.record_id,d.delivery_id,d.notification_id,d.recipient_user_id,a,'cancelled',v->>'reason',
      d.authorization_epoch,d.record_fence_epoch,tick,tick);
    update public.record_notification_deliveries set delivery_state='cancelled',attempt_count=a,attempt_started_at=null,
      next_attempt_at=null,reason_code=v->>'reason',cancelled_at=tick,updated_at=tick where delivery_id=d.delivery_id;
  end if;
  if o.owner_expires_at<=clock_timestamp() or o.expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  perform record_platform_internal.record_external_delivery_queue_commit_check(v,case when $2 then 'start' else 'cancel' end,a,tick);
  return query select a,tick,cap;
end $$;

create function public.record_external_delivery_start(bytea)
returns table(attempt_no bigint,started_at timestamptz,reporting_capability bytea)
language sql security definer set search_path=pg_catalog as $$
  select * from record_platform_internal.record_external_delivery_begin($1,true)
$$;
create function public.record_external_delivery_cancel(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin perform 1 from record_platform_internal.record_external_delivery_begin($1,false); end $$;

-- Reporting has no queue-owner, live delivery, epoch, notification or root
-- dependency. The start lock serializes this append with drain/reconcile.
create function public.record_external_delivery_outcome(bytea)
returns table(attempt_id text,evidence_digest bytea)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; s public.record_notification_delivery_starts; dg bytea; reason text;
begin
  v:=record_platform_internal.record_external_delivery_command($1,'report');
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='external delivery report requires read committed isolation'; end if;
  perform public.source_application_admit();
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform record_platform_internal.record_comparison_writer_fence();
  select x.* into s from public.record_notification_delivery_starts x where x.attempt_id=v->>'attempt_id' for update;
  if not found or s.reporting_capability_hash is null
    or s.reporting_capability_hash is distinct from record_platform_internal.digest(decode(v->>'reporting_capability','hex'),'sha256')
    or row(s.delivery_id,s.attempt_no,s.project_id,s.record_id,s.notification_id,s.recipient_user_id,s.channel,s.binding_id,
      s.source_version,s.authorization_epoch,s.record_fence_epoch,s.started_at,s.outbox_row_id,s.owner_id,s.owner_generation,
      s.owner_expires_at,s.event_expires_at) is distinct from
      row(v->>'delivery_id',(v->>'attempt_no')::integer,v->>'project_id',v->>'record_id',v->>'notification_id',
        v->>'recipient_user_id',v->>'channel',v->>'binding_id',(v->>'source_version')::bigint,
        (v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,(v->>'started_at')::timestamptz,
        (v->>'outbox_row_id')::bigint,v->>'owner_id',(v->>'owner_generation')::bigint,
        (v->>'owner_expires_at')::timestamptz,(v->>'event_expires_at')::timestamptz)
    or s.correlation_digest is distinct from record_platform_internal.record_external_delivery_correlation(v,s.attempt_no,s.started_at) then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  reason:=case v->>'outcome' when 'sent' then 'provider_sent' when 'temporary_failure' then 'provider_temporary_failure'
    when 'permanent_failure' then 'provider_permanent_failure' else 'provider_unknown_outcome' end;
  dg:=record_platform_internal.record_external_delivery_fact_digest(s.correlation_digest,'provider_report',v->>'outcome',reason);
  insert into public.record_notification_delivery_facts(attempt_id,fact_kind,evidence_digest,project_id,record_id,outcome,reason_code,reported_at)
  values(s.attempt_id,'provider_report',dg,s.project_id,s.record_id,v->>'outcome',reason,clock_timestamp())
  on conflict on constraint record_notification_delivery_facts_pkey do nothing;
  if not exists(select 1 from public.record_notification_delivery_facts f where f.attempt_id=s.attempt_id
      and f.fact_kind='provider_report' and f.evidence_digest=dg and f.project_id=s.project_id and f.record_id=s.record_id
      and f.outcome=v->>'outcome' and f.reason_code=reason) then
    raise exception using errcode='55000',message='external delivery fact conflict'; end if;
  return query select s.attempt_id,dg;
end $$;

-- One operation handles the common locking and projection rules; its boolean
-- is private and only the two named public commands select it.
create function record_platform_internal.record_external_delivery_finish(bytea,boolean)
returns table(disposition text,retry_after_us bigint,next_attempt_at timestamptz)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; o public.record_outbox; d public.record_notification_deliveries;
  s public.record_notification_delivery_starts; c public.record_notification_delivery_completions;
  f public.record_notification_delivery_facts; fc bigint; requested bytea; dg bytea;
  a bigint; tick timestamptz; due timestamptz; delay_us bigint; result_delay bigint:=0;
  result_disposition text:='complete'; queue_status text:='sent'; state text;
  attempt_outcome text; attempt_reason text:=''; delivery_reason text:=''; blocked boolean; has_start boolean;
begin
  v:=record_platform_internal.record_external_delivery_command($1,case when $2 then 'reconcile' else 'finalize' end);
  a:=(v->>'attempt_no')::bigint;
  delay_us:=(v->>'retry_after_us')::bigint;
  if not $2 then requested:=decode(v->>'evidence_digest','hex'); end if;
  blocked:=record_platform_internal.record_external_delivery_scope(v,false);
  o:=record_platform_internal.record_external_delivery_lock_claim(v);
  if (v->>'owner_expires_at')::timestamptz<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;

  select x.* into c from public.record_notification_delivery_completions x
    where x.delivery_id=v->>'delivery_id' and x.attempt_no=a;
  if found then
    if row(c.project_id,c.record_id,c.notification_id,c.recipient_user_id,c.channel,c.binding_id,c.source_version,
        c.authorization_epoch,c.record_fence_epoch,c.started_at,c.outbox_row_id,c.event_expires_at,
        c.owner_id,c.owner_generation,c.owner_expires_at) is distinct from
      row(v->>'project_id',v->>'record_id',v->>'notification_id',v->>'recipient_user_id',v->>'channel',v->>'binding_id',
        (v->>'source_version')::bigint,(v->>'authorization_epoch')::bigint,(v->>'record_fence_epoch')::bigint,
        (v->>'started_at')::timestamptz,(v->>'outbox_row_id')::bigint,(v->>'event_expires_at')::timestamptz,
        v->>'owner_id',(v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz)
      or (not $2 and (c.attempt_id is distinct from v->>'attempt_id'
        or requested is distinct from coalesce(c.request_evidence_digest,c.evidence_digest))) then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    if c.attempt_id is not null and not exists(select 1 from public.record_notification_delivery_starts x
      where x.attempt_id=c.attempt_id and x.delivery_id=c.delivery_id and x.attempt_no=c.attempt_no
        and x.record_id=v->>'record_id' and x.notification_id=v->>'notification_id'
        and x.recipient_user_id=v->>'recipient_user_id' and x.channel=v->>'channel' and x.binding_id=v->>'binding_id'
        and x.source_version=(v->>'source_version')::bigint and x.authorization_epoch=(v->>'authorization_epoch')::bigint
        and x.record_fence_epoch=(v->>'record_fence_epoch')::bigint and x.started_at=(v->>'started_at')::timestamptz) then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    if c.owner_expires_at<=clock_timestamp()
      or (c.disposition='retry' and (o.status<>'pending' or o.next_attempt_at is distinct from c.next_attempt_at))
      or (c.disposition='complete' and o.status<>'sent') or (c.disposition='cancel' and o.status<>'cancelled') then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    return query select c.disposition,c.retry_after_us,c.next_attempt_at;
    return;
  end if;
  if o.status<>'processing' or o.owner_id<>v->>'owner_id'
    or o.owner_expires_at is distinct from (v->>'owner_expires_at')::timestamptz
    or o.owner_expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  select x.* into d from public.record_notification_deliveries x
    join public.record_notifications n on n.record_id=x.record_id and n.notification_id=x.notification_id
    where x.delivery_id=v->>'delivery_id' and x.record_id=v->>'record_id'
      and x.notification_id=v->>'notification_id' and x.recipient_user_id=v->>'recipient_user_id'
      and x.channel=v->>'channel' and x.binding_id=v->>'binding_id'
      and x.authorization_epoch=(v->>'authorization_epoch')::bigint and x.record_fence_epoch=(v->>'record_fence_epoch')::bigint
      and n.project_id=v->>'project_id' and n.source_version=(v->>'source_version')::bigint
      and x.delivery_state='processing' and x.attempt_count=a and x.attempt_started_at=(v->>'started_at')::timestamptz
    for update of x;
  if not found then raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  select x.* into s from public.record_notification_delivery_starts x
    where x.delivery_id=d.delivery_id and x.attempt_no=a for update;
  has_start:=found;
  if has_start and (s.attempt_id<>v->>'attempt_id' or s.record_id<>d.record_id or s.notification_id<>d.notification_id
    or s.recipient_user_id<>d.recipient_user_id or s.channel<>d.channel or s.binding_id<>d.binding_id
    or s.source_version<>(v->>'source_version')::bigint or s.authorization_epoch<>d.authorization_epoch
    or s.record_fence_epoch<>d.record_fence_epoch or s.started_at<>(v->>'started_at')::timestamptz
    or s.outbox_row_id<>o.outbox_row_id or s.event_expires_at<>o.expires_at) then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  if not has_start and not $2 then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  if exists(select 1 from public.record_notification_delivery_attempts x
      where (x.delivery_id=d.delivery_id and x.attempt_no=a) or x.attempt_id=v->>'attempt_id') then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;

  if has_start then
    if not $2 and not exists(select 1 from public.record_notification_delivery_facts x
      where x.attempt_id=s.attempt_id and x.fact_kind='provider_report' and x.evidence_digest=requested) then
      raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
    select count(*) into fc from public.record_notification_delivery_facts x
      where x.attempt_id=s.attempt_id and x.fact_kind='provider_report';
    select x.* into f from public.record_notification_delivery_facts x
      where x.attempt_id=s.attempt_id and x.fact_kind='drain_observation'
      order by x.reported_at,x.evidence_digest limit 1;
    if not found and fc=1 then
      select x.* into strict f from public.record_notification_delivery_facts x
        where x.attempt_id=s.attempt_id and x.fact_kind='provider_report';
    elsif not found then
      dg:=record_platform_internal.record_external_delivery_fact_digest(s.correlation_digest,
        'drain_observation','unknown_outcome','lease_takeover_unknown');
      insert into public.record_notification_delivery_facts(attempt_id,fact_kind,evidence_digest,project_id,record_id,outcome,reason_code,reported_at)
        values(s.attempt_id,'drain_observation',dg,s.project_id,s.record_id,'unknown_outcome','lease_takeover_unknown',clock_timestamp())
        on conflict on constraint record_notification_delivery_facts_pkey do nothing;
      select x.* into strict f from public.record_notification_delivery_facts x
        where x.attempt_id=s.attempt_id and x.fact_kind='drain_observation' and x.evidence_digest=dg;
    end if;
    attempt_outcome:=f.outcome;
    if $2 and f.fact_kind='provider_report' then requested:=f.evidence_digest; end if;
  else
    attempt_outcome:='unknown_outcome';
  end if;
  tick:=clock_timestamp();
  if o.owner_expires_at<=tick or (v->>'started_at')::timestamptz>tick then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  case attempt_outcome
    when 'sent' then state:='sent';
    when 'permanent_failure' then state:='permanent_failure';
      attempt_reason:='provider_permanent_failure'; delivery_reason:=attempt_reason;
    when 'unknown_outcome' then state:='unknown_outcome';
      attempt_reason:=case when has_start then f.reason_code else 'legacy_processing_unknown' end;
      delivery_reason:=attempt_reason;
    when 'temporary_failure' then
      attempt_reason:='provider_temporary_failure'; delivery_reason:=attempt_reason;
      if a=8 then state:='permanent_failure'; delivery_reason:='attempts_exhausted';
      else
        if delay_us<=0 then raise exception using errcode='22023',message='invalid delivery retry delay'; end if;
        due:=tick+make_interval(secs=>(delay_us/1000000)::double precision)+(delay_us%1000000)*interval '1 microsecond';
        if blocked or due>=o.expires_at then
          state:='cancelled'; result_disposition:='cancel'; queue_status:='cancelled';
          delivery_reason:=case when blocked then 'record_deleted' else 'event_expired' end; due:=null;
        else state:='retry_wait'; result_disposition:='retry'; result_delay:=delay_us; queue_status:='pending'; end if;
      end if;
    else raise exception using errcode='55000',message='invalid persisted delivery fact';
  end case;
  insert into public.record_notification_delivery_attempts(attempt_id,record_id,delivery_id,notification_id,
    recipient_user_id,attempt_no,outcome,reason_code,authorization_epoch,record_fence_epoch,started_at,completed_at)
  values(v->>'attempt_id',d.record_id,d.delivery_id,d.notification_id,d.recipient_user_id,a,attempt_outcome,
    attempt_reason,d.authorization_epoch,d.record_fence_epoch,(v->>'started_at')::timestamptz,tick);
  update public.record_notification_deliveries set delivery_state=state,attempt_started_at=null,next_attempt_at=due,
    reason_code=delivery_reason,sent_at=case when state='sent' then tick end,
    cancelled_at=case when state='cancelled' then tick end,updated_at=tick where delivery_id=d.delivery_id;
  update public.record_outbox as q set record_id=coalesce(q.record_id,d.record_id),status=queue_status,owner_id='',owner_expires_at=null,
    next_attempt_at=case when queue_status='pending' then due else q.next_attempt_at end,
    sent_at=case when queue_status='sent' then tick else q.sent_at end where q.outbox_row_id=o.outbox_row_id;
  insert into public.record_notification_delivery_completions(delivery_id,attempt_no,attempt_id,fact_kind,evidence_digest,
    request_evidence_digest,project_id,record_id,notification_id,recipient_user_id,channel,binding_id,source_version,
    authorization_epoch,record_fence_epoch,started_at,outbox_row_id,event_expires_at,owner_id,owner_generation,owner_expires_at,
    disposition,retry_after_us,next_attempt_at,completed_at)
  values(d.delivery_id,a,case when has_start then s.attempt_id end,case when has_start then f.fact_kind end,
    case when has_start then f.evidence_digest end,requested,'default',d.record_id,d.notification_id,d.recipient_user_id,
    d.channel,d.binding_id,(v->>'source_version')::bigint,d.authorization_epoch,d.record_fence_epoch,
    (v->>'started_at')::timestamptz,o.outbox_row_id,o.expires_at,v->>'owner_id',(v->>'owner_generation')::bigint,
    (v->>'owner_expires_at')::timestamptz,result_disposition,result_delay,due,tick);
  if o.owner_expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='external delivery outcome authority unavailable'; end if;
  perform record_platform_internal.record_external_delivery_queue_commit_check(v,'finish',a,(v->>'started_at')::timestamptz);
  return query select result_disposition,result_delay,due;
end $$;

create function public.record_external_delivery_finalize(bytea)
returns table(disposition text,retry_after_us bigint,next_attempt_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select * from record_platform_internal.record_external_delivery_finish($1,false)
$$;
create function public.record_external_delivery_reconcile(bytea)
returns table(disposition text,retry_after_us bigint,next_attempt_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select * from record_platform_internal.record_external_delivery_finish($1,true)
$$;
revoke all on function record_platform_internal.record_external_delivery_scope(jsonb,boolean),
  record_platform_internal.record_external_delivery_lock_claim(jsonb),record_platform_internal.record_external_delivery_begin(bytea,boolean),
  record_platform_internal.record_external_delivery_finish(bytea,boolean),public.record_external_delivery_start(bytea),
  public.record_external_delivery_cancel(bytea),public.record_external_delivery_outcome(bytea),
  public.record_external_delivery_finalize(bytea),public.record_external_delivery_reconcile(bytea) from public;

create function public.record_collaboration_start_inventory(text,bigint)
returns table(start_digest bytea,start_count bigint,mismatched boolean)
language plpgsql security definer set search_path=pg_catalog as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  if $1 is null or length($1) not between 1 and 128 or $2 is null or $2<0 then
    raise exception using errcode='22023',message='invalid collaboration start inventory'; end if;
  return query select sha256(convert_to(coalesce(jsonb_agg(jsonb_build_array(
      s.delivery_id,s.attempt_no,s.attempt_id,s.record_id,s.notification_id,s.recipient_user_id,s.channel,s.binding_id,
      s.source_version,s.authorization_epoch,s.record_fence_epoch,extract(epoch from s.started_at),s.outbox_row_id,
      s.owner_id,s.owner_generation,extract(epoch from s.owner_expires_at),extract(epoch from s.event_expires_at),
      encode(s.correlation_digest,'hex')) order by s.delivery_id collate "C",s.attempt_no),'[]'::jsonb)::text,'UTF8')),
    count(*)::bigint,coalesce(bool_or(s.record_fence_epoch<>$2),false)
    from public.record_notification_delivery_starts s where s.project_id='default' and s.record_id=$1;
end $$;

-- Includes orphan retained obligations. No reporting capability or hash is
-- returned or incorporated. A single conflicting/unknown attempt dominates a
-- sent attempt so each delivery appears in at most one disclosure category.
create function public.record_collaboration_delivery_inventory(text,bigint)
returns table(notification_id text,delivery_id text,classification text,evidence_digest bytea,mismatched boolean)
language plpgsql security definer set search_path=pg_catalog as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  if $1 is null or $1 !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$' or $2 is null or $2<0 then
    raise exception using errcode='22023',message='invalid collaboration delivery inventory'; end if;
  return query
  with identities as (
    select d.delivery_id,d.notification_id,d.record_fence_epoch from public.record_notification_deliveries d where d.record_id=$1
    union all select s.delivery_id,s.notification_id,s.record_fence_epoch from public.record_notification_delivery_starts s
      where s.project_id='default' and s.record_id=$1
    union all select h.delivery_id,h.notification_id,h.record_fence_epoch from public.record_notification_delivery_handoffs h
      where h.project_id='default' and h.record_id=$1
    union all select c.delivery_id,c.notification_id,c.record_fence_epoch from public.record_notification_delivery_completions c
      where c.project_id='default' and c.record_id=$1
  ), ids as (
    select i.delivery_id,min(i.notification_id) as notification_id,
      bool_or(i.record_fence_epoch<>$2) or count(distinct i.notification_id)<>1 as mismatched
      from identities i group by i.delivery_id
  ), start_state as (
    select s.delivery_id,s.attempt_no,s.attempt_id,s.correlation_digest,
      count(f.evidence_digest) filter(where f.fact_kind='provider_report') as providers,
      min(f.outcome) filter(where f.fact_kind='provider_report') as outcome
    from public.record_notification_delivery_starts s left join public.record_notification_delivery_facts f on f.attempt_id=s.attempt_id
    where s.project_id='default' and s.record_id=$1 group by s.delivery_id,s.attempt_no,s.attempt_id,s.correlation_digest
  ), start_summary as (
    select x.delivery_id,bool_or(x.providers<>1 or x.outcome='unknown_outcome') as uncertain,
      bool_or(x.providers=1 and x.outcome='sent') as sent,
      bool_or(x.providers=1 and x.outcome='permanent_failure') as permanent
    from start_state x group by x.delivery_id
  ), legacy_attempts as (
    select a.delivery_id,bool_or(a.outcome='unknown_outcome') as uncertain,
      bool_or(a.outcome='sent') as sent,bool_or(a.outcome='permanent_failure') as permanent
    from public.record_notification_delivery_attempts a where a.record_id=$1
      and not exists(select 1 from public.record_notification_delivery_starts s
        where s.delivery_id=a.delivery_id and s.attempt_no=a.attempt_no)
    group by a.delivery_id
  ), legacy_handoffs as (
    select h.delivery_id,bool_or(h.observed_status='possible_external') as uncertain,
      bool_or(h.observed_status='sent') as sent
    from public.record_notification_delivery_handoffs h where h.project_id='default' and h.record_id=$1
      and h.attempt_id is null group by h.delivery_id
  ), legacy_completions as (
    select c.delivery_id,true as uncertain from public.record_notification_delivery_completions c
      where c.project_id='default' and c.record_id=$1 and c.attempt_id is null group by c.delivery_id
  )
  select i.notification_id,i.delivery_id,
    case when coalesce(ss.uncertain,false) or coalesce(la.uncertain,false) or coalesce(lh.uncertain,false)
        or coalesce(lc.uncertain,false) or (d.delivery_state in ('processing','unknown_outcome')
          and not exists(select 1 from public.record_notification_delivery_starts s where s.delivery_id=d.delivery_id
            and s.attempt_no=d.attempt_count)) then 'possible_external'
      when coalesce(ss.sent,false) or coalesce(la.sent,false) or coalesce(lh.sent,false)
        or d.delivery_state='sent' then 'sent'
      when coalesce(ss.permanent,false) or coalesce(la.permanent,false) or d.delivery_state='permanent_failure'
        then 'permanent_failure' else 'none' end,
    sha256(convert_to(jsonb_build_object(
      'delivery',coalesce((select jsonb_build_array(x.delivery_state,x.attempt_count,x.reason_code,x.record_fence_epoch,
        extract(epoch from x.attempt_started_at),extract(epoch from x.next_attempt_at))
        from public.record_notification_deliveries x where x.delivery_id=i.delivery_id and x.record_id=$1),'null'::jsonb),
      'starts',coalesce((select jsonb_agg(jsonb_build_array(x.attempt_no,encode(x.correlation_digest,'hex')) order by x.attempt_no)
        from public.record_notification_delivery_starts x where x.delivery_id=i.delivery_id and x.record_id=$1),'[]'::jsonb),
      'facts',coalesce((select jsonb_agg(jsonb_build_array(s.attempt_no,f.fact_kind,encode(f.evidence_digest,'hex'),f.outcome,f.reason_code)
          order by s.attempt_no,f.fact_kind collate "C",f.evidence_digest)
        from public.record_notification_delivery_starts s join public.record_notification_delivery_facts f on f.attempt_id=s.attempt_id
        where s.delivery_id=i.delivery_id and s.record_id=$1),'[]'::jsonb),
      'handoffs',coalesce((select jsonb_agg(jsonb_build_array(h.operation_id,h.attempt_no,h.observed_status,
          encode(h.legacy_observation_digest,'hex'),encode(h.start_correlation_digest,'hex'))
          order by h.operation_id collate "C",h.attempt_no)
        from public.record_notification_delivery_handoffs h where h.delivery_id=i.delivery_id and h.record_id=$1),'[]'::jsonb),
      'legacy_attempts',coalesce((select jsonb_agg(jsonb_build_array(a.attempt_no,a.outcome,a.reason_code)
          order by a.attempt_no) from public.record_notification_delivery_attempts a
        where a.delivery_id=i.delivery_id and a.record_id=$1 and not exists(select 1
          from public.record_notification_delivery_starts s where s.delivery_id=a.delivery_id and s.attempt_no=a.attempt_no)),'[]'::jsonb)
      )::text,'UTF8')),i.mismatched
  from ids i left join public.record_notification_deliveries d on d.delivery_id=i.delivery_id and d.record_id=$1
    left join start_summary ss on ss.delivery_id=i.delivery_id left join legacy_attempts la on la.delivery_id=i.delivery_id
    left join legacy_handoffs lh on lh.delivery_id=i.delivery_id left join legacy_completions lc on lc.delivery_id=i.delivery_id
  order by i.delivery_id collate "C";
end $$;
revoke all on function public.record_collaboration_start_inventory(text,bigint),
  public.record_collaboration_delivery_inventory(text,bigint) from public;

create function record_platform_internal.record_external_delivery_insert_guard()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare admission public.source_authority_admission; source_present boolean; ids text[]:='{}'; rid text;
  epoch bigint; lease_expiry timestamptz;
begin
  if current_setting('role')='none' and session_user=(select pg_get_userbyid(c.relowner) from pg_catalog.pg_class c
      where c.oid='public.record_notification_deliveries'::regclass)
    and exists(select 1 from pg_catalog.pg_roles r where r.rolname=session_user and r.rolcanlogin) then return new; end if;
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='delivery insert requires read committed isolation'; end if;
  if new.delivery_state<>'pending' or new.attempt_count<>0 or new.attempt_started_at is not null
    or new.next_attempt_at is not null or new.reason_code<>'' or new.sent_at is not null or new.cancelled_at is not null then
    raise exception using errcode='42501',message='delivery must be inserted pending'; end if;
  begin
    select s.* into admission from public.source_authority_admission s where s.singleton for share nowait;
    source_present:=found;
    if source_present and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=admission.generation and p.purpose in ('runtime','admin','worker'))) then
      raise exception using errcode='42501',message='source application admission is closed or stale'; end if;
    perform record_platform_internal.record_birth_launch_admit(admission);
    if not pg_try_advisory_xact_lock_shared(1213154899,1) or not pg_try_advisory_xact_lock_shared(1213154899,81)
      or source_present<>exists(select 1 from public.source_authority_admission s where s.singleton) then
      raise exception using errcode='40001',message='delivery insert admission changed; restart transaction'; end if;
    for rid in select r.reservation_id from public.deletion_reservations r where r.project_id='default'
      and r.object_kind='record' and r.object_id=new.record_id order by r.reservation_id collate "C" for update nowait
      loop ids:=array_append(ids,rid); end loop;
    select e.delivery_epoch into epoch from public.content_delivery_epochs e where e.project_id='default'
      and e.object_kind='record' and e.object_id=new.record_id for update nowait;
    if not found or epoch is distinct from new.record_fence_epoch or exists(select 1 from public.deletion_reservations r
      where r.project_id='default' and r.object_kind='record' and r.object_id=new.record_id
        and (not (r.reservation_id=any(ids)) or r.state in ('fenced','committed'))) then
      raise exception using errcode='55000',message='delivery insert record scope unavailable'; end if;
    select l.expires_at into lease_expiry from public.deletion_fence_leases l where l.project_id='default'
      and l.object_kind='record' and l.object_id=new.record_id for update nowait;
    perform 1 from public.object_content_leases l where l.project_id='default'
      and l.object_kind='record' and l.object_id=new.record_id for update nowait;
    perform 1 from public.record_deletion_gates g where g.project_id='default' and g.record_id=new.record_id for share nowait;
    if found or coalesce(lease_expiry>clock_timestamp(),false) then
      raise exception using errcode='55000',message='delivery insert record gate closed'; end if;
    perform 1 from public.records r where r.project_id='default' and r.record_id=new.record_id
      and r.current_revision_id is not null and r.authorization_epoch=new.authorization_epoch for update nowait;
    if not found then raise exception using errcode='55000',message='delivery insert record unavailable'; end if;
    perform 1 from public.record_notifications n where n.project_id='default' and n.record_id=new.record_id
      and n.notification_id=new.notification_id and n.authorization_epoch=new.authorization_epoch
      and n.record_fence_epoch=new.record_fence_epoch for share nowait;
    if not found then raise exception using errcode='55000',message='delivery insert notification route unavailable'; end if;
  exception when lock_not_available then
    raise exception using errcode='40001',message='delivery insert route changed; restart transaction'; end;
  return new;
end $$;
create trigger record_notification_delivery_insert_guard before insert on public.record_notification_deliveries
  for each row execute function record_platform_internal.record_external_delivery_insert_guard();
revoke all on function record_platform_internal.record_external_delivery_insert_guard() from public;

create function record_platform_internal.local_blob_command(bytea, text[])
returns jsonb language plpgsql immutable set search_path = pg_catalog
as $$
declare v jsonb;
begin
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode = '22023', message = 'invalid local blob command size';
  end if;
  v := convert_from($1, 'UTF8')::jsonb;
  if jsonb_typeof(v) <> 'object' or
    array(select key from jsonb_object_keys(v) as key order by key) is distinct from
    array(select key from unnest($2) as key order by key) then
    raise exception using errcode = '22023', message = 'invalid local blob command fields';
  end if;
  if exists (select 1 from jsonb_each(v) field where jsonb_typeof(field.value) not in ('string', 'number', 'null')
    or (field.value = 'null'::jsonb and field.key not in (
      'source_recovery_id','origin_owner_id','origin_owner_generation','origin_owner_expires_at',
      'draft_id','plan_digest','archive_digest','namespace_id','incarnation_id','publication_id',
      'target_record_id','target_attachment_id','anchor_inode','anchor_nonce','version',
      'cleanup_expires_at','operation_id','operation_owner_id','operation_generation','operation_expires_at',
      'expected_version','orphaned_before','preview_publication_id','preview_media_type'))) then
    raise exception using errcode = '22023', message = 'invalid local blob command field type';
  end if;
  return v;
end
$$;

create function record_platform_internal.local_blob_admission(uuid, uuid)
returns void language plpgsql security definer set search_path = pg_catalog
as $$
begin
  perform public.source_application_admit();
  perform 1 from public.local_blob_namespaces
    where namespace_id = $1 and current_incarnation_id = $2 and admission_state = 'active'
    for share;
  if not found then
    raise exception using errcode = '55000', message = 'local namespace admission is closed or stale';
  end if;
end
$$;

create function public.local_blob_namespace_provision(bytea)
returns public.local_blob_namespaces language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; n public.local_blob_namespaces; s public.source_authority_admission;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array[
    'namespace_id','incarnation_id','request_id','root_path','boot_id','device',
    'root_inode','digest_inode','locks_inode','marker_inode','owner_uid','owner_gid',
    'marker_digest','marker_nonce','source_recovery_id']);
  select * into s from public.source_authority_admission where singleton for share;
  if found and (s.mode <> 'closed' or s.recovery_id is null or s.recovery_id is distinct from v->>'source_recovery_id') then
    raise exception using errcode = '55000', message = 'source participant requires current closed recovery';
  end if;
  if s.singleton is null and v->>'source_recovery_id' is not null then
    raise exception using errcode = '55000', message = 'source recovery authority unavailable';
  end if;
  -- Serialize provisioning only; no file lock is acquired by SQL.
  lock table public.local_blob_namespaces in share row exclusive mode;
  select * into n from public.local_blob_namespaces where namespace_id = (v->>'namespace_id')::uuid;
  if found then
    if n.provision_command is distinct from $1 then
      raise exception using errcode = '55000', message = 'local namespace provision replay conflict';
    end if;
    return n;
  end if;
  insert into public.local_blob_namespaces(namespace_id, root_path, current_incarnation_id,
    admission_state, provision_request_id, provision_command, source_recovery_id)
    values ((v->>'namespace_id')::uuid, v->>'root_path', (v->>'incarnation_id')::uuid,
      'closed', (v->>'request_id')::uuid, $1, v->>'source_recovery_id') returning * into n;
  insert into public.local_blob_namespace_incarnations(namespace_id, incarnation_id, boot_id,
    filesystem_device, root_inode, digest_inode, locks_inode, marker_inode,
    owner_uid, owner_gid, marker_digest, marker_nonce)
    values (n.namespace_id, n.current_incarnation_id, (v->>'boot_id')::uuid,
      (v->>'device')::bigint, (v->>'root_inode')::bigint, (v->>'digest_inode')::bigint,
      (v->>'locks_inode')::bigint, (v->>'marker_inode')::bigint,
      (v->>'owner_uid')::bigint, (v->>'owner_gid')::bigint,
      decode(v->>'marker_digest', 'hex'), (v->>'marker_nonce')::uuid);
  return n;
end
$$;

create function public.local_blob_namespace_admit(bytea)
returns public.local_blob_namespaces language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; n public.local_blob_namespaces;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['namespace_id','incarnation_id','request_id','marker_digest']);
  -- The outer source coordinator owns its final APP/W2 readback. Until that
  -- capability is wired, a local participant can create only CLOSED bindings.
  if exists (select 1 from public.source_authority_admission) then
    raise exception using errcode = '55000', message = 'source outer local handoff capability unavailable';
  end if;
  select * into strict n from public.local_blob_namespaces where namespace_id = (v->>'namespace_id')::uuid for update;
  if n.current_incarnation_id is distinct from (v->>'incarnation_id')::uuid
    or n.provision_request_id is distinct from (v->>'request_id')::uuid or n.source_recovery_id is not null
    or not exists (select 1 from public.local_blob_namespace_incarnations i
      where i.namespace_id = n.namespace_id and i.incarnation_id = n.current_incarnation_id
        and i.marker_digest = decode(v->>'marker_digest', 'hex')) then
    raise exception using errcode = '55000', message = 'local namespace admission identity conflict';
  end if;
  if n.admission_state = 'closed' then
    update public.local_blob_namespaces set admission_state = 'active', admitted_at = clock_timestamp()
      where namespace_id = n.namespace_id returning * into n;
  end if;
  return n;
end
$$;

create function public.local_blob_anchor_register(bytea)
returns public.local_blob_key_anchors language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; a public.local_blob_key_anchors;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['namespace_id','incarnation_id','key','device','inode','nonce']);
  perform record_platform_internal.local_blob_admission((v->>'namespace_id')::uuid, (v->>'incarnation_id')::uuid);
  if not exists (select 1 from public.local_blob_namespace_incarnations i
    where i.namespace_id = (v->>'namespace_id')::uuid and i.incarnation_id = (v->>'incarnation_id')::uuid
      and i.filesystem_device = (v->>'device')::bigint) then
    raise exception using errcode = '55000', message = 'local anchor device conflict';
  end if;
  insert into public.local_blob_key_anchors(namespace_id, incarnation_id, canonical_key, filesystem_device, lock_inode, lock_nonce)
    values ((v->>'namespace_id')::uuid, (v->>'incarnation_id')::uuid, v->>'key',
      (v->>'device')::bigint, (v->>'inode')::bigint, (v->>'nonce')::uuid)
    on conflict (namespace_id, incarnation_id, canonical_key) do nothing;
  select * into strict a from public.local_blob_key_anchors
    where namespace_id = (v->>'namespace_id')::uuid and incarnation_id = (v->>'incarnation_id')::uuid and canonical_key = v->>'key';
  if row(a.filesystem_device, a.lock_inode, a.lock_nonce) is distinct from
    row((v->>'device')::bigint, (v->>'inode')::bigint, (v->>'nonce')::uuid) then
    raise exception using errcode = '55000', message = 'local anchor replay conflict';
  end if;
  return a;
end
$$;
revoke all on function record_platform_internal.local_blob_direct_login(),
  record_platform_internal.local_blob_command(bytea, text[]),
  record_platform_internal.local_blob_admission(uuid, uuid),
  public.local_blob_namespace_provision(bytea), public.local_blob_namespace_admit(bytea),
  public.local_blob_anchor_register(bytea) from public;

create function record_platform_internal.record_blob_strong_fence()
returns void language plpgsql security definer set search_path=pg_catalog
as $$
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='Blob mutation requires read committed isolation';
  end if;
  if exists(select 1 from pg_locks l where l.pid=pg_backend_pid() and l.granted
    and l.relation in ('public.blob_objects'::regclass,'public.attachment_upload_parts'::regclass)
    and l.mode<>'AccessShareLock' and not exists(select 1 from pg_locks held where held.pid=l.pid
      and held.relation=l.relation and held.granted and held.mode in ('ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock'))) then
    raise exception using errcode='55000',message='strong Blob fence must precede publication locks';
  end if;
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
end $$;
revoke all on function record_platform_internal.record_blob_strong_fence() from public;

create function record_platform_internal.local_blob_record_epoch(text)
returns bigint language plpgsql security definer set search_path = pg_catalog
as $$
declare e bigint; state text;
begin
  select r.state into state from public.deletion_reservations r
    where r.project_id = 'default' and r.object_kind = 'record' and r.object_id = $1
      and r.state in ('previewed', 'fenced', 'committed')
    order by case when r.state in ('fenced', 'committed') then 0 else 1 end, r.reservation_id
    limit 1 for update;
  if state in ('fenced', 'committed') then
    raise exception using errcode = '55000', message = 'record write gate closed';
  end if;
  insert into public.content_delivery_epochs(project_id, object_kind, object_id, delivery_epoch)
    values ('default', 'record', $1, 0) on conflict do nothing;
  select delivery_epoch into strict e from public.content_delivery_epochs
    where project_id = 'default' and object_kind = 'record' and object_id = $1 for update;
  perform 1 from public.deletion_fence_leases
    where project_id = 'default' and object_kind = 'record' and object_id = $1
      and expires_at > clock_timestamp() for update;
  if found or exists (select 1 from public.record_deletion_gates where project_id = 'default' and record_id = $1)
    or exists (select 1 from public.deletion_reservations r2 where r2.project_id = 'default'
      and r2.object_kind = 'record' and r2.object_id = $1 and r2.state in ('fenced', 'committed')) then
    raise exception using errcode = '55000', message = 'record write gate closed';
  end if;
  perform 1 from public.records where project_id = 'default' and record_id = $1 for update;
  if not found then
    raise exception using errcode = '55000', message = 'record write root unavailable';
  end if;
  return e;
end
$$;

-- Discover the route before locking it, then recheck after locking its owner.
-- Caller-supplied record/epoch values are never mutation authority.
create function record_platform_internal.record_write_origin(jsonb)
returns table(record_id text, record_epoch bigint)
language plpgsql security definer set search_path = pg_catalog
as $$
declare v alias for $1; route text; rechecked text; draft text; upload text;
  u public.attachment_uploads; j public.attachment_processor_jobs;
  ij public.record_import_jobs; ej public.record_export_jobs; birth record; binding record;
  target_ids text[]; current_targets text[]; target text;
  destination_kind text; destination_source text; admission public.source_authority_admission; source_present boolean;
begin
  if v->>'origin_kind' in ('upload', 'processor_preview') then
    if v->>'origin_kind' = 'upload' then
      upload := v->>'origin_id';
    else
      select upload_id into upload from public.attachment_processor_jobs where processor_job_id = v->>'origin_id';
      if not found then
        raise exception using errcode = '55000', message = 'processor write claim unavailable';
      end if;
    end if;
    select coalesce(a.record_id, d.record_id), u0.origin_draft_id into strict route, draft
      from public.attachment_uploads u0 join public.record_attachments a on a.attachment_id = u0.attachment_id
      left join public.record_drafts d on d.draft_id = a.draft_id where u0.upload_id = upload;
    if route is not null then record_epoch := record_platform_internal.local_blob_record_epoch(route); end if;
    if exists (select 1 from public.record_drafts where draft_id = draft) then
      perform 1 from public.record_drafts where draft_id = draft and expires_at > clock_timestamp() for update;
      if not found then raise exception using errcode = '55000', message = 'write draft expired'; end if;
    elsif route is null then
      raise exception using errcode = '55000', message = 'standalone write draft unavailable';
    end if;
    -- Reject terminal uploads without taking their row lock or waiting for the
    -- Blob fence. This is only an early rejection; the locked check below still
    -- determines mutation authority after the fence has been acquired.
    if v->>'origin_kind' = 'upload' then
      select * into strict u from public.attachment_uploads where upload_id = upload;
      if u.upload_state = 'expired' or u.expires_at <= clock_timestamp() then
        raise exception using errcode = '55000', message = 'upload write owner expired';
      end if;
      if u.upload_state not in ('created', 'uploading') then
        raise exception using errcode = '55000', message = 'upload write origin unavailable';
      end if;
    end if;
    perform record_platform_internal.local_blob_write_fence(v->>'backend_kind',(v->>'namespace_id')::uuid,v->>'key',v->>'obligation_id');
    perform 1 from public.record_attachments a0 join public.attachment_uploads u0 on u0.attachment_id = a0.attachment_id
      where u0.upload_id = upload for update of a0;
    select * into strict u from public.attachment_uploads where upload_id = upload for update;
    select coalesce(a.record_id, d.record_id) into strict rechecked from public.record_attachments a
      left join public.record_drafts d on d.draft_id = a.draft_id where a.attachment_id = u.attachment_id;
    if route is distinct from rechecked or u.origin_draft_id is distinct from v->>'draft_id'
      or u.project_id <> v->>'project_id' or u.expires_at <= clock_timestamp() then
      raise exception using errcode = '55000', message = 'write origin route changed';
    end if;
    if v->>'origin_kind' = 'upload' then
      if (v->>'origin_generation')::bigint is distinct from 1 or u.upload_state not in ('created', 'uploading') then
        raise exception using errcode = '55000', message = 'upload write origin unavailable';
      end if;
    else
      select * into j from public.attachment_processor_jobs where processor_job_id = v->>'origin_id' for update;
      if not found or j.processor_state <> 'claimed' or j.upload_id <> upload
        or j.owner_id is distinct from v->>'origin_owner_id'
        or j.owner_generation is distinct from (v->>'origin_owner_generation')::bigint
        or j.owner_generation is distinct from (v->>'origin_generation')::bigint
        or j.lease_expires_at is distinct from (v->>'origin_owner_expires_at')::timestamptz
        or j.lease_expires_at <= clock_timestamp() then
        raise exception using errcode = '55000', message = 'processor write claim unavailable';
      end if;
    end if;
  elsif v->>'origin_kind' = 'export_artifact' then
    select e.record_id into strict route from public.record_export_jobs e where export_job_id = v->>'origin_id';
    if route is not null then record_epoch := record_platform_internal.local_blob_record_epoch(route); end if;
    perform record_platform_internal.local_blob_write_fence(v->>'backend_kind',(v->>'namespace_id')::uuid,v->>'key',v->>'obligation_id');
    select * into strict ej from public.record_export_jobs where export_job_id = v->>'origin_id' for update;
    if ej.record_id is distinct from route or ej.project_id <> v->>'project_id'
      or ej.lock_version is distinct from (v->>'origin_generation')::bigint
      or ej.job_state <> 'staging' or ej.expires_at <= clock_timestamp() then
      raise exception using errcode = '55000', message = 'export write origin unavailable';
    end if;
  elsif v->>'origin_kind' in ('import_attachment', 'import_archive') then
    -- Direct SQL callers must participate in source admission and the same
    -- shared graph fence as Go, without waiting backwards across later ranks.
    select * into admission from public.source_authority_admission where singleton for share nowait;
    source_present:=found;
    if source_present and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=admission.generation and p.purpose in ('runtime','admin','worker'))) then
      raise exception using errcode='42501',message='import source admission unavailable';
    end if;
    perform record_platform_internal.record_birth_launch_admit(admission);
    if not pg_try_advisory_xact_lock_shared(1213154899,1) then
      raise exception using errcode='40001',message='import source graph busy; restart transaction';
    end if;
    if source_present<>exists(select 1 from public.source_authority_admission where singleton) then
      raise exception using errcode='40001',message='import source admission changed; restart transaction';
    end if;
    select destination_subject_kind,destination_subject_source_id into destination_kind,destination_source
      from public.record_import_jobs where import_job_id=v->>'origin_id';
    if not found or destination_kind is null or destination_source is null then
      raise exception using errcode='55000',message='import destination unavailable';
    end if;
    perform record_platform_internal.evidence_live_source(destination_kind,destination_source);
    -- The durable obligation may retain targets after plan owners disappear.
    -- Discover both sources before any job or Blob lock.
    select array(select x.record_id collate "C" from (
      select m.target_id as record_id from public.record_import_plans p
        join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
        where p.import_job_id=v->>'origin_id' and m.entity_kind='record'
      union select t.record_id from public.record_write_obligation_targets t where t.obligation_id=v->>'obligation_id'
    ) x order by x.record_id collate "C") into target_ids;
    foreach target in array target_ids loop
      perform record_platform_internal.record_birth_writer_guard(target);
    end loop;
    if v->>'origin_kind' = 'import_attachment' and
      (v->>'target_record_id' !~ '^rec2_[0-9a-f]{32}$' or v->>'target_attachment_id' !~ '^att_[a-z0-9]{1,64}$'
       or not (v->>'target_record_id'=any(target_ids))) then
      raise exception using errcode='55000',message='invalid import attachment target';
    end if;
    -- Job rank precedes the Blob table fence. NOWAIT also protects callers
    -- that reach this guard while holding a later-ranked resource.
    select * into strict ij from public.record_import_jobs where import_job_id = v->>'origin_id' for update nowait;
    perform record_platform_internal.local_blob_write_fence(v->>'backend_kind',(v->>'namespace_id')::uuid,v->>'key',v->>'obligation_id');
    if (ij.destination_subject_kind,ij.destination_subject_source_id) is distinct from (destination_kind,destination_source)
      or ij.project_id <> v->>'project_id' or ij.lock_version is distinct from (v->>'origin_generation')::bigint
      or ij.archive_digest is distinct from decode(v->>'archive_digest', 'hex')
      or ij.expires_at <= clock_timestamp()
      or (v->>'origin_kind' = 'import_archive' and ij.job_state not in ('uploaded', 'quarantined', 'dry_run'))
      or (v->>'origin_kind' = 'import_attachment' and ij.job_state <> 'planned') then
      raise exception using errcode = '55000', message = 'import write origin unavailable';
    end if;
    select array(select x.record_id collate "C" from (
      select m.target_id as record_id from public.record_import_plans p
        join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
        where p.import_job_id=ij.import_job_id and m.entity_kind='record'
      union select t.record_id from public.record_write_obligation_targets t where t.obligation_id=v->>'obligation_id'
    ) x order by x.record_id collate "C") into current_targets;
    if current_targets is distinct from target_ids then
      raise exception using errcode='40001',message='import write target route changed';
    end if;
    for birth in select allocation.*,r.target_id as mapped_target from public.record_import_plans p
      join public.record_import_entity_mappings r on r.import_plan_id=p.import_plan_id and r.entity_kind='record'
      left join record_platform_internal.record_birth_allocations allocation on allocation.allocation_id=r.birth_allocation_id
      where p.import_job_id=ij.import_job_id order by r.target_id collate "C" loop
      if birth.allocation_id is null or (birth.project_id,birth.actor_id,birth.purpose,birth.record_id)
        is distinct from (ij.project_id,ij.actor_id,'import'::text,birth.mapped_target)
        or birth.state not in ('allocated','preparing','prepared')
        or exists(select 1 from public.records root where root.record_id=birth.mapped_target) then
        raise exception using errcode='55000',message='import write allocation unavailable';
      end if;
      if birth.domain='certifiable' then
        binding:=record_platform_internal.record_birth_binding();
        if binding.generation is null or (binding.generation,binding.key_id,binding.cutover_digest) is distinct from
          (birth.binding_generation,birth.binding_key_id,birth.binding_cutover_digest) then
          raise exception using errcode='55000',message='import write allocation binding is stale';
        end if;
      end if;
    end loop;
    if v->>'origin_kind' = 'import_attachment' then
      select allocation.* into birth from public.record_import_plans p
      join public.record_import_entity_mappings r on r.import_plan_id=p.import_plan_id and r.entity_kind='record'
      join public.record_import_entity_mappings a on a.import_plan_id=p.import_plan_id and a.entity_kind='attachment'
        and a.owner_target_record_id=r.target_id
      join record_platform_internal.record_birth_allocations allocation on allocation.allocation_id=r.birth_allocation_id
      where p.import_job_id=ij.import_job_id and p.plan_digest=decode(v->>'plan_digest','hex')
        and p.expires_at>clock_timestamp() and r.target_id=v->>'target_record_id'
        and a.target_id=v->>'target_attachment_id'
        and (allocation.project_id,allocation.actor_id,allocation.purpose,allocation.record_id)=
          (ij.project_id,ij.actor_id,'import'::text,r.target_id)
        and allocation.state in ('allocated','preparing','prepared')
        and not exists(select 1 from public.records where records.record_id=r.target_id)
      for update of r,a,allocation nowait;
      if not found then
        raise exception using errcode='55000',message='import write target is not plan authenticated';
      end if;
      if birth.domain='certifiable' then
        binding:=record_platform_internal.record_birth_binding();
        if binding.generation is null or (binding.generation,binding.key_id,binding.cutover_digest) is distinct from
          (birth.binding_generation,birth.binding_key_id,birth.binding_cutover_digest) then
          raise exception using errcode='55000',message='import write allocation binding is stale';
        end if;
      end if;
    end if;
  else
    raise exception using errcode = '22023', message = 'invalid write origin kind';
  end if;
  record_id := route;
  return next;
exception when lock_not_available then
  raise exception using errcode='40001',message='write origin earlier scope busy; restart transaction';
end
$$;

create function record_platform_internal.local_blob_write_fence(text, uuid, text, text)
returns void language plpgsql security definer set search_path = pg_catalog
as $$
begin
  perform record_platform_internal.record_blob_strong_fence();
  if exists (select 1 from public.blob_gc_deletions g where g.backend_kind = $1 and g.blob_key = $3
      and (g.namespace_id is not distinct from $2 or ($1 = 'local' and g.namespace_id is null)) and g.deletion_state <> 'completed')
    or exists (select 1 from public.blob_publication_intents p where p.backend_kind = $1 and p.blob_key = $3
      and (p.namespace_id is not distinct from $2 or ($1 = 'local' and p.namespace_id is null))
      and p.publication_state in ('cleanup_claimed', 'retry_wait'))
    or exists (select 1 from public.record_write_obligations o where o.backend_kind = $1 and o.canonical_key = $3
      and o.namespace_id is not distinct from $2 and o.obligation_id is distinct from $4
      and o.cleanup_owner_id is not null and o.cleanup_completed_at is null) then
    raise exception using errcode = '55000', message = 'blob key has active cleanup responsibility';
  end if;
end
$$;
revoke all on function record_platform_internal.local_blob_record_epoch(text),
  record_platform_internal.record_write_origin(jsonb),
  record_platform_internal.local_blob_write_fence(text, uuid, text, text) from public;

create function public.record_write_register(bytea)
returns public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; route record;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array[
    'obligation_id','writer_instance','request_seq','project_id','origin_kind','origin_id','origin_generation',
    'origin_owner_id','origin_owner_generation','origin_owner_expires_at','draft_id','plan_digest','archive_digest',
    'namespace_id','incarnation_id','backend_kind','key','sha256','size','publication_id','target_record_id','target_attachment_id']);
  if v->>'project_id' is distinct from 'default' then
    raise exception using errcode = '22023', message = 'invalid write project';
  end if;
  -- Exact replay resolves an unknown registration without requiring its former
  -- owner to remain live. It cannot grant another physical dispatch.
  select * into o from public.record_write_obligations where obligation_id = v->>'obligation_id';
  if found then
    if o.registration_command is distinct from $1 or o.writer_principal <> session_user then
      raise exception using errcode = '55000', message = 'write registration replay conflict';
    end if;
    return o;
  end if;
  if v->>'backend_kind' = 'local' then
    perform record_platform_internal.local_blob_admission((v->>'namespace_id')::uuid, (v->>'incarnation_id')::uuid);
  else
    perform public.source_application_admit();
  end if;
  select * into strict route from record_platform_internal.record_write_origin(v);
  perform record_platform_internal.local_blob_write_fence(v->>'backend_kind', (v->>'namespace_id')::uuid, v->>'key', v->>'obligation_id');
  if exists (select 1 from public.record_write_obligations
    where writer_instance = (v->>'writer_instance')::uuid and request_seq >= (v->>'request_seq')::bigint) then
    raise exception using errcode = '55000', message = 'write request sequence is not increasing';
  end if;
  if v->>'origin_kind' in ('upload', 'processor_preview') and not exists (
    select 1 from public.blob_publication_intents p where p.publication_id = v->>'publication_id'
      and p.project_id = 'default' and p.owner_kind = v->>'origin_kind' and p.owner_id = v->>'origin_id'
      and p.owner_generation = (v->>'origin_generation')::bigint and p.publication_state = 'prepared'
      and p.publish_expires_at > clock_timestamp() and p.blob_key = v->>'key'
      and p.sha256_digest = decode(v->>'sha256', 'hex') and p.size_bytes = (v->>'size')::bigint
      and p.backend_kind = v->>'backend_kind'
  ) then
    raise exception using errcode = '55000', message = 'write publication identity unavailable';
  end if;
  insert into public.record_write_obligations(obligation_id, writer_instance, request_seq, writer_principal,
    project_id, origin_kind, origin_id, origin_generation, origin_owner_id, origin_owner_generation,
    origin_owner_expires_at, plan_digest, archive_digest, namespace_id, incarnation_id, backend_kind,
    canonical_key, sha256_digest, size_bytes, publication_id, record_id, record_epoch,
    registration_command, temporary_key, quota_settlement_id)
  values (v->>'obligation_id', (v->>'writer_instance')::uuid, (v->>'request_seq')::bigint, session_user,
    v->>'project_id', v->>'origin_kind', v->>'origin_id', (v->>'origin_generation')::bigint,
    v->>'origin_owner_id', (v->>'origin_owner_generation')::bigint, (v->>'origin_owner_expires_at')::timestamptz,
    decode(v->>'plan_digest', 'hex'), decode(v->>'archive_digest', 'hex'),
    (v->>'namespace_id')::uuid, (v->>'incarnation_id')::uuid, v->>'backend_kind', v->>'key',
    decode(v->>'sha256', 'hex'), (v->>'size')::bigint, v->>'publication_id', route.record_id, route.record_epoch,
    $1, case when v->>'backend_kind' = 'local' then 'sha256/.blob-tmp-' || (v->>'obligation_id') end, v->>'obligation_id')
  returning * into o;
  if o.origin_kind = 'import_attachment' then
    insert into public.record_write_obligation_targets(obligation_id, record_id, attachment_id, plan_digest)
      values (o.obligation_id, v->>'target_record_id', v->>'target_attachment_id', o.plan_digest);
  elsif o.origin_kind = 'import_archive' then
    -- Planning normally precedes staging. Preserve every certified target even
    -- when no archive obligation existed when the mapping trigger ran.
    insert into public.record_write_obligation_targets(obligation_id, record_id, plan_digest)
      select o.obligation_id, m.target_id, p.plan_digest
      from public.record_import_plans p
      join public.record_import_entity_mappings m on m.import_plan_id = p.import_plan_id
      where p.import_job_id = o.origin_id and m.entity_kind = 'record'
      on conflict (obligation_id, record_id) do nothing;
  end if;
  return o;
end
$$;

create function public.record_write_dispatch(bytea)
returns public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; route record; original jsonb;
  initial_targets text[]; current_targets text[]; plan_targets text[]; obligation_targets text[];
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','writer_instance','dispatch_id','anchor_inode','anchor_nonce']);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id';
  if o.writer_principal <> session_user or o.writer_instance is distinct from (v->>'writer_instance')::uuid
    or v->>'dispatch_id' is null then
    raise exception using errcode = '42501', message = 'write dispatch identity conflict';
  end if;
  -- A replay reports the original dispatch decision; it does not create a new
  -- dispatch or waive the writer's duty to avoid a second physical write.
  if o.dispatch_id is not null then
    if o.dispatch_id is distinct from (v->>'dispatch_id')::uuid then
      raise exception using errcode='55000',message='write dispatch replay conflict';
    end if;
    return o;
  end if;
  if o.backend_kind = 'local' then
    perform record_platform_internal.local_blob_admission(o.namespace_id, o.incarnation_id);
    if not exists (select 1 from public.local_blob_key_anchors a where a.namespace_id = o.namespace_id
      and a.incarnation_id = o.incarnation_id and a.canonical_key = o.canonical_key
      and a.lock_inode = (v->>'anchor_inode')::bigint and a.lock_nonce = (v->>'anchor_nonce')::uuid) then
      raise exception using errcode = '55000', message = 'write dispatch anchor unavailable';
    end if;
  else
    perform public.source_application_admit();
  end if;
  original := convert_from(o.registration_command, 'UTF8')::jsonb;
  if o.origin_kind in ('import_archive','import_attachment') then
    select array(select x.record_id collate "C" from (
      select m.target_id as record_id from public.record_import_plans p
        join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
        where p.import_job_id=o.origin_id and m.entity_kind='record'
      union select t.record_id from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
    ) x order by x.record_id collate "C") into initial_targets;
  end if;
  select * into strict route from record_platform_internal.record_write_origin(original);
  if row(o.record_id, o.record_epoch) is distinct from row(route.record_id, route.record_epoch) then
    raise exception using errcode = '55000', message = 'write dispatch record route changed';
  end if;
  perform record_platform_internal.local_blob_write_fence(o.backend_kind, o.namespace_id, o.canonical_key, o.obligation_id);
  select * into strict o from public.record_write_obligations where obligation_id = o.obligation_id for update;
  if o.dispatch_id is not null then
    if o.dispatch_id is distinct from (v->>'dispatch_id')::uuid then
      raise exception using errcode = '55000', message = 'write dispatch replay conflict';
    end if;
    return o;
  end if;
  if o.origin_kind in ('import_archive','import_attachment') then
    perform 1 from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
      order by t.record_id collate "C" for update nowait;
    select array(select m.target_id collate "C" from public.record_import_plans p
      join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
      where p.import_job_id=o.origin_id and m.entity_kind='record' order by m.target_id collate "C") into plan_targets;
    select array(select t.record_id collate "C" from public.record_write_obligation_targets t
      where t.obligation_id=o.obligation_id order by t.record_id collate "C") into obligation_targets;
    select array(select x.record_id collate "C" from (
      select unnest(plan_targets) as record_id union select unnest(obligation_targets)
    ) x order by x.record_id collate "C") into current_targets;
    if initial_targets is distinct from current_targets then
      raise exception using errcode='40001',message='import dispatch target route changed';
    end if;
    if exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
      and (t.bound_at is not null or t.record_epoch is not null or t.handed_off_at is not null))
      or cardinality(plan_targets)<>(select count(distinct id) from unnest(plan_targets) id) then
      raise exception using errcode='55000',message='import dispatch target unavailable or ambiguous';
    end if;
    if o.origin_kind='import_archive' then
      if plan_targets is distinct from obligation_targets or exists(
        select 1 from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
          and (t.attachment_id is not null or t.plan_digest is distinct from
            (select p.plan_digest from public.record_import_plans p where p.import_job_id=o.origin_id))) then
        raise exception using errcode='55000',message='import archive target provenance changed';
      end if;
    elsif obligation_targets is distinct from array[original->>'target_record_id']
      or exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
        and (t.attachment_id is distinct from original->>'target_attachment_id' or t.plan_digest is distinct from o.plan_digest))
      or (select count(*) from public.record_import_plans p
        join public.record_import_entity_mappings a on a.import_plan_id=p.import_plan_id and a.entity_kind='attachment'
        join public.record_import_entity_mappings r on r.import_plan_id=p.import_plan_id and r.entity_kind='record'
          and r.target_id=a.owner_target_record_id
        where p.import_job_id=o.origin_id and p.plan_digest=o.plan_digest
          and a.target_id=original->>'target_attachment_id' and a.owner_target_record_id=original->>'target_record_id')<>1 then
      raise exception using errcode='55000',message='import attachment target provenance changed';
    end if;
  end if;
  if o.outcome <> 'registered' or o.handed_off_at is not null or o.cleanup_owner_id is not null
    or exists (select 1 from public.blob_gc_deletions g where g.backend_kind = o.backend_kind
      and g.blob_key = o.canonical_key and g.namespace_id is not distinct from o.namespace_id
      and g.completed_at >= o.created_at) then
    raise exception using errcode = '55000', message = 'write responsibility has been sealed';
  end if;
  update public.record_write_obligations set dispatch_id = (v->>'dispatch_id')::uuid, dispatched_at = clock_timestamp()
    where obligation_id = o.obligation_id returning * into o;
  return o;
exception when lock_not_available then
  raise exception using errcode='40001',message='write dispatch target busy; restart transaction';
end
$$;

-- Readback, unlike dispatch, remains available after owner handoff and gate
-- closure. It reports the original decision without authorizing another I/O.
create function public.record_write_resolve(bytea)
returns public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','writer_instance']);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id';
  if o.writer_principal <> session_user or o.writer_instance is distinct from (v->>'writer_instance')::uuid then
    raise exception using errcode = '42501', message = 'write readback identity conflict';
  end if;
  return o;
end
$$;

create function public.record_write_temporary_created(bytea)
returns public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','writer_instance','dispatch_id','device','inode']);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id' for update;
  if o.writer_principal <> session_user or o.writer_instance is distinct from (v->>'writer_instance')::uuid
    or o.dispatch_id is null or o.dispatch_id is distinct from (v->>'dispatch_id')::uuid or o.backend_kind <> 'local'
    or v->>'device' is null or v->>'inode' is null then
    raise exception using errcode = '42501', message = 'temporary creation identity conflict';
  end if;
  if o.temporary_inode is not null then
    if row(o.temporary_device, o.temporary_inode) is distinct from row((v->>'device')::bigint, (v->>'inode')::bigint) then
      raise exception using errcode = '55000', message = 'temporary creation replay conflict';
    end if;
    return o;
  end if;
  update public.record_write_obligations set temporary_device = (v->>'device')::bigint,
    temporary_inode = (v->>'inode')::bigint, temporary_created_at = clock_timestamp()
    where obligation_id = o.obligation_id returning * into o;
  return o;
end
$$;

create function public.record_write_return(bytea)
returns public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','writer_instance','dispatch_id','outcome','version','key','sha256','size']);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id' for update;
  if o.writer_principal <> session_user or o.writer_instance is distinct from (v->>'writer_instance')::uuid
    or o.dispatch_id is null or o.dispatch_id is distinct from (v->>'dispatch_id')::uuid
    or o.canonical_key is distinct from v->>'key' or o.sha256_digest is distinct from decode(v->>'sha256', 'hex')
    or o.size_bytes is distinct from (v->>'size')::bigint
    or v->>'outcome' is null or v->>'outcome' not in ('materialized', 'failed', 'remote_unknown') then
    raise exception using errcode = '42501', message = 'write return identity conflict';
  end if;
  if o.return_command is not null then
    if o.return_command is distinct from $1 then
      raise exception using errcode = '55000', message = 'write return replay conflict';
    end if;
    return o;
  end if;
  update public.record_write_obligations set outcome = v->>'outcome', object_version = v->>'version',
    returned_at = clock_timestamp(), return_command = $1 where obligation_id = o.obligation_id returning * into o;
  return o;
end
$$;
revoke all on function public.record_write_register(bytea), public.record_write_dispatch(bytea),
  public.record_write_resolve(bytea), public.record_write_temporary_created(bytea), public.record_write_return(bytea) from public;

create function record_platform_internal.local_blob_cleanup_operation(text, text, bigint, timestamptz, text)
returns void language plpgsql security definer set search_path = pg_catalog
as $$
declare reservation public.deletion_reservations; fence public.deletion_fence_leases;
  gate public.record_deletion_gates; operation public.record_purge_operations; discovered text; epoch bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode='25000',message='comparison writer requires read committed isolation';
  end if;
  select o.reservation_id into discovered from public.record_purge_operations o where o.operation_id=$1;
  if not found then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select r.* into reservation from public.deletion_reservations r where r.reservation_id=discovered for update;
  if not found then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  select e.delivery_epoch into epoch from public.content_delivery_epochs e where e.project_id=reservation.project_id
    and e.object_kind=reservation.object_kind and e.object_id=reservation.object_id for update;
  select f.* into fence from public.deletion_fence_leases f where f.project_id=reservation.project_id
    and f.object_kind=reservation.object_kind and f.object_id=reservation.object_id for update;
  if not found then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  select g.* into gate from public.record_deletion_gates g where g.project_id=reservation.project_id and g.record_id=reservation.object_id for share;
  if not found then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  select o.* into operation from public.record_purge_operations o where o.operation_id=$1 for update;
  if not found then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  if (reservation.state,reservation.object_kind,reservation.object_id,reservation.deletion_contract_version)
      is distinct from ('fenced','record',$5,2::bigint)
    or (epoch is not null and epoch<>reservation.fence_epoch)
    or (reservation.owner_id,reservation.owner_generation,reservation.owner_expires_at) is distinct from ($2,$3,$4)
    or (fence.owner_id,fence.owner_generation,fence.expires_at) is distinct from ($2,$3,$4)
    or (operation.reservation_id,operation.project_id,operation.deletion_contract_version,operation.operation_state,
        operation.owner_id,operation.owner_generation,operation.owner_expires_at)
      is distinct from (reservation.reservation_id,reservation.project_id,2::bigint,'online_purging',$2,$3,$4)
    or (gate.operation_id,gate.project_id,gate.record_id,gate.fence_epoch,gate.binding_digest,gate.request_fingerprint,gate.actor_scope_digest,gate.actor_id)
      is distinct from (operation.operation_id,reservation.project_id,reservation.object_id,reservation.fence_epoch,
        reservation.preview_binding_digest,reservation.request_fingerprint,reservation.actor_scope_digest,operation.actor_id)
    or $4<=clock_timestamp() then
    raise exception using errcode='42501',message='local cleanup operation authority unavailable';
  end if;
  perform 1 from public.records r where r.project_id=reservation.project_id and r.record_id=reservation.object_id for update;
  if found and epoch is null then raise exception using errcode='42501',message='local cleanup operation authority unavailable'; end if;
  if $4<=clock_timestamp() then
    raise exception using errcode='42501',message='local cleanup operation authority unavailable';
  end if;
end
$$;

create function record_platform_internal.local_blob_origin_closed(text)
returns boolean language sql stable security definer set search_path = pg_catalog
as $$
  select o.handed_off_at is not null
    or (o.record_id is not null and exists (select 1 from public.record_deletion_gates g where g.record_id = o.record_id))
    or (o.origin_kind = 'upload' and exists (select 1 from public.attachment_uploads u
      where u.upload_id = o.origin_id and (u.upload_state in ('available','rejected','expired') or u.expires_at <= statement_timestamp())))
    or (o.origin_kind = 'processor_preview' and exists (select 1 from public.attachment_processor_jobs j
      where j.processor_job_id = o.origin_id and (j.processor_state in ('succeeded','rejected','expired') or j.expires_at <= statement_timestamp())))
    or (o.origin_kind = 'export_artifact' and exists (select 1 from public.record_export_jobs j
      where j.export_job_id = o.origin_id and (j.job_state in ('revoked','failed','expired') or j.expires_at <= statement_timestamp())))
    or (o.origin_kind in ('import_archive','import_attachment') and exists (select 1 from public.record_import_jobs j
      where j.import_job_id = o.origin_id and (j.job_state in ('applied','failed','expired') or j.expires_at <= statement_timestamp())))
  from public.record_write_obligations o where o.obligation_id = $1
$$;

create function record_platform_internal.local_blob_key_referenced(uuid, text)
returns boolean language sql stable security definer set search_path = pg_catalog
as $$
  select exists (select 1 from public.record_attachments a join public.blob_objects b
      on b.blob_key in (a.blob_key, a.preview_blob_key)
      where b.blob_key = $2 and (b.namespace_id = $1 or b.namespace_id is null))
    or exists (select 1 from public.attachment_upload_parts p
      where 'sha256/' || encode(p.sha256_digest, 'hex') = $2 and (p.namespace_id = $1 or p.namespace_id is null))
    or exists (select 1 from public.blob_gc_pins p join public.blob_objects b on b.blob_key = p.blob_key
      where b.blob_key = $2 and (b.namespace_id = $1 or b.namespace_id is null) and p.expires_at > statement_timestamp())
    or exists (select 1 from public.record_export_artifacts a where a.backend_kind = 'local'
      and a.blob_key = $2 and (a.namespace_id = $1 or a.namespace_id is null)
      and a.revoked_at is null and a.expires_at > statement_timestamp())
    or exists (select 1 from public.record_import_artifacts a where a.backend_kind = 'local'
      and a.blob_key = $2 and (a.namespace_id = $1 or a.namespace_id is null) and a.expires_at > statement_timestamp())
    or exists (select 1 from public.blob_publication_intents p where p.backend_kind = 'local'
      and p.blob_key = $2 and (p.namespace_id = $1 or p.namespace_id is null)
      and p.publication_state in ('prepared','published') and p.publish_expires_at > statement_timestamp())
$$;

-- The caller already holds the descriptor-bound key guard. Every member of the
-- returned set is required physical cleanup inventory, including exact temp names.
create function record_platform_internal.local_blob_cleanup_claim(bytea, boolean)
returns setof public.record_write_obligations language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; generation bigint; expiry timestamptz;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','namespace_id','incarnation_id',
    'anchor_inode','anchor_nonce','cleanup_owner_id','cleanup_generation','cleanup_expires_at','cleanup_dispatch_id',
    'operation_id','operation_owner_id','operation_generation','operation_expires_at']);
  perform record_platform_internal.local_blob_admission((v->>'namespace_id')::uuid, (v->>'incarnation_id')::uuid);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id';
  if o.backend_kind <> 'local' or o.namespace_id is distinct from (v->>'namespace_id')::uuid
    or o.incarnation_id is distinct from (v->>'incarnation_id')::uuid
    or not exists (select 1 from public.local_blob_key_anchors a where a.namespace_id = o.namespace_id
      and a.incarnation_id = o.incarnation_id and a.canonical_key = o.canonical_key
      and a.lock_inode = (v->>'anchor_inode')::bigint and a.lock_nonce = (v->>'anchor_nonce')::uuid) then
    raise exception using errcode = '55000', message = 'local cleanup namespace or anchor conflict';
  end if;
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id', v->>'operation_owner_id',
      (v->>'operation_generation')::bigint, (v->>'operation_expires_at')::timestamptz, o.record_id);
    if o.operation_id is not null and o.operation_id is distinct from v->>'operation_id' then
      raise exception using errcode = '55000', message = 'local cleanup operation identity conflict';
    end if;
  elsif v->>'operation_id' is not null or o.operation_id is not null or not record_platform_internal.local_blob_origin_closed(o.obligation_id) then
    raise exception using errcode = '42501', message = 'ordinary local cleanup origin unavailable';
  end if;
  perform 1 from public.attachment_quota_accounts where project_id = o.project_id for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  perform 1 from public.record_write_obligations w where w.namespace_id = o.namespace_id and w.canonical_key = o.canonical_key
    order by w.obligation_id for update;
  select * into strict o from public.record_write_obligations w where w.obligation_id = o.obligation_id;
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id);
  end if;
  if row(o.cleanup_generation, o.cleanup_expires_at) is distinct from
    row((v->>'cleanup_generation')::bigint, (v->>'cleanup_expires_at')::timestamptz) then
    raise exception using errcode = '55000', message = 'local cleanup observed claim changed';
  end if;
  if o.cleanup_completed_at is not null then
    return next o;
    if $2 then perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id); end if;
    return;
  end if;
  if o.cleanup_owner_id is not null and o.cleanup_owner_id <> v->>'cleanup_owner_id' and o.cleanup_expires_at > clock_timestamp() then
    raise exception using errcode = '55000', message = 'local cleanup claim is live';
  end if;
  if exists (select 1 from public.record_write_obligations w where w.namespace_id = o.namespace_id and w.canonical_key = o.canonical_key
    and w.cleanup_completed_at is null and w.obligation_id <> o.obligation_id
    and (not record_platform_internal.local_blob_origin_closed(w.obligation_id)
      or (w.cleanup_owner_id is not null and w.cleanup_owner_id <> v->>'cleanup_owner_id' and w.cleanup_expires_at > clock_timestamp())
      or (w.operation_id is not null and w.operation_id is distinct from v->>'operation_id'))) then
    raise exception using errcode = '55000', message = 'other writable responsibility prevents local cleanup';
  end if;
  select coalesce(max(w.cleanup_generation), 0) + 1 into generation from public.record_write_obligations w
    where w.namespace_id = o.namespace_id and w.canonical_key = o.canonical_key;
  expiry := clock_timestamp() + interval '1 minute';
  return query update public.record_write_obligations w set cleanup_owner_id = v->>'cleanup_owner_id',
    cleanup_generation = generation, cleanup_expires_at = expiry, cleanup_dispatch_id = (v->>'cleanup_dispatch_id')::uuid,
    operation_id = case when w.obligation_id = o.obligation_id and $2 then v->>'operation_id' else w.operation_id end,
    outcome = case when w.dispatched_at is null then 'local_excluded' else w.outcome end,
    handed_off_at = coalesce(w.handed_off_at, clock_timestamp())
    where w.namespace_id = o.namespace_id and w.canonical_key = o.canonical_key and w.cleanup_completed_at is null
    returning w.*;
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id);
  end if;
end
$$;

create function public.local_blob_cleanup_claim(bytea)
returns setof public.record_write_obligations language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.local_blob_cleanup_claim($1, false) $$;
create function public.local_blob_purge_claim(bytea)
returns setof public.record_write_obligations language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.local_blob_cleanup_claim($1, true) $$;

create function record_platform_internal.local_blob_cleanup_complete(bytea, boolean)
returns bigint language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; retained boolean; removed bigint; completed bigint; receipt bytea;
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['obligation_id','cleanup_owner_id','cleanup_generation',
    'cleanup_expires_at','cleanup_dispatch_id','outcome','inventory_digest','operation_id',
    'operation_owner_id','operation_generation','operation_expires_at']);
  select * into strict o from public.record_write_obligations where obligation_id = v->>'obligation_id';
  perform record_platform_internal.local_blob_admission(o.namespace_id, o.incarnation_id);
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id', v->>'operation_owner_id',
      (v->>'operation_generation')::bigint, (v->>'operation_expires_at')::timestamptz, o.record_id);
  elsif v->>'operation_id' is not null or o.operation_id is not null then
    raise exception using errcode = '42501', message = 'ordinary cleanup cannot complete a purge';
  end if;
  perform 1 from public.attachment_quota_accounts where project_id = o.project_id for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  select * into strict o from public.record_write_obligations w where w.obligation_id = o.obligation_id for update;
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id);
  end if;
  if row(o.cleanup_owner_id, o.cleanup_generation, o.cleanup_expires_at, o.cleanup_dispatch_id) is distinct from
    row(v->>'cleanup_owner_id', (v->>'cleanup_generation')::bigint, (v->>'cleanup_expires_at')::timestamptz, (v->>'cleanup_dispatch_id')::uuid)
    or o.cleanup_owner_id is null or o.cleanup_expires_at <= clock_timestamp() then
    raise exception using errcode = '42501', message = 'local cleanup completion claim unavailable';
  end if;
  if v->>'outcome' is null or v->>'outcome' not in ('deleted','already_absent','retained_referenced')
    or octet_length(decode(v->>'inventory_digest', 'hex')) is distinct from 32 then
    raise exception using errcode = '22023', message = 'invalid local cleanup evidence';
  end if;
  receipt := record_platform_internal.digest(convert_to('HOUFENG-LOCAL-CLEANUP-V2', 'UTF8') || $1, 'sha256');
  if o.cleanup_completed_at is not null then
    if o.cleanup_receipt is distinct from receipt then
      raise exception using errcode = '55000', message = 'local cleanup completion replay conflict';
    end if;
    if $2 then perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id); end if;
    return 0;
  end if;
  retained := record_platform_internal.local_blob_key_referenced(o.namespace_id, o.canonical_key);
  if retained is distinct from (v->>'outcome' = 'retained_referenced') then
    raise exception using errcode = '55000', message = 'local cleanup reference disposition changed';
  end if;
  if not retained then
    delete from public.blob_gc_pins p using public.blob_objects b
      where b.namespace_id=o.namespace_id and b.blob_key=o.canonical_key
        and p.blob_key=b.blob_key and p.blob_object_version=b.object_version and p.expires_at<=statement_timestamp();
    delete from public.blob_objects b where b.namespace_id = o.namespace_id and b.blob_key = o.canonical_key
      returning b.size_bytes into removed;
    if removed is not null then
      update public.attachment_quota_accounts set physical_bytes = physical_bytes - removed,
        quota_version = quota_version + 1, updated_at = clock_timestamp()
        where project_id = o.project_id and physical_bytes >= removed;
      if not found then raise exception using errcode = '55000', message = 'local cleanup quota settlement conflict'; end if;
    end if;
  end if;
  update public.record_write_obligations w set cleanup_outcome = v->>'outcome', cleanup_receipt = receipt,
    cleanup_completed_at = clock_timestamp(), quota_settled_at = case when not retained then clock_timestamp() end
    where w.namespace_id = o.namespace_id and w.canonical_key = o.canonical_key
      and w.cleanup_owner_id = o.cleanup_owner_id and w.cleanup_generation = o.cleanup_generation
      and w.cleanup_expires_at = o.cleanup_expires_at and w.cleanup_dispatch_id = o.cleanup_dispatch_id
      and w.cleanup_completed_at is null;
  get diagnostics completed = row_count;
  if $2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,o.record_id);
  end if;
  return completed;
end
$$;
create function public.local_blob_cleanup_complete(bytea)
returns bigint language sql security definer set search_path = pg_catalog
as $$ select record_platform_internal.local_blob_cleanup_complete($1, false) $$;
create function public.local_blob_purge_complete(bytea)
returns bigint language sql security definer set search_path = pg_catalog
as $$ select record_platform_internal.local_blob_cleanup_complete($1, true) $$;
revoke all on function record_platform_internal.local_blob_cleanup_operation(text, text, bigint, timestamptz, text),
  record_platform_internal.local_blob_origin_closed(text),
  record_platform_internal.local_blob_key_referenced(uuid, text),
  record_platform_internal.local_blob_cleanup_claim(bytea, boolean),
  record_platform_internal.local_blob_cleanup_complete(bytea, boolean),
  public.local_blob_cleanup_claim(bytea), public.local_blob_purge_claim(bytea),
  public.local_blob_cleanup_complete(bytea), public.local_blob_purge_complete(bytea) from public;

-- Origin deletion transfers responsibility in its own transaction. The trigger
-- grants no physical cleanup or receipt authority and never erases evidence.
create function record_platform_internal.record_write_origin_handoff()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
declare origin text; kinds text[];
begin
  case tg_table_name
    when 'attachment_uploads' then origin := old.upload_id; kinds := array['upload'];
    when 'attachment_processor_jobs' then origin := old.processor_job_id; kinds := array['processor_preview'];
    when 'record_import_jobs' then origin := old.import_job_id; kinds := array['import_archive','import_attachment'];
    when 'record_export_jobs' then origin := old.export_job_id; kinds := array['export_artifact'];
    else raise exception using errcode = '55000', message = 'invalid write origin handoff table';
  end case;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  update public.record_write_obligations set handed_off_at = coalesce(handed_off_at, clock_timestamp()),
    outcome = case when backend_kind = 'local' and dispatched_at is null then 'local_excluded' else outcome end
    where origin_kind = any(kinds) and origin_id = origin;
  return old;
end
$$;
create trigger record_write_upload_handoff before delete on public.attachment_uploads
  for each row execute function record_platform_internal.record_write_origin_handoff();
create trigger record_write_processor_handoff before delete on public.attachment_processor_jobs
  for each row execute function record_platform_internal.record_write_origin_handoff();
create trigger record_write_import_handoff before delete on public.record_import_jobs
  for each row execute function record_platform_internal.record_write_origin_handoff();
create trigger record_write_export_handoff before delete on public.record_export_jobs
  for each row execute function record_platform_internal.record_write_origin_handoff();

create function record_platform_internal.record_write_import_target_register()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
begin
  if new.entity_kind = 'record' then
    lock table public.blob_objects in share row exclusive mode;
    lock table public.attachment_upload_parts in share row exclusive mode;
    insert into public.record_write_obligation_targets(obligation_id, record_id, plan_digest)
      select o.obligation_id, new.target_id, p.plan_digest
      from public.record_import_plans p join public.record_write_obligations o on o.origin_id = p.import_job_id
        and o.origin_kind = 'import_archive'
      where p.import_plan_id = new.import_plan_id
      on conflict (obligation_id, record_id) do nothing;
  end if;
  return new;
end
$$;
create trigger record_write_import_target_register after insert on public.record_import_entity_mappings
  for each row execute function record_platform_internal.record_write_import_target_register();

create function public.record_write_bind_record(bytea)
returns bigint language plpgsql security definer set search_path = pg_catalog
as $$
declare v jsonb; epoch bigint; bound bigint; n record; admitted uuid[]:='{}';
begin
  perform record_platform_internal.local_blob_direct_login();
  v := record_platform_internal.local_blob_command($1, array['record_id','origin_kind','origin_id','origin_generation']);
  perform public.source_application_admit();
  for n in select distinct o.namespace_id,ns.current_incarnation_id from public.record_write_obligations o
    join public.local_blob_namespaces ns on ns.namespace_id=o.namespace_id
    where o.origin_kind=v->>'origin_kind' and o.origin_id=v->>'origin_id'
      and (o.origin_kind in ('upload','processor_preview') or exists(select 1 from public.record_write_obligation_targets t
        where t.obligation_id=o.obligation_id and t.record_id=v->>'record_id')) order by o.namespace_id loop
    perform record_platform_internal.local_blob_admission(n.namespace_id,n.current_incarnation_id);
    admitted:=array_append(admitted,n.namespace_id);
  end loop;
  epoch := record_platform_internal.local_blob_record_epoch(v->>'record_id');
  if not exists(select 1 from public.records where record_id=v->>'record_id' and current_revision_id is not null) then
    raise exception using errcode='55000',message='record write handoff requires an applied revision';
  end if;
  if v->>'origin_kind' in ('import_archive','import_attachment') then
    perform 1 from public.record_import_jobs j join public.record_import_plans p on p.import_job_id=j.import_job_id
      join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
      where j.import_job_id=v->>'origin_id' and j.lock_version=(v->>'origin_generation')::bigint
        and j.job_state in ('planned','applying','applied') and m.entity_kind='record' and m.target_id=v->>'record_id'
      for update of j nowait;
    if not found then
      raise exception using errcode='55000',message='import write handoff route unavailable';
    end if;
  end if;
  perform record_platform_internal.record_blob_strong_fence();
  if exists(select 1 from public.record_write_obligations o where o.origin_kind=v->>'origin_kind' and o.origin_id=v->>'origin_id'
    and o.namespace_id is not null and not(o.namespace_id=any(admitted))
    and (o.origin_kind in ('upload','processor_preview') or exists(select 1 from public.record_write_obligation_targets t
      where t.obligation_id=o.obligation_id and t.record_id=v->>'record_id'))) then
    raise exception using errcode='40001',message='record write handoff namespace discovery changed';
  end if;
  if v->>'origin_kind' in ('upload','processor_preview') then
    perform 1 from public.attachment_uploads u join public.record_attachments a on a.attachment_id = u.attachment_id
      where a.record_id = v->>'record_id' and (
        (v->>'origin_kind' = 'upload' and u.upload_id = v->>'origin_id' and (v->>'origin_generation')::bigint = 1)
        or (v->>'origin_kind' = 'processor_preview' and exists (select 1 from public.attachment_processor_jobs j
          where j.upload_id = u.upload_id and j.processor_job_id = v->>'origin_id' and j.owner_generation = (v->>'origin_generation')::bigint)))
      for update of u,a;
    if not found then
      raise exception using errcode = '55000', message = 'draft write handoff route unavailable';
    end if;
    if v->>'origin_kind'='processor_preview' then
      perform 1 from public.attachment_processor_jobs where processor_job_id=v->>'origin_id'
        and owner_generation=(v->>'origin_generation')::bigint for update;
      if not found then raise exception using errcode='55000',message='processor handoff generation changed'; end if;
    end if;
  elsif v->>'origin_kind' in ('import_archive','import_attachment') then
    perform 1 from public.record_import_jobs j join public.record_import_plans p on p.import_job_id = j.import_job_id
      join public.record_import_entity_mappings m on m.import_plan_id = p.import_plan_id
      where j.import_job_id = v->>'origin_id' and j.lock_version = (v->>'origin_generation')::bigint
        and j.job_state in ('planned','applying','applied') and m.entity_kind = 'record' and m.target_id = v->>'record_id'
      for update of j nowait;
    if not found then
      raise exception using errcode = '55000', message = 'import write handoff route unavailable';
    end if;
  else
    raise exception using errcode = '22023', message = 'invalid record write handoff origin';
  end if;
  update public.record_write_obligations o set record_id = v->>'record_id', record_epoch = epoch
    where o.origin_kind = v->>'origin_kind' and o.origin_id = v->>'origin_id'
      and (o.origin_kind in ('upload','processor_preview') or exists (
        select 1 from public.record_write_obligation_targets t where t.obligation_id = o.obligation_id
          and t.record_id = v->>'record_id' and t.attachment_id is not null))
      and o.record_id is null and o.cleanup_owner_id is null and o.handed_off_at is null;
  get diagnostics bound = row_count;
  update public.record_write_obligation_targets t set record_epoch = epoch, bound_at = clock_timestamp()
    from public.record_write_obligations o where o.obligation_id = t.obligation_id
      and o.origin_kind = v->>'origin_kind' and o.origin_id = v->>'origin_id'
      and t.record_id = v->>'record_id' and t.record_epoch is null and o.cleanup_owner_id is null;
  return bound;
exception when lock_not_available then
  raise exception using errcode='40001',message='record write handoff scope busy; restart transaction';
end
$$;
revoke all on function record_platform_internal.record_write_origin_handoff(),
  record_platform_internal.record_write_import_target_register(), public.record_write_bind_record(bytea) from public;

-- A finished retained write is provenance, not authority for a later owner's
-- cleanup. Local v2 GC therefore has its own durable task and claim. Pending
-- tasks can be handed off before owner removal, without claiming physical IO.
alter table public.blob_gc_deletions
  add column local_contract_version bigint not null default 1 check (local_contract_version in (1,2)),
  add column incarnation_id uuid,
  add column cleanup_dispatch_id uuid,
  add column inventory_digest bytea check (octet_length(inventory_digest)=32),
  add column final_identity_bound boolean not null default false,
  add column final_was_present boolean,
  add column final_device bigint check (final_device>=0),
  add column final_inode bigint check (final_inode>0),
  add column completion_command bytea,
  alter column object_version drop not null,
  alter column size_bytes drop not null,
  alter column blob_created_at drop not null,
  alter column owner_id drop not null,
  alter column owner_generation drop not null,
  alter column attempt drop not null,
  alter column lease_expires_at drop not null,
  add foreign key(namespace_id,incarnation_id) references public.local_blob_namespace_incarnations(namespace_id,incarnation_id);
do $$
declare constraint_name text;
begin
  -- These two columns participate in the old state checks. Preserve all other
  -- checks and replace only those checks with the explicit v1/v2 contract.
  for constraint_name in select c.conname from pg_constraint c
    where c.conrelid='public.blob_gc_deletions'::regclass and c.contype='c'
      and c.conkey && array(select a.attnum from pg_attribute a where a.attrelid=c.conrelid
        and a.attname in ('deletion_state','physical_delete_result'))
  loop execute format('alter table public.blob_gc_deletions drop constraint %I',constraint_name); end loop;
end $$;
alter table public.blob_gc_deletions
  add constraint blob_gc_local_contract check (
    (local_contract_version=1 and object_version is not null and size_bytes is not null and blob_created_at is not null
      and owner_id is not null and owner_generation is not null and attempt is not null and lease_expires_at is not null)
    or (local_contract_version=2 and backend_kind='local' and namespace_id is not null and incarnation_id is not null)),
  add constraint blob_gc_local_state check (
    (local_contract_version=2 and deletion_state='pending' and owner_id is null and owner_generation is null
      and lease_expires_at is null and attempt is null and retry_at is null and physical_delete_result is null
      and receipt_digest is null and completed_at is null)
    or (deletion_state in ('claimed','retry_wait') and owner_id is not null and owner_generation is not null
      and lease_expires_at is not null and attempt is not null and physical_delete_result is null
      and receipt_digest is null and completed_at is null and ((deletion_state='retry_wait')=(retry_at is not null)))
    or (deletion_state='completed' and owner_id is not null and owner_generation is not null and attempt is not null
      and lease_expires_at is not null and retry_at is null and physical_delete_result is not null
      and receipt_digest is not null and completed_at is not null)),
  add constraint blob_gc_local_result check (physical_delete_result in ('deleted','already_absent')
    or (local_contract_version=2 and physical_delete_result='retained_referenced')),
  add constraint blob_gc_local_final_identity check (not final_identity_bound or
    (local_contract_version=2 and final_was_present is not null and
      ((final_was_present and object_version is not null and size_bytes is not null and final_device is not null and final_inode is not null)
       or (not final_was_present and object_version is null and size_bytes is null and final_device is null and final_inode is null))));
create unique index uq_blob_gc_local_active_key on public.blob_gc_deletions(namespace_id,incarnation_id,blob_key)
  where local_contract_version=2 and deletion_state<>'completed';
create table public.local_blob_gc_obligations (
  deletion_id text not null references public.blob_gc_deletions(deletion_id) on delete restrict,
  obligation_id text not null references public.record_write_obligations(obligation_id) on delete restrict,
  seal_obligation boolean not null,
  primary key(deletion_id,obligation_id)
);

create function record_platform_internal.local_blob_gc_authority(jsonb,boolean)
returns text language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; target_record text;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform record_platform_internal.local_blob_admission((v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid);
  if $2 then
    select g.record_id into strict target_record from public.record_deletion_gates g where g.operation_id=v->>'operation_id';
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
      (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,target_record);
  elsif v->>'operation_id' is not null or v->>'operation_owner_id' is not null
    or v->>'operation_generation' is not null or v->>'operation_expires_at' is not null then
    raise exception using errcode='42501',message='ordinary local GC cannot use purge authority';
  end if;
  return target_record;
end $$;

create function record_platform_internal.local_blob_gc_prepare(bytea,boolean)
returns public.blob_gc_deletions language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; g public.blob_gc_deletions; target_record text;
begin
  v:=record_platform_internal.local_blob_command($1,array['deletion_id','namespace_id','incarnation_id','key',
    'operation_id','operation_owner_id','operation_generation','operation_expires_at','expected_version','orphaned_before','publication_id']);
  target_record:=record_platform_internal.local_blob_gc_authority(v,$2);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  select * into g from public.blob_gc_deletions where deletion_id=v->>'deletion_id' for update;
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  if g.deletion_id is not null then
    if g.local_contract_version<>2 or row(g.namespace_id,g.incarnation_id,g.blob_key,g.operation_id) is distinct from
      row((v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,v->>'key',v->>'operation_id') then
      raise exception using errcode='55000',message='local GC task identity conflict';
    end if;
    if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
    return g;
  end if;
  if v->>'expected_version' is not null and not exists(select 1 from public.blob_objects b
    where b.namespace_id=(v->>'namespace_id')::uuid and b.blob_key=v->>'key' and b.object_version=v->>'expected_version'
      and (v->>'orphaned_before' is null or b.created_at<=(v->>'orphaned_before')::timestamptz)) then
    raise exception using errcode='55000',message='local GC discovery changed';
  end if;
  if v->>'publication_id' is not null and not exists(select 1 from public.blob_publication_intents p
    where p.publication_id=v->>'publication_id' and p.namespace_id=(v->>'namespace_id')::uuid and p.blob_key=v->>'key'
      and p.backend_kind='local' and p.publication_state<>'completed' and p.publish_expires_at<=clock_timestamp()) then
    raise exception using errcode='55000',message='local publication cleanup discovery changed';
  end if;
  if not exists(select 1 from public.record_write_obligations o where o.namespace_id=(v->>'namespace_id')::uuid
    and o.incarnation_id=(v->>'incarnation_id')::uuid and o.canonical_key=v->>'key') and v->>'publication_id' is null then
    raise exception using errcode='55000',message='local GC provenance unavailable';
  end if;
  if $2 and not (
    exists(select 1 from public.record_attachments a where
      (a.record_id=target_record or a.draft_id in (select d.draft_id from public.record_drafts d where d.record_id=target_record))
      and v->>'key' in (a.blob_key,a.preview_blob_key))
    or exists(select 1 from public.attachment_upload_parts p join public.attachment_uploads u on u.upload_id=p.upload_id
      join public.record_attachments a on a.attachment_id=u.attachment_id where
        (a.record_id=target_record or a.draft_id in (select d.draft_id from public.record_drafts d where d.record_id=target_record))
        and 'sha256/'||encode(p.sha256_digest,'hex')=v->>'key')
    or exists(select 1 from public.record_write_obligations o where o.namespace_id=(v->>'namespace_id')::uuid
      and o.canonical_key=v->>'key' and (o.record_id=target_record or o.operation_id=v->>'operation_id'
        or exists(select 1 from public.record_write_obligation_targets t
          where t.obligation_id=o.obligation_id and t.record_id=target_record)))) then
    raise exception using errcode='42501',message='purge does not own local GC target';
  end if;
  -- Pending tasks already fence publication; do not strand a live writer
  -- behind a task that its own responsibility prevents from being claimed.
  if exists(select 1 from public.record_write_obligations o
    where o.namespace_id=(v->>'namespace_id')::uuid and o.canonical_key=v->>'key'
      and o.cleanup_completed_at is null and o.outcome not in ('failed','local_excluded') and o.published_at is null
      and not record_platform_internal.local_blob_origin_closed(o.obligation_id)) then
    raise exception using errcode='55000',message='writable responsibility prevents local GC';
  end if;
  insert into public.blob_gc_deletions(deletion_id,project_id,purge_mode,blob_key,sha256_digest,backend_kind,
    deletion_state,namespace_id,incarnation_id,operation_id,local_contract_version)
    values(v->>'deletion_id','default',case when $2 then 'permanent' else 'ordinary' end,v->>'key',
      decode(substr(v->>'key',8),'hex'),'local','pending',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,
      v->>'operation_id',2) returning * into g;
  if $2 then
    perform record_platform_internal.local_blob_gc_authority(v,true);
  end if;
  return g;
end $$;

create function record_platform_internal.local_blob_gc_snapshot(text)
returns jsonb language sql stable security definer set search_path=pg_catalog
as $$
  select jsonb_build_object('task',to_jsonb(g),'referenced',record_platform_internal.local_blob_key_referenced(g.namespace_id,g.blob_key),
    'obligations',coalesce((select jsonb_agg(to_jsonb(o)||jsonb_build_object('sha256',encode(o.sha256_digest,'hex')) order by o.obligation_id)
      from public.record_write_obligations o where o.namespace_id=g.namespace_id and o.incarnation_id=g.incarnation_id
        and o.canonical_key=g.blob_key),'[]'::jsonb))
  from public.blob_gc_deletions g where g.deletion_id=$1
$$;

create function record_platform_internal.local_blob_gc_claim(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; g public.blob_gc_deletions; result jsonb;
begin
  v:=record_platform_internal.local_blob_command($1,array['deletion_id','namespace_id','incarnation_id',
    'anchor_inode','anchor_nonce','cleanup_owner_id','cleanup_generation','cleanup_expires_at','cleanup_dispatch_id',
    'operation_id','operation_owner_id','operation_generation','operation_expires_at']);
  perform record_platform_internal.local_blob_gc_authority(v,$2);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  select * into strict g from public.blob_gc_deletions where deletion_id=v->>'deletion_id' for update;
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  if g.local_contract_version<>2 or row(g.namespace_id,g.incarnation_id,g.operation_id) is distinct from
    row((v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,v->>'operation_id')
    or not exists(select 1 from public.local_blob_key_anchors a where a.namespace_id=g.namespace_id
      and a.incarnation_id=g.incarnation_id and a.canonical_key=g.blob_key
      and a.lock_inode=(v->>'anchor_inode')::bigint and a.lock_nonce=(v->>'anchor_nonce')::uuid) then
    raise exception using errcode='42501',message='local GC claim identity conflict';
  end if;
  if g.deletion_state='completed' then
    result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
    if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
    return result;
  end if;
  if row(coalesce(g.owner_generation,0),g.lease_expires_at) is distinct from
    row((v->>'cleanup_generation')::bigint,(v->>'cleanup_expires_at')::timestamptz)
    or (g.owner_id is not null and g.owner_id<>v->>'cleanup_owner_id' and g.lease_expires_at>clock_timestamp()) then
    raise exception using errcode='55000',message='local GC claim changed or live';
  end if;
  perform 1 from public.record_write_obligations o where o.namespace_id=g.namespace_id
    and o.canonical_key=g.blob_key order by o.obligation_id for update;
  if exists(select 1 from public.record_write_obligations o where o.namespace_id=g.namespace_id and o.canonical_key=g.blob_key
    and o.cleanup_completed_at is null and o.outcome not in ('failed','local_excluded') and o.published_at is null
    and not record_platform_internal.local_blob_origin_closed(o.obligation_id)) then
    raise exception using errcode='55000',message='writable responsibility prevents local GC';
  end if;
  if exists(select 1 from public.record_write_obligations o where o.namespace_id=g.namespace_id and o.canonical_key=g.blob_key
    and o.cleanup_completed_at is null and o.cleanup_owner_id is not null
    and o.cleanup_owner_id<>v->>'cleanup_owner_id' and o.cleanup_expires_at>clock_timestamp()) then
    raise exception using errcode='55000',message='local responsibility cleanup claim is live';
  end if;
  update public.blob_gc_deletions set deletion_state='claimed',owner_id=v->>'cleanup_owner_id',
    owner_generation=coalesce(owner_generation,0)+1,attempt=coalesce(attempt,0)+1,lease_expires_at=clock_timestamp()+interval '1 minute',
    cleanup_dispatch_id=(v->>'cleanup_dispatch_id')::uuid,retry_at=null,updated_at=clock_timestamp()
    where deletion_id=g.deletion_id returning * into g;
  insert into public.local_blob_gc_obligations(deletion_id,obligation_id,seal_obligation)
    select g.deletion_id,o.obligation_id,o.cleanup_completed_at is null
      and o.operation_id is not distinct from g.operation_id
      and (g.operation_id is not null or coalesce(record_platform_internal.local_blob_origin_closed(o.obligation_id),false))
    from public.record_write_obligations o where o.namespace_id=g.namespace_id and o.incarnation_id=g.incarnation_id
      and o.canonical_key=g.blob_key on conflict do nothing;
  update public.record_write_obligations o set handed_off_at=coalesce(handed_off_at,clock_timestamp()),
    outcome=case when dispatched_at is null then 'local_excluded' else outcome end
    where exists(select 1 from public.local_blob_gc_obligations l where l.deletion_id=g.deletion_id
      and l.obligation_id=o.obligation_id and l.seal_obligation) and o.cleanup_completed_at is null;
  result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  return result;
end $$;

create function record_platform_internal.local_blob_gc_current(jsonb,boolean)
returns public.blob_gc_deletions language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; g public.blob_gc_deletions;
begin
  perform record_platform_internal.local_blob_gc_authority(v,$2);
  select * into strict g from public.blob_gc_deletions where deletion_id=v->>'deletion_id' for update;
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  if g.local_contract_version<>2 or row(g.namespace_id,g.incarnation_id,g.operation_id,g.owner_id,g.owner_generation,g.lease_expires_at,g.cleanup_dispatch_id)
    is distinct from row((v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,v->>'operation_id',v->>'cleanup_owner_id',
      (v->>'cleanup_generation')::bigint,(v->>'cleanup_expires_at')::timestamptz,(v->>'cleanup_dispatch_id')::uuid)
    or (g.deletion_state<>'completed' and (g.deletion_state<>'claimed' or g.lease_expires_at<=clock_timestamp())) then
    raise exception using errcode='42501',message='local GC current claim unavailable';
  end if;
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  return g;
end $$;

create function record_platform_internal.local_blob_gc_resolve(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; g public.blob_gc_deletions; result jsonb;
begin
  v:=record_platform_internal.local_blob_command($1,array['deletion_id','namespace_id','incarnation_id','cleanup_owner_id',
    'cleanup_dispatch_id','operation_id','operation_owner_id','operation_generation','operation_expires_at']);
  perform record_platform_internal.local_blob_gc_authority(v,$2);
  select * into strict g from public.blob_gc_deletions where deletion_id=v->>'deletion_id';
  if g.local_contract_version<>2 or row(g.namespace_id,g.incarnation_id,g.operation_id,g.owner_id,g.cleanup_dispatch_id)
    is distinct from row((v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,v->>'operation_id',v->>'cleanup_owner_id',(v->>'cleanup_dispatch_id')::uuid)
    or (g.deletion_state<>'completed' and (g.deletion_state<>'claimed' or g.lease_expires_at<=clock_timestamp())) then
    raise exception using errcode='42501',message='local GC dispatch readback unavailable';
  end if;
  result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  return result;
end $$;

create function record_platform_internal.local_blob_gc_bind_final(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; g public.blob_gc_deletions; expected_size bigint; present boolean; result jsonb;
begin
  v:=record_platform_internal.local_blob_command($1,array['deletion_id','namespace_id','incarnation_id','cleanup_owner_id',
    'cleanup_generation','cleanup_expires_at','cleanup_dispatch_id','operation_id','operation_owner_id','operation_generation',
    'operation_expires_at','version','device','inode','inventory_digest']);
  g:=record_platform_internal.local_blob_gc_current(v,$2);
  if g.deletion_state='completed' then
    result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
    if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
    return result;
  end if;
  present:=v->>'version' is not null;
  if present then
    select o.size_bytes into expected_size from public.record_write_obligations o
      where o.namespace_id=g.namespace_id and o.incarnation_id=g.incarnation_id and o.canonical_key=g.blob_key
        and o.dispatched_at is not null and 'local-v2-'||o.obligation_id=v->>'version';
    if expected_size is null or (v->>'device')::bigint<0 or (v->>'inode')::bigint<=0 then
      raise exception using errcode='55000',message='local final materialization provenance unavailable';
    end if;
  elsif (v->>'device')::bigint<>0 or (v->>'inode')::bigint<>0 then
    raise exception using errcode='22023',message='absent local final has physical identity';
  end if;
  if g.final_identity_bound then
    if row(g.final_was_present,g.object_version,g.final_device,g.final_inode,g.inventory_digest) is distinct from
      row(present,v->>'version',case when present then (v->>'device')::bigint end,
        case when present then (v->>'inode')::bigint end,decode(v->>'inventory_digest','hex')) then
      raise exception using errcode='55000',message='local final binding replay conflict';
    end if;
  else
    update public.blob_gc_deletions set final_identity_bound=true,final_was_present=present,object_version=v->>'version',
      size_bytes=expected_size,final_device=case when present then (v->>'device')::bigint end,
      final_inode=case when present then (v->>'inode')::bigint end,inventory_digest=decode(v->>'inventory_digest','hex')
      where deletion_id=g.deletion_id;
  end if;
  result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  return result;
end $$;

create function record_platform_internal.local_blob_gc_complete(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; g public.blob_gc_deletions; retained boolean; removed bigint; receipt bytea; result jsonb;
begin
  v:=record_platform_internal.local_blob_command($1,array['deletion_id','namespace_id','incarnation_id','cleanup_owner_id',
    'cleanup_generation','cleanup_expires_at','cleanup_dispatch_id','operation_id','operation_owner_id','operation_generation',
    'operation_expires_at','outcome','inventory_digest']);
  perform record_platform_internal.local_blob_gc_authority(v,$2);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  g:=record_platform_internal.local_blob_gc_current(v,$2);
  if g.deletion_state='completed' then
    if g.completion_command is distinct from $1 then raise exception using errcode='55000',message='local GC completion replay conflict'; end if;
    result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
    if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
    return result;
  end if;
  retained:=record_platform_internal.local_blob_key_referenced(g.namespace_id,g.blob_key);
  if not g.final_identity_bound or g.inventory_digest is distinct from decode(v->>'inventory_digest','hex')
    or v->>'outcome' is null or v->>'outcome' not in ('deleted','already_absent','retained_referenced')
    or retained is distinct from (v->>'outcome'='retained_referenced')
    or (v->>'outcome'='deleted' and not g.final_was_present) then
    raise exception using errcode='55000',message='local GC completion evidence conflict';
  end if;
  receipt:=record_platform_internal.digest(convert_to('HOUFENG-LOCAL-GC-V2','UTF8')||$1,'sha256');
  if not retained then
    delete from public.blob_gc_pins p using public.blob_objects b
      where b.namespace_id=g.namespace_id and b.blob_key=g.blob_key
        and p.blob_key=b.blob_key and p.blob_object_version=b.object_version and p.expires_at<=statement_timestamp();
    delete from public.blob_objects where namespace_id=g.namespace_id and blob_key=g.blob_key returning size_bytes into removed;
    if removed is not null then
      update public.attachment_quota_accounts set physical_bytes=physical_bytes-removed,quota_version=quota_version+1,updated_at=clock_timestamp()
        where project_id=g.project_id and physical_bytes>=removed;
      if not found then raise exception using errcode='55000',message='local GC quota settlement conflict'; end if;
    end if;
  end if;
  update public.record_write_obligations o set cleanup_outcome=v->>'outcome',cleanup_receipt=receipt,
    cleanup_completed_at=clock_timestamp(),quota_settled_at=case when not retained then clock_timestamp() end
    where exists(select 1 from public.local_blob_gc_obligations l where l.deletion_id=g.deletion_id
      and l.obligation_id=o.obligation_id and l.seal_obligation) and o.cleanup_completed_at is null;
  update public.blob_publication_intents p set publication_state='completed',completion_outcome=v->>'outcome',
    object_version=case when v->>'outcome'='deleted' then coalesce(p.object_version,g.object_version) else p.object_version end,
    cleanup_owner_id=g.owner_id,cleanup_generation=g.owner_generation,attempt=g.attempt,cleanup_lease_expires_at=g.lease_expires_at,
    retry_at=null,receipt_digest=receipt,completed_at=clock_timestamp()
    where p.namespace_id=g.namespace_id and p.backend_kind='local' and p.blob_key=g.blob_key
      and p.publication_state<>'completed' and p.publish_expires_at<=clock_timestamp();
  update public.blob_gc_deletions set deletion_state='completed',physical_delete_result=v->>'outcome',receipt_digest=receipt,
    completion_command=$1,completed_at=clock_timestamp(),updated_at=clock_timestamp() where deletion_id=g.deletion_id;
  result:=record_platform_internal.local_blob_gc_snapshot(g.deletion_id);
  if $2 then perform record_platform_internal.local_blob_gc_authority(v,true); end if;
  return result;
end $$;

create function public.local_blob_gc_prepare(bytea) returns public.blob_gc_deletions language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_blob_gc_prepare($1,false) $$;
create function public.local_blob_purge_prepare(bytea) returns public.blob_gc_deletions language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_blob_gc_prepare($1,true) $$;
