revoke all on function record_platform_internal.local_blob_gc_authority(jsonb,boolean),
  record_platform_internal.local_blob_gc_prepare(bytea,boolean),record_platform_internal.local_blob_gc_snapshot(text),
  record_platform_internal.local_blob_gc_claim(bytea,boolean),record_platform_internal.local_blob_gc_current(jsonb,boolean),
  record_platform_internal.local_blob_gc_resolve(bytea,boolean),record_platform_internal.local_blob_gc_bind_final(bytea,boolean),
  record_platform_internal.local_blob_gc_complete(bytea,boolean),public.local_blob_gc_prepare(bytea),public.local_blob_purge_prepare(bytea),
  public.local_blob_gc_claim(bytea),public.local_blob_gc_resolve(bytea),public.local_blob_gc_bind_final(bytea),public.local_blob_gc_complete(bytea),
  public.local_blob_purge_task_claim(bytea),public.local_blob_purge_task_resolve(bytea),public.local_blob_purge_bind_final(bytea),
  public.local_blob_purge_task_complete(bytea) from public;

-- Recording the exact return does not authorize a new reference. Consumption
-- separately validates the current business owner and its record gate.
create function public.record_blob_publication_bind(bytea)
returns public.blob_publication_intents language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; p public.blob_publication_intents;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['publication_id','obligation_id']);
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='publication requires read committed isolation';
  end if;
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id';
  if o.backend_kind='local' then
    perform record_platform_internal.local_blob_admission(o.namespace_id,o.incarnation_id);
  else
    perform public.source_application_admit();
  end if;
  lock table public.blob_objects in row exclusive mode;
  lock table public.attachment_upload_parts in row exclusive mode;
  if exists(select 1 from public.blob_gc_deletions g where g.backend_kind=o.backend_kind and g.blob_key=o.canonical_key
      and (g.namespace_id is not distinct from o.namespace_id or (o.backend_kind='local' and g.namespace_id is null))
      and g.deletion_state<>'completed')
    or exists(select 1 from public.record_write_obligations w where w.backend_kind=o.backend_kind
      and w.namespace_id is not distinct from o.namespace_id and w.canonical_key=o.canonical_key
      and w.cleanup_owner_id is not null and w.cleanup_completed_at is null) then
    raise exception using errcode='55000',message='publication key has active cleanup responsibility';
  end if;
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id' for update;
  select * into strict p from public.blob_publication_intents where publication_id=v->>'publication_id' for update;
  if o.writer_principal<>session_user or o.outcome<>'materialized' or o.dispatched_at is null or o.returned_at is null
    or o.object_version is null or o.handed_off_at is not null or o.cleanup_completed_at is not null
    or row(o.publication_id,o.project_id,o.origin_kind,o.origin_id,o.origin_generation,o.backend_kind,o.namespace_id,
      o.canonical_key,o.sha256_digest,o.size_bytes) is distinct from
      row(p.publication_id,p.project_id,p.owner_kind,p.owner_id,p.owner_generation,p.backend_kind,p.namespace_id,
      p.blob_key,p.sha256_digest,p.size_bytes)
    or p.publication_state not in ('prepared','published') then
    raise exception using errcode='55000',message='publication return evidence conflict';
  end if;
  if p.publication_state='published' then
    if row(p.object_version,p.obligation_id) is distinct from row(o.object_version,o.obligation_id) then
      raise exception using errcode='55000',message='publication version replay conflict';
    end if;
    return p;
  end if;
  update public.blob_publication_intents set object_version=o.object_version,obligation_id=o.obligation_id,
    publication_state='published' where publication_id=p.publication_id returning * into p;
  return p;
end $$;
revoke all on function public.record_blob_publication_bind(bytea) from public;

create function record_platform_internal.record_artifact_publication_origin(jsonb,text)
returns public.record_write_obligations language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; o public.record_write_obligations; route record; expiry timestamptz;
begin
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id';
  if o.backend_kind='local' then
    perform record_platform_internal.local_blob_admission(o.namespace_id,o.incarnation_id);
  else
    perform public.source_application_admit();
  end if;
  if row(o.origin_kind,o.origin_id,o.backend_kind,o.namespace_id,o.canonical_key,o.object_version,o.sha256_digest,o.size_bytes)
    is distinct from row($2,v->>'job_id',v->>'backend_kind',nullif(v->>'namespace_id','')::uuid,
      v->>'key',v->>'version',decode(v->>'sha256','hex'),(v->>'size')::bigint) then
    raise exception using errcode='55000',message='artifact write provenance conflict';
  end if;
  select * into strict route from record_platform_internal.record_write_origin(convert_from(o.registration_command,'UTF8')::jsonb);
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id' for update;
  if o.writer_principal<>session_user or o.outcome<>'materialized' or o.returned_at is null or o.object_version is null
    or o.handed_off_at is not null or o.cleanup_owner_id is not null or o.cleanup_completed_at is not null
    or row(o.record_id,o.record_epoch) is distinct from row(route.record_id,route.record_epoch) then
    raise exception using errcode='55000',message='artifact publication authority unavailable';
  end if;
  if $2='export_artifact' then
    select expires_at into strict expiry from public.record_export_jobs where export_job_id=o.origin_id;
  else
    select expires_at into strict expiry from public.record_import_jobs where import_job_id=o.origin_id;
  end if;
  if (v->>'expires_at')::timestamptz>expiry or (v->>'expires_at')::timestamptz<=clock_timestamp() then
    raise exception using errcode='55000',message='artifact publication expiry conflict';
  end if;
  return o;
end $$;

create function public.record_export_artifact_publish(bytea)
returns public.record_export_artifacts language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; a public.record_export_artifacts;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['artifact_id','job_id','kind','content_type','backend_kind',
    'namespace_id','key','version','sha256','size','expires_at','obligation_id']);
  for pass in 1..2 loop
  select * into a from public.record_export_artifacts where export_job_id=v->>'job_id' and artifact_kind=v->>'kind';
  if found then
    if row(a.content_type,a.backend_kind,a.namespace_id,a.blob_key,a.object_version_id,a.sha256,a.byte_size,a.expires_at,a.obligation_id)
      is distinct from row(v->>'content_type',v->>'backend_kind',nullif(v->>'namespace_id','')::uuid,v->>'key',v->>'version',
        decode(v->>'sha256','hex'),(v->>'size')::bigint,(v->>'expires_at')::timestamptz,v->>'obligation_id') or a.revoked_at is not null then
      raise exception using errcode='55000',message='export artifact publication replay conflict';
    end if;
    return a;
  end if;
  if pass=1 then o:=record_platform_internal.record_artifact_publication_origin(v,'export_artifact'); end if;
  end loop;
  if not exists(select 1 from public.record_export_jobs where export_job_id=o.origin_id and export_kind=v->>'kind') then
    raise exception using errcode='55000',message='export artifact kind conflicts with job';
  end if;
  insert into public.record_export_artifacts(export_artifact_id,export_job_id,artifact_kind,content_type,
    backend_kind,namespace_id,blob_key,object_version_id,sha256,byte_size,expires_at,obligation_id)
    values(v->>'artifact_id',o.origin_id,v->>'kind',v->>'content_type',o.backend_kind,o.namespace_id,
      o.canonical_key,o.object_version,o.sha256_digest,o.size_bytes,(v->>'expires_at')::timestamptz,o.obligation_id)
    returning * into a;
  update public.record_write_obligations set published_at=coalesce(published_at,clock_timestamp()) where obligation_id=o.obligation_id;
  return a;
end $$;

create function public.record_import_artifact_publish(bytea)
returns public.record_import_artifacts language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; a public.record_import_artifacts;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['artifact_id','job_id','kind','backend_kind',
    'namespace_id','key','version','sha256','size','expires_at','obligation_id']);
  if v->>'kind' is distinct from 'archive' then
    raise exception using errcode='22023',message='invalid import artifact publication role';
  end if;
  for pass in 1..2 loop
  select * into a from public.record_import_artifacts where import_job_id=v->>'job_id' and artifact_role='archive';
  if found then
    if row(a.backend_kind,a.namespace_id,a.blob_key,a.object_version_id,a.sha256,a.byte_size,a.expires_at,a.obligation_id)
      is distinct from row(v->>'backend_kind',nullif(v->>'namespace_id','')::uuid,v->>'key',v->>'version',
        decode(v->>'sha256','hex'),(v->>'size')::bigint,(v->>'expires_at')::timestamptz,v->>'obligation_id') then
      raise exception using errcode='55000',message='import artifact publication replay conflict';
    end if;
    return a;
  end if;
  if pass=1 then o:=record_platform_internal.record_artifact_publication_origin(v,'import_archive'); end if;
  end loop;
  insert into public.record_import_artifacts(import_artifact_id,import_job_id,artifact_role,backend_kind,
    namespace_id,blob_key,object_version_id,sha256,byte_size,expires_at,obligation_id)
    values(v->>'artifact_id',o.origin_id,'archive',o.backend_kind,o.namespace_id,o.canonical_key,o.object_version,
      o.sha256_digest,o.size_bytes,(v->>'expires_at')::timestamptz,o.obligation_id) returning * into a;
  update public.record_write_obligations set published_at=coalesce(published_at,clock_timestamp()) where obligation_id=o.obligation_id;
  return a;
end $$;

create function public.record_export_artifact_revoke(bytea)
returns bigint language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; changed bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['job_id','lock_version']);
  perform record_platform_internal.record_blob_strong_fence();
  update public.record_export_jobs set job_state='revoked',lock_version=lock_version+1,updated_at=clock_timestamp()
    where export_job_id=v->>'job_id' and lock_version=(v->>'lock_version')::bigint;
  get diagnostics changed=row_count;
  if changed=0 then return 0; end if;
  update public.record_export_artifacts set revoked_at=clock_timestamp()
    where export_job_id=v->>'job_id' and revoked_at is null;
  update public.record_write_obligations set handed_off_at=coalesce(handed_off_at,clock_timestamp()),
    outcome=case when backend_kind='local' and dispatched_at is null then 'local_excluded' else outcome end
    where origin_kind='export_artifact' and origin_id=v->>'job_id';
  return changed;
end $$;
revoke all on function record_platform_internal.record_artifact_publication_origin(jsonb,text),
  public.record_export_artifact_publish(bytea),public.record_import_artifact_publish(bytea),
  public.record_export_artifact_revoke(bytea) from public;

create function public.record_blob_publication_prepare(bytea)
returns public.blob_publication_intents language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; origin jsonb; p public.blob_publication_intents; ns uuid; incarnation uuid; upload text; draft text; expiry timestamptz;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['publication_id','project_id','owner_kind','owner_id','owner_generation',
    'key','sha256','size','backend_kind','namespace_id','publish_expires_at','origin_owner_id','origin_owner_expires_at']);
  if v->>'project_id' is distinct from 'default' or v->>'owner_kind' not in ('upload','processor_preview') then
    raise exception using errcode='22023',message='invalid publication owner';
  end if;
  ns:=nullif(v->>'namespace_id','')::uuid;
  if v->>'backend_kind'='local' then
    select current_incarnation_id into strict incarnation from public.local_blob_namespaces where namespace_id=ns;
    perform record_platform_internal.local_blob_admission(ns,incarnation);
  elsif v->>'backend_kind' is distinct from 's3' or ns is not null then
    raise exception using errcode='22023',message='invalid publication backend identity';
  end if;
  if v->>'owner_kind'='upload' then
    if v->>'origin_owner_id' is not null or v->>'origin_owner_expires_at' is not null then
      raise exception using errcode='22023',message='upload publication cannot use processor authority';
    end if;
    upload:=v->>'owner_id';
  else
    select upload_id into upload from public.attachment_processor_jobs where processor_job_id=v->>'owner_id';
    if not found then
      raise exception using errcode='55000',message='processor write claim unavailable';
    end if;
  end if;
  select origin_draft_id into draft from public.attachment_uploads where upload_id=upload;
  if not found then
    raise exception using errcode='55000',message='upload write owner unavailable';
  end if;
  origin:=jsonb_build_object('project_id',v->>'project_id','origin_kind',v->>'owner_kind','origin_id',v->>'owner_id',
    'origin_generation',v->>'owner_generation','origin_owner_id',v->>'origin_owner_id',
    'origin_owner_generation',case when v->>'owner_kind'='processor_preview' then v->>'owner_generation' end,
    'origin_owner_expires_at',v->>'origin_owner_expires_at','draft_id',draft,
    'backend_kind',v->>'backend_kind','namespace_id',ns,'key',v->>'key');
  perform record_platform_internal.record_write_origin(origin);
  if v->>'owner_kind'='upload' then
    select expires_at into strict expiry from public.attachment_uploads where upload_id=upload;
  else
    select expires_at into strict expiry from public.attachment_processor_jobs where processor_job_id=v->>'owner_id';
  end if;
  if (v->>'publish_expires_at')::timestamptz>expiry or (v->>'publish_expires_at')::timestamptz<=clock_timestamp() then
    raise exception using errcode='55000',message='publication owner deadline conflict';
  end if;
  select * into p from public.blob_publication_intents where blob_key=v->>'key' and publication_state<>'completed' for update;
  if found then
    if row(p.project_id,p.owner_kind,p.owner_id,p.backend_kind,p.namespace_id,p.blob_key,p.sha256_digest,p.size_bytes,p.publish_expires_at)
      is distinct from row(v->>'project_id',v->>'owner_kind',v->>'owner_id',v->>'backend_kind',ns,v->>'key',
        decode(v->>'sha256','hex'),(v->>'size')::bigint,(v->>'publish_expires_at')::timestamptz)
      or p.publication_state not in ('prepared','published')
      or p.owner_generation>(v->>'owner_generation')::bigint
      or (p.owner_generation<>(v->>'owner_generation')::bigint and p.owner_kind<>'processor_preview') then
      raise exception using errcode='55000',message='publication preparation replay conflict';
    end if;
    if p.owner_generation<(v->>'owner_generation')::bigint then
      update public.blob_publication_intents set owner_generation=(v->>'owner_generation')::bigint
        where publication_id=p.publication_id returning * into p;
    end if;
    return p;
  end if;
  insert into public.blob_publication_intents(publication_id,project_id,owner_kind,owner_id,owner_generation,
    blob_key,sha256_digest,size_bytes,backend_kind,namespace_id,publication_state,publish_expires_at)
    values(v->>'publication_id',v->>'project_id',v->>'owner_kind',v->>'owner_id',(v->>'owner_generation')::bigint,
      v->>'key',decode(v->>'sha256','hex'),(v->>'size')::bigint,v->>'backend_kind',ns,'prepared',
      (v->>'publish_expires_at')::timestamptz) returning * into p;
  return p;
end $$;
revoke all on function public.record_blob_publication_prepare(bytea) from public;

create function public.record_upload_part_publish(bytea)
returns public.blob_publication_intents language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.blob_publication_intents; o public.record_write_obligations; route record;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['publication_id','obligation_id','upload_id']);
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id';
  if o.backend_kind='local' then
    perform record_platform_internal.local_blob_admission(o.namespace_id,o.incarnation_id);
  else
    perform public.source_application_admit();
  end if;
  select * into strict p from public.blob_publication_intents where publication_id=v->>'publication_id';
  if p.owner_kind<>'upload' or p.owner_id is distinct from v->>'upload_id'
    or p.obligation_id is distinct from o.obligation_id
    or row(o.publication_id,o.project_id,o.origin_kind,o.origin_id,o.origin_generation,o.backend_kind,o.namespace_id,
      o.canonical_key,o.object_version,o.sha256_digest,o.size_bytes) is distinct from
      row(p.publication_id,p.project_id,p.owner_kind,p.owner_id,p.owner_generation,p.backend_kind,p.namespace_id,
        p.blob_key,p.object_version,p.sha256_digest,p.size_bytes)
    or o.writer_principal<>session_user or o.outcome<>'materialized' or o.returned_at is null then
    raise exception using errcode='55000',message='upload part publication provenance conflict';
  end if;
  if p.publication_state='completed' and p.completion_outcome='consumed' then
    if not exists(select 1 from public.attachment_upload_parts part where part.upload_id=p.owner_id and part.part_number=1
      and row(part.size_bytes,part.sha256_digest,part.object_version,part.namespace_id,part.obligation_id)
        is not distinct from row(p.size_bytes,p.sha256_digest,p.object_version,p.namespace_id,p.obligation_id)) then
      raise exception using errcode='55000',message='consumed upload part unavailable';
    end if;
    return p;
  end if;
  select * into strict route from record_platform_internal.record_write_origin(convert_from(o.registration_command,'UTF8')::jsonb);
  select * into strict o from public.record_write_obligations where obligation_id=o.obligation_id for update;
  select * into strict p from public.blob_publication_intents where publication_id=p.publication_id for update;
  if p.publication_state<>'published' or p.publish_expires_at<=clock_timestamp()
    or o.handed_off_at is not null or o.cleanup_owner_id is not null or o.cleanup_completed_at is not null
    or row(o.record_id,o.record_epoch) is distinct from row(route.record_id,route.record_epoch) then
    raise exception using errcode='55000',message='upload part publication authority unavailable';
  end if;
  insert into public.attachment_upload_parts(upload_id,part_number,size_bytes,sha256_digest,object_version,namespace_id,obligation_id)
    values(p.owner_id,1,p.size_bytes,p.sha256_digest,p.object_version,p.namespace_id,p.obligation_id)
    on conflict(upload_id,part_number) do nothing;
  if not exists(select 1 from public.attachment_upload_parts part where part.upload_id=p.owner_id and part.part_number=1
    and row(part.size_bytes,part.sha256_digest,part.object_version,part.namespace_id,part.obligation_id)
      is not distinct from row(p.size_bytes,p.sha256_digest,p.object_version,p.namespace_id,p.obligation_id)) then
    raise exception using errcode='55000',message='upload part identity conflict';
  end if;
  update public.record_write_obligations set published_at=coalesce(published_at,clock_timestamp()) where obligation_id=o.obligation_id;
  update public.blob_publication_intents set publication_state='completed',completion_outcome='consumed',
    receipt_digest=sha256_digest,completed_at=clock_timestamp() where publication_id=p.publication_id returning * into p;
  return p;
end $$;
revoke all on function public.record_upload_part_publish(bytea) from public;

-- The processor submits the exact route it discovered before acquiring the
-- shared writer protocol. JSON null is allowed only for genuinely optional
-- preview, namespace, and standalone-record identities.
create function record_platform_internal.record_processor_publication_command(bytea)
returns jsonb language plpgsql immutable set search_path=pg_catalog
as $$
declare raw json; v jsonb;
  fields constant text[] := array['job_id','owner_id','owner_generation','lease_expires_at','attempt',
    'preview_publication_id','preview_media_type','source_obligation_id','preview_obligation_id',
    'source_namespace_id','source_incarnation_id','attachment_id','upload_id','draft_id','record_id'];
  optional constant text[] := array['preview_publication_id','preview_media_type','preview_obligation_id',
    'source_namespace_id','source_incarnation_id','record_id'];
begin
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode='22023',message='invalid processor publication command';
  end if;
  raw := convert_from($1,'UTF8')::json;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw)) <> cardinality(fields)
    or (select count(distinct f.key) from json_each(raw) f) <> cardinality(fields)
    or exists(select 1 from json_each(raw) f where not (f.key=any(fields)) or
      case when f.key in ('owner_generation','attempt') then
        case when json_typeof(f.value)<>'number' or f.value::text !~ '^[1-9][0-9]*$' then true
          else f.value::text::numeric > 9223372036854775807::numeric end
      when f.key=any(optional) then json_typeof(f.value) not in ('string','null')
      else json_typeof(f.value)<>'string' end) then
    raise exception using errcode='22023',message='invalid processor publication fields';
  end if;
  v := raw::jsonb;
  if v->>'source_obligation_id' !~ '^rwo_[0-9a-f]{32}$'
    or (v->>'preview_obligation_id' is not null and v->>'preview_obligation_id' !~ '^rwo_[0-9a-f]{32}$')
    or (v->>'preview_publication_id' is null) <> (v->>'preview_obligation_id' is null)
    or (v->>'preview_publication_id' is null) <> (v->>'preview_media_type' is null)
    or (v->>'source_namespace_id' is null) <> (v->>'source_incarnation_id' is null)
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$'
    or length(v->>'job_id') not between 1 and 128 or length(v->>'attachment_id') not between 1 and 128
    or length(v->>'upload_id') not between 1 and 128 or length(v->>'draft_id') not between 1 and 128 then
    raise exception using errcode='22023',message='invalid processor publication identity';
  end if;
  return v;
end $$;
revoke all on function record_platform_internal.record_processor_publication_command(bytea) from public;

create function record_platform_internal.record_processor_publication_lock(jsonb)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; j public.attachment_processor_jobs; u public.attachment_uploads;
  a public.record_attachments; d public.record_drafts; part public.attachment_upload_parts;
  o public.record_write_obligations; preview public.record_write_obligations; p public.blob_publication_intents;
  admission public.source_authority_admission;
  observed_record text; epoch bigint; rid text; reservation_ids text[] := array[]::text[]; fence_expiry timestamptz;
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='processor publication requires read committed isolation';
  end if;
  -- Discovery is only a candidate. A missing or changed route cannot cause a
  -- late acquisition of a different record, namespace, or obligation.
  select * into j from public.attachment_processor_jobs where processor_job_id=v->>'job_id';
  if not found then raise exception using errcode='40001',message='processor job route changed'; end if;
  select * into u from public.attachment_uploads where upload_id=j.upload_id;
  if not found then raise exception using errcode='40001',message='processor upload route changed'; end if;
  select * into a from public.record_attachments where attachment_id=u.attachment_id;
  if not found then raise exception using errcode='40001',message='processor attachment route changed'; end if;
  select * into d from public.record_drafts where draft_id=u.origin_draft_id;
  if not found then raise exception using errcode='40001',message='processor draft route changed'; end if;
  observed_record := coalesce(a.record_id,d.record_id);
  select * into part from public.attachment_upload_parts where upload_id=u.upload_id and part_number=1;
  if not found then raise exception using errcode='40001',message='processor source part changed'; end if;
  select * into o from public.record_write_obligations where obligation_id=part.obligation_id;
  if not found then raise exception using errcode='40001',message='processor source obligation changed'; end if;
  if row(j.upload_id,j.attachment_id,u.attachment_id,u.origin_draft_id,observed_record,part.obligation_id,
       o.namespace_id::text,o.incarnation_id::text) is distinct from
     row(v->>'upload_id',v->>'attachment_id',v->>'attachment_id',v->>'draft_id',v->>'record_id',
       v->>'source_obligation_id',v->>'source_namespace_id',v->>'source_incarnation_id')
    or a.draft_id is distinct from u.origin_draft_id or o.record_id is distinct from observed_record then
    raise exception using errcode='40001',message='processor source route changed';
  end if;
  if v->>'preview_publication_id' is not null then
    select * into p from public.blob_publication_intents where publication_id=v->>'preview_publication_id';
    if not found or p.obligation_id is distinct from v->>'preview_obligation_id'
      or p.backend_kind is distinct from o.backend_kind or p.namespace_id is distinct from o.namespace_id then
      raise exception using errcode='40001',message='processor preview route changed';
    end if;
    select * into preview from public.record_write_obligations where obligation_id=v->>'preview_obligation_id';
    if not found or preview.record_id is distinct from observed_record
      or preview.namespace_id is distinct from o.namespace_id or preview.incarnation_id is distinct from o.incarnation_id then
      raise exception using errcode='40001',message='processor preview obligation route changed';
    end if;
  end if;
  -- The caller may already hold later ranks. Recheck this fixed prefix with
  -- nonblocking acquisitions; never wait on a newly discovered earlier row.
  begin
    select * into admission from public.source_authority_admission where singleton for share nowait;
    if found and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals principal
      where principal.principal=session_user and principal.generation=admission.generation
        and principal.purpose in ('runtime','admin','worker'))) then
      raise exception using errcode='42501',message='source application admission is closed or stale';
    end if;
    perform record_platform_internal.record_birth_launch_admit(admission);
    if not pg_try_advisory_xact_lock_shared(1213154899,1) then
      raise exception using errcode='40001',message='processor graph fence changed; restart transaction';
    end if;
    if o.backend_kind='local' then
      perform 1 from public.local_blob_namespaces n where n.namespace_id=o.namespace_id
        and n.current_incarnation_id=o.incarnation_id and n.admission_state='active' for share nowait;
      if not found then raise exception using errcode='55000',message='local namespace admission is closed or stale'; end if;
    end if;
    if not pg_try_advisory_xact_lock_shared(1213154899,81) then
      raise exception using errcode='40001',message='processor comparison fence changed; restart transaction';
    end if;
    perform record_platform_internal.record_comparison_writer_fence();
  exception when lock_not_available then
    raise exception using errcode='40001',message='processor admission changed; restart transaction';
  end;

  begin
    if observed_record is not null then
      for rid in select r.reservation_id from public.deletion_reservations r
        where r.project_id='default' and r.object_kind='record' and r.object_id=observed_record
        order by r.reservation_id collate "C" for update nowait loop
        reservation_ids:=array_append(reservation_ids,rid);
      end loop;
      select e.delivery_epoch into epoch from public.content_delivery_epochs e
        where e.project_id='default' and e.object_kind='record' and e.object_id=observed_record for update nowait;
      if not found then raise exception using errcode='55000',message='processor record epoch unavailable'; end if;
      if exists(select 1 from public.deletion_reservations r where r.project_id='default' and r.object_kind='record'
        and r.object_id=observed_record and not (r.reservation_id=any(reservation_ids))) then
        raise exception using errcode='40001',message='processor reservation route changed';
      end if;
      select l.expires_at into fence_expiry from public.deletion_fence_leases l
        where l.project_id='default' and l.object_kind='record' and l.object_id=observed_record for update nowait;
      if coalesce(fence_expiry>clock_timestamp(),false) then
        raise exception using errcode='55000',message='processor record fence is live';
      end if;
      perform 1 from public.object_content_leases l
        where l.project_id='default' and l.object_kind='record' and l.object_id=observed_record for update nowait;
      perform 1 from public.record_deletion_gates g
        where g.project_id='default' and g.record_id=observed_record for share nowait;
      if found or exists(select 1 from public.deletion_reservations r where r.project_id='default'
        and r.object_kind='record' and r.object_id=observed_record and r.state in ('fenced','committed')) then
        raise exception using errcode='55000',message='processor record gate closed';
      end if;
      perform 1 from public.records r where r.project_id='default' and r.record_id=observed_record for update nowait;
      if not found then raise exception using errcode='55000',message='processor record root unavailable'; end if;
    end if;
    perform 1 from public.attachment_quota_accounts where project_id='default' for update nowait;
    if not found then raise exception using errcode='55000',message='processor quota unavailable'; end if;
    select * into d from public.record_drafts where draft_id=v->>'draft_id' for update nowait;
    if not found then raise exception using errcode='40001',message='processor draft route changed'; end if;
    select * into a from public.record_attachments where attachment_id=v->>'attachment_id' for update nowait;
    if not found then raise exception using errcode='40001',message='processor attachment route changed'; end if;
    select * into u from public.attachment_uploads where upload_id=v->>'upload_id' for update nowait;
    if not found then raise exception using errcode='40001',message='processor upload route changed'; end if;
    select * into j from public.attachment_processor_jobs where processor_job_id=v->>'job_id' for update nowait;
    if not found or row(j.upload_id,j.attachment_id,u.attachment_id,u.origin_draft_id,coalesce(a.record_id,d.record_id))
      is distinct from row(v->>'upload_id',v->>'attachment_id',v->>'attachment_id',v->>'draft_id',v->>'record_id')
      or a.draft_id is distinct from d.draft_id then
      raise exception using errcode='40001',message='processor locked route changed';
    end if;
  exception when lock_not_available then
    raise exception using errcode='40001',message='processor route lock changed; restart transaction';
  end;
  if d.expires_at<=clock_timestamp() or u.expires_at<=clock_timestamp() or u.project_id<>'default'
    or j.processor_state<>'claimed' or j.owner_id is distinct from v->>'owner_id'
    or j.owner_generation is distinct from (v->>'owner_generation')::bigint
    or j.lease_expires_at is distinct from (v->>'lease_expires_at')::timestamptz
    or j.lease_expires_at<=clock_timestamp() or j.attempt is distinct from (v->>'attempt')::bigint
    or j.expires_at<=clock_timestamp() or u.upload_state<>'quarantined' then
    raise exception using errcode='55000',message='processor owner unavailable';
  end if;

  perform record_platform_internal.record_blob_strong_fence();
  select * into part from public.attachment_upload_parts where upload_id=u.upload_id and part_number=1 for update;
  if not found or part.obligation_id is distinct from v->>'source_obligation_id' then
    raise exception using errcode='40001',message='processor source part changed';
  end if;
  perform 1 from public.record_write_obligations w
    where w.obligation_id in (v->>'source_obligation_id',v->>'preview_obligation_id')
    order by w.obligation_id collate "C" for update;
  select * into strict o from public.record_write_obligations where obligation_id=v->>'source_obligation_id';
  if row(o.namespace_id::text,o.incarnation_id::text) is distinct from row(v->>'source_namespace_id',v->>'source_incarnation_id') then
    raise exception using errcode='40001',message='processor source namespace changed';
  end if;
  perform record_platform_internal.local_blob_write_fence(o.backend_kind,o.namespace_id,o.canonical_key,o.obligation_id);
  if o.origin_kind<>'upload' or o.origin_id<>u.upload_id or o.origin_generation<>1
    or o.outcome<>'materialized' or o.returned_at is null or o.published_at is null
    or o.handed_off_at is not null or o.cleanup_owner_id is not null or o.cleanup_completed_at is not null
    or row(o.record_id,o.record_epoch) is distinct from row(observed_record,epoch)
    or row(o.namespace_id,o.object_version,o.sha256_digest,o.size_bytes) is distinct from
      row(part.namespace_id,part.object_version,part.sha256_digest,part.size_bytes)
    or o.canonical_key is distinct from 'sha256/'||encode(part.sha256_digest,'hex')
    or o.sha256_digest is distinct from u.actual_sha256_digest or o.size_bytes is distinct from u.actual_size_bytes then
    raise exception using errcode='55000',message='processor source publication authority unavailable';
  end if;
  if v->>'preview_publication_id' is not null then
    select * into preview from public.record_write_obligations where obligation_id=v->>'preview_obligation_id';
    if not found then raise exception using errcode='40001',message='processor preview obligation changed'; end if;
    select * into p from public.blob_publication_intents where publication_id=v->>'preview_publication_id' for update;
    if not found or p.obligation_id is distinct from v->>'preview_obligation_id'
      or p.backend_kind is distinct from o.backend_kind or p.namespace_id is distinct from o.namespace_id then
      raise exception using errcode='40001',message='processor preview publication route changed';
    end if;
    perform record_platform_internal.local_blob_write_fence(p.backend_kind,p.namespace_id,p.blob_key,p.obligation_id);
    if p.owner_kind<>'processor_preview' or p.owner_id<>j.processor_job_id or p.owner_generation<>j.owner_generation
      or p.publication_state<>'published' or p.publish_expires_at<=clock_timestamp()
      or preview.origin_generation>j.owner_generation or preview.origin_kind<>'processor_preview'
      or preview.origin_id<>j.processor_job_id or preview.outcome<>'materialized' or preview.returned_at is null
      or preview.handed_off_at is not null or preview.cleanup_owner_id is not null or preview.cleanup_completed_at is not null
      or preview.incarnation_id is distinct from o.incarnation_id
      or row(preview.record_id,preview.record_epoch) is distinct from row(observed_record,epoch)
      or row(preview.publication_id,preview.backend_kind,preview.namespace_id,preview.canonical_key,preview.object_version,preview.sha256_digest,preview.size_bytes)
        is distinct from row(p.publication_id,p.backend_kind,p.namespace_id,p.blob_key,p.object_version,p.sha256_digest,p.size_bytes)
      or length(v->>'preview_media_type') not between 1 and 255 then
      raise exception using errcode='55000',message='processor preview publication authority unavailable';
    end if;
  end if;
  if j.lease_expires_at<=clock_timestamp() or j.expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='processor owner expired while waiting';
  end if;
end $$;

create function public.record_processor_publication_lock(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.record_processor_publication_command($1);
  perform record_platform_internal.record_processor_publication_lock(v);
end $$;

create function record_platform_internal.record_blob_metadata_publish(text,bytea,text,bigint,text,uuid)
returns boolean language plpgsql security definer set search_path=pg_catalog
as $$
declare changed bigint;
begin
  perform record_platform_internal.local_blob_write_fence($5,$6,$1,null);
  insert into public.blob_objects(blob_key,sha256_digest,object_version,size_bytes,backend_kind,namespace_id)
    values($1,$2,$3,$4,$5,$6) on conflict(blob_key) do nothing;
  get diagnostics changed=row_count;
  if not exists(select 1 from public.blob_objects b where b.blob_key=$1
    and row(b.sha256_digest,b.object_version,b.size_bytes,b.backend_kind,b.namespace_id) is not distinct from row($2,$3,$4,$5,$6)) then
    raise exception using errcode='55000',message='Blob metadata identity conflict';
  end if;
  return changed=1;
end $$;

create function public.record_processor_publication_finish(bytea)
returns bigint language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; j public.attachment_processor_jobs; o public.record_write_obligations;
  p public.blob_publication_intents; physical_delta bigint:=0; changed bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.record_processor_publication_command($1);
  perform record_platform_internal.record_processor_publication_lock(v);
  select * into strict j from public.attachment_processor_jobs where processor_job_id=v->>'job_id';
  select w.* into strict o from public.record_write_obligations w join public.attachment_upload_parts part
    on part.obligation_id=w.obligation_id where part.upload_id=j.upload_id and part.part_number=1;
  if record_platform_internal.record_blob_metadata_publish(o.canonical_key,o.sha256_digest,o.object_version,o.size_bytes,o.backend_kind,o.namespace_id) then
    physical_delta:=o.size_bytes;
  end if;
  if v->>'preview_publication_id' is not null then
    select * into strict p from public.blob_publication_intents where publication_id=v->>'preview_publication_id';
    if record_platform_internal.record_blob_metadata_publish(p.blob_key,p.sha256_digest,p.object_version,p.size_bytes,p.backend_kind,p.namespace_id) then
      physical_delta:=physical_delta+p.size_bytes;
    end if;
    update public.record_write_obligations set published_at=coalesce(published_at,clock_timestamp()) where obligation_id=p.obligation_id;
    update public.blob_publication_intents set publication_state='completed',completion_outcome='consumed',
      receipt_digest=sha256_digest,completed_at=clock_timestamp() where publication_id=p.publication_id;
  end if;
  update public.record_attachments a set attachment_state='available',blob_key=o.canonical_key,blob_object_version=o.object_version,
    preview_blob_key=p.blob_key,preview_blob_object_version=p.object_version,preview_media_type=v->>'preview_media_type',
    preview_size_bytes=p.size_bytes,updated_at=clock_timestamp()
    where a.attachment_id=j.attachment_id and a.project_id=o.project_id and a.attachment_state='quarantined'
      and a.record_id is null and a.draft_id=(select origin_draft_id from public.attachment_uploads where upload_id=j.upload_id)
      and a.blob_key is null and a.blob_object_version is null and a.preview_blob_key is null and a.preview_blob_object_version is null
      and a.preview_media_type is null and a.preview_size_bytes is null;
  get diagnostics changed=row_count;
  if changed<>1 then raise exception using errcode='55000',message='processor attachment publication conflict'; end if;
  update public.attachment_uploads set upload_state='available',updated_at=clock_timestamp() where upload_id=j.upload_id;
  if j.lease_expires_at<=clock_timestamp() or j.expires_at<=clock_timestamp()
    or (v->>'preview_publication_id' is not null and p.publish_expires_at<=clock_timestamp()) then
    raise exception using errcode='55000',message='processor owner expired before publication committed';
  end if;
  return physical_delta;
end $$;
revoke all on function record_platform_internal.record_processor_publication_lock(jsonb),
  public.record_processor_publication_lock(bytea), public.record_processor_publication_finish(bytea),
  record_platform_internal.record_blob_metadata_publish(text,bytea,text,bigint,text,uuid) from public;

create function record_platform_internal.record_blob_reference_fence(text,text)
returns public.blob_objects language plpgsql security definer set search_path=pg_catalog
as $$
declare b public.blob_objects; incarnation uuid;
begin
  perform public.source_application_admit();
  select * into strict b from public.blob_objects where blob_key=$1 and object_version=$2;
  if b.backend_kind='local' then
    select current_incarnation_id into strict incarnation from public.local_blob_namespaces where namespace_id=b.namespace_id;
    perform record_platform_internal.local_blob_admission(b.namespace_id,incarnation);
  end if;
  perform record_platform_internal.local_blob_write_fence(b.backend_kind,b.namespace_id,b.blob_key,null);
  select * into strict b from public.blob_objects where blob_key=$1 and object_version=$2 for share;
  return b;
end $$;

create function public.record_blob_pin_create(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.blob_gc_pins;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['pin_id','owner_kind','owner_id','key','version','expires_at']);
  perform record_platform_internal.record_blob_reference_fence(v->>'key',v->>'version');
  insert into public.blob_gc_pins(pin_id,pin_owner_kind,pin_owner_id,blob_key,blob_object_version,expires_at)
    values(v->>'pin_id',v->>'owner_kind',v->>'owner_id',v->>'key',v->>'version',(v->>'expires_at')::timestamptz)
    on conflict(pin_id) do nothing;
  select * into strict p from public.blob_gc_pins where pin_id=v->>'pin_id';
  if row(p.pin_owner_kind,p.pin_owner_id,p.blob_key,p.blob_object_version,p.expires_at) is distinct from
    row(v->>'owner_kind',v->>'owner_id',v->>'key',v->>'version',(v->>'expires_at')::timestamptz) then
    raise exception using errcode='55000',message='Blob pin publication replay conflict';
  end if;
end $$;

create function public.record_blob_pin_release(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.blob_gc_pins; b public.blob_objects; incarnation uuid;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['pin_id','owner_kind','owner_id','key','version']);
  select * into b from public.blob_objects where blob_key=v->>'key' and object_version=v->>'version';
  if found and b.backend_kind='local' then
    select current_incarnation_id into strict incarnation from public.local_blob_namespaces where namespace_id=b.namespace_id;
    perform record_platform_internal.local_blob_admission(b.namespace_id,incarnation);
  end if;
  perform record_platform_internal.record_blob_strong_fence();
  select * into p from public.blob_gc_pins where pin_id=v->>'pin_id' for update;
  if not found then return; end if;
  if row(p.pin_owner_kind,p.pin_owner_id,p.blob_key,p.blob_object_version) is distinct from
    row(v->>'owner_kind',v->>'owner_id',v->>'key',v->>'version') then
    raise exception using errcode='55000',message='Blob pin release identity conflict';
  end if;
  delete from public.blob_gc_pins where pin_id=p.pin_id;
end $$;
revoke all on function record_platform_internal.record_blob_reference_fence(text,text),
  public.record_blob_pin_create(bytea),public.record_blob_pin_release(bytea) from public;

create function record_platform_internal.record_attachment_copy_source(jsonb)
returns public.record_attachments language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; a public.record_attachments; b public.blob_objects; incarnation uuid; record_key text;
begin
  perform public.source_application_admit();
  if v->>'project_id' is distinct from 'default' then
    raise exception using errcode='22023',message='invalid attachment copy project';
  end if;
  select * into strict a from public.record_attachments where attachment_id=v->>'source_attachment_id'
    and project_id=v->>'project_id' and record_id=v->>'source_record_id' and attachment_state='available';
  select * into strict b from public.blob_objects where blob_key=a.blob_key and object_version=a.blob_object_version;
  if b.backend_kind='local' then
    select current_incarnation_id into strict incarnation from public.local_blob_namespaces where namespace_id=b.namespace_id;
    perform record_platform_internal.local_blob_admission(b.namespace_id,incarnation);
  end if;
  for record_key in select distinct value from unnest(array[v->>'source_record_id',v->>'target_record_id']) value order by value loop
    perform record_platform_internal.local_blob_record_epoch(record_key);
  end loop;
  perform record_platform_internal.local_blob_write_fence(b.backend_kind,b.namespace_id,b.blob_key,null);
  select * into strict a from public.record_attachments where attachment_id=v->>'source_attachment_id'
    and project_id=v->>'project_id' and record_id=v->>'source_record_id' and attachment_state='available' for share;
  if row(a.blob_key,a.blob_object_version) is distinct from row(b.blob_key,b.object_version)
    or not exists(select 1 from public.blob_objects current_blob where current_blob.blob_key=b.blob_key
      and row(current_blob.object_version,current_blob.backend_kind,current_blob.namespace_id)
        is not distinct from row(b.object_version,b.backend_kind,b.namespace_id)) then
    raise exception using errcode='55000',message='attachment copy source changed';
  end if;
  return a;
end $$;

create function public.record_attachment_copy_source(bytea)
returns public.record_attachments language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['project_id','source_record_id','target_record_id',
    'source_attachment_id','target_attachment_id','actor_id']);
  return record_platform_internal.record_attachment_copy_source(v);
end $$;

create function public.record_attachment_copy_publish(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; a public.record_attachments;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['project_id','source_record_id','target_record_id',
    'source_attachment_id','target_attachment_id','actor_id']);
  a:=record_platform_internal.record_attachment_copy_source(v);
  insert into public.record_attachments(attachment_id,project_id,record_id,copied_from_attachment_id,
    attachment_state,display_name,media_type,logical_size_bytes,blob_key,blob_object_version,created_by)
    values(v->>'target_attachment_id',a.project_id,v->>'target_record_id',a.attachment_id,
      'available',a.display_name,a.media_type,a.logical_size_bytes,a.blob_key,a.blob_object_version,v->>'actor_id');
end $$;
revoke all on function record_platform_internal.record_attachment_copy_source(jsonb),
  public.record_attachment_copy_source(bytea),public.record_attachment_copy_publish(bytea) from public;

create function record_platform_internal.record_attachment_draft_lock(jsonb)
returns public.record_drafts language plpgsql security definer set search_path=pg_catalog
as $$
declare v alias for $1; d public.record_drafts; initial_record text;
begin
  perform public.source_application_admit();
  select * into strict d from public.record_drafts where draft_id=v->>'draft_id'
    and project_id=v->>'project_id' and author_id=v->>'author_id';
  initial_record:=d.record_id;
  if initial_record is not null then perform record_platform_internal.local_blob_record_epoch(initial_record); end if;
  select * into strict d from public.record_drafts where draft_id=v->>'draft_id'
    and project_id=v->>'project_id' and author_id=v->>'author_id' for update;
  if d.record_id is distinct from initial_record then
    raise exception using errcode='55000',message='attachment draft owner changed';
  end if;
  return d;
end $$;

create function public.record_attachment_draft_lock(bytea)
returns public.record_drafts language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['project_id','draft_id','author_id']);
  return record_platform_internal.record_attachment_draft_lock(v);
end $$;

create function public.record_attachment_reserve(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; d public.record_drafts;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['attachment_id','project_id','draft_id','author_id','display_name','media_type','size']);
  d:=record_platform_internal.record_attachment_draft_lock(v);
  if d.expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='attachment reservation draft expired';
  end if;
  insert into public.record_attachments(attachment_id,project_id,draft_id,origin_draft_id,
    attachment_state,display_name,media_type,logical_size_bytes,created_by)
    values(v->>'attachment_id',d.project_id,d.draft_id,d.draft_id,'created',v->>'display_name',v->>'media_type',(v->>'size')::bigint,d.author_id);
end $$;

create function public.record_attachment_state_set(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; u public.attachment_uploads; changed bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['project_id','upload_id','attachment_id','draft_id','previous_state','target_state']);
  if not ((v->>'previous_state'='created' and v->>'target_state' in ('uploading','rejected','expired'))
    or (v->>'previous_state'='uploading' and v->>'target_state' in ('quarantined','rejected','expired'))
    or (v->>'previous_state'='quarantined' and v->>'target_state' in ('rejected','expired'))) then
    raise exception using errcode='22023',message='invalid attachment state transition';
  end if;
  select * into strict u from public.attachment_uploads where upload_id=v->>'upload_id' for update;
  if row(u.project_id,u.attachment_id,u.origin_draft_id,u.upload_state) is distinct from
    row(v->>'project_id',v->>'attachment_id',v->>'draft_id',v->>'target_state') then
    raise exception using errcode='55000',message='attachment state upload identity conflict';
  end if;
  update public.record_attachments set attachment_state=u.upload_state,updated_at=clock_timestamp()
    where attachment_id=u.attachment_id and project_id=u.project_id and draft_id=u.origin_draft_id
      and attachment_state=v->>'previous_state' and record_id is null
      and blob_key is null and blob_object_version is null and preview_blob_key is null and preview_blob_object_version is null
      and preview_media_type is null and preview_size_bytes is null;
  get diagnostics changed=row_count;
  if changed<>1 then raise exception using errcode='55000',message='attachment state transition conflict'; end if;
end $$;
revoke all on function record_platform_internal.record_attachment_draft_lock(jsonb),public.record_attachment_draft_lock(bytea),
  public.record_attachment_reserve(bytea),public.record_attachment_state_set(bytea) from public;

-- Acquisition only: a replay/no-op may lock a closed namespace without gaining
-- publication authority. Every mutating command still checks active admission.
create function public.record_revision_namespace_lock(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['namespace_id']);
  perform 1 from public.local_blob_namespaces where namespace_id=(v->>'namespace_id')::uuid for share;
  if not found then raise exception using errcode='55000',message='revision namespace unavailable'; end if;
end $$;

create function public.record_revision_blob_fence()
returns void language plpgsql security definer set search_path=pg_catalog
as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  perform record_platform_internal.record_blob_strong_fence();
end $$;
revoke all on function public.record_revision_namespace_lock(bytea),public.record_revision_blob_fence() from public;

create function public.record_import_attachment_publish(bytea)
returns boolean language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; o public.record_write_obligations; j public.record_import_jobs; epoch bigint; inserted boolean;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['record_id','attachment_id','obligation_id','namespace_id',
    'backend_kind','key','version','sha256','size','display_name','media_type','created_by','gc_count']);
  select * into strict o from public.record_write_obligations where obligation_id=v->>'obligation_id';
  if o.backend_kind='local' then perform record_platform_internal.local_blob_admission(o.namespace_id,o.incarnation_id); end if;
  epoch:=record_platform_internal.local_blob_record_epoch(v->>'record_id');
  perform record_platform_internal.local_blob_write_fence(o.backend_kind,o.namespace_id,o.canonical_key,o.obligation_id);
  select * into strict j from public.record_import_jobs where import_job_id=o.origin_id for update;
  select * into strict o from public.record_write_obligations where obligation_id=o.obligation_id for update;
  if o.origin_kind<>'import_attachment' or o.outcome<>'materialized' or o.returned_at is null
    or o.handed_off_at is not null or o.cleanup_owner_id is not null or o.cleanup_completed_at is not null
    or row(o.namespace_id,o.backend_kind,o.canonical_key,o.object_version,o.sha256_digest,o.size_bytes) is distinct from
      row(nullif(v->>'namespace_id','')::uuid,v->>'backend_kind',v->>'key',v->>'version',decode(v->>'sha256','hex'),(v->>'size')::bigint)
    or j.lock_version<>o.origin_generation or j.job_state not in ('planned','applying') or j.expires_at<=clock_timestamp()
    or not exists(select 1 from public.records r where r.record_id=v->>'record_id' and r.current_revision_id is not null)
    or not exists(select 1 from public.record_write_obligation_targets t join public.record_import_plans p
      on p.import_job_id=j.import_job_id and p.plan_digest=t.plan_digest
      join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id and m.entity_kind='attachment'
        and m.target_id=t.attachment_id and m.owner_target_record_id=t.record_id
      where t.obligation_id=o.obligation_id and t.record_id=v->>'record_id' and t.attachment_id=v->>'attachment_id'
        and p.plan_digest=o.plan_digest and p.expires_at>clock_timestamp()) then
    raise exception using errcode='55000',message='import attachment provenance unavailable';
  end if;
  if (select count(*) from public.blob_gc_deletions where blob_key=o.canonical_key)<>(v->>'gc_count')::bigint then
    raise exception using errcode='55000',message='import attachment GC history changed';
  end if;
  perform public.record_write_bind_record(convert_to(jsonb_build_object('record_id',v->>'record_id','origin_kind',o.origin_kind,
    'origin_id',o.origin_id,'origin_generation',o.origin_generation)::text,'UTF8'));
  if not exists(select 1 from public.record_write_obligations current_write where current_write.obligation_id=o.obligation_id
    and current_write.record_id=v->>'record_id' and current_write.record_epoch=epoch) then
    raise exception using errcode='55000',message='import attachment epoch binding conflict';
  end if;
  inserted:=record_platform_internal.record_blob_metadata_publish(o.canonical_key,o.sha256_digest,o.object_version,o.size_bytes,o.backend_kind,o.namespace_id);
  insert into public.record_attachments(attachment_id,project_id,record_id,attachment_state,display_name,media_type,
    logical_size_bytes,blob_key,blob_object_version,created_by)
    values(v->>'attachment_id',o.project_id,v->>'record_id','available',v->>'display_name',v->>'media_type',o.size_bytes,
      o.canonical_key,o.object_version,v->>'created_by');
  update public.record_write_obligations set published_at=coalesce(published_at,clock_timestamp()) where obligation_id=o.obligation_id;
  return inserted;
end $$;
revoke all on function public.record_import_attachment_publish(bytea) from public;

create function public.record_revision_attachment_publish(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; observed public.record_attachments; a public.record_attachments; d public.record_drafts;
  revision_author text; n record; origin record;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.local_blob_command($1,array['project_id','record_id','revision_id','draft_id','attachment_id','ordinal']);
  if v->>'project_id' is distinct from 'default' or (v->>'ordinal')::bigint<0 then
    raise exception using errcode='22023',message='invalid revision attachment publication';
  end if;
  select * into strict observed from public.record_attachments where attachment_id=v->>'attachment_id' and project_id=v->>'project_id';
  for n in select distinct b.namespace_id,ns.current_incarnation_id from public.blob_objects b
    join public.local_blob_namespaces ns on ns.namespace_id=b.namespace_id
    where b.blob_key in (observed.blob_key,observed.preview_blob_key) and b.backend_kind='local' order by b.namespace_id loop
    perform record_platform_internal.local_blob_admission(n.namespace_id,n.current_incarnation_id);
  end loop;
  perform record_platform_internal.local_blob_record_epoch(v->>'record_id');
  select author_id into strict revision_author from public.record_revisions
    where record_id=v->>'record_id' and revision_id=v->>'revision_id';
  if nullif(v->>'draft_id','') is not null then
    select * into strict d from public.record_drafts where draft_id=v->>'draft_id' for update;
    if d.project_id<>v->>'project_id' or d.author_id<>revision_author
      or (d.record_id is not null and d.record_id<>v->>'record_id') then
      raise exception using errcode='55000',message='revision attachment draft authority conflict';
    end if;
  end if;
  perform record_platform_internal.record_blob_strong_fence();
  select * into strict a from public.record_attachments where attachment_id=observed.attachment_id for update;
  if a.attachment_state<>'available' or row(a.blob_key,a.blob_object_version,a.preview_blob_key,a.preview_blob_object_version)
    is distinct from row(observed.blob_key,observed.blob_object_version,observed.preview_blob_key,observed.preview_blob_object_version) then
    raise exception using errcode='55000',message='revision attachment publication changed';
  end if;
  perform record_platform_internal.record_blob_reference_fence(a.blob_key,a.blob_object_version);
  if a.preview_blob_key is not null then
    perform record_platform_internal.record_blob_reference_fence(a.preview_blob_key,a.preview_blob_object_version);
  end if;
  if a.record_id=v->>'record_id' and a.draft_id is null then
    null;
  elsif a.record_id is null and a.draft_id=d.draft_id then
    update public.record_attachments set record_id=v->>'record_id',draft_id=null,updated_at=clock_timestamp()
      where attachment_id=a.attachment_id;
    for origin in select 'upload'::text as kind,u.upload_id as id,1::bigint as generation
      from public.attachment_uploads u where u.attachment_id=a.attachment_id
      union all select 'processor_preview',j.processor_job_id,j.owner_generation from public.attachment_processor_jobs j
        where j.attachment_id=a.attachment_id and j.owner_generation is not null loop
      perform public.record_write_bind_record(convert_to(jsonb_build_object('record_id',v->>'record_id',
        'origin_kind',origin.kind,'origin_id',origin.id,'origin_generation',origin.generation)::text,'UTF8'));
    end loop;
  else
    raise exception using errcode='55000',message='revision attachment ownership conflict';
  end if;
  insert into public.record_revision_attachments(record_id,revision_id,ordinal,attachment_id)
    values(v->>'record_id',v->>'revision_id',(v->>'ordinal')::bigint,a.attachment_id);
end $$;
revoke all on function public.record_revision_attachment_publish(bytea) from public;

create function record_platform_internal.record_import_plan_lock(p_job text, p_namespace_ids text)
returns public.record_import_jobs language plpgsql security definer set search_path=pg_catalog
as $$
declare j public.record_import_jobs; n record; discovered text; current_namespaces text;
  s public.source_authority_admission;
begin
  perform record_platform_internal.local_blob_direct_login();
  select * into s from public.source_authority_admission where singleton for share nowait;
  if found and (s.mode<>'active' or not exists (select 1 from public.source_application_principals p
    where p.principal=session_user and p.generation=s.generation and p.purpose in ('runtime','admin','worker'))) then
    raise exception using errcode='42501',message='source application admission is closed or stale';
  end if;
  perform record_platform_internal.record_birth_launch_admit(s);
  select coalesce(string_agg(q.namespace_id::text,',' order by q.namespace_id::text collate "C"),'') into discovered
    from (select distinct o.namespace_id from public.record_write_obligations o
      where o.origin_id=p_job and o.origin_kind in ('import_archive','import_attachment')
        and o.namespace_id is not null) q;
  if p_namespace_ids is not null and p_namespace_ids<>discovered then
    raise exception using errcode='40001',message='import plan namespace discovery changed';
  end if;
  for n in select distinct o.namespace_id from public.record_write_obligations o
    where o.origin_id=p_job and o.origin_kind in ('import_archive','import_attachment')
      and o.namespace_id is not null order by o.namespace_id loop
    -- Callers acquired these admissions before record ranks. Direct calls may
    -- recheck them here, but must never wait for an earlier-rank lock.
    if p_namespace_ids is not null and not (n.namespace_id::text=any(string_to_array(p_namespace_ids,','))) then
      raise exception using errcode='40001',message='import plan namespace discovery changed';
    end if;
    perform 1 from public.local_blob_namespaces ns where ns.namespace_id=n.namespace_id
      and ns.admission_state='active' for share nowait;
    if not found then raise exception using errcode='55000',message='local namespace admission unavailable'; end if;
  end loop;
  select * into strict j from public.record_import_jobs where import_job_id=p_job for update;
  if j.job_state not in ('uploaded','quarantined','dry_run') or j.expires_at<=clock_timestamp() then
    raise exception using errcode='55000',message='import planning authority unavailable';
  end if;
  perform record_platform_internal.record_blob_strong_fence();
  select coalesce(string_agg(q.namespace_id::text,',' order by q.namespace_id::text collate "C"),'') into current_namespaces
    from (select distinct o.namespace_id from public.record_write_obligations o
      where o.origin_id=p_job and o.origin_kind in ('import_archive','import_attachment')
        and o.namespace_id is not null) q;
  if current_namespaces<>discovered then
    raise exception using errcode='40001',message='import plan namespace discovery changed';
  end if;
  return j;
exception when lock_not_available then
  raise exception using errcode='40001',message='import plan earlier admission busy; restart transaction';
end $$;

create function public.record_import_plan_lock(bytea)
returns public.record_import_jobs language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.record_birth_command($1,array['import_job_id','namespace_ids'],'{}');
  return record_platform_internal.record_import_plan_lock(v->>'import_job_id',v->>'namespace_ids');
end $$;

create function public.record_import_mapping_insert(bytea)
returns void language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.record_import_plans; j public.record_import_jobs;
  a record; b record; matched bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.record_birth_command($1,
    array['import_plan_id','entity_kind','source_id','source_identity_digest','target_id','created_at','birth_allocation_id','owner_target_record_id'],'{}');
  select * into strict p from public.record_import_plans where import_plan_id=v->>'import_plan_id';
  j:=record_platform_internal.record_import_plan_lock(p.import_job_id,null);
  select * into strict p from public.record_import_plans where import_plan_id=v->>'import_plan_id';
  if p.import_job_id is distinct from j.import_job_id then
    raise exception using errcode='40001',message='import plan route changed; restart transaction';
  end if;
  if p.expires_at<=clock_timestamp() or v->>'source_identity_digest' !~ '^[0-9a-f]{64}$'
    or decode(v->>'source_identity_digest','hex') is distinct from sha256(convert_to(v->>'source_id','UTF8')) then
    raise exception using errcode='55000',message='import mapping identity unavailable';
  end if;
  if v->>'entity_kind'='record' then
    if v->>'birth_allocation_id' !~ '^rqa_[0-9a-f]{32}$' or v->>'target_id' !~ '^rec2_[0-9a-f]{32}$'
      or v->>'owner_target_record_id'<>'' or v->>'source_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$' then
      raise exception using errcode='22023',message='invalid import birth allocation';
    end if;
    -- This is a recheck of the caller's earlier rank-60 acquisition. A direct
    -- caller can never wait backwards across the job or Blob fence.
    perform record_platform_internal.record_birth_writer_guard(v->>'target_id');
    select * into a from record_platform_internal.record_birth_allocations
      where allocation_id=v->>'birth_allocation_id' for update nowait;
    if not found or (a.project_id,a.actor_id,a.purpose,a.record_id) is distinct from
      (j.project_id,j.actor_id,'import'::text,v->>'target_id')
      or a.idempotency_key is distinct from 'import-'||encode(sha256(convert_to(
        '{"Domain":"houfeng.record-import-allocation-key.v1","JobID":'||to_json(j.import_job_id)::text||
        ',"SourceID":'||to_json(v->>'source_id')::text||'}','UTF8')),'hex')
      or a.state not in ('allocated','preparing','prepared') then
      raise exception using errcode='55000',message='import allocation owner or state mismatch';
    end if;
    if a.domain='certifiable' then
      b:=record_platform_internal.record_birth_binding();
      if b.generation is null or (b.generation,b.key_id,b.cutover_digest) is distinct from
        (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
        raise exception using errcode='55000',message='import allocation binding is no longer current';
      end if;
    end if;
  elsif v->>'entity_kind' in ('evidence','attachment') then
    if v->>'birth_allocation_id'<>'' or v->>'owner_target_record_id' !~ '^rec2_[0-9a-f]{32}$'
      or (v->>'entity_kind'='evidence' and v->>'target_id' !~ '^evs_[a-z0-9]{1,64}$')
      or (v->>'entity_kind'='attachment' and v->>'target_id' !~ '^att_[a-z0-9]{1,64}$') then
      raise exception using errcode='22023',message='invalid import mapping owner identity';
    end if;
    perform record_platform_internal.record_birth_writer_guard(v->>'owner_target_record_id');
    select count(*) into matched from public.record_import_entity_mappings m
      where m.import_plan_id=p.import_plan_id and m.entity_kind='record'
        and m.target_id=v->>'owner_target_record_id' and m.birth_allocation_id is not null;
    if matched<>1 then
      raise exception using errcode='55000',message='import mapping record owner unavailable or ambiguous';
    end if;
    select allocation.* into strict a from public.record_import_entity_mappings m
      join record_platform_internal.record_birth_allocations allocation on allocation.allocation_id=m.birth_allocation_id
      where m.import_plan_id=p.import_plan_id and m.entity_kind='record'
        and m.target_id=v->>'owner_target_record_id' for update of m,allocation nowait;
    if (a.project_id,a.actor_id,a.purpose,a.record_id) is distinct from
        (j.project_id,j.actor_id,'import'::text,v->>'owner_target_record_id')
      or a.state not in ('allocated','preparing','prepared') then
      raise exception using errcode='55000',message='import mapping owner allocation unavailable';
    end if;
    if a.domain='certifiable' then
      b:=record_platform_internal.record_birth_binding();
      if b.generation is null or (b.generation,b.key_id,b.cutover_digest) is distinct from
        (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
        raise exception using errcode='55000',message='import mapping owner binding is no longer current';
      end if;
    end if;
    if exists(select 1 from public.record_import_entity_mappings m where m.import_plan_id=p.import_plan_id
      and m.entity_kind=v->>'entity_kind' and m.target_id=v->>'target_id') then
      raise exception using errcode='23505',message='import mapping target already assigned';
    end if;
  elsif v->>'birth_allocation_id'<>'' or v->>'owner_target_record_id'<>'' then
    raise exception using errcode='22023',message='import mapping has unexpected owner identity';
  end if;
  insert into public.record_import_entity_mappings(import_plan_id,entity_kind,source_id,source_identity_digest,target_id,created_at,birth_allocation_id,owner_target_record_id)
    values(p.import_plan_id,v->>'entity_kind',v->>'source_id',decode(v->>'source_identity_digest','hex'),v->>'target_id',
      (v->>'created_at')::timestamptz,nullif(v->>'birth_allocation_id',''),nullif(v->>'owner_target_record_id',''));
exception when lock_not_available then
  raise exception using errcode='40001',message='import allocation busy; restart transaction';
end $$;
revoke all on function record_platform_internal.record_import_plan_lock(text,text),public.record_import_plan_lock(bytea),
  public.record_import_mapping_insert(bytea) from public;

-- The immutable manifest survives owner removal and process restart. Preparing
-- a target does not claim filesystem IO; the key guard precedes the GC claim.
create table public.attachment_purge_preparations (
  operation_id text primary key references public.record_purge_operations(operation_id) on delete restrict,
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  namespace_id uuid not null,
  incarnation_id uuid not null,
  surface_digest bytea not null check (octet_length(surface_digest)=32),
  logical_rows bigint not null check (logical_rows>=0),
  upload_part_rows bigint not null check (upload_part_rows>=0),
  workspace_count bigint not null check (workspace_count>=0),
  workspace_digest bytea not null check (octet_length(workspace_digest)=32),
  prepared_at timestamptz not null default clock_timestamp(),
  foreign key(namespace_id,incarnation_id) references public.local_blob_namespace_incarnations(namespace_id,incarnation_id)
);
create table public.attachment_purge_targets (
  operation_id text not null references public.attachment_purge_preparations(operation_id) on delete restrict,
  deletion_id text not null unique references public.blob_gc_deletions(deletion_id) on delete restrict,
  blob_key text not null check (blob_key ~ '^sha256/[0-9a-f]{64}$'),
  metadata_present boolean not null,
  primary key(operation_id,blob_key)
);
create table public.attachment_purge_workspace_targets (
  operation_id text not null references public.attachment_purge_preparations(operation_id) on delete restrict,
  workspace_id text not null,
  processor_job_id text not null,
  attempt bigint not null check (attempt>=0),
  workspace_path_digest bytea not null check (octet_length(workspace_path_digest)=32),
  workspace_state text not null check (workspace_state='purged'),
  workspace_expires_at timestamptz not null,
  removed_surface_digest bytea not null check (octet_length(removed_surface_digest)=32),
  receipt_digest bytea not null check (octet_length(receipt_digest)=32),
  removed_row_count bigint not null check (removed_row_count>=0),
  verified_absent_at timestamptz not null,
  primary key(operation_id,workspace_id)
);
create trigger attachment_purge_workspace_target_immutable before update or delete on public.attachment_purge_workspace_targets
  for each row execute function record_platform_internal.local_blob_immutable_identity();

-- This reproduces the workspace producer's 32-bit string framing and signed
-- 64-bit counts/timestamp; path and attempt remain separate registry facts.
create function record_platform_internal.workspace_purge_receipt_valid(id text, surface bytea, receipt bytea, removed bigint, verified timestamptz)
returns boolean language sql immutable set search_path=pg_catalog as $$
  select surface=sha256(int4send(octet_length(convert_to('houfeng.attachments.workspace-purge-surface.v1','UTF8')))
      ||convert_to('houfeng.attachments.workspace-purge-surface.v1','UTF8')||int4send(octet_length(convert_to(id,'UTF8')))
      ||convert_to(id,'UTF8')||int8send(removed)||int4send(15)||convert_to('verified_absent','UTF8'))
    and receipt=sha256(int4send(octet_length(convert_to('houfeng.attachments.workspace-purge-receipt.v1','UTF8')))
      ||convert_to('houfeng.attachments.workspace-purge-receipt.v1','UTF8')||int4send(octet_length(convert_to(id,'UTF8')))
      ||convert_to(id,'UTF8')||surface||int8send(removed)||int8send((extract(epoch from verified)*1000000)::bigint))
$$;
revoke all on table public.attachment_purge_workspace_targets from public;
revoke all on function record_platform_internal.workspace_purge_receipt_valid(text,bytea,bytea,bigint,timestamptz) from public;

create function record_platform_internal.workspace_purge_manifest_valid(op text)
returns boolean language sql security definer set search_path=pg_catalog as $$
  select exists(select 1 from public.attachment_purge_preparations p where p.operation_id=op
    and p.workspace_count=(select count(*) from public.attachment_purge_workspace_targets t where t.operation_id=op)
    and p.workspace_digest=sha256(convert_to(jsonb_build_array('HOUFENG-WORKSPACE-PURGE-MANIFEST-V2',op,
      coalesce((select jsonb_agg(jsonb_build_array(t.workspace_id,t.processor_job_id,t.attempt,encode(t.workspace_path_digest,'hex'),
        t.workspace_state,to_char(t.workspace_expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
        encode(t.removed_surface_digest,'hex'),encode(t.receipt_digest,'hex'),t.removed_row_count,
        to_char(t.verified_absent_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) order by t.workspace_id collate "C")
        from public.attachment_purge_workspace_targets t where t.operation_id=op),'[]'::jsonb))::text,'UTF8'))
    and not exists(select 1 from public.attachment_purge_workspace_targets t
      left join public.content_workspace_purge_receipts r on r.workspace_id=t.workspace_id
      where t.operation_id=op and (r.workspace_id is null
        or (r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at)
          is distinct from (t.removed_surface_digest,t.receipt_digest,t.removed_row_count,t.verified_absent_at)
        or not record_platform_internal.workspace_purge_receipt_valid(t.workspace_id,t.removed_surface_digest,
          t.receipt_digest,t.removed_row_count,t.verified_absent_at))))
$$;
revoke all on function record_platform_internal.workspace_purge_manifest_valid(text) from public;
create trigger attachment_purge_preparation_immutable before update or delete on public.attachment_purge_preparations
  for each row execute function record_platform_internal.local_blob_immutable_identity();
create trigger attachment_purge_target_immutable before update or delete on public.attachment_purge_targets
  for each row execute function record_platform_internal.local_blob_immutable_identity();

create function record_platform_internal.local_blob_adapter_purge_authority(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; target_record text;
begin
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='attachment purge requires read committed isolation';
  end if;
  v:=record_platform_internal.local_blob_command($1,array['operation_id','operation_owner_id','operation_generation',
    'operation_expires_at','namespace_id','incarnation_id','record_id','reservation_id','fence_epoch','surface_digest']);
  target_record:=record_platform_internal.local_blob_gc_authority(v,true);
  if target_record is distinct from v->>'record_id' or not exists (
    select 1 from public.record_purge_operations o join public.deletion_reservations r using(reservation_id)
    join public.record_deletion_gates g on g.operation_id=o.operation_id
    where o.operation_id=v->>'operation_id' and o.reservation_id=v->>'reservation_id'
      and r.deletion_contract_version=2 and r.project_id='default' and r.object_kind='record'
      and r.object_id=target_record and r.fence_epoch=(v->>'fence_epoch')::bigint
      and g.fence_epoch=r.fence_epoch)
    or octet_length(decode(v->>'surface_digest','hex')) is distinct from 32 then
    raise exception using errcode='42501',message='attachment purge operation identity conflict';
  end if;
  return v;
end $$;

create function public.local_attachment_purge_prepare(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.attachment_purge_preparations; g public.blob_gc_deletions;
  attachment_ids text[]; obligation_ids text[]; keys text[]; key text;
  released_logical_bytes bigint; released_reserved_bytes bigint; logical_rows bigint; part_rows bigint;
  workspace_count bigint; workspace_material jsonb; workspace_digest bytea; result jsonb;
begin
  v:=record_platform_internal.local_blob_adapter_purge_authority($1);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  select * into p from public.attachment_purge_preparations where operation_id=v->>'operation_id';
  if found then
    if row(p.record_id,p.namespace_id,p.incarnation_id,p.surface_digest) is distinct from
      row(v->>'record_id',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,decode(v->>'surface_digest','hex')) then
      raise exception using errcode='55000',message='attachment purge manifest conflict';
    end if;
    if not record_platform_internal.workspace_purge_manifest_valid(p.operation_id) then
      raise exception using errcode='55000',message='workspace purge manifest conflict'; end if;
  else
    select coalesce(array_agg(a.attachment_id order by a.attachment_id),'{}'::text[]),
      coalesce(sum(a.logical_size_bytes) filter(where a.attachment_state='available'),0),
      coalesce(sum(a.logical_size_bytes) filter(where a.attachment_state not in ('available','rejected','expired')),0)
      into attachment_ids,released_logical_bytes,released_reserved_bytes from public.record_attachments a
      where a.record_id=v->>'record_id' or a.draft_id in
        (select d.draft_id from public.record_drafts d where d.record_id=v->>'record_id');
    perform 1 from public.record_attachments where attachment_id=any(attachment_ids) order by attachment_id for update;
    perform 1 from public.attachment_uploads where attachment_id=any(attachment_ids) order by upload_id for update;
    perform 1 from public.attachment_processor_jobs where attachment_id=any(attachment_ids) order by processor_job_id for update;
    lock table public.content_processor_workspaces in share row exclusive mode;
    if exists(select 1 from public.content_processor_workspaces w join public.attachment_processor_jobs j using(processor_job_id)
      where j.attachment_id=any(attachment_ids) and w.workspace_state<>'purged') then
      raise exception using errcode='55000',message='processor workspace cleanup remains outstanding';
    end if;
    if exists(select 1 from public.attachment_uploads u where u.attachment_id=any(attachment_ids)
      and u.temporary_object_key is not null and u.temporary_object_deleted_at is null) then
      raise exception using errcode='55000',message='remote capability closure unknown';
    end if;
    select coalesce(array_agg(o.obligation_id order by o.obligation_id),'{}'::text[]) into obligation_ids
      from public.record_write_obligations o where o.origin_kind in ('upload','processor_preview','import_attachment')
      and (o.record_id=v->>'record_id'
        or exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=o.obligation_id
          and t.record_id=v->>'record_id')
        or (o.origin_kind='upload' and o.origin_id in
          (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(attachment_ids)))
        or (o.origin_kind='processor_preview' and o.origin_id in
          (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(attachment_ids))));
    if exists(select 1 from public.record_write_obligations o where o.obligation_id=any(obligation_ids)
      and (o.backend_kind<>'local' or o.namespace_id is distinct from (v->>'namespace_id')::uuid
        or o.incarnation_id is distinct from (v->>'incarnation_id')::uuid
        or (o.operation_id is not null and o.operation_id<>v->>'operation_id'))) then
      raise exception using errcode='55000',message='attachment write responsibility requires another authority';
    end if;
    if exists(select 1 from public.blob_objects b join public.record_attachments a
      on b.blob_key in (a.blob_key,a.preview_blob_key) where a.attachment_id=any(attachment_ids)
      and (b.backend_kind<>'local' or b.namespace_id is distinct from (v->>'namespace_id')::uuid))
      or exists(select 1 from public.attachment_upload_parts part join public.attachment_uploads u using(upload_id)
        where u.attachment_id=any(attachment_ids) and (part.namespace_id is distinct from (v->>'namespace_id')::uuid
          or part.obligation_id is null)) then
      raise exception using errcode='55000',message='legacy attachment capability unresolved';
    end if;
    if exists(select 1 from public.blob_publication_intents publication where publication.publication_state<>'completed'
      and ((publication.owner_kind='upload' and publication.owner_id in
        (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(attachment_ids)))
        or (publication.owner_kind='processor_preview' and publication.owner_id in
        (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(attachment_ids))))
      and (publication.backend_kind<>'local' or publication.namespace_id is distinct from (v->>'namespace_id')::uuid
        or (publication.obligation_id is null and not exists(select 1 from public.record_write_obligations o
          where o.publication_id=publication.publication_id and o.obligation_id=any(obligation_ids))))) then
      raise exception using errcode='55000',message='legacy publication capability unresolved';
    end if;
    select coalesce(array_agg(k order by k),'{}'::text[]) into keys from (
      select a.blob_key k from public.record_attachments a where a.attachment_id=any(attachment_ids) and a.blob_key is not null
      union select a.preview_blob_key from public.record_attachments a where a.attachment_id=any(attachment_ids) and a.preview_blob_key is not null
      union select 'sha256/'||encode(part.sha256_digest,'hex') from public.attachment_upload_parts part
        join public.attachment_uploads u using(upload_id) where u.attachment_id=any(attachment_ids)
      union select o.canonical_key from public.record_write_obligations o where o.obligation_id=any(obligation_ids)
      union select publication.blob_key from public.blob_publication_intents publication
        where publication.publication_state<>'completed' and
          ((publication.owner_kind='upload' and publication.owner_id in
            (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(attachment_ids)))
          or (publication.owner_kind='processor_preview' and publication.owner_id in
            (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(attachment_ids))))
    ) target_keys;
    -- An unregistered publication is not proof that its writer never ran.
    if exists(select 1 from unnest(keys) k where not exists(select 1 from public.record_write_obligations o
      where o.namespace_id=(v->>'namespace_id')::uuid and o.incarnation_id=(v->>'incarnation_id')::uuid and o.canonical_key=k)) then
      raise exception using errcode='55000',message='legacy attachment capability unresolved';
    end if;
    select cardinality(attachment_ids)
      +(select count(*) from public.attachment_uploads where attachment_id=any(attachment_ids))
      +(select count(*) from public.attachment_processor_jobs where attachment_id=any(attachment_ids))
      +(select count(*) from public.content_processor_workspaces w join public.attachment_processor_jobs j using(processor_job_id)
        where j.attachment_id=any(attachment_ids))
      +(select count(*) from public.record_revision_attachments where attachment_id=any(attachment_ids)) into logical_rows;
    select count(*) into part_rows from public.attachment_upload_parts part join public.attachment_uploads u using(upload_id)
      where u.attachment_id=any(attachment_ids);
    select count(*),coalesce(jsonb_agg(jsonb_build_array(w.workspace_id,w.processor_job_id,w.attempt,encode(w.workspace_path_digest,'hex'),
      w.workspace_state,to_char(w.expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
      encode(receipt.removed_surface_digest,'hex'),encode(receipt.receipt_digest,'hex'),receipt.removed_row_count,
      to_char(receipt.verified_absent_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) order by w.workspace_id collate "C"),'[]'::jsonb)
      into workspace_count,workspace_material from public.content_processor_workspaces w
      join public.attachment_processor_jobs j using(processor_job_id)
      left join public.content_workspace_purge_receipts receipt using(workspace_id)
      where j.attachment_id=any(attachment_ids);
    workspace_digest:=sha256(convert_to(jsonb_build_array('HOUFENG-WORKSPACE-PURGE-MANIFEST-V2',v->>'operation_id',workspace_material)::text,'UTF8'));
    insert into public.attachment_purge_preparations(operation_id,record_id,namespace_id,incarnation_id,surface_digest,logical_rows,upload_part_rows,workspace_count,workspace_digest)
      values(v->>'operation_id',v->>'record_id',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,
        decode(v->>'surface_digest','hex'),logical_rows,part_rows,workspace_count,workspace_digest) returning * into p;
    update public.record_write_obligations set operation_id=p.operation_id,
      handed_off_at=coalesce(handed_off_at,clock_timestamp()),
      outcome=case when dispatched_at is null then 'local_excluded' else outcome end
      where obligation_id=any(obligation_ids);
    update public.blob_publication_intents publication set publish_expires_at=least(publish_expires_at,statement_timestamp())
      where publication.publication_state<>'completed' and
        ((publication.owner_kind='upload' and publication.owner_id in
          (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(attachment_ids)))
        or (publication.owner_kind='processor_preview' and publication.owner_id in
          (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(attachment_ids))));
    foreach key in array keys loop
      select * into g from public.blob_gc_deletions existing
        where existing.namespace_id=p.namespace_id and existing.incarnation_id=p.incarnation_id
          and existing.blob_key=key and existing.local_contract_version=2 and existing.deletion_state<>'completed'
        for update;
      if found then
        if g.operation_id is distinct from p.operation_id or g.deletion_state<>'pending' then
          raise exception using errcode='55000',message='attachment cleanup target already claimed by another preparation';
        end if;
      else
        g:=record_platform_internal.local_blob_gc_prepare(convert_to(jsonb_build_object(
          'deletion_id','bgd_'||encode(sha256(convert_to(jsonb_build_array('attachment-purge-v2',p.operation_id,p.namespace_id,p.incarnation_id,key)::text,'UTF8')),'hex'),
          'namespace_id',p.namespace_id,'incarnation_id',p.incarnation_id,'key',key,
          'operation_id',p.operation_id,'operation_owner_id',v->>'operation_owner_id',
          'operation_generation',(v->>'operation_generation')::bigint,'operation_expires_at',v->>'operation_expires_at',
          'expected_version',null,'orphaned_before',null,'publication_id',null)::text,'UTF8'),true);
      end if;
      insert into public.attachment_purge_targets(operation_id,deletion_id,blob_key,metadata_present)
        values(p.operation_id,g.deletion_id,key,exists(select 1 from public.blob_objects b where b.blob_key=key and b.namespace_id=p.namespace_id));
    end loop;
    -- A workspace is a separate physical responsibility; keep its registry
    -- and job until its janitor has recorded the actual purge.
    if exists(select 1 from public.content_processor_workspaces w
      join public.attachment_processor_jobs j on j.processor_job_id=w.processor_job_id
      left join public.content_workspace_purge_receipts receipt on receipt.workspace_id=w.workspace_id
      where j.attachment_id=any(attachment_ids)
        and (w.workspace_state<>'purged' or w.purged_at is distinct from receipt.verified_absent_at
          or receipt.workspace_id is null or not record_platform_internal.workspace_purge_receipt_valid(
            receipt.workspace_id,receipt.removed_surface_digest,receipt.receipt_digest,receipt.removed_row_count,receipt.verified_absent_at))) then
      raise exception using errcode='55000',message='processor workspace cleanup remains outstanding';
    end if;
    insert into public.attachment_purge_workspace_targets(operation_id,workspace_id,processor_job_id,attempt,workspace_path_digest,
      workspace_state,workspace_expires_at,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
      select p.operation_id,w.workspace_id,w.processor_job_id,w.attempt,w.workspace_path_digest,w.workspace_state,w.expires_at,
        receipt.removed_surface_digest,receipt.receipt_digest,receipt.removed_row_count,receipt.verified_absent_at
      from public.content_processor_workspaces w join public.attachment_processor_jobs j using(processor_job_id)
      join public.content_workspace_purge_receipts receipt using(workspace_id)
      where j.attachment_id=any(attachment_ids);
    if not record_platform_internal.workspace_purge_manifest_valid(p.operation_id) then
      raise exception using errcode='55000',message='workspace purge manifest conflict'; end if;
    delete from public.content_processor_workspaces w using public.attachment_processor_jobs j
      where w.processor_job_id=j.processor_job_id and j.attachment_id=any(attachment_ids);
    delete from public.attachment_processor_jobs where attachment_id=any(attachment_ids);
    delete from public.attachment_upload_parts part using public.attachment_uploads u
      where part.upload_id=u.upload_id and u.attachment_id=any(attachment_ids);
    delete from public.attachment_uploads where attachment_id=any(attachment_ids);
    delete from public.record_revision_attachments where attachment_id=any(attachment_ids);
    delete from public.record_attachments where attachment_id=any(attachment_ids);
    if released_logical_bytes>0 or released_reserved_bytes>0 then
      update public.attachment_quota_accounts set logical_bytes=logical_bytes-released_logical_bytes,
        reserved_bytes=reserved_bytes-released_reserved_bytes,quota_version=quota_version+1,updated_at=clock_timestamp()
        where project_id='default' and logical_bytes>=released_logical_bytes
          and reserved_bytes>=released_reserved_bytes;
      if not found then raise exception using errcode='55000',message='attachment purge quota settlement conflict'; end if;
    end if;
  end if;
  result:=jsonb_build_object('targets',coalesce((select jsonb_agg(jsonb_build_object('deletion_id',t.deletion_id,'key',t.blob_key)
    order by t.blob_key) from public.attachment_purge_targets t where t.operation_id=p.operation_id),'[]'::jsonb));
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  return result;
end $$;
revoke all on function record_platform_internal.local_blob_adapter_purge_authority(bytea),
  public.local_attachment_purge_prepare(bytea) from public;

create function record_platform_internal.local_attachment_purge_finish(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.attachment_purge_preparations; material jsonb; inventory bytea;
  physical_rows bigint; receipt_rows bigint; surface text; removed_rows bigint;
  marker bytea; expected_receipt bytea; verified_at timestamptz; latest_verified_at timestamptz; result jsonb;
begin
  v:=record_platform_internal.local_blob_adapter_purge_authority($1);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  select * into strict p from public.attachment_purge_preparations where operation_id=v->>'operation_id';
  if row(p.record_id,p.namespace_id,p.incarnation_id,p.surface_digest) is distinct from
    row(v->>'record_id',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,decode(v->>'surface_digest','hex')) then
    raise exception using errcode='55000',message='attachment purge manifest conflict';
  end if;
  if not record_platform_internal.workspace_purge_manifest_valid(p.operation_id) then
    raise exception using errcode='55000',message='workspace purge manifest conflict'; end if;
  if exists(select 1 from public.record_attachments a where a.record_id=p.record_id or a.draft_id in
      (select d.draft_id from public.record_drafts d where d.record_id=p.record_id))
    or exists(select 1 from public.record_revision_attachments where record_id=p.record_id) then
    raise exception using errcode='55000',message='attachment owner references remain';
  end if;
  if exists(select 1 from public.attachment_purge_targets t join public.blob_gc_deletions g using(deletion_id)
    where t.operation_id=p.operation_id and (g.operation_id is distinct from p.operation_id
      or g.namespace_id is distinct from p.namespace_id or g.incarnation_id is distinct from p.incarnation_id
      or g.blob_key<>t.blob_key or g.local_contract_version<>2 or g.deletion_state<>'completed'
      or g.physical_delete_result is null or g.physical_delete_result not in ('deleted','already_absent','retained_referenced')
      or g.receipt_digest is null or g.completed_at is null or not g.final_identity_bound
      or g.inventory_digest is null or g.completion_command is null))
    or exists(select 1 from public.record_write_obligations o where o.operation_id=p.operation_id
      and o.origin_kind in ('upload','processor_preview','import_attachment') and o.cleanup_completed_at is null) then
    raise exception using errcode='55000',message='attachment physical cleanup remains outstanding';
  end if;
  select coalesce(jsonb_agg(jsonb_build_array(t.blob_key,t.deletion_id,t.metadata_present,
      g.physical_delete_result,encode(g.receipt_digest,'hex')) order by t.blob_key),'[]'::jsonb),
    count(*) filter(where t.metadata_present and g.physical_delete_result in ('deleted','already_absent'))
    into material,physical_rows from public.attachment_purge_targets t join public.blob_gc_deletions g using(deletion_id)
    where t.operation_id=p.operation_id;
  inventory:=sha256(convert_to(jsonb_build_array('HOUFENG-ATTACHMENT-PURGE-V2',p.operation_id,
    encode(p.surface_digest,'hex'),p.logical_rows,p.upload_part_rows,physical_rows,material)::text,'UTF8'));
  select count(*) into receipt_rows from public.attachment_purge_receipts where operation_id=p.operation_id;
  if receipt_rows not in (0,3) or (not $2 and receipt_rows<>3) then
    raise exception using errcode='55000',message='attachment purge receipt set unavailable';
  end if;
  foreach surface in array array['logical_attachment','upload_part','blob_object'] loop
    removed_rows:=case surface when 'logical_attachment' then p.logical_rows when 'upload_part' then p.upload_part_rows else physical_rows end;
    marker:=sha256(convert_to(jsonb_build_array('HOUFENG-ATTACHMENT-PURGE-V2',p.operation_id,surface)::text,'UTF8'));
    expected_receipt:=sha256(inventory||marker);
    if $2 and receipt_rows=0 then
      insert into public.attachment_purge_receipts(operation_id,surface_kind,object_version_digest,
        removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
        values(p.operation_id,surface,marker,p.surface_digest,expected_receipt,removed_rows,clock_timestamp());
    end if;
    select r.verified_absent_at into strict verified_at from public.attachment_purge_receipts r
      where r.operation_id=p.operation_id and r.surface_kind=surface and r.object_version_digest=marker
        and r.removed_surface_digest=p.surface_digest and r.receipt_digest=expected_receipt and r.removed_row_count=removed_rows;
    latest_verified_at:=greatest(latest_verified_at,verified_at);
  end loop;
  result:=jsonb_build_object('receipt_digest',encode(inventory,'hex'),
    'removed_row_count',p.logical_rows+p.upload_part_rows+physical_rows,'verified_absent_at',latest_verified_at);
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  return result;
end $$;
create function public.local_attachment_purge_complete(bytea)
returns jsonb language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_attachment_purge_finish($1,true) $$;
create function public.local_attachment_purge_verify(bytea)
returns jsonb language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_attachment_purge_finish($1,false) $$;
revoke all on function record_platform_internal.local_attachment_purge_finish(bytea,boolean),
  public.local_attachment_purge_complete(bytea),public.local_attachment_purge_verify(bytea) from public;

create table public.record_portability_cleanup_preparations (
  operation_id text primary key references public.record_purge_operations(operation_id) on delete restrict,
  record_id text not null check (record_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  namespace_id uuid not null,
  incarnation_id uuid not null,
  surface_digest bytea not null check (octet_length(surface_digest)=32),
  removed_rows bigint not null check (removed_rows>=0),
  prepared_at timestamptz not null default clock_timestamp(),
  foreign key(namespace_id,incarnation_id) references public.local_blob_namespace_incarnations(namespace_id,incarnation_id)
);
create table public.record_portability_cleanup_targets (
  operation_id text not null,
  deletion_id text not null references public.blob_gc_deletions(deletion_id) on delete restrict,
  blob_key text not null check (blob_key ~ '^sha256/[0-9a-f]{64}$'),
  primary key(operation_id,blob_key),
  foreign key(operation_id) references public.record_portability_cleanup_preparations(operation_id)
    on delete restrict deferrable initially deferred
);
create trigger record_portability_cleanup_preparation_immutable before update or delete on public.record_portability_cleanup_preparations
  for each row execute function record_platform_internal.local_blob_immutable_identity();
create trigger record_portability_cleanup_target_immutable before update or delete on public.record_portability_cleanup_targets
  for each row execute function record_platform_internal.local_blob_immutable_identity();

create function public.local_portability_purge_prepare(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.record_portability_cleanup_preparations; g public.blob_gc_deletions;
  export_jobs text[]; import_jobs text[]; removable_jobs text[]; plans text[]; keys text[]; key text;
  changed bigint; removed bigint:=0; result jsonb;
begin
  v:=record_platform_internal.local_blob_adapter_purge_authority($1);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  select * into p from public.record_portability_cleanup_preparations where operation_id=v->>'operation_id';
  if found then
    if row(p.record_id,p.namespace_id,p.incarnation_id,p.surface_digest) is distinct from
      row(v->>'record_id',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,decode(v->>'surface_digest','hex')) then
      raise exception using errcode='55000',message='portability cleanup manifest conflict';
    end if;
  else
    p.operation_id:=v->>'operation_id'; p.record_id:=v->>'record_id';
    p.namespace_id:=(v->>'namespace_id')::uuid; p.incarnation_id:=(v->>'incarnation_id')::uuid;
    p.surface_digest:=decode(v->>'surface_digest','hex');
    select coalesce(array_agg(export_job_id order by export_job_id),'{}'::text[]) into export_jobs
      from public.record_export_jobs where record_id=p.record_id;
    select coalesce(array_agg(distinct import_plan_id),'{}'::text[]) into plans
      from public.record_import_entity_mappings where entity_kind='record' and target_id=p.record_id;
    select coalesce(array_agg(distinct job_id),'{}'::text[]) into import_jobs from (
      select import_job_id job_id from public.record_import_plans where import_plan_id=any(plans)
      union select o.origin_id from public.record_write_obligations o join public.record_write_obligation_targets t using(obligation_id)
        where o.origin_kind='import_archive' and t.record_id=p.record_id
    ) affected_jobs;
    perform 1 from public.record_export_jobs where export_job_id=any(export_jobs) order by export_job_id for update;
    perform 1 from public.record_import_jobs where import_job_id=any(import_jobs) order by import_job_id for update;
    if exists(select 1 from public.record_export_jobs where export_job_id=any(export_jobs) and export_kind='pdf') then
      raise exception using errcode='55000',message='PDF workspace cleanup evidence unavailable';
    end if;
    if exists(select 1 from public.record_export_artifacts a where a.export_job_id=any(export_jobs)
      and (a.backend_kind<>'local' or a.namespace_id is distinct from p.namespace_id
        or a.object_version_id is null or a.obligation_id is null))
      or exists(select 1 from public.record_import_artifacts a where a.import_job_id=any(import_jobs)
        and (a.backend_kind<>'local' or a.namespace_id is distinct from p.namespace_id
          or a.object_version_id is null or a.obligation_id is null))
      or exists(select 1 from public.record_write_obligations o where
        ((o.origin_kind='export_artifact' and o.origin_id=any(export_jobs))
          or (o.origin_kind='import_archive' and o.origin_id=any(import_jobs)))
        and (o.backend_kind<>'local' or o.namespace_id is distinct from p.namespace_id or o.incarnation_id is distinct from p.incarnation_id)) then
      raise exception using errcode='55000',message='portability local identity or remote capability unresolved';
    end if;
    select coalesce(array_agg(k order by k),'{}'::text[]) into keys from (
      select blob_key k from public.record_export_artifacts where export_job_id=any(export_jobs)
      union select blob_key from public.record_import_artifacts where import_job_id=any(import_jobs)
      union select canonical_key from public.record_write_obligations o where
        (o.origin_kind='export_artifact' and o.origin_id=any(export_jobs))
        or (o.origin_kind='import_archive' and o.origin_id=any(import_jobs))
    ) target_keys;
    foreach key in array keys loop
      select * into g from public.blob_gc_deletions existing where existing.namespace_id=p.namespace_id
        and existing.incarnation_id=p.incarnation_id and existing.blob_key=key
        and existing.local_contract_version=2 and existing.deletion_state<>'completed' for update;
      if found then
        if g.operation_id is distinct from p.operation_id or g.deletion_state<>'pending' then
          raise exception using errcode='55000',message='portability cleanup target already claimed by another preparation';
        end if;
      else
        g:=record_platform_internal.local_blob_gc_prepare(convert_to(jsonb_build_object(
          'deletion_id','bgd_'||encode(sha256(convert_to(jsonb_build_array('portability-purge-v2',p.operation_id,p.namespace_id,p.incarnation_id,key)::text,'UTF8')),'hex'),
          'namespace_id',p.namespace_id,'incarnation_id',p.incarnation_id,'key',key,
          'operation_id',p.operation_id,'operation_owner_id',v->>'operation_owner_id',
          'operation_generation',(v->>'operation_generation')::bigint,'operation_expires_at',v->>'operation_expires_at',
          'expected_version',null,'orphaned_before',null,'publication_id',null)::text,'UTF8'),true);
      end if;
      insert into public.record_portability_cleanup_targets(operation_id,deletion_id,blob_key) values(p.operation_id,g.deletion_id,key);
    end loop;
    insert into public.record_origin_tombstones(project_id,origin_digest,operation_id)
      select distinct 'default',archive_digest,p.operation_id from public.record_import_jobs where import_job_id=any(import_jobs)
      on conflict do nothing;
    insert into public.record_origin_tombstones(project_id,origin_digest,operation_id)
      select project_id,origin_digest,p.operation_id from public.record_origins where source_record_id=p.record_id
      on conflict do nothing;
    -- Retire only this record's archive interest. Other target and non-record
    -- mapping owners survive; a published archive is not an unowned obligation.
    update public.record_write_obligation_targets t set handed_off_at=coalesce(t.handed_off_at,clock_timestamp())
      where t.record_id=p.record_id and exists(select 1 from public.record_write_obligations o
        where o.obligation_id=t.obligation_id and o.origin_kind='import_archive' and o.origin_id=any(import_jobs));
    delete from public.record_import_entity_mappings where (entity_kind='record' and target_id=p.record_id)
      or (entity_kind in ('evidence','attachment') and owner_target_record_id=p.record_id);
    get diagnostics changed=row_count; removed:=removed+changed;
    select coalesce(array_agg(j.import_job_id order by j.import_job_id),'{}'::text[]) into removable_jobs
      from public.record_import_jobs j where j.import_job_id=any(import_jobs)
      and not exists(select 1 from public.record_import_plans plan join public.record_import_entity_mappings m using(import_plan_id)
        where plan.import_job_id=j.import_job_id)
      and not exists(select 1 from public.record_write_obligations o join public.record_write_obligation_targets t using(obligation_id)
        where o.origin_id=j.import_job_id and o.origin_kind in ('import_archive','import_attachment')
          and t.record_id<>p.record_id and t.handed_off_at is null);
    if exists(select 1 from public.record_write_obligations o where
      ((o.origin_kind='export_artifact' and o.origin_id=any(export_jobs))
        or (o.origin_kind='import_archive' and o.origin_id=any(removable_jobs)))
      and o.operation_id is not null and o.operation_id<>p.operation_id) then
      raise exception using errcode='55000',message='portability responsibility already handed to another operation';
    end if;
    update public.record_write_obligations o set operation_id=p.operation_id,
      handed_off_at=coalesce(o.handed_off_at,clock_timestamp()),
      outcome=case when o.dispatched_at is null then 'local_excluded' else o.outcome end
      where (o.origin_kind='export_artifact' and o.origin_id=any(export_jobs))
        or (o.origin_kind='import_archive' and o.origin_id=any(removable_jobs));
    delete from public.record_export_artifacts where export_job_id=any(export_jobs);
    get diagnostics changed=row_count; removed:=removed+changed;
    delete from public.record_export_jobs where export_job_id=any(export_jobs);
    get diagnostics changed=row_count; removed:=removed+changed;
    delete from public.record_import_artifacts where import_job_id=any(removable_jobs);
    get diagnostics changed=row_count; removed:=removed+changed;
    delete from public.record_import_plans where import_job_id=any(removable_jobs);
    get diagnostics changed=row_count; removed:=removed+changed;
    delete from public.record_import_jobs where import_job_id=any(removable_jobs);
    get diagnostics changed=row_count; removed:=removed+changed;
    delete from public.record_origins where source_record_id=p.record_id;
    get diagnostics changed=row_count; removed:=removed+changed;
    insert into public.record_portability_cleanup_preparations(operation_id,record_id,namespace_id,incarnation_id,surface_digest,removed_rows)
      values(p.operation_id,p.record_id,p.namespace_id,p.incarnation_id,p.surface_digest,removed) returning * into p;
  end if;
  result:=jsonb_build_object('targets',coalesce((select jsonb_agg(jsonb_build_object('deletion_id',t.deletion_id,'key',t.blob_key)
    order by t.blob_key) from public.record_portability_cleanup_targets t where t.operation_id=p.operation_id),'[]'::jsonb));
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  return result;
end $$;
revoke all on function public.local_portability_purge_prepare(bytea) from public;

create function record_platform_internal.local_portability_purge_finish(bytea,boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; p public.record_portability_cleanup_preparations; material jsonb;
  expected_receipt bytea; verified_at timestamptz; result jsonb;
begin
  v:=record_platform_internal.local_blob_adapter_purge_authority($1);
  perform 1 from public.attachment_quota_accounts where project_id='default' for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  select * into strict p from public.record_portability_cleanup_preparations where operation_id=v->>'operation_id';
  if row(p.record_id,p.namespace_id,p.incarnation_id,p.surface_digest) is distinct from
    row(v->>'record_id',(v->>'namespace_id')::uuid,(v->>'incarnation_id')::uuid,decode(v->>'surface_digest','hex')) then
    raise exception using errcode='55000',message='portability cleanup manifest conflict';
  end if;
  if exists(select 1 from public.record_export_jobs where record_id=p.record_id)
    or exists(select 1 from public.record_origins where source_record_id=p.record_id)
    or exists(select 1 from public.record_import_entity_mappings where entity_kind='record' and target_id=p.record_id)
    or exists(select 1 from public.record_write_obligation_targets t join public.record_write_obligations o using(obligation_id)
      where t.record_id=p.record_id and o.origin_kind='import_archive' and t.handed_off_at is null) then
    raise exception using errcode='55000',message='portability owner references remain';
  end if;
  if exists(select 1 from public.record_portability_cleanup_targets t join public.blob_gc_deletions g using(deletion_id)
    where t.operation_id=p.operation_id and (g.operation_id is distinct from p.operation_id
      or g.namespace_id is distinct from p.namespace_id or g.incarnation_id is distinct from p.incarnation_id
      or g.blob_key<>t.blob_key or g.local_contract_version<>2 or g.deletion_state<>'completed'
      or g.physical_delete_result is null or g.physical_delete_result not in ('deleted','already_absent','retained_referenced')
      or g.receipt_digest is null or g.completed_at is null or not g.final_identity_bound
      or g.inventory_digest is null or g.completion_command is null))
    or exists(select 1 from public.record_write_obligations o where o.operation_id=p.operation_id
      and o.origin_kind in ('export_artifact','import_archive') and o.cleanup_completed_at is null) then
    raise exception using errcode='55000',message='portability physical cleanup remains outstanding';
  end if;
  select coalesce(jsonb_agg(jsonb_build_array(t.blob_key,t.deletion_id,g.physical_delete_result,encode(g.receipt_digest,'hex'))
    order by t.blob_key),'[]'::jsonb) into material from public.record_portability_cleanup_targets t
    join public.blob_gc_deletions g using(deletion_id) where t.operation_id=p.operation_id;
  expected_receipt:=sha256(convert_to(jsonb_build_array('HOUFENG-PORTABILITY-PURGE-V2',p.operation_id,
    encode(p.surface_digest,'hex'),p.removed_rows,material)::text,'UTF8'));
  if $2 then
    insert into public.record_portability_purge_receipts(operation_id,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
      values(p.operation_id,p.surface_digest,expected_receipt,p.removed_rows,clock_timestamp()) on conflict do nothing;
  end if;
  select verified_absent_at into strict verified_at from public.record_portability_purge_receipts
    where operation_id=p.operation_id and removed_surface_digest=p.surface_digest
      and receipt_digest=expected_receipt and removed_row_count=p.removed_rows;
  result:=jsonb_build_object('receipt_digest',encode(expected_receipt,'hex'),'removed_row_count',p.removed_rows,'verified_absent_at',verified_at);
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'operation_owner_id',
    (v->>'operation_generation')::bigint,(v->>'operation_expires_at')::timestamptz,v->>'record_id');
  return result;
end $$;
create function public.local_portability_purge_complete(bytea)
returns jsonb language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_portability_purge_finish($1,true) $$;
create function public.local_portability_purge_verify(bytea)
returns jsonb language sql security definer set search_path=pg_catalog
as $$ select record_platform_internal.local_portability_purge_finish($1,false) $$;
revoke all on function record_platform_internal.local_portability_purge_finish(bytea,boolean),
  public.local_portability_purge_complete(bytea),public.local_portability_purge_verify(bytea) from public;

-- Full stored facts for recovery inventory. This command performs no physical
-- observation and never grants source/local admission or a cold-handoff proof.
create function public.local_blob_recovery_inventory()
returns jsonb language plpgsql stable security definer set search_path=pg_catalog
as $$
declare spec record; columns jsonb; rows jsonb; tables jsonb:='[]'::jsonb; ordering text;
begin
  perform record_platform_internal.local_blob_direct_login();
  for spec in select * from (values
    ('attachment_purge_preparations',array['operation_id']::text[],''),
    ('attachment_purge_receipts',array['operation_id','surface_kind','object_version_digest'],''),
    ('attachment_purge_targets',array['operation_id','blob_key'],''),
    ('blob_gc_deletions',array['deletion_id'],'where r.backend_kind=''local'''),
    ('blob_gc_pins',array['pin_id'],''),
    ('blob_publication_intents',array['publication_id'],'where r.backend_kind=''local'''),
    ('local_blob_gc_obligations',array['deletion_id','obligation_id'],''),
    ('local_blob_key_anchors',array['namespace_id','incarnation_id','canonical_key'],''),
    ('local_blob_namespace_incarnations',array['namespace_id','incarnation_id'],''),
    ('local_blob_namespaces',array['namespace_id'],''),
    ('record_portability_cleanup_preparations',array['operation_id'],''),
    ('record_portability_cleanup_targets',array['operation_id','blob_key'],''),
    ('record_portability_purge_receipts',array['operation_id'],''),
    ('record_write_obligation_targets',array['obligation_id','record_id'],
      'where exists(select 1 from public.record_write_obligations o where o.obligation_id=r.obligation_id and o.backend_kind=''local'')'),
    ('record_write_obligations',array['obligation_id'],'where r.backend_kind=''local''')
  ) entries(name,identity_columns,predicate) order by name loop
    select jsonb_agg(a.attname order by a.attname) into strict columns from pg_attribute a
      where a.attrelid=format('public.%I',spec.name)::regclass and a.attnum>0 and not a.attisdropped;
    select string_agg(format('r.%I',key),',' order by ordinal) into ordering
      from unnest(spec.identity_columns) with ordinality keys(key,ordinal);
    execute format('select coalesce(jsonb_agg(to_jsonb(r) order by %s),''[]''::jsonb) from public.%I r %s',
      ordering,spec.name,spec.predicate) into rows;
    tables:=tables||jsonb_build_array(jsonb_build_object('name',spec.name,'columns',columns,
      'identity_columns',to_jsonb(spec.identity_columns),'rows',rows));
  end loop;
  return jsonb_build_object('format_version',1,'schema_revision','C81-local-io-v1',
    'physical_evidence','not_observed','tables',tables);
end $$;
revoke all on function public.local_blob_recovery_inventory() from public;

-- Retain consumed draft parts as GC metadata before deleting their owners.
-- The caller's transaction also transfers obligations and settles quota.
create function public.record_draft_upload_parts_handoff(bytea)
returns bigint language plpgsql security definer set search_path=pg_catalog
as $$
declare v jsonb; d public.record_drafts; initial_record text; n record; part record;
  physical bigint:=0; draft_epoch bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.local_blob_command($1,array['draft_id']);
  perform public.source_application_admit();
  for n in select distinct p.namespace_id,ns.current_incarnation_id
    from public.record_attachments a join public.attachment_uploads u on u.attachment_id=a.attachment_id
    join public.attachment_upload_parts p on p.upload_id=u.upload_id
    left join public.local_blob_namespaces ns on ns.namespace_id=p.namespace_id
    where a.draft_id=v->>'draft_id' and u.transport_kind='local'
    order by p.namespace_id,ns.current_incarnation_id
  loop
    perform record_platform_internal.local_blob_admission(n.namespace_id,n.current_incarnation_id);
  end loop;
  select * into strict d from public.record_drafts where draft_id=v->>'draft_id' and project_id='default';
  initial_record:=d.record_id;
  if initial_record is not null then draft_epoch:=record_platform_internal.local_blob_record_epoch(initial_record); end if;
  select * into strict d from public.record_drafts where draft_id=v->>'draft_id' and project_id='default' for update;
  if d.record_id is distinct from initial_record then
    raise exception using errcode='55000',message='draft attachment handoff route changed';
  end if;
  perform record_platform_internal.record_blob_strong_fence();
  for part in select p.*,u.transport_kind,u.origin_draft_id,a.project_id,
      o.obligation_id as registered_obligation,o.origin_kind,o.origin_id,
      convert_from(o.registration_command,'UTF8')::jsonb->>'draft_id' as write_draft,
      o.canonical_key,o.backend_kind,o.namespace_id as write_namespace,o.object_version as write_version,
      o.sha256_digest as write_digest,o.size_bytes as write_size,o.outcome,o.returned_at,
      o.record_id as write_record,o.record_epoch,o.publication_id
    from public.record_attachments a join public.attachment_uploads u on u.attachment_id=a.attachment_id
    join public.attachment_upload_parts p on p.upload_id=u.upload_id
    left join public.record_write_obligations o on o.obligation_id=p.obligation_id
    where a.draft_id=d.draft_id order by p.sha256_digest,p.upload_id,p.part_number
    for update of a,u,p
  loop
    if part.registered_obligation is null or part.origin_kind<>'upload' or part.origin_id<>part.upload_id
      or part.write_draft is distinct from d.draft_id or part.origin_draft_id<>d.draft_id
      or part.project_id<>d.project_id or part.outcome<>'materialized' or part.returned_at is null
      or part.write_record is distinct from d.record_id
      or row(part.canonical_key,part.backend_kind,part.write_namespace,part.write_version,part.write_digest,part.write_size)
        is distinct from row('sha256/'||encode(part.sha256_digest,'hex'),part.transport_kind,part.namespace_id,
          part.object_version,part.sha256_digest,part.size_bytes)
      or not exists(select 1 from public.blob_publication_intents p where p.publication_id=part.publication_id
        and p.obligation_id=part.obligation_id and p.owner_kind='upload' and p.owner_id=part.upload_id
        and p.publication_state='completed' and p.completion_outcome='consumed') then
      raise exception using errcode='55000',message='draft upload part handoff provenance unavailable';
    end if;
    if part.record_epoch is distinct from draft_epoch then
      raise exception using errcode='55000',message='draft upload part handoff epoch changed';
    end if;
    if record_platform_internal.record_blob_metadata_publish(part.canonical_key,part.sha256_digest,
      part.object_version,part.size_bytes,part.backend_kind,part.namespace_id) then
      physical:=physical+part.size_bytes;
    end if;
  end loop;
  return physical;
end $$;
revoke all on function public.record_draft_upload_parts_handoff(bytea) from public;

-- Client metadata receipts survive the root and must remain exact on replay.
create function record_platform_internal.enforce_client_purge_receipt_immutable()
returns trigger language plpgsql set search_path = pg_catalog
as $$
begin
  raise exception using errcode = '55000', message = 'client purge receipt is immutable';
end
$$;

create trigger record_markdown_client_purge_receipts_immutable
  before update or delete or truncate on public.record_markdown_client_purge_receipts
  for each statement execute function record_platform_internal.enforce_client_purge_receipt_immutable();
create trigger record_comparison_purge_receipts_immutable
  before update or delete or truncate on public.record_comparison_purge_receipts
  for each statement execute function record_platform_internal.enforce_client_purge_receipt_immutable();
create trigger record_collaboration_purge_receipts_immutable
  before update or delete or truncate on public.record_collaboration_purge_receipts
  for each statement execute function record_platform_internal.enforce_client_purge_receipt_immutable();

-- The receipt uses the same unsigned 64-bit, big-endian length framing as
-- the deletion adapters. Counts are nonnegative PostgreSQL bigints.
create function record_platform_internal.client_purge_field(bytea)
returns bytea language sql immutable strict parallel safe set search_path = pg_catalog
as $$ select int8send(octet_length($1)::bigint) || $1 $$;

create function record_platform_internal.record_outbox_observed_route(public.record_outbox)
returns text language plpgsql stable security definer set search_path=pg_catalog as $$
declare o alias for $1; route text; n bigint;
begin
  case o.subject_kind
    when 'record' then
      if o.subject_id !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$' then return null; end if;
      route:=o.subject_id;
    when 'action' then
      select a.record_id into route from public.record_actions a where a.project_id=o.project_id and a.action_id=o.subject_id;
    when 'comment' then
      select c.record_id into route from public.record_comments c where c.project_id=o.project_id and c.comment_id=o.subject_id;
    when 'delivery' then
      select d.record_id into route from public.record_notification_deliveries d join public.record_notifications x
        on x.record_id=d.record_id and x.notification_id=d.notification_id
        where x.project_id=o.project_id and d.delivery_id=o.subject_id;
      if route is null then
        select min(s.record_id),count(distinct s.record_id) into route,n from public.record_notification_delivery_starts s
          where s.project_id=o.project_id and s.delivery_id=o.subject_id and s.outbox_row_id=o.outbox_row_id
            and s.source_version=o.source_version and s.authorization_epoch=o.authorization_epoch
            and s.record_fence_epoch=o.record_fence_epoch and s.event_expires_at=o.expires_at;
        if n>1 then return null; end if;
      end if;
    else return null;
  end case;
  if route is not null and o.record_id is not null and route<>o.record_id then return null; end if;
  return coalesce(route,o.record_id);
end $$;

-- Called with the relevant serialization locks held by drain/purge. It also
-- checks predecessor attempts, including those already terminal before gate.
create function record_platform_internal.record_outbox_handoff_complete(text,text)
returns boolean language plpgsql stable security definer set search_path=pg_catalog as $$
declare op alias for $1; target alias for $2;
begin
  if exists(select 1 from public.record_outbox o where o.subject_kind in ('record','action','comment','delivery')
      and record_platform_internal.record_outbox_observed_route(o) is null)
    or exists(select 1 from public.record_outbox o where o.project_id='default' and o.status in ('pending','processing')
      and record_platform_internal.record_outbox_observed_route(o)=target)
    or exists(select 1 from public.record_outbox o where o.project_id='default' and o.record_id is null
      and record_platform_internal.record_outbox_observed_route(o)=target)
    or exists(select 1 from public.record_notification_deliveries d where d.record_id=target and d.delivery_state='processing')
    or exists(select 1 from public.record_notification_deliveries d where d.record_id=target and d.attempt_count=0
      and d.delivery_state in ('sent','permanent_failure','unknown_outcome','retry_wait'))
    or exists(select 1 from public.record_outbox o join public.record_notification_deliveries d
      on o.project_id='default' and o.subject_kind='delivery' and o.subject_id=d.delivery_id
      where d.record_id=target and d.delivery_state='pending' and d.attempt_count=0 and o.status='sent')
    or exists(select 1 from public.record_notification_deliveries d where d.record_id=target and d.attempt_count=0
      and d.delivery_state='cancelled' and not exists(select 1 from public.record_notification_delivery_handoffs h
        where h.operation_id=op and h.delivery_id=d.delivery_id and h.attempt_no=1 and h.record_id=d.record_id
          and h.notification_id=d.notification_id and h.record_fence_epoch=d.record_fence_epoch
          and h.legacy_observation_kind='not_started' and h.observed_status='not_sent'))
    or exists(select 1 from public.record_notification_deliveries d where d.record_id=target and d.attempt_count>0
      and not exists(select 1 from public.record_notification_delivery_starts s where s.delivery_id=d.delivery_id and s.attempt_no=d.attempt_count)
      and not exists(select 1 from public.record_notification_delivery_attempts a where a.delivery_id=d.delivery_id and a.attempt_no=d.attempt_count)
      and not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=op
        and h.delivery_id=d.delivery_id and h.attempt_no=d.attempt_count and h.attempt_id is null
        and h.record_id=d.record_id and h.notification_id=d.notification_id and h.record_fence_epoch=d.record_fence_epoch))
    or exists(select 1 from public.record_notification_delivery_starts s
      where s.project_id='default' and s.record_id=target and not exists(
        select 1 from public.record_notification_delivery_handoffs h where h.operation_id=op
          and h.delivery_id=s.delivery_id and h.attempt_no=s.attempt_no and h.attempt_id=s.attempt_id
          and h.project_id=s.project_id and h.record_id=s.record_id and h.notification_id=s.notification_id
          and h.record_fence_epoch=s.record_fence_epoch and h.start_correlation_digest=s.correlation_digest))
    or exists(select 1 from public.record_notification_delivery_attempts a where a.record_id=target
      and not exists(select 1 from public.record_notification_delivery_starts s where s.delivery_id=a.delivery_id and s.attempt_no=a.attempt_no)
      and not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=op
        and h.delivery_id=a.delivery_id and h.attempt_no=a.attempt_no and h.attempt_id is null
        and h.record_id=a.record_id and h.notification_id=a.notification_id and h.record_fence_epoch=a.record_fence_epoch))
    or exists(select 1 from public.record_notification_delivery_completions c where c.project_id='default' and c.record_id=target
      and c.attempt_id is null and not exists(select 1 from public.record_notification_delivery_handoffs h
        where h.operation_id=op and h.delivery_id=c.delivery_id and h.attempt_no=c.attempt_no and h.attempt_id is null
          and h.record_id=c.record_id and h.notification_id=c.notification_id and h.record_fence_epoch=c.record_fence_epoch))
    or exists(select 1 from public.record_outbox o where o.project_id='default' and o.subject_kind='delivery'
      and record_platform_internal.record_outbox_observed_route(o)=target
      and not exists(select 1 from public.record_notification_deliveries d where d.delivery_id=o.subject_id and d.record_id=target)
      and not exists(select 1 from public.record_notification_delivery_starts s where s.outbox_row_id=o.outbox_row_id
        and s.delivery_id=o.subject_id and s.record_id=target)
      and not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=op
        and h.delivery_id=o.subject_id and h.record_id=target and h.legacy_outbox_row_id=o.outbox_row_id)) then return false; end if;
  return true;
end $$;

create function public.record_outbox_drain_v2(bytea)
returns table(drained_count bigint,remaining boolean)
language plpgsql security definer set search_path=pg_catalog as $$
declare raw json; v jsonb; res public.deletion_reservations; gate public.record_deletion_gates;
  operation public.record_purge_operations; epoch bigint; expiry timestamptz; generation bigint;
  actual_reservation text; s public.record_notification_delivery_starts; d public.record_notification_deliveries;
  o public.record_outbox; legacy record; c public.record_notification_delivery_completions;
  cnt bigint:=0; providers bigint; queue_count bigint; sent_outcome text; obs boolean; dg bytea; legacy_bytes bytea;
  target_status text; tick timestamptz; chosen_outcome text; reason text; aid text; still boolean;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='outbox drain requires read committed isolation'; end if;
  perform public.source_application_admit();
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode='22023',message='invalid outbox drain command size'; end if;
  begin raw:=convert_from($1,'UTF8')::json;
  exception when data_exception then raise exception using errcode='22023',message='invalid outbox drain command'; end;
  if json_typeof(raw) is distinct from 'object' or (select count(*) from json_each(raw))<>8
    or (select count(distinct x.key) from json_each(raw) x)<>8 or exists(select 1 from json_each(raw) x
      where x.key not in ('operation_id','record_id','reservation_id','fence_epoch','owner_id','owner_generation','owner_expires_at','surface_digest')
        or case when x.key in ('fence_epoch','owner_generation') then case
          when json_typeof(x.value)<>'number' or x.value::text !~ '^[1-9][0-9]*$' then true
          else x.value::text::numeric>9223372036854775807::numeric end
        else json_typeof(x.value)<>'string' end) then
    raise exception using errcode='22023',message='invalid outbox drain fields'; end if;
  v:=raw::jsonb;
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$'
    or v->>'surface_digest'<>'03498615d38f1445dc2414657d4efe45fb4c8b564430d79f40220e209c9802e8'
    or v->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception using errcode='22023',message='invalid outbox drain identity'; end if;
  generation:=(v->>'owner_generation')::bigint;
  begin expiry:=(v->>'owner_expires_at')::timestamptz;
  exception when data_exception then raise exception using errcode='22023',message='invalid outbox drain expiry'; end;
  select x.reservation_id into strict actual_reservation from public.record_purge_operations x where x.operation_id=v->>'operation_id';
  select x.* into strict res from public.deletion_reservations x where x.reservation_id=actual_reservation for update;
  if res.deletion_contract_version<>2 or res.project_id<>'default' or res.object_kind<>'record'
    or res.object_id<>v->>'record_id' or res.reservation_id<>v->>'reservation_id'
    or res.fence_epoch<>(v->>'fence_epoch')::bigint or res.state not in ('fenced','committed') then
    raise exception using errcode='42501',message='outbox drain reservation unavailable'; end if;
  select e.delivery_epoch into epoch from public.content_delivery_epochs e where e.project_id=res.project_id
    and e.object_kind=res.object_kind and e.object_id=res.object_id for update;
  if found and epoch<>res.fence_epoch then raise exception using errcode='42501',message='outbox drain epoch mismatch'; end if;
  perform 1 from public.deletion_fence_leases x where x.project_id=res.project_id
    and x.object_kind=res.object_kind and x.object_id=res.object_id for update;
  select x.* into strict gate from public.record_deletion_gates x where x.operation_id=v->>'operation_id' for share;
  if gate.project_id<>res.project_id or gate.record_id<>res.object_id or gate.fence_epoch<>res.fence_epoch then
    raise exception using errcode='42501',message='outbox drain gate mismatch'; end if;
  perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'owner_id',generation,expiry,res.object_id);
  select x.* into strict operation from public.record_purge_operations x where x.operation_id=v->>'operation_id';
  if operation.reservation_id<>res.reservation_id or operation.project_id<>res.project_id then
    raise exception using errcode='42501',message='outbox drain operation mismatch'; end if;
  perform 1 from public.records x where x.project_id=res.project_id and x.record_id=res.object_id for update;
  perform 1 from public.object_content_leases x where x.project_id=res.project_id
    and x.object_kind=res.object_kind and x.object_id=res.object_id for update;
  lock table public.record_outbox in share row exclusive mode;
  begin
    lock table public.record_actions,public.record_comments,public.record_notification_deliveries,
      public.record_notification_delivery_attempts,public.record_notifications in share mode nowait;
  exception when lock_not_available then raise exception using errcode='40001',message='outbox drain route changed; restart transaction'; end;
  if exists(select 1 from public.record_outbox x where x.subject_kind in ('record','action','comment','delivery')
      and record_platform_internal.record_outbox_observed_route(x) is null) then
    raise exception using errcode='55000',message='ambiguous legacy outbox route'; end if;

  while cnt<100 loop
    -- First hand off every actual start, including starts on terminal queues.
    select x.* into s from public.record_notification_delivery_starts x where x.project_id=res.project_id and x.record_id=res.object_id
      and not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
        and h.delivery_id=x.delivery_id and h.attempt_no=x.attempt_no)
      order by x.outbox_row_id,x.delivery_id collate "C",x.attempt_no limit 1;
    if found then
      perform 1 from public.record_outbox x where x.outbox_row_id=s.outbox_row_id for update;
      perform 1 from public.record_notification_deliveries x where x.delivery_id=s.delivery_id for update;
      select x.* into strict s from public.record_notification_delivery_starts x where x.attempt_id=s.attempt_id for update;
      if exists(select 1 from public.record_outbox x where x.outbox_row_id=s.outbox_row_id
          and (x.subject_kind<>'delivery' or x.subject_id<>s.delivery_id
            or record_platform_internal.record_outbox_observed_route(x)<>s.record_id))
        or exists(select 1 from public.record_notification_deliveries x where x.delivery_id=s.delivery_id
          and (x.record_id<>s.record_id or x.notification_id<>s.notification_id or x.record_fence_epoch<>s.record_fence_epoch)) then
        raise exception using errcode='55000',message='delivery handoff route conflict'; end if;
      select count(*),min(x.outcome) into providers,sent_outcome from public.record_notification_delivery_facts x
        where x.attempt_id=s.attempt_id and x.fact_kind='provider_report';
      target_status:=case when providers=1 and sent_outcome='sent' then 'sent'
        when providers=1 and sent_outcome in ('temporary_failure','permanent_failure') then 'not_sent'
        else 'possible_external' end;
      if target_status='possible_external' then
        dg:=record_platform_internal.record_external_delivery_fact_digest(s.correlation_digest,'drain_observation',
          'unknown_outcome','deletion_handoff_unknown');
        insert into public.record_notification_delivery_facts(attempt_id,fact_kind,evidence_digest,project_id,record_id,outcome,reason_code,reported_at)
          values(s.attempt_id,'drain_observation',dg,s.project_id,s.record_id,'unknown_outcome','deletion_handoff_unknown',clock_timestamp())
          on conflict on constraint record_notification_delivery_facts_pkey do nothing;
      end if;
      insert into public.record_notification_delivery_handoffs(operation_id,delivery_id,attempt_no,project_id,record_id,notification_id,
        record_fence_epoch,attempt_id,start_correlation_digest,legacy_observation_digest,legacy_observation,legacy_outbox_row_id,
        legacy_observation_kind,observed_status,observed_at)
      values(operation.operation_id,s.delivery_id,s.attempt_no,s.project_id,s.record_id,s.notification_id,s.record_fence_epoch,
        s.attempt_id,s.correlation_digest,null,null,null,null,target_status,clock_timestamp());
      cnt:=cnt+1; continue;
    end if;

    -- Predecessor attempts and processing projections have no fabricated
    -- start. Completed legacy observations survive the online projection too.
    select z.* into legacy from (
      select 1 as priority,a.delivery_id,a.attempt_no,a.record_id,a.notification_id,a.record_fence_epoch,
        a.started_at,a.outcome,a.attempt_id as legacy_attempt_id
      from public.record_notification_delivery_attempts a where a.record_id=res.object_id
        and not exists(select 1 from public.record_notification_delivery_starts x where x.delivery_id=a.delivery_id and x.attempt_no=a.attempt_no)
      union all
      select 2,completed.delivery_id,completed.attempt_no,completed.record_id,completed.notification_id,completed.record_fence_epoch,completed.started_at,
        'unknown_outcome'::text,null::text from public.record_notification_delivery_completions completed
        where completed.project_id=res.project_id and completed.record_id=res.object_id and completed.attempt_id is null
      union all
      select 3,x.delivery_id,x.attempt_count,x.record_id,x.notification_id,x.record_fence_epoch,x.attempt_started_at,
        'unknown_outcome'::text,null::text from public.record_notification_deliveries x
        where x.record_id=res.object_id and x.delivery_state='processing'
          and not exists(select 1 from public.record_notification_delivery_starts t where t.delivery_id=x.delivery_id and t.attempt_no=x.attempt_count)
      union all
      select 4,x.delivery_id,x.attempt_count,x.record_id,x.notification_id,x.record_fence_epoch,
        coalesce(x.sent_at,x.cancelled_at,x.updated_at),case when x.delivery_state='sent' then 'sent' else 'unknown_outcome' end,null::text
      from public.record_notification_deliveries x where x.record_id=res.object_id and x.attempt_count>0 and x.delivery_state<>'processing'
        and not exists(select 1 from public.record_notification_delivery_starts t where t.delivery_id=x.delivery_id and t.attempt_no=x.attempt_count)
        and not exists(select 1 from public.record_notification_delivery_attempts t where t.delivery_id=x.delivery_id and t.attempt_no=x.attempt_count)
    ) z where not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
        and h.delivery_id=z.delivery_id and h.attempt_no=z.attempt_no)
      order by z.delivery_id collate "C",z.attempt_no,z.priority limit 1;
    if found then
      if legacy.attempt_no not between 1 and 8 or legacy.started_at is null then
        raise exception using errcode='55000',message='legacy delivery identity unavailable'; end if;
      select count(*) into queue_count from public.record_outbox x where x.project_id=res.project_id
        and x.subject_kind='delivery' and x.subject_id=legacy.delivery_id;
      if queue_count>1 then raise exception using errcode='55000',message='ambiguous legacy delivery queue'; end if;
      select x.* into o from public.record_outbox x where x.project_id=res.project_id and x.subject_kind='delivery'
        and x.subject_id=legacy.delivery_id for update;
      select x.* into d from public.record_notification_deliveries x where x.delivery_id=legacy.delivery_id for update;
      select x.* into c from public.record_notification_delivery_completions x where x.delivery_id=legacy.delivery_id
        and x.attempt_no=legacy.attempt_no and x.attempt_id is null;
      if o.outbox_row_id is not null and c.outbox_row_id is not null and o.outbox_row_id<>c.outbox_row_id then
        raise exception using errcode='55000',message='legacy delivery queue identity conflict'; end if;
      target_status:=case when legacy.outcome='sent' then 'sent'
        when legacy.outcome in ('temporary_failure','permanent_failure','cancelled') then 'not_sent' else 'possible_external' end;
      -- This is a fixed, server-constructed tuple of bounded database fields,
      -- not a provider body, credential, arbitrary JSON or error message.
      legacy_bytes:=convert_to(jsonb_build_array('houfeng.external-delivery.legacy-handoff.v1',res.project_id,legacy.record_id,
        legacy.delivery_id,legacy.attempt_no,legacy.notification_id,legacy.record_fence_epoch,
        extract(epoch from legacy.started_at),legacy.outcome,legacy.legacy_attempt_id,
        case when d.delivery_id is null then null else jsonb_build_array(d.recipient_user_id,d.channel,d.binding_id,
          d.authorization_epoch,d.delivery_state,d.attempt_count,extract(epoch from d.attempt_started_at),
          extract(epoch from d.next_attempt_at),extract(epoch from d.sent_at),extract(epoch from d.cancelled_at),extract(epoch from d.updated_at)) end,
        case when o.outbox_row_id is null then null else jsonb_build_array(o.outbox_row_id,o.event_kind,o.subject_kind,o.subject_id,
          o.source_version,o.authorization_epoch,o.record_fence_epoch,o.status,o.owner_id,o.owner_generation,
          extract(epoch from o.owner_expires_at),extract(epoch from o.expires_at)) end,
        case when c.delivery_id is null then null else jsonb_build_array(c.outbox_row_id,c.recipient_user_id,c.channel,c.binding_id,
          c.source_version,c.authorization_epoch,c.record_fence_epoch,c.owner_id,c.owner_generation,
          extract(epoch from c.owner_expires_at),extract(epoch from c.event_expires_at),extract(epoch from c.started_at)) end)::text,'UTF8');
      dg:=sha256(legacy_bytes);
      insert into public.record_notification_delivery_handoffs(operation_id,delivery_id,attempt_no,project_id,record_id,notification_id,
        record_fence_epoch,attempt_id,start_correlation_digest,legacy_observation_digest,legacy_observation,legacy_outbox_row_id,
        legacy_observation_kind,observed_status,observed_at)
      values(operation.operation_id,legacy.delivery_id,legacy.attempt_no,res.project_id,legacy.record_id,legacy.notification_id,
        legacy.record_fence_epoch,null,null,dg,legacy_bytes,coalesce(o.outbox_row_id,c.outbox_row_id),'predecessor',target_status,clock_timestamp());
      cnt:=cnt+1; continue;
    end if;

    -- Terminate processing projections only after the corresponding handoff.
    select x.* into d from public.record_notification_deliveries x where x.record_id=res.object_id and x.delivery_state='processing'
      order by x.delivery_id collate "C" limit 1;
    if found then
      if d.attempt_count not between 1 and 8 or d.attempt_started_at is null then
        raise exception using errcode='55000',message='legacy delivery identity unavailable'; end if;
      perform 1 from public.record_outbox x where x.project_id=res.project_id and x.subject_kind='delivery'
        and x.subject_id=d.delivery_id order by x.outbox_row_id for update;
      select x.* into strict d from public.record_notification_deliveries x where x.delivery_id=d.delivery_id for update;
      select x.* into s from public.record_notification_delivery_starts x where x.delivery_id=d.delivery_id and x.attempt_no=d.attempt_count for update;
      obs:=found;
      if not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
        and h.delivery_id=d.delivery_id and h.attempt_no=d.attempt_count
        and (not obs and h.attempt_id is null or obs and h.attempt_id=s.attempt_id and h.start_correlation_digest=s.correlation_digest)) then
        raise exception using errcode='55000',message='delivery handoff unavailable'; end if;
      chosen_outcome:='unknown_outcome'; reason:='deletion_handoff_unknown';
      aid:='rna_'||encode(record_platform_internal.digest(
        record_platform_internal.source_retirement_field(convert_to('houfeng.record-collaboration.notification-delivery-attempt.v1','UTF8'))||
        record_platform_internal.source_retirement_field(convert_to(d.delivery_id,'UTF8'))||int8send(d.attempt_count::bigint),'sha256'),'hex');
      if obs then
        if s.attempt_id<>aid or s.started_at<>d.attempt_started_at then
          raise exception using errcode='55000',message='delivery start mismatch'; end if;
        select count(*),min(x.outcome) into providers,sent_outcome from public.record_notification_delivery_facts x
          where x.attempt_id=s.attempt_id and x.fact_kind='provider_report';
        if providers=1 and not exists(select 1 from public.record_notification_delivery_facts x
            where x.attempt_id=s.attempt_id and x.fact_kind='drain_observation') then
          chosen_outcome:=sent_outcome;
          reason:=case sent_outcome when 'sent' then '' when 'temporary_failure' then 'provider_temporary_failure'
            when 'permanent_failure' then 'provider_permanent_failure' else 'provider_unknown_outcome' end;
        end if;
      else reason:='legacy_processing_unknown'; end if;
      if exists(select 1 from public.record_notification_delivery_attempts x
        where x.delivery_id=d.delivery_id and x.attempt_no=d.attempt_count or x.attempt_id=aid) then
        raise exception using errcode='55000',message='delivery attempt projection conflict'; end if;
      tick:=clock_timestamp();
      insert into public.record_notification_delivery_attempts(attempt_id,record_id,delivery_id,notification_id,recipient_user_id,
        attempt_no,outcome,reason_code,authorization_epoch,record_fence_epoch,started_at,completed_at)
      values(aid,d.record_id,d.delivery_id,d.notification_id,d.recipient_user_id,d.attempt_count,chosen_outcome,reason,
        d.authorization_epoch,d.record_fence_epoch,d.attempt_started_at,tick);
      target_status:=case chosen_outcome when 'sent' then 'sent' when 'permanent_failure' then 'permanent_failure'
        when 'temporary_failure' then 'cancelled' else 'unknown_outcome' end;
      update public.record_notification_deliveries set delivery_state=target_status,attempt_started_at=null,next_attempt_at=null,
        reason_code=case when target_status='cancelled' then 'record_deleted' else reason end,
        sent_at=case when target_status='sent' then tick end,cancelled_at=case when target_status='cancelled' then tick end,updated_at=tick
        where delivery_id=d.delivery_id;
      cnt:=cnt+1; continue;
    end if;

    -- Bind every still-verifiable predecessor route before its subject can be
    -- purged, including terminal rows. NULL can never stand for zero inventory.
    select x.* into o from public.record_outbox x where x.project_id=res.project_id and x.record_id is null
      and record_platform_internal.record_outbox_observed_route(x)=res.object_id order by x.outbox_row_id limit 1 for update;
    if found then
      update public.record_outbox set record_id=res.object_id where outbox_row_id=o.outbox_row_id and record_id is null;
      if not found then raise exception using errcode='40001',message='outbox drain route changed; restart transaction'; end if;
      cnt:=cnt+1; continue;
    end if;

    -- Cancel all routed pending or processing work, regardless of its lease,
    -- next-attempt time or event TTL. Preserve proven sent state.
    select x.* into o from public.record_outbox x where x.project_id=res.project_id
      and (x.status in ('pending','processing') or (x.status='cancelled' and x.subject_kind='delivery'
        and exists(select 1 from public.record_notification_deliveries p
          where p.delivery_id=x.subject_id and p.record_id=res.object_id and p.delivery_state='pending' and p.attempt_count=0)))
      and record_platform_internal.record_outbox_observed_route(x)=res.object_id order by x.outbox_row_id limit 1 for update;
    if found then
      target_status:='cancelled';
      if o.subject_kind='delivery' then
        select x.* into d from public.record_notification_deliveries x where x.delivery_id=o.subject_id for update;
        if found then
          if d.record_id<>res.object_id or d.delivery_state='processing' then
            raise exception using errcode='55000',message='delivery drain projection unavailable'; end if;
          if d.delivery_state='pending' and d.attempt_count=0 then
            if exists(select 1 from public.record_notification_delivery_starts prior where prior.delivery_id=d.delivery_id)
              or exists(select 1 from public.record_notification_delivery_attempts a where a.delivery_id=d.delivery_id)
              or (select count(*) from public.record_outbox x where x.project_id=res.project_id
                    and x.subject_kind='delivery' and x.subject_id=d.delivery_id)<>1 then
              raise exception using errcode='55000',message='unstarted delivery identity ambiguous'; end if;
            if not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
                and h.delivery_id=d.delivery_id and h.attempt_no=1) then
              legacy_bytes:=convert_to(jsonb_build_array('houfeng.external-delivery.not-started.v1',res.project_id,d.record_id,
                d.delivery_id,d.notification_id,d.recipient_user_id,d.channel,d.binding_id,d.authorization_epoch,d.record_fence_epoch,
                d.delivery_state,d.attempt_count,o.outbox_row_id,o.event_kind,o.subject_kind,o.subject_id,o.source_version,
                o.authorization_epoch,o.record_fence_epoch,o.status,o.owner_id,o.owner_generation,
                extract(epoch from o.owner_expires_at),extract(epoch from o.expires_at))::text,'UTF8');
              insert into public.record_notification_delivery_handoffs(operation_id,delivery_id,attempt_no,project_id,record_id,notification_id,
                record_fence_epoch,attempt_id,start_correlation_digest,legacy_observation_digest,legacy_observation,legacy_outbox_row_id,
                legacy_observation_kind,observed_status,observed_at)
              values(operation.operation_id,d.delivery_id,1,res.project_id,d.record_id,d.notification_id,d.record_fence_epoch,
                null,null,sha256(legacy_bytes),legacy_bytes,o.outbox_row_id,'not_started','not_sent',clock_timestamp());
              cnt:=cnt+1; continue;
            elsif not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
                and h.delivery_id=d.delivery_id and h.attempt_no=1 and h.record_id=d.record_id and h.notification_id=d.notification_id
                and h.record_fence_epoch=d.record_fence_epoch and h.legacy_observation_kind='not_started'
                and h.legacy_outbox_row_id=o.outbox_row_id and h.observed_status='not_sent') then
              raise exception using errcode='55000',message='unstarted delivery handoff conflict';
            end if;
          end if;
          if d.delivery_state='sent' then target_status:='sent';
          elsif d.delivery_state in ('pending','retry_wait') then
            update public.record_notification_deliveries set delivery_state='cancelled',attempt_started_at=null,next_attempt_at=null,
              reason_code='record_deleted',cancelled_at=clock_timestamp(),updated_at=clock_timestamp() where delivery_id=d.delivery_id;
          end if;
        elsif not exists(select 1 from public.record_notification_delivery_starts x where x.outbox_row_id=o.outbox_row_id
            and x.delivery_id=o.subject_id and x.record_id=res.object_id)
          and not exists(select 1 from public.record_notification_delivery_handoffs h where h.operation_id=operation.operation_id
            and h.delivery_id=o.subject_id and h.record_id=res.object_id and h.legacy_outbox_row_id=o.outbox_row_id) then
          raise exception using errcode='55000',message='legacy delivery evidence unavailable';
        end if;
      end if;
      update public.record_outbox set record_id=coalesce(record_id,res.object_id),status=target_status,owner_id='',owner_expires_at=null,
        sent_at=case when target_status='sent' then clock_timestamp() else sent_at end where outbox_row_id=o.outbox_row_id;
      cnt:=cnt+1; continue;
    end if;
    exit;
  end loop;
  still:=not record_platform_internal.record_outbox_handoff_complete(operation.operation_id,res.object_id);
  if cnt=0 and still then raise exception using errcode='55000',message='outbox drain cannot establish complete handoff'; end if;
  perform record_platform_internal.local_blob_cleanup_operation(operation.operation_id,v->>'owner_id',generation,expiry,res.object_id);
  return query select cnt,still;
end $$;
revoke all on function record_platform_internal.record_outbox_observed_route(public.record_outbox),
  record_platform_internal.record_outbox_handoff_complete(text,text),public.record_outbox_drain_v2(bytea) from public;

create function record_platform_internal.client_metadata_purge(bytea, text, boolean)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language plpgsql security definer set search_path = pg_catalog
as $$
declare
  command_json json;
  command jsonb;
  expected_surface bytea;
  actual_reservation_id text;
  actual_delivery_epoch bigint;
  reservation public.deletion_reservations;
  gate public.record_deletion_gates;
  operation public.record_purge_operations;
  owner_generation bigint;
  owner_expires_at timestamptz;
  stored_surface bytea;
  stored_receipt bytea;
  stored_count bigint;
  stored_absent_at timestamptz;
  has_receipt boolean;
  removed bigint := 0;
  affected bigint;
  expected_receipt bytea;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'client purge requires read committed isolation';
  end if;
  perform public.source_application_admit();
  perform pg_advisory_xact_lock_shared(1213154899, 1);
  perform pg_advisory_xact_lock(1213154899,81);

  if $1 is null or octet_length($1) not between 1 and 65536 then
    raise exception using errcode = '22023', message = 'invalid client purge command size';
  end if;
  -- Inspect json before conversion to jsonb: jsonb discards duplicate keys.
  command_json := convert_from($1, 'UTF8')::json;
  if json_typeof(command_json) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'invalid client purge command object';
  end if;
  if (select count(*) from json_each(command_json)) <> 8
    or (select count(distinct field.key) from json_each(command_json) as field) <> 8
    or exists (select 1 from json_each(command_json) as field
      where field.key not in ('operation_id', 'record_id', 'reservation_id', 'fence_epoch',
          'owner_id', 'owner_generation', 'owner_expires_at', 'surface_digest')
        or (field.key in ('owner_generation', 'fence_epoch') and
          (json_typeof(field.value) <> 'number' or field.value::text !~ '^[1-9][0-9]*$'))
        or (field.key not in ('owner_generation', 'fence_epoch') and json_typeof(field.value) <> 'string')) then
    raise exception using errcode = '22023', message = 'invalid client purge command fields';
  end if;
  command := command_json::jsonb;
  if command->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$'
    or command->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or command->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or command->>'owner_id' !~ '^[a-z0-9_-]{1,128}$'
    or command->>'surface_digest' !~ '^[0-9a-f]{64}$'
    or command->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception using errcode = '22023', message = 'invalid client purge identity';
  end if;
  owner_generation := (command->>'owner_generation')::bigint;
  owner_expires_at := (command->>'owner_expires_at')::timestamptz;
  if $2 = 'record_markdown_client' then
    expected_surface := decode('fbf3be26fad82b0045f9c13f7379b1808eb590cc46107e36e2d19ea2e7df6c32', 'hex');
  elsif $2 = 'record_comparison' then
    expected_surface := decode('e83ca414d2cefa65a747f68ce0b6a855b7eddd633e427ea350dc5fb182885780', 'hex');
  elsif $2 = 'record_collaboration' then
    expected_surface := decode('03498615d38f1445dc2414657d4efe45fb4c8b564430d79f40220e209c9802e8', 'hex');
  else
    raise exception using errcode = '22023', message = 'invalid client purge adapter';
  end if;
  if decode(command->>'surface_digest', 'hex') is distinct from expected_surface then
    raise exception using errcode = '22023', message = 'client purge surface mismatch';
  end if;

  -- Discovery does not authorize a mutation. Lock the actual reservation
  -- before the optional epoch and lease, gate, operation, and optional root.
  select o.reservation_id into strict actual_reservation_id from public.record_purge_operations o
    where o.operation_id = command->>'operation_id';
  select r.* into strict reservation from public.deletion_reservations r
    where r.reservation_id = actual_reservation_id for update;
  if reservation.deletion_contract_version <> 2 or reservation.project_id <> 'default'
    or reservation.reservation_id is distinct from command->>'reservation_id'
    or reservation.fence_epoch is distinct from (command->>'fence_epoch')::bigint
    or reservation.object_kind <> 'record' or reservation.object_id is distinct from command->>'record_id'
    or reservation.state not in ('fenced', 'committed') or reservation.fence_epoch <= 0 then
    raise exception using errcode = '42501', message = 'client purge reservation unavailable';
  end if;
  select e.delivery_epoch into actual_delivery_epoch from public.content_delivery_epochs e
    where e.project_id = reservation.project_id and e.object_kind = reservation.object_kind
      and e.object_id = reservation.object_id for update;
  if found and actual_delivery_epoch is distinct from reservation.fence_epoch then
    raise exception using errcode = '42501', message = 'client purge delivery epoch mismatch';
  end if;
  perform 1 from public.deletion_fence_leases l
    where l.project_id = reservation.project_id and l.object_kind = reservation.object_kind
      and l.object_id = reservation.object_id for update;
  select g.* into strict gate from public.record_deletion_gates g
    where g.operation_id = command->>'operation_id' for share;
  if gate.project_id is distinct from reservation.project_id
    or gate.record_id is distinct from reservation.object_id
    or gate.fence_epoch is distinct from reservation.fence_epoch then
    raise exception using errcode = '42501', message = 'client purge gate mismatch';
  end if;
  perform record_platform_internal.local_blob_cleanup_operation(command->>'operation_id', command->>'owner_id',
    owner_generation, owner_expires_at, reservation.object_id);
  select o.* into strict operation from public.record_purge_operations o
    where o.operation_id = command->>'operation_id';
  if operation.reservation_id is distinct from reservation.reservation_id
    or operation.project_id is distinct from reservation.project_id
    or not exists (select 1 from public.browser_record_cleanup_events event
      where event.operation_id = gate.operation_id and event.project_id = gate.project_id
        and event.record_id = gate.record_id and event.cleanup_epoch = gate.fence_epoch
        and event.scopes = array['markdown_draft_buffer', 'markdown_workspace',
          'comparison_workbench', 'comparison_save_attempt']::text[]) then
    raise exception using errcode = '42501', message = 'client purge operation or cleanup event mismatch';
  end if;
  perform 1 from public.records r where r.project_id = reservation.project_id
    and r.record_id = reservation.object_id for update;

  -- Freeze the affected metadata tables during effects and absence checks.
  -- These locks do not authorize or change any browser delivery evidence.
  if $2 = 'record_markdown_client' then
    lock table public.markdown_client_draft_buffers in share row exclusive mode;
    lock table public.markdown_client_workspaces in share row exclusive mode;
    select r.removed_surface_digest, r.receipt_digest, r.removed_row_count, r.verified_absent_at
      into stored_surface, stored_receipt, stored_count, stored_absent_at
      from public.record_markdown_client_purge_receipts r where r.operation_id = operation.operation_id;
    has_receipt := found;
  elsif $2 = 'record_comparison' then
    lock table public.comparison_client_save_attempts in share row exclusive mode;
    lock table public.comparison_client_workbenches in share row exclusive mode;
    lock table public.comparison_result_dependencies in share row exclusive mode;
    lock table public.comparison_result_dependency_index_completions in share row exclusive mode;
    select r.removed_surface_digest, r.receipt_digest, r.removed_row_count, r.verified_absent_at
      into stored_surface, stored_receipt, stored_count, stored_absent_at
      from public.record_comparison_purge_receipts r where r.operation_id = operation.operation_id;
    has_receipt := found;
  else
    lock table public.record_outbox in share row exclusive mode;
    begin
      lock table public.record_action_events, public.record_actions, public.record_comment_mentions,
        public.record_comment_replies, public.record_comment_revisions, public.record_comment_tombstones,
        public.record_comments, public.record_followers, public.record_notification_audit_summaries,
        public.record_notification_deliveries, public.record_notification_delivery_attempts,
        public.record_notification_delivery_starts, public.record_notification_recipients,
        public.record_notifications in share row exclusive mode nowait;
    exception when lock_not_available then
      raise exception using errcode='40001',message='collaboration purge route changed; restart transaction';
    end;
    select r.removed_surface_digest, r.receipt_digest, r.removed_row_count, r.verified_absent_at
      into stored_surface, stored_receipt, stored_count, stored_absent_at
      from public.record_collaboration_purge_receipts r where r.operation_id = operation.operation_id;
    has_receipt := found;
  end if;
  if $2='record_collaboration' and not record_platform_internal.record_outbox_handoff_complete(
      operation.operation_id,reservation.object_id) then
    raise exception using errcode='55000',message='collaboration outbox handoff incomplete';
  end if;
  if $3 and not has_receipt then
    raise exception using errcode = '55000', message = 'client purge receipt unavailable';
  end if;
  perform record_platform_internal.local_blob_cleanup_operation(operation.operation_id, command->>'owner_id',
    owner_generation, owner_expires_at, reservation.object_id);

  if not has_receipt then
    if $2 = 'record_markdown_client' then
      delete from public.markdown_client_draft_buffers b
        where b.project_id = reservation.project_id and b.record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.markdown_client_workspaces w
        where w.project_id = reservation.project_id and w.record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
    elsif $2 = 'record_comparison' then
      delete from public.comparison_client_save_attempts a
        where a.project_id = reservation.project_id and
          (a.destination_record_id = reservation.object_id or reservation.object_id = any(a.source_record_ids));
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.comparison_client_workbenches w
        where w.project_id = reservation.project_id and
          (w.destination_record_id = reservation.object_id or reservation.object_id = any(w.source_record_ids));
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.comparison_result_dependencies d using public.evidence_snapshots s
        where d.result_snapshot_id = s.snapshot_id and s.record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.comparison_result_dependency_index_completions c using public.evidence_snapshots s
        where c.result_snapshot_id = s.snapshot_id and s.record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
    else
      -- Starts, facts, completions and handoffs are retained responsibilities,
      -- not deleted content and not part of the removed-row count.
      delete from public.record_notification_delivery_attempts where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_notification_audit_summaries where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_notification_deliveries where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_notification_recipients where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_notifications where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_comment_mentions where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_comment_replies where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_comment_revisions where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_comment_tombstones where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_comments where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_action_events where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_actions where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
      delete from public.record_followers where record_id = reservation.object_id;
      get diagnostics affected = row_count; removed := removed + affected;
    end if;
  end if;

  if $2 = 'record_markdown_client' then
    if exists (select 1 from public.markdown_client_draft_buffers b
        where b.project_id = reservation.project_id and b.record_id = reservation.object_id)
      or exists (select 1 from public.markdown_client_workspaces w
        where w.project_id = reservation.project_id and w.record_id = reservation.object_id) then
      raise exception using errcode = '55000', message = 'markdown client purge absence unavailable';
    end if;
  elsif $2 = 'record_comparison' then
    if exists (select 1 from public.comparison_client_save_attempts a
        where a.project_id = reservation.project_id and
          (a.destination_record_id = reservation.object_id or reservation.object_id = any(a.source_record_ids)))
      or exists (select 1 from public.comparison_client_workbenches w
        where w.project_id = reservation.project_id and
          (w.destination_record_id = reservation.object_id or reservation.object_id = any(w.source_record_ids)))
      or exists (select 1 from public.comparison_result_dependencies d join public.evidence_snapshots s
        on s.snapshot_id = d.result_snapshot_id where s.record_id = reservation.object_id)
      or exists (select 1 from public.comparison_result_dependency_index_completions c join public.evidence_snapshots s
        on s.snapshot_id = c.result_snapshot_id where s.record_id = reservation.object_id) then
      raise exception using errcode = '55000', message = 'comparison purge absence unavailable';
    end if;
  else
    if exists (select 1 from public.record_action_events where record_id = reservation.object_id)
      or exists (select 1 from public.record_actions where record_id = reservation.object_id)
      or exists (select 1 from public.record_comment_mentions where record_id = reservation.object_id)
      or exists (select 1 from public.record_comment_replies where record_id = reservation.object_id)
      or exists (select 1 from public.record_comment_revisions where record_id = reservation.object_id)
      or exists (select 1 from public.record_comment_tombstones where record_id = reservation.object_id)
      or exists (select 1 from public.record_comments where record_id = reservation.object_id)
      or exists (select 1 from public.record_followers where record_id = reservation.object_id)
      or exists (select 1 from public.record_notification_audit_summaries where record_id = reservation.object_id)
      or exists (select 1 from public.record_notification_deliveries where record_id = reservation.object_id)
      or exists (select 1 from public.record_notification_delivery_attempts where record_id = reservation.object_id)
      or exists (select 1 from public.record_notification_recipients where record_id = reservation.object_id)
      or exists (select 1 from public.record_notifications where record_id = reservation.object_id) then
      raise exception using errcode = '55000', message = 'collaboration purge absence unavailable';
    end if;
  end if;
  if $2='record_collaboration' and not record_platform_internal.record_outbox_handoff_complete(
      operation.operation_id,reservation.object_id) then
    raise exception using errcode='55000',message='collaboration outbox handoff incomplete';
  end if;

  if has_receipt then
    removed := stored_count;
  end if;
  expected_receipt := sha256(
    record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.client-purge.v1', 'UTF8')) ||
    record_platform_internal.client_purge_field(convert_to(operation.operation_id, 'UTF8')) ||
    record_platform_internal.client_purge_field(convert_to(reservation.object_id, 'UTF8')) ||
    record_platform_internal.client_purge_field(convert_to($2, 'UTF8')) ||
    record_platform_internal.client_purge_field(expected_surface) ||
    record_platform_internal.client_purge_field(int8send(removed)));
  if has_receipt and (stored_surface is distinct from expected_surface
      or stored_receipt is distinct from expected_receipt or stored_count < 0 or stored_absent_at is null) then
    raise exception using errcode = '55000', message = 'client purge receipt mismatch';
  end if;

  if not has_receipt then
    stored_surface := expected_surface;
    stored_receipt := expected_receipt;
    stored_count := removed;
    stored_absent_at := clock_timestamp();
    if $2 = 'record_markdown_client' then
      insert into public.record_markdown_client_purge_receipts
        (operation_id, removed_surface_digest, receipt_digest, removed_row_count, verified_absent_at)
        values (operation.operation_id, stored_surface, stored_receipt, stored_count, stored_absent_at);
    elsif $2 = 'record_comparison' then
      insert into public.record_comparison_purge_receipts
        (operation_id, removed_surface_digest, receipt_digest, removed_row_count, verified_absent_at)
        values (operation.operation_id, stored_surface, stored_receipt, stored_count, stored_absent_at);
    else
      insert into public.record_collaboration_purge_receipts
        (operation_id, removed_surface_digest, receipt_digest, removed_row_count, verified_absent_at)
        values (operation.operation_id, stored_surface, stored_receipt, stored_count, stored_absent_at);
    end if;
  end if;
  perform record_platform_internal.local_blob_cleanup_operation(operation.operation_id, command->>'owner_id',
    owner_generation, owner_expires_at, reservation.object_id);
  return query select stored_surface, stored_receipt, stored_count, stored_absent_at;
end
$$;

create function public.record_markdown_client_purge(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_markdown_client', false) $$;

create function public.record_markdown_client_purge_verify(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_markdown_client', true) $$;

create function public.record_comparison_purge(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_comparison', false) $$;

create function public.record_comparison_purge_verify(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_comparison', true) $$;

create function public.record_collaboration_purge_v2(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_collaboration', false) $$;

create function public.record_collaboration_purge_verify_v2(bytea)
returns table (removed_surface_digest bytea, receipt_digest bytea,
  removed_row_count bigint, verified_absent_at timestamptz)
language sql security definer set search_path = pg_catalog
as $$ select * from record_platform_internal.client_metadata_purge($1, 'record_collaboration', true) $$;

revoke all on function record_platform_internal.enforce_client_purge_receipt_immutable(),
  record_platform_internal.client_purge_field(bytea),
  record_platform_internal.client_metadata_purge(bytea, text, boolean),
  public.record_markdown_client_purge(bytea), public.record_markdown_client_purge_verify(bytea),
  public.record_comparison_purge(bytea), public.record_comparison_purge_verify(bytea),
  public.record_collaboration_purge_v2(bytea), public.record_collaboration_purge_verify_v2(bytea) from public;

-- The runtime issuer is the trusted caller for source authorization and the
-- nine-adapter snapshot. These commands enforce its persisted identity and CAS;
-- they do not manufacture or independently attest those application facts.
create function record_platform_internal.record_deletion_issuer_admit()
returns void language plpgsql security definer set search_path = pg_catalog
as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'deletion issuer requires read committed isolation';
  end if;
  perform public.source_application_admit();
  if exists (select 1 from public.source_authority_admission where singleton)
    and not exists (
      select 1 from public.source_authority_admission s
      join public.source_application_principals p on p.generation = s.generation
      where s.singleton and s.mode = 'active' and p.principal = session_user and p.purpose = 'runtime'
    ) then
    raise exception using errcode = '42501', message = 'deletion issuer requires the admitted runtime login';
  end if;
end
$$;

-- Inspect JSON before converting to jsonb, which would discard duplicate keys.
-- The limit includes the largest permitted (hex encoded) authorization bytes.
create function record_platform_internal.record_deletion_issuer_command(bytea, text[])
returns jsonb language plpgsql immutable set search_path = pg_catalog
as $$
declare
  input_json json;
  command jsonb;
begin
  if $1 is null or octet_length($1) not between 1 and 140000 then
    raise exception using errcode = '22023', message = 'invalid deletion issuer command size';
  end if;
  input_json := convert_from($1, 'UTF8')::json;
  if json_typeof(input_json) is distinct from 'object' then
    raise exception using errcode = '22023', message = 'invalid deletion issuer command object';
  end if;
  if (select count(*) from json_each(input_json)) <> cardinality($2)
    or (select count(distinct field.key) from json_each(input_json) field) <> cardinality($2)
    or exists (
      select 1 from json_each(input_json) field
      where not (field.key = any($2))
        or case
          when field.key in ('lock_version', 'authorization_epoch', 'content_epoch') then
            json_typeof(field.value) <> 'number' or field.value::text !~ '^(0|[1-9][0-9]*)$'
          when field.key = 'confirmed' then
            json_typeof(field.value) <> 'boolean' or field.value::text <> 'true'
          when field.key = 'backup_inventory_digest' then
            json_typeof(field.value) not in ('string', 'null')
          else json_typeof(field.value) <> 'string'
        end
    ) then
    raise exception using errcode = '22023', message = 'invalid deletion issuer command fields';
  end if;
  command := input_json::jsonb;
  if (command ? 'deployment_id' and command->>'deployment_id' !~ '^dp-[0-9a-f]{64}$')
    or (command ? 'record_id' and command->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$')
    or (command ? 'actor_id' and command->>'actor_id' !~ '^usr_[a-z0-9]{1,64}$')
    or (command ? 'reservation_id' and command->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$')
    or (command ? 'operation_id' and command->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$')
    or (command ? 'owner_id' and command->>'owner_id' !~ '^[a-z0-9_-]{1,128}$')
    or (command ? 'revision_id' and command->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$')
    or (command ? 'lifecycle' and command->>'lifecycle' not in ('active', 'trashed'))
    or exists (
      select 1 from jsonb_each(command) field
      where field.key in ('actor_scope_digest', 'token_commitment', 'request_fingerprint',
          'binding_digest', 'dependency_digest', 'processor_digest', 'obligation_digest',
          'adapter_readiness_digest', 'adapter_preview_digest', 'backup_inventory_digest')
        and field.value <> 'null'::jsonb and field.value #>> '{}' !~ '^[0-9a-f]{64}$'
    )
    or (command ? 'authorization_evidence' and (
      length(command->>'authorization_evidence') not between 2 and 131072
      or length(command->>'authorization_evidence') % 2 <> 0
      or command->>'authorization_evidence' !~ '^[0-9a-f]+$')) then
    raise exception using errcode = '22023', message = 'invalid deletion issuer command identity';
  end if;
  return command;
end
$$;

-- Existing reservation rows are locked first, then the epoch serializes an
-- empty reservation/gate scope as well as all competing fence acquisitions.
create function record_platform_internal.record_deletion_issuer_snapshot(text)
returns table (lifecycle text, revision_id text, lock_version bigint,
  authorization_epoch bigint, content_epoch bigint, fence_generation bigint,
  deletion_lease_live boolean, object_lease_live boolean)
language plpgsql security definer set search_path = pg_catalog
as $$
declare
  root public.records;
  fence public.deletion_fence_leases;
  content_lease public.object_content_leases;
  epoch_value bigint;
begin
  -- A V1 preview may appear after the caller acquired its prefix and its
  -- fencer may already be waiting on that caller's epoch. Never wait on such
  -- a newly discovered reservation while holding the epoch or root.
  perform r.reservation_id from public.deletion_reservations r
    where r.project_id = 'default' and r.object_kind = 'record' and r.object_id = $1
    order by r.reservation_id for update nowait;
  select e.delivery_epoch into epoch_value from public.content_delivery_epochs e
    where e.project_id = 'default' and e.object_kind = 'record' and e.object_id = $1 for update;
  if not found then
    raise exception using errcode = '55000', message = 'deletion issuer record epoch missing';
  end if;
  select l.* into fence from public.deletion_fence_leases l
    where l.project_id = 'default' and l.object_kind = 'record' and l.object_id = $1 for update;
  select l.* into content_lease from public.object_content_leases l
    where l.project_id = 'default' and l.object_kind = 'record' and l.object_id = $1 for update;
  perform g.operation_id from public.record_deletion_gates g
    where g.project_id = 'default' and g.record_id = $1 for share;
  if found or exists (
    select 1 from public.deletion_reservations r where r.project_id = 'default'
      and r.object_kind = 'record' and r.object_id = $1 and r.state in ('fenced', 'committed')
  ) then
    raise exception using errcode = '55000', message = 'record deletion already fenced';
  end if;
  select r.* into root from public.records r
    where r.project_id = 'default' and r.record_id = $1 for update;
  if not found then
    raise exception using errcode = '55000', message = 'deletion issuer record missing';
  end if;
  lifecycle := root.lifecycle;
  revision_id := root.current_revision_id;
  lock_version := root.lock_version;
  authorization_epoch := root.authorization_epoch;
  content_epoch := epoch_value;
  fence_generation := coalesce(fence.owner_generation, 0);
  deletion_lease_live := coalesce(fence.expires_at > clock_timestamp(), false);
  object_lease_live := coalesce(content_lease.expires_at > clock_timestamp(), false);
  return next;
end
$$;

create function public.record_deletion_preview_create(bytea)
returns public.record_deletion_previews
language plpgsql security definer set search_path = pg_catalog
as $$
declare
  command jsonb;
  snapshot record;
  preview public.record_deletion_previews;
  created timestamptz;
begin
  perform record_platform_internal.record_deletion_issuer_admit();
  command := record_platform_internal.record_deletion_issuer_command($1, array[
    'deployment_id', 'record_id', 'actor_id', 'actor_scope_digest', 'token_commitment', 'reservation_id',
    'request_fingerprint', 'binding_digest', 'authorization_evidence', 'lifecycle',
    'revision_id', 'lock_version', 'authorization_epoch', 'content_epoch',
    'dependency_digest', 'processor_digest', 'obligation_digest', 'adapter_readiness_digest',
    'adapter_preview_digest', 'backup_inventory_digest']);
  perform 1 from public.users u
    where u.user_id = command->>'actor_id' and u.role = 'admin' and u.disabled_at is null for share;
  if not found then
    raise exception using errcode = '42501', message = 'deletion actor is not an enabled administrator';
  end if;
  if exists (select 1 from public.source_authority_admission s
    where s.singleton and s.deployment_id <> command->>'deployment_id') then
    raise exception using errcode = '55000', message = 'deletion deployment identity changed';
  end if;
  select * into strict snapshot from record_platform_internal.record_deletion_issuer_snapshot(command->>'record_id');
  if row(snapshot.lifecycle, snapshot.revision_id, snapshot.lock_version, snapshot.authorization_epoch, snapshot.content_epoch)
    is distinct from row(command->>'lifecycle', command->>'revision_id', (command->>'lock_version')::bigint,
      (command->>'authorization_epoch')::bigint, (command->>'content_epoch')::bigint) then
    raise exception using errcode = '55000', message = 'deletion preview snapshot changed';
  end if;
  created := clock_timestamp();
  insert into public.record_deletion_previews (
    deletion_token_commitment, reservation_id, project_id, record_id, deployment_id, expected_lifecycle,
    expected_revision_id, expected_lock_version, expected_authorization_epoch, content_delivery_epoch,
    dependency_graph_digest, processor_inventory_digest, obligation_inventory_digest,
    adapter_readiness_digest, adapter_preview_digest, backup_inventory_digest,
    actor_id, actor_scope_digest, request_fingerprint, binding_digest, authorization_evidence,
    created_at, expires_at
  ) values (
    decode(command->>'token_commitment', 'hex'), command->>'reservation_id', 'default', command->>'record_id', command->>'deployment_id',
    command->>'lifecycle', command->>'revision_id', (command->>'lock_version')::bigint,
    (command->>'authorization_epoch')::bigint, (command->>'content_epoch')::bigint,
    decode(command->>'dependency_digest', 'hex'), decode(command->>'processor_digest', 'hex'),
    decode(command->>'obligation_digest', 'hex'), decode(command->>'adapter_readiness_digest', 'hex'),
    decode(command->>'adapter_preview_digest', 'hex'), decode(command->>'backup_inventory_digest', 'hex'),
    command->>'actor_id', decode(command->>'actor_scope_digest', 'hex'),
    decode(command->>'request_fingerprint', 'hex'), decode(command->>'binding_digest', 'hex'),
    decode(command->>'authorization_evidence', 'hex'), created, created + interval '10 minutes'
  ) returning * into preview;
  return preview;
end
$$;

create function public.record_deletion_preview_lock(bytea)
returns setof public.record_deletion_previews
language plpgsql security definer set search_path = pg_catalog
as $$
declare command jsonb;
begin
  perform record_platform_internal.record_deletion_issuer_admit();
  command := record_platform_internal.record_deletion_issuer_command($1,
    array['reservation_id', 'actor_id', 'record_id']);
  return query select p.* from public.record_deletion_previews p
    where p.reservation_id = command->>'reservation_id'
      and p.actor_id = command->>'actor_id' and p.project_id = 'default' and p.record_id = command->>'record_id'
    for update;
end
$$;

create function public.record_deletion_issue(bytea)
returns public.record_purge_operations
language plpgsql security definer set search_path = pg_catalog
as $$
declare
  command jsonb;
  preview public.record_deletion_previews;
  snapshot record;
  operation public.record_purge_operations;
  generation bigint;
  issued timestamptz;
  owner_expiry timestamptz;
  new_epoch bigint;
begin
  perform record_platform_internal.record_deletion_issuer_admit();
  command := record_platform_internal.record_deletion_issuer_command($1, array[
    'token_commitment', 'actor_id', 'actor_scope_digest', 'record_id', 'binding_digest',
    'authorization_evidence', 'request_fingerprint', 'reservation_id', 'operation_id', 'owner_id', 'confirmed']);
  perform 1 from public.users u
    where u.user_id = command->>'actor_id' and u.role = 'admin' and u.disabled_at is null for share;
  if not found then
    raise exception using errcode = '42501', message = 'deletion actor is not an enabled administrator';
  end if;
  select p.* into preview from public.record_deletion_previews p
    where p.deletion_token_commitment = decode(command->>'token_commitment', 'hex') for update;
  if not found or row(preview.reservation_id, preview.project_id, preview.record_id, preview.actor_id, preview.actor_scope_digest,
      preview.binding_digest, preview.authorization_evidence, preview.request_fingerprint)
    is distinct from row(command->>'reservation_id', 'default'::text, command->>'record_id', command->>'actor_id',
      decode(command->>'actor_scope_digest', 'hex'), decode(command->>'binding_digest', 'hex'),
      decode(command->>'authorization_evidence', 'hex'), decode(command->>'request_fingerprint', 'hex')) then
    raise exception using errcode = '55000', message = 'deletion preview identity conflict';
  end if;
  if exists (select 1 from public.source_authority_admission s
    where s.singleton and s.deployment_id <> preview.deployment_id) then
    raise exception using errcode = '55000', message = 'deletion deployment identity changed';
  end if;
  if preview.operation_id is not null then
    select o.* into operation from public.record_purge_operations o
    join public.deletion_reservations r on r.reservation_id = o.reservation_id
    join public.record_deletion_gates g on g.operation_id = o.operation_id
    where o.operation_id = preview.operation_id and o.deletion_contract_version = 2
      and o.project_id = preview.project_id and o.deployment_id = preview.deployment_id and o.actor_id = preview.actor_id
      and r.project_id = preview.project_id and r.object_kind = 'record' and r.object_id = preview.record_id
      and r.deletion_token_commitment = preview.deletion_token_commitment
      and r.request_fingerprint = preview.request_fingerprint
      and g.project_id = preview.project_id and g.record_id = preview.record_id
      and g.actor_id = preview.actor_id and g.actor_scope_digest = preview.actor_scope_digest
      and g.binding_digest = preview.binding_digest and g.authorization_evidence = preview.authorization_evidence
      and g.request_fingerprint = preview.request_fingerprint;
    if not found then
      raise exception using errcode = '55000', message = 'bound deletion operation identity conflict';
    end if;
    return operation;
  end if;
  select * into strict snapshot from record_platform_internal.record_deletion_issuer_snapshot(preview.record_id);
  if row(snapshot.lifecycle, snapshot.revision_id, snapshot.lock_version, snapshot.authorization_epoch, snapshot.content_epoch)
    is distinct from row(preview.expected_lifecycle, preview.expected_revision_id, preview.expected_lock_version,
      preview.expected_authorization_epoch, preview.content_delivery_epoch) then
    raise exception using errcode = '55000', message = 'deletion preview snapshot changed';
  end if;
  if snapshot.deletion_lease_live or snapshot.object_lease_live then
    raise exception using errcode = '55000', message = 'record deletion has a live prior lease';
  end if;
  issued := clock_timestamp();
  if preview.expires_at <= issued then
    raise exception using errcode = '55000', message = 'deletion preview expired';
  end if;
  select greatest(snapshot.fence_generation, coalesce(max(r.owner_generation), 0)) into generation
    from public.deletion_reservations r
    where r.project_id = 'default' and r.object_kind = 'record' and r.object_id = preview.record_id;
  if generation = 9223372036854775807 or snapshot.content_epoch = 9223372036854775807 then
    raise exception using errcode = '22003', message = 'deletion fence counter exhausted';
  end if;
  generation := generation + 1;
  new_epoch := snapshot.content_epoch + 1;
  owner_expiry := issued + interval '1 second';
  update public.content_delivery_epochs e set delivery_epoch = new_epoch, updated_at = issued
    where e.project_id = 'default' and e.object_kind = 'record' and e.object_id = preview.record_id;
  insert into public.deletion_reservations (
    reservation_id, project_id, object_kind, object_id, deletion_token_commitment, request_fingerprint,
    state, fence_epoch, owner_id, owner_generation, owner_expires_at, created_at, expires_at,
    actor_scope_digest, preview_binding_digest, preview_current_revision_id, preview_lock_version,
    preview_authorization_epoch, preview_content_delivery_epoch, preview_dependency_graph_digest,
    preview_backup_inventory_digest, preview_processor_inventory_digest, adapter_readiness_digest,
    adapter_preview_digest, deletion_contract_version
  ) values (
    command->>'reservation_id', preview.project_id, 'record', preview.record_id,
    preview.deletion_token_commitment, preview.request_fingerprint, 'fenced', new_epoch,
    command->>'owner_id', generation, owner_expiry, preview.created_at, preview.expires_at,
    preview.actor_scope_digest, preview.binding_digest, preview.expected_revision_id, preview.expected_lock_version,
    preview.expected_authorization_epoch, preview.content_delivery_epoch, preview.dependency_graph_digest,
    preview.backup_inventory_digest, preview.processor_inventory_digest, preview.adapter_readiness_digest,
    preview.adapter_preview_digest, 2
  );
  insert into public.deletion_fence_leases (
    project_id, object_kind, object_id, owner_id, owner_generation, expires_at, created_at
  ) values (preview.project_id, 'record', preview.record_id, command->>'owner_id', generation, owner_expiry, issued)
  on conflict (project_id, object_kind, object_id) do update
    set owner_id = excluded.owner_id, owner_generation = excluded.owner_generation, expires_at = excluded.expires_at
    where deletion_fence_leases.expires_at <= issued;
  if not found then
    raise exception using errcode = '55000', message = 'record deletion fence lease changed';
  end if;
  insert into public.record_purge_operations (
    operation_id, reservation_id, project_id, operation_state, deployment_id, actor_id, reason_code,
    deletion_contract_version, owner_id, owner_generation, owner_expires_at, started_at, updated_at
  ) values (
    command->>'operation_id', command->>'reservation_id', preview.project_id, 'online_purging',
    preview.deployment_id, preview.actor_id, 'user_confirmed', 2, command->>'owner_id', generation,
    owner_expiry, issued, issued
  ) returning * into operation;
  insert into public.record_deletion_gates (
    operation_id, project_id, record_id, expected_lifecycle, expected_revision_id, expected_lock_version,
    expected_authorization_epoch, fence_epoch, actor_id, actor_scope_digest, request_fingerprint,
    binding_digest, authorization_evidence, issued_at
  ) values (
    operation.operation_id, preview.project_id, preview.record_id, preview.expected_lifecycle,
    preview.expected_revision_id, preview.expected_lock_version, preview.expected_authorization_epoch,
    new_epoch, preview.actor_id, preview.actor_scope_digest, preview.request_fingerprint,
    preview.binding_digest, preview.authorization_evidence, issued
  );
  update public.record_deletion_previews p set operation_id = operation.operation_id
    where p.deletion_token_commitment = preview.deletion_token_commitment and p.operation_id is null;
  if not found then
    raise exception using errcode = '55000', message = 'deletion preview binding changed';
  end if;
  return operation;
end
$$;

revoke all on function record_platform_internal.record_deletion_issuer_admit(),
  record_platform_internal.record_deletion_issuer_command(bytea, text[]),
  record_platform_internal.record_deletion_issuer_snapshot(text),
  public.record_deletion_preview_create(bytea), public.record_deletion_preview_lock(bytea),
  public.record_deletion_issue(bytea) from public;

-- A historical V1 preview can outlive issuance. Its fencer also locks the
-- delivery epoch, but a V2 gate must remain closed after the short issuer
-- lease expires. Preserve V1 fencing before a gate and permit only the gate's
-- own V2 reservation to be renewed or taken over afterward.
create function record_platform_internal.record_deletion_reservation_gate_guard()
returns trigger language plpgsql security definer set search_path = pg_catalog
as $$
begin
  if new.object_kind = 'record' and new.state in ('fenced', 'committed') and exists (
    select 1 from public.record_deletion_gates g
    where g.project_id = new.project_id and g.record_id = new.object_id
      and not exists (
        select 1 from public.record_purge_operations o
        where o.operation_id = g.operation_id and o.project_id = g.project_id
          and o.reservation_id = new.reservation_id and o.deletion_contract_version = 2
          and new.deletion_contract_version = 2
      )
  ) then
    raise exception using errcode = '55000', message = 'record deletion gate belongs to another reservation';
  end if;
  return new;
end
$$;
create trigger record_deletion_reservation_gate_guard
  before insert or update on public.deletion_reservations
  for each row execute function record_platform_internal.record_deletion_reservation_gate_guard();
revoke all on function record_platform_internal.record_deletion_reservation_gate_guard() from public;

-- Lock existing snapshot rows without granting the issuer direct UPDATE on
-- provenance or comparison tables. The caller holds the rank-73 Blob fence
-- and calls after acquiring relevant snapshot/revision rows. NOWAIT prevents
-- a late obligation lock from waiting behind a holder of an earlier rank.
-- An empty set is only an observation, never an absence lock.
create function public.record_deletion_inventory_lock(bytea)
returns bigint language plpgsql security definer set search_path = pg_catalog
as $$
declare
  command jsonb;
  target_record text;
  obligation_ids text[] := array[]::text[];
  snapshot_ids text[] := array[]::text[];
  item record;
  locked bigint := 0;
begin
  perform record_platform_internal.record_deletion_issuer_admit();
  if $1 is null or octet_length($1) > 4096 then
    raise exception using errcode = '22023', message = 'invalid deletion snapshot lock command size';
  end if;
  command := record_platform_internal.record_deletion_issuer_command($1, array['record_id']);
  target_record := command->>'record_id';
  if (select count(distinct l.relation) from pg_locks l
    where l.pid = pg_backend_pid() and l.granted
      and l.relation in ('public.blob_objects'::regclass, 'public.attachment_upload_parts'::regclass)
      and l.mode in ('ShareRowExclusiveLock', 'ExclusiveLock', 'AccessExclusiveLock')) <> 2 then
    raise exception using errcode = '55000', message = 'deletion snapshot requires the strong Blob fence';
  end if;
  for item in
    select p.upload_id from public.attachment_upload_parts p
    where exists (
      select 1 from public.attachment_uploads u
      join public.record_attachments a on a.attachment_id = u.attachment_id
      left join public.record_drafts d on d.draft_id = a.draft_id
      where u.upload_id = p.upload_id and (a.record_id = target_record or d.record_id = target_record))
    order by p.upload_id collate "C", p.part_number for update of p nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select a.export_artifact_id from public.record_export_artifacts a
    where exists (select 1 from public.record_export_jobs j
      where j.export_job_id = a.export_job_id and j.project_id = 'default' and j.record_id = target_record)
    order by a.export_artifact_id collate "C" for update of a nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select a.import_artifact_id from public.record_import_artifacts a
    where exists (
      select 1 from public.record_import_plans p
      join public.record_import_entity_mappings m on m.import_plan_id = p.import_plan_id
      where p.import_job_id = a.import_job_id and m.entity_kind = 'record' and m.target_id = target_record)
      or exists (
        select 1 from public.record_write_obligations o
        join public.record_write_obligation_targets t on t.obligation_id = o.obligation_id
        where o.origin_kind in ('import_archive', 'import_attachment') and o.origin_id = a.import_job_id
          and t.record_id = target_record)
    order by a.import_artifact_id collate "C" for update of a nowait
  loop
    locked := locked + 1;
  end loop;
    for item in
      select o.obligation_id from public.record_write_obligations o
      where o.project_id = 'default' and (
        o.record_id = target_record
        or exists (select 1 from public.record_write_obligation_targets t
          where t.obligation_id = o.obligation_id and t.record_id = target_record)
        or (o.origin_kind in ('upload', 'processor_preview') and exists (
          select 1 from public.record_drafts d where d.record_id = target_record
            and d.draft_id = (convert_from(o.registration_command, 'UTF8')::jsonb)->>'draft_id'))
        or (o.origin_kind = 'upload' and exists (
          select 1 from public.attachment_uploads u
          join public.record_attachments a on a.attachment_id = u.attachment_id
          left join public.record_drafts d on d.draft_id = a.draft_id
          where u.upload_id = o.origin_id and (a.record_id = target_record or d.record_id = target_record)))
        or (o.origin_kind = 'processor_preview' and exists (
          select 1 from public.attachment_processor_jobs j
          join public.record_attachments a on a.attachment_id = j.attachment_id
          left join public.record_drafts d on d.draft_id = a.draft_id
          where j.processor_job_id = o.origin_id and (a.record_id = target_record or d.record_id = target_record)))
        or (o.origin_kind = 'export_artifact' and exists (
          select 1 from public.record_export_jobs j
          where j.export_job_id = o.origin_id and j.record_id = target_record))
        or (o.origin_kind in ('import_archive', 'import_attachment') and exists (
          select 1 from public.record_import_plans p
          join public.record_import_entity_mappings m on m.import_plan_id = p.import_plan_id
          where p.import_job_id = o.origin_id and m.entity_kind = 'record' and m.target_id = target_record))
      ) order by o.obligation_id collate "C" for update of o nowait
    loop
      obligation_ids := array_append(obligation_ids, item.obligation_id);
      locked := locked + 1;
    end loop;
    for item in
      select t.obligation_id from public.record_write_obligation_targets t
      where t.obligation_id = any(obligation_ids)
      order by t.obligation_id collate "C", t.record_id collate "C" for update of t nowait
    loop
      locked := locked + 1;
    end loop;
  for item in
    select i.intent_id from public.evidence_capture_intents i where i.record_id = target_record
    order by i.intent_id collate "C" for update of i nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select r.revision_id from public.record_revisions r
    where r.project_id = 'default' and r.record_id = target_record
    order by r.revision_id collate "C" for update of r nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select p.payload_digest from public.evidence_payloads p
    where exists (
      select 1 from public.evidence_snapshots s where s.payload_digest = p.payload_digest
        and (s.record_id = target_record or exists (
          select 1 from public.comparison_result_dependencies d
          where d.project_id = 'default' and d.result_snapshot_id = s.snapshot_id
            and d.source_record_id = target_record)))
    order by p.payload_digest for update of p nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select s.snapshot_id from public.evidence_snapshots s
    where s.record_id = target_record or exists (
      select 1 from public.comparison_result_dependencies d
      where d.project_id = 'default' and d.result_snapshot_id = s.snapshot_id
        and d.source_record_id = target_record)
    order by s.snapshot_id collate "C" for update of s nowait
  loop
    snapshot_ids := array_append(snapshot_ids, item.snapshot_id);
    locked := locked + 1;
  end loop;
  for item in
    select l.snapshot_id from public.evidence_copy_lineage l
    where l.snapshot_id = any(snapshot_ids) or l.copied_from_snapshot_id = any(snapshot_ids)
    order by l.snapshot_id collate "C" for update of l nowait
  loop
    locked := locked + 1;
  end loop;
    for item in
      select d.result_snapshot_id from public.comparison_result_dependencies d
      where d.project_id = 'default' and (d.source_record_id = target_record or exists (
        select 1 from public.evidence_snapshots s
        where s.snapshot_id = d.result_snapshot_id and s.record_id = target_record))
      order by d.result_snapshot_id collate "C", d.source_record_id collate "C",
        d.source_revision_id collate "C" nulls first, d.source_snapshot_id collate "C" nulls first
      for update of d nowait
    loop
      locked := locked + 1;
    end loop;
    for item in
      select c.result_snapshot_id from public.comparison_result_dependency_index_completions c
      where c.project_id = 'default' and (exists (
        select 1 from public.evidence_snapshots s
        where s.snapshot_id = c.result_snapshot_id and s.record_id = target_record)
        or exists (select 1 from public.comparison_result_dependencies d
          where d.project_id = 'default' and d.result_snapshot_id = c.result_snapshot_id
            and d.source_record_id = target_record))
      order by c.result_snapshot_id collate "C" for update of c nowait
    loop
      locked := locked + 1;
    end loop;
  for item in
    select s.revision_id from public.record_revision_subjects s
    where exists (select 1 from public.record_revisions r
      where r.revision_id = s.revision_id and r.project_id = 'default' and r.record_id = target_record)
    order by s.revision_id collate "C", s.ordinal for update of s nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select a.revision_id from public.record_revision_attachments a
    where a.record_id = target_record
    order by a.revision_id collate "C", a.ordinal for update of a nowait
  loop
    locked := locked + 1;
  end loop;
  for item in
    select e.revision_id from public.record_revision_evidence e
    where e.record_id = target_record
    order by e.revision_id collate "C", e.ordinal for update of e nowait
  loop
    locked := locked + 1;
  end loop;
  return locked;
end
$$;
revoke all on function public.record_deletion_inventory_lock(bytea) from public;

-- Birth authority is installed disabled. These objects are owner-provisioned;
-- neither runtime nor the deletion worker can install keys or enable a binding.
-- The request and birth projection deliberately have no foreign key to records.
create table record_platform_internal.record_birth_lineage (
  singleton boolean primary key default true check (singleton),
  authority_id text not null check (authority_id ~ '^rd-[0-9a-f]{64}$'),
  lineage_id text not null check (lineage_id ~ '^bl-[0-9a-f]{64}$'),
  unique (authority_id, lineage_id)
);
create table record_platform_internal.record_birth_keys (
  key_id text primary key check (key_id ~ '^bk-[0-9a-f]{64}$'),
  key_bytes bytea not null check (octet_length(key_bytes) = 32
    and key_bytes <> decode(repeat('00',32),'hex')),
  key_commitment bytea not null unique check (octet_length(key_commitment) = 32
    and key_commitment = record_platform_internal.digest(key_bytes, 'sha256'))
);
create table record_platform_internal.record_birth_bindings (
  generation bigint not null check (generation > 0),
  key_id text not null references record_platform_internal.record_birth_keys(key_id),
  cutover_digest bytea not null check (octet_length(cutover_digest) = 32
    and cutover_digest <> decode(repeat('00', 32), 'hex')),
  authority_id text not null,
  lineage_id text not null,
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  project_id text not null check (project_id = 'default'),
  primary key (generation, key_id, cutover_digest),
  foreign key (authority_id, lineage_id)
    references record_platform_internal.record_birth_lineage(authority_id, lineage_id)
);
create table record_platform_internal.record_birth_enabled (
  singleton boolean primary key default true check (singleton),
  generation bigint not null,
  key_id text not null,
  cutover_digest bytea not null,
  foreign key (generation, key_id, cutover_digest)
    references record_platform_internal.record_birth_bindings(generation, key_id, cutover_digest)
);

-- The trusted initializer stages both public launch files while participants
-- are fenced. Publication alone cannot open admission: the exact pair must be
-- opened after durable file publication. No runtime role can write this state.
create table record_platform_internal.record_birth_launch_state (
  singleton boolean primary key default true check (singleton),
  revision bigint not null check (revision > 0),
  opened boolean not null default false,
  manifest_digest bytea not null check (octet_length(manifest_digest)=32),
  runtime_principal name not null,
  worker_principal name not null check (worker_principal <> runtime_principal),
  center_binding bytea not null check (octet_length(center_binding) between 1 and 16384),
  processor_binding bytea not null check (octet_length(processor_binding) between 1 and 16384)
);

create function record_platform_internal.record_birth_launch_validate(raw bytea, kind text,
  source public.source_authority_admission)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; expected_witness jsonb; expected_birth jsonb;
  binding record_platform_internal.record_birth_bindings;
  contract public.deployment_contract_state; installed boolean;
begin
  if raw is null or octet_length(raw) not between 1 and 16384
    or kind not in ('center','content-processor') then
    raise exception using errcode='22023',message='invalid runtime launch binding';
  end if;
  v:=convert_from(raw,'UTF8')::jsonb;
  if jsonb_typeof(v) is distinct from 'object'
    or not (v ?& array['protocol_version','process_kind','deployment_id','source_generation',
      'birth_installed','witness','birth_binding','activation_bundle_digest','binary_digest'])
    or v-array['protocol_version','process_kind','deployment_id','source_generation',
      'birth_installed','witness','birth_binding','activation_bundle_digest','binary_digest']<>'{}'::jsonb
    or v->'protocol_version' is distinct from '1'::jsonb
    or v->>'process_kind' is distinct from kind
    or coalesce(v->>'binary_digest','') !~ '^[0-9a-f]{64}$'
    or v->>'binary_digest'=repeat('0',64) then
    raise exception using errcode='22023',message='invalid runtime launch binding';
  end if;
  select * into contract from public.deployment_contract_state where project_id='default';
  if contract.deployment_id is null or contract.activation_bundle_digest is null
    or v->>'deployment_id' is distinct from contract.deployment_id
    or v->>'activation_bundle_digest' is distinct from encode(contract.activation_bundle_digest,'hex') then
    raise exception using errcode='42501',message='runtime launch activation mismatch';
  end if;
  if source.singleton is null then
    expected_witness:=jsonb_build_object('id','','system_identifier','','database_oid',0,'database_name','','epoch',0);
  else
    expected_witness:=jsonb_build_object('id',source.witness_domain_id,
      'system_identifier',source.witness_system_identifier,'database_oid',source.witness_database_oid::bigint,
      'database_name',source.witness_database_name,'epoch',source.witness_identity_epoch);
    if source.deployment_id is distinct from contract.deployment_id then
      raise exception using errcode='42501',message='runtime launch source deployment mismatch';
    end if;
  end if;
  if v->'source_generation' is distinct from to_jsonb(coalesce(source.generation,0))
    or v->'witness' is distinct from expected_witness then
    raise exception using errcode='42501',message='runtime launch source identity mismatch';
  end if;
  installed:=exists(select 1 from record_platform_internal.record_birth_lineage);
  if installed then
    select b.* into binding from record_platform_internal.record_birth_bindings b
      where b.generation=source.generation and b.deployment_id=source.deployment_id
        and b.authority_id=source.witness_domain_id
        and (exists(select 1 from record_platform_internal.record_birth_enabled e
          where (e.generation,e.key_id,e.cutover_digest)=(b.generation,b.key_id,b.cutover_digest))
          or (not exists(select 1 from record_platform_internal.record_birth_enabled)
            and (select count(*) from record_platform_internal.record_birth_bindings current_binding
              where current_binding.generation=source.generation)=1));
    if binding.generation is null then
      raise exception using errcode='42501',message='runtime launch birth binding unavailable';
    end if;
    expected_birth:=jsonb_build_object('authority_id',binding.authority_id,'lineage_id',binding.lineage_id,
      'deployment_id',binding.deployment_id,'project_id',binding.project_id,'generation',binding.generation,
      'key_id',binding.key_id,'cutover_digest',encode(binding.cutover_digest,'hex'));
  else
    expected_birth:=jsonb_build_object('authority_id','','lineage_id','','deployment_id','',
      'project_id','','generation',0,'key_id','','cutover_digest','');
  end if;
  if v->'birth_installed' is distinct from to_jsonb(installed)
    or v->'birth_binding' is distinct from expected_birth then
    raise exception using errcode='42501',message='runtime launch installation mismatch';
  end if;
end $$;

create function record_platform_internal.record_birth_launch_stage(center_body bytea, processor_body bytea,
  runtime_role name, worker_role name, expected_revision bigint)
returns bigint language plpgsql security definer set search_path=pg_catalog as $$
declare source public.source_authority_admission;
  old record_platform_internal.record_birth_launch_state; next_revision bigint; current_manifest bytea;
begin
  select * into source from public.source_authority_admission where singleton for share;
  -- Serialize the absent-row case as well as replacements. The initializer is
  -- the only caller and holds the external exclusive maintenance guard too.
  lock table record_platform_internal.record_birth_launch_state in exclusive mode;
  select * into old from record_platform_internal.record_birth_launch_state where singleton for update;
  select h.manifest_digest into current_manifest from public.app_acl_manifest_head h
    join public.app_acl_manifest_revisions r using(manifest_revision,manifest_digest) where h.singleton;
  if current_manifest is null then
    raise exception using errcode='42501',message='runtime launch requires current application role manifest';
  end if;
  if runtime_role is null or worker_role is null or runtime_role=worker_role
    or runtime_role::text !~ '^[a-z][a-z0-9_]{0,62}$' or worker_role::text !~ '^[a-z][a-z0-9_]{0,62}$'
    or expected_revision is null or expected_revision<0
    or not exists(select 1 from pg_roles where rolname=runtime_role and not rolsuper and not rolinherit)
    or not exists(select 1 from pg_roles where rolname=worker_role and not rolsuper and not rolinherit) then
    raise exception using errcode='22023',message='invalid runtime launch principals or revision';
  end if;
  if source.singleton is not null and (not exists(select 1 from public.source_application_principals
      where generation=source.generation and principal=runtime_role and purpose='runtime')
    or not exists(select 1 from public.source_application_principals
      where generation=source.generation and principal=worker_role and purpose='worker')) then
    raise exception using errcode='42501',message='runtime launch principals are not current';
  end if;
  perform record_platform_internal.record_birth_launch_validate(center_body,'center',source);
  perform record_platform_internal.record_birth_launch_validate(processor_body,'content-processor',source);
  if old.revision is not null and (old.center_binding,old.processor_binding,old.runtime_principal,old.worker_principal,old.manifest_digest)
      is not distinct from (center_body,processor_body,runtime_role,worker_role,current_manifest)
    and old.revision in (expected_revision,expected_revision+1) then return old.revision; end if;
  if coalesce(old.revision,0)<>expected_revision or coalesce(old.opened,false) then
    raise exception using errcode='40001',message='runtime launch stage requires the closed current revision';
  end if;
  next_revision:=expected_revision+1;
  insert into record_platform_internal.record_birth_launch_state
    (revision,opened,runtime_principal,worker_principal,center_binding,processor_binding,manifest_digest)
    values(next_revision,false,runtime_role,worker_role,center_body,processor_body,current_manifest)
    on conflict(singleton) do update set revision=excluded.revision,opened=false,
      runtime_principal=excluded.runtime_principal,worker_principal=excluded.worker_principal,
      center_binding=excluded.center_binding,processor_binding=excluded.processor_binding,
      manifest_digest=excluded.manifest_digest;
  return next_revision;
end $$;

create function record_platform_internal.record_birth_launch_close(expected_revision bigint)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  perform 1 from public.source_authority_admission where singleton for share;
  update record_platform_internal.record_birth_launch_state set opened=false
    where singleton and revision=expected_revision;
  if not found then raise exception using errcode='40001',message='runtime launch revision changed'; end if;
end $$;

create function record_platform_internal.record_birth_launch_open(expected_revision bigint)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare source public.source_authority_admission; state record_platform_internal.record_birth_launch_state;
begin
  select * into source from public.source_authority_admission where singleton for share;
  select * into state from record_platform_internal.record_birth_launch_state where singleton for update;
  if state.revision is distinct from expected_revision or expected_revision is null
    or (source.singleton is not null and source.mode<>'active')
    or not exists(select 1 from public.app_acl_manifest_head where singleton and manifest_digest=state.manifest_digest) then
    raise exception using errcode='42501',message='runtime launch cannot open';
  end if;
  perform record_platform_internal.record_birth_launch_validate(state.center_binding,'center',source);
  perform record_platform_internal.record_birth_launch_validate(state.processor_binding,'content-processor',source);
  update record_platform_internal.record_birth_launch_state set opened=true where singleton;
end $$;

create function record_platform_internal.record_birth_launch_admit(source public.source_authority_admission)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare state record_platform_internal.record_birth_launch_state; claimed text; body bytea; kind text;
begin
  if current_setting('transaction_read_only')='on' then
    select * into state from record_platform_internal.record_birth_launch_state where singleton;
  else
    -- Row guards can arrive after later-ranked content locks. Take both the
    -- relation lock (stage uses EXCLUSIVE) and the row lock without waiting.
    lock table record_platform_internal.record_birth_launch_state in row share mode nowait;
    select * into state from record_platform_internal.record_birth_launch_state where singleton for share nowait;
  end if;
  if state.revision is null then
    if exists(select 1 from record_platform_internal.record_birth_lineage)
      and exists(select 1 from public.source_application_principals where principal=session_user
        and generation=source.generation and purpose in ('runtime','worker')) then
      raise exception using errcode='42501',message='installed birth runtime launch is absent';
    end if;
    return;
  end if;
  if not exists(select 1 from public.app_acl_manifest_head where singleton and manifest_digest=state.manifest_digest) then
    raise exception using errcode='42501',message='runtime launch role manifest is stale';
  end if;
  if session_user<>state.runtime_principal and session_user<>state.worker_principal then
    if exists(select 1 from public.source_application_principals where principal=session_user
      and generation=source.generation and purpose in ('runtime','worker')) then
      raise exception using errcode='42501',message='runtime principal is absent from launch registration';
    end if;
    return;
  end if;
  claimed:=current_setting('houfeng.birth_launch_digest',true);
  if not state.opened or coalesce(claimed,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='42501',message='runtime launch admission is closed or absent';
  end if;
  if decode(claimed,'hex')=record_platform_internal.digest(state.center_binding,'sha256') then
    body:=state.center_binding; kind:='center';
  elsif decode(claimed,'hex')=record_platform_internal.digest(state.processor_binding,'sha256') then
    body:=state.processor_binding; kind:='content-processor';
  else
    raise exception using errcode='42501',message='runtime launch admission is stale';
  end if;
  perform record_platform_internal.record_birth_launch_validate(body,kind,source);
exception when lock_not_available then
  raise exception using errcode='40001',message='runtime launch admission busy; restart transaction';
end $$;
revoke all on record_platform_internal.record_birth_launch_state from public;
revoke all on function
  record_platform_internal.record_birth_launch_validate(bytea,text,public.source_authority_admission),
  record_platform_internal.record_birth_launch_stage(bytea,bytea,name,name,bigint),
  record_platform_internal.record_birth_launch_close(bigint),
  record_platform_internal.record_birth_launch_open(bigint),
  record_platform_internal.record_birth_launch_admit(public.source_authority_admission) from public;

-- Only the constrained heartbeat principal and the owner can inspect this
-- projection. The caller obtains the anchor freshly from the independent W2
-- reader before this APP statement; no W2 I/O happens inside an APP transaction.
create function public.record_birth_launch_inspect(bigint,bytea)
returns table(revision bigint, opened boolean, center_binding bytea, processor_binding bytea)
language plpgsql security definer set search_path=pg_catalog as $$
declare anchor_sequence alias for $1; anchor_hash alias for $2;
  source public.source_authority_admission; state record_platform_internal.record_birth_launch_state;
begin
  perform public.source_maintenance_status();
  select * into source from public.source_authority_admission where singleton;
  select * into state from record_platform_internal.record_birth_launch_state where singleton;
  if state.revision is null or not exists(select 1 from public.app_acl_manifest_head
    where singleton and manifest_digest=state.manifest_digest) then
    raise exception using errcode='42501',message='runtime launch registration is absent';
  end if;
  perform record_platform_internal.record_birth_launch_validate(state.center_binding,'center',source);
  perform record_platform_internal.record_birth_launch_validate(state.processor_binding,'content-processor',source);
  if exists(select 1 from record_platform_internal.record_birth_lineage) then
    if anchor_sequence is null or anchor_sequence<0 or anchor_hash is null or octet_length(anchor_hash)<>32
      or not exists(select 1 from record_platform_internal.record_birth_checkpoint_head where singleton
        and sequence>=anchor_sequence)
      or (anchor_sequence=0 and anchor_hash<>decode(repeat('00',32),'hex'))
      or (anchor_sequence>0 and not exists(select 1 from record_platform_internal.record_birth_checkpoints c
        where c.sequence=anchor_sequence and c.checkpoint_hash=anchor_hash)) then
      raise exception using errcode='42501',message='runtime launch checkpoint ancestry mismatch';
    end if;
  elsif anchor_sequence is not null or anchor_hash is not null then
    raise exception using errcode='42501',message='never-installed runtime launch has an external anchor';
  end if;
  return query select state.revision,state.opened,state.center_binding,state.processor_binding;
end $$;
revoke all on function public.record_birth_launch_inspect(bigint,bytea) from public;
create table record_platform_internal.record_birth_allocations (
  allocation_id text primary key check (allocation_id ~ '^rqa_[0-9a-f]{32}$'),
  project_id text not null check (project_id = 'default'),
  actor_id text not null check (actor_id ~ '^[a-z0-9_]{1,128}$'),
  actor_scope_digest bytea not null check (octet_length(actor_scope_digest) = 32
    and actor_scope_digest <> decode(repeat('00', 32), 'hex')),
  purpose text not null check (purpose in ('record_create','evidence_preview','comparison_save','import')),
  idempotency_key text not null check (idempotency_key ~ '^[A-Za-z0-9._~-]{1,200}$'),
  request_fingerprint bytea not null check (octet_length(request_fingerprint) = 32
    and request_fingerprint <> decode(repeat('00', 32), 'hex')),
  publication_key text check (publication_key is null or publication_key ~ '^[A-Za-z0-9._~-]{1,200}$'),
  publication_digest bytea check (publication_digest is null or (octet_length(publication_digest) = 32
    and publication_digest <> decode(repeat('00',32),'hex'))),
  domain text not null check (domain in ('ordinary','certifiable')),
  binding_generation bigint,
  binding_key_id text,
  binding_cutover_digest bytea,
  reservation_id text unique check (reservation_id is null or reservation_id ~ '^rba_[0-9a-f]{32}$'),
  record_id text unique check (record_id is null or record_id ~ '^rec2_[0-9a-f]{32}$'),
  state text not null check (state in ('pending','allocated','preparing','prepared','consumed','finished','confirmed','tombstoned')),
  revision_id text check (revision_id is null or revision_id ~ '^rrv_[a-z0-9]{1,64}$'),
  canonical_hash bytea check (canonical_hash is null or octet_length(canonical_hash) = 32),
  creation_request_fingerprint bytea check (creation_request_fingerprint is null or octet_length(creation_request_fingerprint) = 32),
  initial_commitment bytea check (initial_commitment is null or octet_length(initial_commitment) = 32),
  finished_txid bigint,
  reserve_receipt bytea,
  prepare_receipt bytea,
  reserve_sequence bigint check (reserve_sequence > 0),
  prepare_sequence bigint check (prepare_sequence > 0),
  created_sequence bigint check (created_sequence > 0),
  created_receipt bytea,
  reserve_event jsonb,
  prepare_event jsonb,
  created_event jsonb,
  unique (project_id, actor_id, purpose, idempotency_key),
  unique (project_id, actor_id, publication_key),
  check ((publication_key is null) = (publication_digest is null)),
  foreign key (binding_generation, binding_key_id, binding_cutover_digest)
    references record_platform_internal.record_birth_bindings(generation, key_id, cutover_digest),
  check ((domain = 'ordinary' and binding_generation is null and binding_key_id is null and binding_cutover_digest is null)
    or (domain = 'certifiable' and binding_generation is not null and binding_key_id is not null and binding_cutover_digest is not null)),
  check ((state = 'pending' and domain = 'certifiable' and record_id is null and reservation_id is null)
    or (state <> 'pending' and record_id is not null and reservation_id is not null)),
  check (record_id is null or (domain = 'ordinary' and record_id ~ '^rec2_[0-7][0-9a-f]{31}$')
    or (domain = 'certifiable' and record_id ~ '^rec2_[89a-f][0-9a-f]{31}$')),
  check ((state in ('pending','allocated') and revision_id is null and canonical_hash is null
      and creation_request_fingerprint is null and initial_commitment is null)
    or (state not in ('pending','allocated') and revision_id is not null and canonical_hash is not null
      and creation_request_fingerprint is not null and initial_commitment is not null)),
  check (domain <> 'ordinary' or (reserve_receipt is null and prepare_receipt is null and created_receipt is null)),
  check ((reserve_receipt is null) = (reserve_event is null) and (reserve_receipt is null) = (reserve_sequence is null)),
  check ((prepare_receipt is null) = (prepare_event is null) and (prepare_receipt is null) = (prepare_sequence is null)),
  check ((created_receipt is null) = (created_event is null) and (created_receipt is null) = (created_sequence is null)),
  check (domain <> 'certifiable' or state = 'pending' or reserve_receipt is not null),
  check (domain <> 'certifiable' or state in ('pending','allocated','preparing') or prepare_receipt is not null),
  check (state <> 'confirmed' or (domain = 'certifiable' and created_receipt is not null))
);

-- This chain records certifiable request selection, independently of record
-- existence, progress, tombstones, and the W2 birth-event chain.
create table record_platform_internal.record_birth_checkpoint_head (
  singleton boolean primary key default true check (singleton),
  sequence bigint not null check (sequence >= 0),
  checkpoint_hash bytea not null check (octet_length(checkpoint_hash)=32),
  check ((sequence=0)=(checkpoint_hash=decode(repeat('00',32),'hex')))
);
insert into record_platform_internal.record_birth_checkpoint_head
  values (true,0,decode(repeat('00',32),'hex'));
create table record_platform_internal.record_birth_checkpoints (
  sequence bigint primary key check (sequence > 0),
  previous_hash bytea not null check (octet_length(previous_hash)=32),
  checkpoint_hash bytea not null unique check (octet_length(checkpoint_hash)=32
    and checkpoint_hash<>decode(repeat('00',32),'hex')),
  allocation_id text not null unique references record_platform_internal.record_birth_allocations(allocation_id),
  binding_generation bigint not null,
  binding_key_id text not null,
  binding_cutover_digest bytea not null,
  project_id text not null check (project_id='default'),
  actor_id text not null check (actor_id ~ '^[a-z0-9_]{1,128}$'),
  actor_scope_digest bytea not null check (octet_length(actor_scope_digest)=32
    and actor_scope_digest<>decode(repeat('00',32),'hex')),
  purpose text not null check (purpose in ('record_create','evidence_preview','comparison_save','import')),
  idempotency_key text not null check (idempotency_key ~ '^[A-Za-z0-9._~-]{1,200}$'
    and idempotency_key !~ 'drt1_[A-Za-z0-9_-]{43}'),
  request_fingerprint bytea not null check (octet_length(request_fingerprint)=32
    and request_fingerprint<>decode(repeat('00',32),'hex')),
  unique (project_id,actor_id,purpose,idempotency_key),
  foreign key (binding_generation,binding_key_id,binding_cutover_digest)
    references record_platform_internal.record_birth_bindings(generation,key_id,cutover_digest),
  check ((sequence=1)=(previous_hash=decode(repeat('00',32),'hex')))
);
create trigger record_birth_checkpoints_immutable before update or delete or truncate
  on record_platform_internal.record_birth_checkpoints for each statement
  execute function record_platform_internal.reject_source_retirement_mutation();
revoke all on record_platform_internal.record_birth_checkpoints,
  record_platform_internal.record_birth_checkpoint_head from public;

create function record_platform_internal.record_birth_binding_bytes(b record_platform_internal.record_birth_bindings)
returns bytea language sql immutable strict set search_path=pg_catalog as $$
  select record_platform_internal.source_retirement_field(convert_to((b).authority_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((b).lineage_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((b).deployment_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((b).project_id,'UTF8')) ||
    int8send((b).generation) || record_platform_internal.source_retirement_field(convert_to((b).key_id,'UTF8')) ||
    (b).cutover_digest
$$;

create function record_platform_internal.record_birth_checkpoint_bytes(c record_platform_internal.record_birth_checkpoints)
returns bytea language sql stable strict security definer set search_path=pg_catalog as $$
  select record_platform_internal.source_retirement_field(convert_to('houfeng.record-birth.app-checkpoint-entry.v1','UTF8')) ||
    record_platform_internal.record_birth_binding_bytes(b) || int8send((c).sequence) || (c).previous_hash ||
    record_platform_internal.source_retirement_field(convert_to((c).allocation_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((c).actor_id,'UTF8')) || (c).actor_scope_digest ||
    record_platform_internal.source_retirement_field(convert_to((c).purpose,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((c).idempotency_key,'UTF8')) || (c).request_fingerprint
  from record_platform_internal.record_birth_bindings b
  where (b.generation,b.key_id,b.cutover_digest)=((c).binding_generation,(c).binding_key_id,(c).binding_cutover_digest)
$$;

-- Callers acquire the lineage head at rank 55 before allocation/root rank 60.
-- Only the persisted winning allocation can enter the chain.
create function record_platform_internal.record_birth_checkpoint_append(a record_platform_internal.record_birth_allocations)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare h record_platform_internal.record_birth_checkpoint_head;
  c record_platform_internal.record_birth_checkpoints;
begin
  if a.domain<>'certifiable' then return; end if;
  select * into strict h from record_platform_internal.record_birth_checkpoint_head where singleton for update nowait;
  select * into c from record_platform_internal.record_birth_checkpoints where allocation_id=a.allocation_id;
  if found then
    if (c.project_id,c.actor_id,c.actor_scope_digest,c.purpose,c.idempotency_key,c.request_fingerprint,
      c.binding_generation,c.binding_key_id,c.binding_cutover_digest) is distinct from
      (a.project_id,a.actor_id,a.actor_scope_digest,a.purpose,a.idempotency_key,a.request_fingerprint,
      a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
      raise exception using errcode='55000',message='checkpoint allocation binding mismatch';
    end if;
    return;
  end if;
  c.sequence:=h.sequence+1; c.previous_hash:=h.checkpoint_hash; c.allocation_id:=a.allocation_id;
  c.binding_generation:=a.binding_generation; c.binding_key_id:=a.binding_key_id;
  c.binding_cutover_digest:=a.binding_cutover_digest; c.project_id:=a.project_id;
  c.actor_id:=a.actor_id; c.actor_scope_digest:=a.actor_scope_digest; c.purpose:=a.purpose;
  c.idempotency_key:=a.idempotency_key; c.request_fingerprint:=a.request_fingerprint;
  c.checkpoint_hash:=record_platform_internal.digest(record_platform_internal.record_birth_checkpoint_bytes(c),'sha256');
  insert into record_platform_internal.record_birth_checkpoints select c.*;
  update record_platform_internal.record_birth_checkpoint_head
    set sequence=c.sequence,checkpoint_hash=c.checkpoint_hash where singleton;
end $$;

-- Proofs can only describe already committed inputs. Merely requiring READ ONLY
-- is insufficient: PostgreSQL permits switching a previously writing transaction
-- to READ ONLY. An assigned top-level xid also rejects subtransaction writes.
create function public.record_birth_checkpoint_proof(bytea)
returns bytea language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  c record_platform_internal.record_birth_checkpoints;
  h record_platform_internal.record_birth_checkpoint_head;
  b record_platform_internal.record_birth_bindings;
  original record_platform_internal.record_birth_bindings;
  expected_sequence bigint; expected_hash bytea; canonical bytea; secret bytea;
begin
  if current_setting('transaction_read_only')<>'on' or pg_current_xact_id_if_assigned() is not null then
    raise exception using errcode='25000',message='checkpoint proof requires a new read-only transaction';
  end if;
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint',
      'expected_sequence','expected_hash'],array['expected_sequence']);
  a:=record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is null or a.domain<>'certifiable' or v->>'expected_hash' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='55000',message='checkpoint request unavailable';
  end if;
  expected_sequence:=(v->>'expected_sequence')::bigint; expected_hash:=decode(v->>'expected_hash','hex');
  select binding.* into strict b from record_platform_internal.record_birth_enabled e
    join record_platform_internal.record_birth_bindings binding using(generation,key_id,cutover_digest)
    join public.source_authority_admission s on s.singleton and s.mode='active'
      and s.generation=binding.generation and s.deployment_id=binding.deployment_id
      and s.witness_domain_id=binding.authority_id where e.singleton;
  select * into strict h from record_platform_internal.record_birth_checkpoint_head where singleton;
  select * into strict c from record_platform_internal.record_birth_checkpoints where allocation_id=a.allocation_id;
  select * into strict original from record_platform_internal.record_birth_bindings
    where (generation,key_id,cutover_digest)=(c.binding_generation,c.binding_key_id,c.binding_cutover_digest);
  if (b.authority_id,b.lineage_id,b.deployment_id,b.project_id) is distinct from
      (original.authority_id,original.lineage_id,original.deployment_id,original.project_id)
    or original.generation>b.generation or expected_sequence>h.sequence or c.sequence>h.sequence
    or ((expected_sequence=0) is distinct from (expected_hash=decode(repeat('00',32),'hex')))
    or (expected_sequence>0 and not exists (select 1 from record_platform_internal.record_birth_checkpoints
      where sequence=expected_sequence and checkpoint_hash=expected_hash))
    or not exists (select 1 from record_platform_internal.record_birth_checkpoints
      where sequence=h.sequence and checkpoint_hash=h.checkpoint_hash)
    or c.checkpoint_hash<>record_platform_internal.digest(record_platform_internal.record_birth_checkpoint_bytes(c),'sha256') then
    raise exception using errcode='55000',message='APP canonical checkpoint ancestry unavailable';
  end if;
  select key_bytes into strict secret from record_platform_internal.record_birth_keys where key_id=b.key_id;
  canonical:=record_platform_internal.source_retirement_field(convert_to('houfeng.record-birth.app-checkpoint.v1','UTF8')) ||
    record_platform_internal.record_birth_binding_bytes(b) || int8send(expected_sequence) || expected_hash ||
    int8send(h.sequence) || h.checkpoint_hash || record_platform_internal.record_birth_checkpoint_bytes(c) || c.checkpoint_hash;
  return canonical || record_platform_internal.hmac(canonical,secret,'sha256');
exception when no_data_found then
  raise exception using errcode='55000',message='checkpoint proof authority unavailable';
end $$;
revoke all on function record_platform_internal.record_birth_binding_bytes(record_platform_internal.record_birth_bindings),
  record_platform_internal.record_birth_checkpoint_bytes(record_platform_internal.record_birth_checkpoints),
  record_platform_internal.record_birth_checkpoint_append(record_platform_internal.record_birth_allocations),
  public.record_birth_checkpoint_proof(bytea) from public;

-- Disabled installed lineages still require the independent continuity reader.
-- Absence is meaningful only under the protected initializer's launch binding.
create function record_platform_internal.record_birth_installed_binding()
returns record_platform_internal.record_birth_bindings language plpgsql security definer set search_path=pg_catalog as $$
declare b record_platform_internal.record_birth_bindings;
begin
  perform record_platform_internal.record_birth_admit();
  if not exists(select 1 from record_platform_internal.record_birth_lineage) then return null; end if;
  select binding.* into b from record_platform_internal.record_birth_bindings binding
    join public.source_authority_admission s on s.singleton and s.mode='active' and s.generation=binding.generation
      and s.deployment_id=binding.deployment_id and s.witness_domain_id=binding.authority_id
    where exists(select 1 from record_platform_internal.record_birth_enabled e where e.singleton
      and (e.generation,e.key_id,e.cutover_digest)=(binding.generation,binding.key_id,binding.cutover_digest))
    or (not exists(select 1 from record_platform_internal.record_birth_enabled)
      and (select count(*) from record_platform_internal.record_birth_bindings current_binding
        where current_binding.generation=s.generation)=1);
  if b.generation is null then
    raise exception using errcode='55000',message='installed birth continuity binding unavailable';
  end if;
  return b;
end $$;

create function public.record_birth_continuity_binding()
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare b record_platform_internal.record_birth_bindings;
begin
  b:=record_platform_internal.record_birth_installed_binding();
  if b.generation is null then return null; end if;
  return jsonb_build_object('authority_id',b.authority_id,'lineage_id',b.lineage_id,
    'deployment_id',b.deployment_id,'project_id',b.project_id,'generation',b.generation,
    'key_id',b.key_id,'cutover_digest',encode(b.cutover_digest,'hex'));
end $$;

-- Authenticating an immutable ancestor needs no head lock: source admission
-- fences all invalidating recovery, while normal concurrent appends preserve it.
-- Early rank-30 epoch creation uses this check before the rank-55 head lock.
create function record_platform_internal.record_birth_continuity_validate(raw bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare b record_platform_internal.record_birth_bindings; prefix bytea; secret bytea;
  pos integer; i integer; anchor_sequence bigint:=0; anchor_hash bytea; enabled integer;
  h record_platform_internal.record_birth_checkpoint_head;
begin
  b:=record_platform_internal.record_birth_installed_binding();
  if b.generation is null then
    if raw is null or octet_length(raw)<>0 then
      raise exception using errcode='55000',message='birth installation expectation mismatch';
    end if;
    perform set_config('houfeng.birth_continuity_proof','',true);
    return;
  end if;
  prefix:=record_platform_internal.source_retirement_field(convert_to('houfeng.record-birth.continuity.v1','UTF8')) ||
    record_platform_internal.record_birth_binding_bytes(b);
  pos:=octet_length(prefix);
  if raw is null or octet_length(raw)<>pos+73 or substring(raw from 1 for pos)<>prefix
    or get_byte(raw,pos)>127 or get_byte(raw,pos+40) not in (0,1) then
    raise exception using errcode='42501',message='authenticated birth continuity proof required';
  end if;
  select key_bytes into strict secret from record_platform_internal.record_birth_keys where key_id=b.key_id;
  if substring(raw from octet_length(raw)-31) is distinct from
    record_platform_internal.hmac(substring(raw from 1 for octet_length(raw)-32),secret,'sha256') then
    raise exception using errcode='42501',message='birth continuity proof authentication failed';
  end if;
  for i in 0..7 loop anchor_sequence:=anchor_sequence*256+get_byte(raw,pos+i); end loop;
  anchor_hash:=substring(raw from pos+9 for 32); enabled:=get_byte(raw,pos+40);
  if enabled<>(case when exists(select 1 from record_platform_internal.record_birth_enabled e where e.singleton
    and (e.generation,e.key_id,e.cutover_digest)=(b.generation,b.key_id,b.cutover_digest)) then 1 else 0 end) then
    raise exception using errcode='55000',message='birth continuity enablement changed';
  end if;
  select * into strict h from record_platform_internal.record_birth_checkpoint_head where singleton;
  if anchor_sequence>h.sequence or ((anchor_sequence=0) is distinct from (anchor_hash=decode(repeat('00',32),'hex')))
    or (anchor_sequence>0 and not exists(select 1 from record_platform_internal.record_birth_checkpoints c
      where c.sequence=anchor_sequence and c.checkpoint_hash=anchor_hash))
    or (h.sequence>0 and not exists(select 1 from record_platform_internal.record_birth_checkpoints c
      where c.sequence=h.sequence and c.checkpoint_hash=h.checkpoint_hash)) then
    raise exception using errcode='55000',message='birth continuity anchor absent from APP canonical chain';
  end if;
  perform set_config('houfeng.birth_continuity_proof',encode(raw,'hex'),true);
exception when lock_not_available then
  raise exception using errcode='40001',message='birth continuity earlier rank busy; restart transaction';
end $$;

-- Current mutable head acquisition remains at rank 55, before allocations.
create function record_platform_internal.record_birth_continuity_check(raw bytea, exclusive_head boolean)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  perform record_platform_internal.record_birth_continuity_validate(raw);
  if exists(select 1 from record_platform_internal.record_birth_lineage) then
    if exclusive_head then
      perform 1 from record_platform_internal.record_birth_checkpoint_head where singleton for update nowait;
    else
      perform 1 from record_platform_internal.record_birth_checkpoint_head where singleton for share nowait;
    end if;
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='birth continuity earlier rank busy; restart transaction';
end $$;

create function public.record_birth_continuity_assert(bytea)
returns void language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.record_birth_continuity_check($1,false)
$$;

create function record_platform_internal.record_birth_continuity_guard()
returns void language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.record_birth_continuity_check(
    decode(coalesce(current_setting('houfeng.birth_continuity_proof',true),''),'hex'),false)
$$;
revoke all on function record_platform_internal.record_birth_installed_binding(),
  record_platform_internal.record_birth_continuity_validate(bytea),
  public.record_birth_continuity_binding(),record_platform_internal.record_birth_continuity_check(bytea,boolean),
  public.record_birth_continuity_assert(bytea),record_platform_internal.record_birth_continuity_guard() from public;

-- Capture intents remain linked to the allocation that authorized a pre-root
-- preview. Existing-record and predecessor intents have no allocation.
alter table public.evidence_capture_intents add column birth_allocation_id text
  references record_platform_internal.record_birth_allocations(allocation_id);
-- Predecessor intents have no actor binding and cannot authorize new payloads.
alter table public.evidence_capture_intents add column capture_actor_id text;
alter table public.evidence_capture_intents add column capture_actor_scope_digest bytea;
alter table public.evidence_capture_intents add constraint evidence_capture_actor_binding_check
  check ((capture_actor_id is null and capture_actor_scope_digest is null) or
    (capture_actor_id is not null and capture_actor_scope_digest is not null
      and capture_actor_id ~ '^usr_[a-z0-9]{1,64}$' and octet_length(capture_actor_scope_digest)=32));

-- Existing mappings retain NULL. Only the restricted command may attach a
-- new record mapping to its immutable birth allocation.
alter table public.record_import_entity_mappings add column birth_allocation_id text;
alter table public.record_import_entity_mappings add constraint record_import_mapping_birth_identity_check
  check (birth_allocation_id is null or (entity_kind='record' and birth_allocation_id ~ '^rqa_[0-9a-f]{32}$'));
alter table public.record_import_entity_mappings add column owner_target_record_id text;
alter table public.record_import_entity_mappings add constraint record_import_mapping_owner_identity_check
  check (owner_target_record_id is null or (entity_kind in ('evidence','attachment')
    and owner_target_record_id ~ '^rec2_[0-9a-f]{32}$'));

create function public.record_birth_allocation_lock(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations; b record_platform_internal.record_birth_bindings;
begin
  perform record_platform_internal.local_blob_direct_login();
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint','allocation_id','record_id'],'{}');
  perform record_platform_internal.record_birth_validate_request(v);
  if v->>'allocation_id' !~ '^rqa_[0-9a-f]{32}$' or v->>'record_id' !~ '^rec2_[0-9a-f]{32}$' then
    raise exception using errcode='22023',message='invalid birth allocation identity';
  end if;
  perform record_platform_internal.record_birth_writer_guard(v->>'record_id');
  select * into a from record_platform_internal.record_birth_allocations
    where allocation_id=v->>'allocation_id' for update;
  if not found or (a.project_id,a.actor_id,a.actor_scope_digest,a.purpose,a.idempotency_key,a.request_fingerprint,a.record_id)
    is distinct from (v->>'project_id',v->>'actor_id',decode(v->>'actor_scope_digest','hex'),v->>'purpose',
      v->>'idempotency_key',decode(v->>'request_fingerprint','hex'),v->>'record_id')
    or a.state not in ('allocated','preparing','prepared') then
    raise exception using errcode='55000',message='birth allocation request or state mismatch';
  end if;
  if a.domain='certifiable' then
    b:=record_platform_internal.record_birth_binding();
    if b.generation is null or (b.generation,b.key_id,b.cutover_digest) is distinct from
      (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
      raise exception using errcode='55000',message='birth allocation binding is no longer current';
    end if;
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='birth allocation earlier scope busy; restart transaction';
end $$;
revoke all on function public.record_birth_allocation_lock(bytea) from public;
revoke all on record_platform_internal.record_birth_lineage, record_platform_internal.record_birth_keys,
  record_platform_internal.record_birth_bindings, record_platform_internal.record_birth_enabled,
  record_platform_internal.record_birth_allocations from public;

-- Strict command parsing precedes jsonb conversion so duplicate keys cannot
-- disappear. All fields are required; only generation/sequence are numbers.
create function record_platform_internal.record_birth_command(bytea, text[], text[])
returns jsonb language plpgsql immutable set search_path = pg_catalog as $$
declare raw json;
begin
  if $1 is null or octet_length($1) not between 1 and 32768 then
    raise exception using errcode = '22023', message = 'invalid birth command size';
  end if;
  raw := convert_from($1, 'UTF8')::json;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw)) <> cardinality($2)
    or (select count(distinct f.key) from json_each(raw) f) <> cardinality($2)
    or exists (select 1 from json_each(raw) f where not (f.key = any($2)) or
      case when f.key = any($3) then
        case when json_typeof(f.value) <> 'number' or f.value::text !~ '^(0|[1-9][0-9]*)$' then true
          else f.value::text::numeric > 9223372036854775807::numeric end
      else json_typeof(f.value) <> 'string' end) then
    raise exception using errcode = '22023', message = 'invalid birth command fields';
  end if;
  return raw::jsonb;
end $$;

create function record_platform_internal.record_birth_validate_request(jsonb)
returns void language plpgsql immutable set search_path = pg_catalog as $$
begin
  if $1->>'project_id' is distinct from 'default' or $1->>'actor_id' !~ '^[a-z0-9_]{1,128}$'
    or $1->>'purpose' not in ('record_create','evidence_preview','comparison_save','import')
    or $1->>'idempotency_key' !~ '^[A-Za-z0-9._~-]{1,200}$'
    or $1->>'idempotency_key' ~ 'drt1_[A-Za-z0-9_-]{43}'
    or $1->>'actor_scope_digest' !~ '^[0-9a-f]{64}$'
    or $1->>'request_fingerprint' !~ '^[0-9a-f]{64}$'
    or $1->>'actor_scope_digest' = repeat('0', 64) or $1->>'request_fingerprint' = repeat('0', 64) then
    raise exception using errcode = '22023', message = 'invalid birth request identity';
  end if;
end $$;

create function record_platform_internal.record_birth_admit()
returns bigint language plpgsql security definer set search_path = pg_catalog as $$
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode = '25000', message = 'birth commands require read committed';
  end if;
  return public.source_application_admit();
end $$;

create function record_platform_internal.record_birth_binding()
returns record_platform_internal.record_birth_bindings language plpgsql security definer set search_path = pg_catalog as $$
declare b record_platform_internal.record_birth_bindings; s public.source_authority_admission;
begin
  select binding.* into b from record_platform_internal.record_birth_enabled e
    join record_platform_internal.record_birth_bindings binding using (generation, key_id, cutover_digest)
    where e.singleton for share of e nowait;
  if not found then return null; end if;
  select * into s from public.source_authority_admission where singleton for share nowait;
  if not found or s.mode <> 'active' or s.generation <> b.generation
    or s.deployment_id <> b.deployment_id or s.witness_domain_id <> b.authority_id then
    raise exception using errcode = '55000', message = 'birth binding is not currently admitted';
  end if;
  return b;
end $$;

create function record_platform_internal.record_birth_project(a record_platform_internal.record_birth_allocations)
returns jsonb language sql stable security definer set search_path = pg_catalog as $$
  select jsonb_build_object(
    'allocation_id',(a).allocation_id,'domain',(a).domain,'state',(a).state,
    'project_id',(a).project_id,'actor_id',(a).actor_id,'actor_scope_digest',encode((a).actor_scope_digest,'hex'),
    'purpose',(a).purpose,'idempotency_key',(a).idempotency_key,'request_fingerprint',encode((a).request_fingerprint,'hex'),
    'authority_id',coalesce(b.authority_id,''),'lineage_id',coalesce(b.lineage_id,''),
    'deployment_id',coalesce(b.deployment_id,''),'generation',coalesce(b.generation,0),
    'key_id',coalesce(b.key_id,''),'cutover_digest',coalesce(encode(b.cutover_digest,'hex'),''),
    'reservation_id',coalesce((a).reservation_id,''),'record_id',coalesce((a).record_id,''),
    'revision_id',coalesce((a).revision_id,''),'canonical_hash',coalesce(encode((a).canonical_hash,'hex'),''),
    'creation_request_fingerprint',coalesce(encode((a).creation_request_fingerprint,'hex'),''),
    'reserve_receipt',coalesce(encode((a).reserve_receipt,'hex'),''),
    'prepare_receipt',coalesce(encode((a).prepare_receipt,'hex'),''),
    'created_receipt',coalesce(encode((a).created_receipt,'hex'),''))
  from (select 1) one left join record_platform_internal.record_birth_bindings b
    on (b.generation,b.key_id,b.cutover_digest) = ((a).binding_generation,(a).binding_key_id,(a).binding_cutover_digest)
$$;

create function record_platform_internal.record_birth_request_row(v jsonb)
returns record_platform_internal.record_birth_allocations language plpgsql security definer set search_path = pg_catalog as $$
declare a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_validate_request(v);
  select * into a from record_platform_internal.record_birth_allocations
    where project_id=v->>'project_id' and actor_id=v->>'actor_id' and purpose=v->>'purpose'
      and idempotency_key=v->>'idempotency_key';
  if found and (a.actor_scope_digest <> decode(v->>'actor_scope_digest','hex')
    or a.request_fingerprint <> decode(v->>'request_fingerprint','hex')) then
    raise exception using errcode = '23505', message = 'birth request binding conflict';
  end if;
  return a;
end $$;

create function public.record_birth_allocation_find(bytea)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_admit();
  v := record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint'], '{}');
  a := record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is null then return null; end if;
  return record_platform_internal.record_birth_project(a);
end $$;

create function public.record_birth_current_binding()
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare b record_platform_internal.record_birth_bindings;
begin
  perform record_platform_internal.record_birth_admit();
  b := record_platform_internal.record_birth_binding();
  if b.generation is null then return null; end if;
  return jsonb_build_object('authority_id',b.authority_id,'lineage_id',b.lineage_id,
    'deployment_id',b.deployment_id,'project_id',b.project_id,'generation',b.generation,
    'key_id',b.key_id,'cutover_digest',encode(b.cutover_digest,'hex'));
end $$;

create function public.record_birth_allocation_begin(bytea)
returns jsonb language plpgsql security definer set search_path = pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  b record_platform_internal.record_birth_bindings; random_bytes bytea; selected text;
begin
  perform record_platform_internal.record_birth_admit();
  v := record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint',
      'domain','authority_id','lineage_id','deployment_id','generation','key_id','cutover_digest','continuity_proof'], array['generation']);
  perform record_platform_internal.record_birth_validate_request(v);
  selected := v->>'domain';
  if selected not in ('ordinary','certifiable') then
    raise exception using errcode='22023',message='invalid birth allocation domain';
  end if;
  perform record_platform_internal.record_birth_continuity_check(decode(v->>'continuity_proof','hex'),selected='certifiable');
  if selected = 'ordinary' then
    if (v->>'generation')::bigint <> 0 or v->>'authority_id' <> '' or v->>'lineage_id' <> ''
      or v->>'deployment_id' <> '' or v->>'key_id' <> '' or v->>'cutover_digest' <> '' then
      raise exception using errcode='22023',message='ordinary allocation has a binding';
    end if;
  else
    if (v->>'generation')::bigint <= 0 or v->>'authority_id' !~ '^rd-[0-9a-f]{64}$'
      or v->>'lineage_id' !~ '^bl-[0-9a-f]{64}$' or v->>'deployment_id' !~ '^dp-[0-9a-f]{64}$'
      or v->>'key_id' !~ '^bk-[0-9a-f]{64}$' or v->>'cutover_digest' !~ '^[0-9a-f]{64}$' then
      raise exception using errcode='22023',message='invalid certified allocation binding';
    end if;
  end if;
  -- Existing requests win over a concurrent domain selection. A certified
  -- request never changes lineage, even if its original binding is retired.
  a := record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is not null then
    if selected='certifiable' and a.domain='certifiable' and not exists (
      select 1 from record_platform_internal.record_birth_bindings original
      where (original.generation,original.key_id,original.cutover_digest) =
        (a.binding_generation,a.binding_key_id,a.binding_cutover_digest)
        and original.authority_id=v->>'authority_id' and original.lineage_id=v->>'lineage_id'
        and original.project_id=v->>'project_id' and original.deployment_id=v->>'deployment_id'
        and original.generation=(v->>'generation')::bigint and original.key_id=v->>'key_id'
        and original.cutover_digest=decode(v->>'cutover_digest','hex')) then
      raise exception using errcode='23505',message='birth allocation binding conflict';
    end if;
    return record_platform_internal.record_birth_project(a);
  end if;
  if selected='certifiable' then
    b := record_platform_internal.record_birth_binding();
    if b.generation is null or b.authority_id<>v->>'authority_id' or b.lineage_id<>v->>'lineage_id'
      or b.deployment_id<>v->>'deployment_id' or b.project_id<>v->>'project_id'
      or b.generation<>(v->>'generation')::bigint or b.key_id<>v->>'key_id'
      or b.cutover_digest<>decode(v->>'cutover_digest','hex') then
      raise exception using errcode='55000',message='birth binding is not current';
    end if;
  end if;
  loop
    begin
      random_bytes := record_platform_internal.gen_random_bytes(16);
      random_bytes := set_byte(random_bytes,0,get_byte(random_bytes,0) & 127);
      insert into record_platform_internal.record_birth_allocations (
        allocation_id,project_id,actor_id,actor_scope_digest,purpose,idempotency_key,request_fingerprint,
        domain,binding_generation,binding_key_id,binding_cutover_digest,reservation_id,record_id,state)
      values ('rqa_'||encode(record_platform_internal.gen_random_bytes(16),'hex'),v->>'project_id',v->>'actor_id',
        decode(v->>'actor_scope_digest','hex'),v->>'purpose',v->>'idempotency_key',decode(v->>'request_fingerprint','hex'),
        selected,b.generation,b.key_id,b.cutover_digest,
        case when selected='ordinary' then 'rba_'||encode(record_platform_internal.gen_random_bytes(16),'hex') end,
        case when selected='ordinary' then 'rec2_'||encode(random_bytes,'hex') end,
        case when selected='ordinary' then 'allocated' else 'pending' end)
      on conflict (project_id,actor_id,purpose,idempotency_key) do nothing
      returning * into a;
    exception when unique_violation then
      -- Only generated ID collisions retry. Request conflicts below must escape.
      continue;
    end;
    if a.allocation_id is null then a := record_platform_internal.record_birth_request_row(v); end if;
    exit when a.allocation_id is not null;
  end loop;
  if a.domain='certifiable' and selected='certifiable' and not exists (
    select 1 from record_platform_internal.record_birth_bindings original
    where (original.generation,original.key_id,original.cutover_digest)=
      (a.binding_generation,a.binding_key_id,a.binding_cutover_digest)
      and original.authority_id=v->>'authority_id' and original.lineage_id=v->>'lineage_id'
      and original.project_id=v->>'project_id' and original.deployment_id=v->>'deployment_id'
      and original.generation=(v->>'generation')::bigint and original.key_id=v->>'key_id'
      and original.cutover_digest=decode(v->>'cutover_digest','hex')) then
    raise exception using errcode='23505',message='birth allocation binding conflict';
  end if;
  perform record_platform_internal.record_birth_checkpoint_append(a);
  return record_platform_internal.record_birth_project(a);
end $$;

create function record_platform_internal.record_birth_initial_commitment(a record_platform_internal.record_birth_allocations)
returns bytea language sql immutable set search_path=pg_catalog as $$
  select record_platform_internal.digest(
    record_platform_internal.source_retirement_field(convert_to('houfeng.record-birth.initial.v1','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((a).reservation_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((a).record_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((a).revision_id,'UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to((a).actor_id,'UTF8')) ||
    (a).canonical_hash || (a).creation_request_fingerprint, 'sha256')
$$;

create function public.record_birth_prepare_create(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  b record_platform_internal.record_birth_bindings;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint',
      'reservation_id','record_id','revision_id','canonical_hash','creation_request_fingerprint','continuity_proof'], '{}');
  perform record_platform_internal.record_birth_continuity_check(decode(v->>'continuity_proof','hex'),false);
  a:=record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is null then raise exception using errcode='55000',message='birth allocation unavailable'; end if;
  if v->>'reservation_id' !~ '^rba_[0-9a-f]{32}$' or v->>'record_id' !~ '^rec2_[0-9a-f]{32}$'
    or v->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$' or v->>'canonical_hash' !~ '^[0-9a-f]{64}$'
    or v->>'creation_request_fingerprint' !~ '^[0-9a-f]{64}$'
    or v->>'canonical_hash'=repeat('0',64) or v->>'creation_request_fingerprint'=repeat('0',64) then
    raise exception using errcode='22023',message='invalid initial creation';
  end if;
  select * into strict a from record_platform_internal.record_birth_allocations where allocation_id=a.allocation_id for update;
  if a.reservation_id is distinct from v->>'reservation_id' or a.record_id is distinct from v->>'record_id' then
    raise exception using errcode='23505',message='birth reservation conflict';
  end if;
  if a.state='allocated' then
    if a.domain='certifiable' then
      b:=record_platform_internal.record_birth_binding();
      if b.generation is null or (b.generation,b.key_id,b.cutover_digest) is distinct from
          (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
        raise exception using errcode='55000',message='birth preparation binding is no longer current';
      end if;
    end if;
    a.revision_id:=v->>'revision_id'; a.canonical_hash:=decode(v->>'canonical_hash','hex');
    a.creation_request_fingerprint:=decode(v->>'creation_request_fingerprint','hex');
    a.initial_commitment:=record_platform_internal.record_birth_initial_commitment(a);
    update record_platform_internal.record_birth_allocations set revision_id=a.revision_id,canonical_hash=a.canonical_hash,
      creation_request_fingerprint=a.creation_request_fingerprint,initial_commitment=a.initial_commitment,
      state=case when a.domain='ordinary' then 'prepared' else 'preparing' end
      where allocation_id=a.allocation_id returning * into a;
  elsif a.revision_id is distinct from v->>'revision_id' or a.canonical_hash is distinct from decode(v->>'canonical_hash','hex')
    or a.creation_request_fingerprint is distinct from decode(v->>'creation_request_fingerprint','hex') then
    raise exception using errcode='23505',message='initial creation conflict';
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

-- The fields accompany the receipt only to avoid an unbounded byte parser in
-- SQL. Reconstructing every framed byte and verifying the MAC means that none
-- of those fields is trusted independently of the authenticated receipt.
create function record_platform_internal.record_birth_receipt_check(v jsonb)
returns bytea language plpgsql security definer set search_path=pg_catalog as $$
declare canonical bytea; receipt bytea; secret bytea; expected_mac bytea; mac_difference integer := 0; i integer;
  zero text := repeat('0',64);
begin
  perform record_platform_internal.record_birth_validate_request(v);
  if v->>'authority_id' !~ '^rd-[0-9a-f]{64}$' or v->>'lineage_id' !~ '^bl-[0-9a-f]{64}$'
    or v->>'deployment_id' !~ '^dp-[0-9a-f]{64}$' or v->>'key_id' !~ '^bk-[0-9a-f]{64}$'
    or v->>'cutover_digest' !~ '^[0-9a-f]{64}$' or v->>'cutover_digest'=zero
    or v->>'previous_hash' !~ '^[0-9a-f]{64}$' or v->>'initial_commitment' !~ '^[0-9a-f]{64}$'
    or (v->>'generation')::bigint <= 0 or (v->>'sequence')::bigint <= 0
    or ((v->>'sequence')::bigint=1) <> (v->>'previous_hash'=zero)
    or v->>'kind' not in ('reserved','prepared','created')
    or (v->>'kind'='reserved') <> (v->>'initial_commitment'=zero)
    or v->>'reservation_id' !~ '^rba_[0-9a-f]{32}$'
    or v->>'record_id' !~ '^rec2_[89a-f][0-9a-f]{31}$'
    or length(v->>'receipt') not between 64 and 8192 or length(v->>'receipt') % 2 <> 0
    or v->>'receipt' !~ '^[0-9a-f]+$' then
    raise exception using errcode='22023',message='invalid birth receipt fields';
  end if;
  select k.key_bytes into secret from record_platform_internal.record_birth_bindings b
    join record_platform_internal.record_birth_keys k on k.key_id=b.key_id
    where b.authority_id=v->>'authority_id' and b.lineage_id=v->>'lineage_id'
      and b.deployment_id=v->>'deployment_id' and b.project_id=v->>'project_id'
      and b.generation=(v->>'generation')::bigint and b.key_id=v->>'key_id'
      and b.cutover_digest=decode(v->>'cutover_digest','hex');
  if not found then raise exception using errcode='55000',message='unknown historical birth binding'; end if;
  canonical :=
    record_platform_internal.source_retirement_field(convert_to('houfeng.record-birth.receipt.v1','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'authority_id','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'lineage_id','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'deployment_id','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'project_id','UTF8')) ||
    int8send((v->>'generation')::bigint) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'key_id','UTF8')) ||
    decode(v->>'cutover_digest','hex') || int8send((v->>'sequence')::bigint) || decode(v->>'previous_hash','hex') ||
    record_platform_internal.source_retirement_field(convert_to(v->>'kind','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'reservation_id','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'record_id','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'actor_id','UTF8')) ||
    decode(v->>'actor_scope_digest','hex') ||
    record_platform_internal.source_retirement_field(convert_to(v->>'purpose','UTF8')) ||
    record_platform_internal.source_retirement_field(convert_to(v->>'idempotency_key','UTF8')) ||
    decode(v->>'request_fingerprint','hex') || decode(v->>'initial_commitment','hex');
  receipt:=decode(v->>'receipt','hex');
  if octet_length(receipt)<>octet_length(canonical)+32
    or substring(receipt from 1 for octet_length(canonical))<>canonical then
    raise exception using errcode='22023',message='birth receipt authentication failed';
  end if;
  expected_mac:=record_platform_internal.hmac(canonical,secret,'sha256');
  for i in 0..31 loop
    mac_difference:=mac_difference | (get_byte(receipt,octet_length(canonical)+i) # get_byte(expected_mac,i));
  end loop;
  if mac_difference<>0 then
    raise exception using errcode='22023',message='birth receipt authentication failed';
  end if;
  return receipt;
end $$;

create function record_platform_internal.record_birth_actual_first(a record_platform_internal.record_birth_allocations)
returns boolean language sql stable security definer set search_path=pg_catalog as $$
  select (a).initial_commitment = record_platform_internal.record_birth_initial_commitment(a)
    and exists (select 1 from public.records r join public.record_revisions rev
      on rev.project_id=r.project_id and rev.record_id=r.record_id
      where r.project_id=(a).project_id and r.record_id=(a).record_id
        and rev.revision_id=(a).revision_id and rev.revision_no=1 and rev.base_revision_id is null
        and rev.author_id=(a).actor_id and rev.canonical_hash=(a).canonical_hash)
$$;

create function public.record_birth_receipt_register(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  historical record_platform_internal.record_birth_bindings; current_binding record_platform_internal.record_birth_bindings;
  receipt bytea; event_kind text; event_sequence bigint;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint',
      'authority_id','lineage_id','deployment_id','generation','key_id','cutover_digest','sequence','previous_hash',
      'kind','reservation_id','record_id','initial_commitment','receipt','continuity_proof'], array['generation','sequence']);
  perform record_platform_internal.record_birth_continuity_check(decode(v->>'continuity_proof','hex'),false);
  a:=record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is null or a.domain<>'certifiable' then
    raise exception using errcode='55000',message='certified allocation unavailable';
  end if;
  receipt:=record_platform_internal.record_birth_receipt_check(v);
  select * into strict historical from record_platform_internal.record_birth_bindings
    where (generation,key_id,cutover_digest)=(a.binding_generation,a.binding_key_id,a.binding_cutover_digest);
  if historical.authority_id<>v->>'authority_id' or historical.lineage_id<>v->>'lineage_id' then
    raise exception using errcode='23505',message='birth receipt lineage conflict';
  end if;
  select * into strict a from record_platform_internal.record_birth_allocations where allocation_id=a.allocation_id for update;
  event_kind:=v->>'kind'; event_sequence:=(v->>'sequence')::bigint;
  if event_kind='reserved' and a.reserve_receipt is not null then
    if a.reserve_receipt<>receipt then raise exception using errcode='23505',message='reserve receipt conflict'; end if;
    return record_platform_internal.record_birth_project(a);
  elsif event_kind='prepared' and a.prepare_receipt is not null then
    if a.prepare_receipt<>receipt then raise exception using errcode='23505',message='prepare receipt conflict'; end if;
    return record_platform_internal.record_birth_project(a);
  elsif event_kind='created' and a.created_receipt is not null then
    if a.created_receipt<>receipt then raise exception using errcode='23505',message='created receipt conflict'; end if;
    return record_platform_internal.record_birth_project(a);
  end if;
  if event_kind in ('reserved','prepared') then
    current_binding:=record_platform_internal.record_birth_binding();
    if current_binding.generation is null or (current_binding.generation,current_binding.key_id,current_binding.cutover_digest)
      is distinct from (a.binding_generation,a.binding_key_id,a.binding_cutover_digest)
      or (current_binding.authority_id,current_binding.lineage_id,current_binding.deployment_id,current_binding.project_id,
          current_binding.generation,current_binding.key_id,current_binding.cutover_digest) is distinct from
        (v->>'authority_id',v->>'lineage_id',v->>'deployment_id',v->>'project_id',
          (v->>'generation')::bigint,v->>'key_id',decode(v->>'cutover_digest','hex')) then
      raise exception using errcode='55000',message='birth binding no longer permits new effects';
    end if;
  end if;
  if event_kind='reserved' and a.state='pending' then
    update record_platform_internal.record_birth_allocations set state='allocated',
      reservation_id=v->>'reservation_id',record_id=v->>'record_id',reserve_receipt=receipt,reserve_sequence=event_sequence,reserve_event=v
      where allocation_id=a.allocation_id returning * into a;
  elsif event_kind='prepared' and a.state='preparing'
    and a.reservation_id=v->>'reservation_id' and a.record_id=v->>'record_id'
    and a.initial_commitment=decode(v->>'initial_commitment','hex') and event_sequence>a.reserve_sequence then
    update record_platform_internal.record_birth_allocations set state='prepared',prepare_receipt=receipt,
      prepare_sequence=event_sequence,prepare_event=v where allocation_id=a.allocation_id returning * into a;
  elsif event_kind='created' and a.state='finished'
    and a.reservation_id=v->>'reservation_id' and a.record_id=v->>'record_id'
    and a.initial_commitment=decode(v->>'initial_commitment','hex') and event_sequence>a.prepare_sequence
    and a.finished_txid is not null and a.finished_txid<>txid_current()
    and record_platform_internal.record_birth_actual_first(a) then
    update record_platform_internal.record_birth_allocations set state='confirmed',created_receipt=receipt,
      created_sequence=event_sequence,created_event=v where allocation_id=a.allocation_id returning * into a;
  else
    raise exception using errcode='23505',message='birth receipt transition conflict';
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

-- Called at rank 60. Any earlier scope that cannot be reacquired immediately
-- forces whole-transaction reselection; this function never waits backwards.
create function record_platform_internal.record_birth_writer_guard(target text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare s public.source_authority_admission; source_present boolean; epoch bigint;
  reservation_ids text[] := '{}'; item text; lease_expiry timestamptz;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='birth consume requires read committed';
  end if;
  select * into s from public.source_authority_admission where singleton for share nowait;
  source_present:=found;
  if source_present and (s.mode<>'active' or not exists (select 1 from public.source_application_principals p
    where p.principal=session_user and p.generation=s.generation and p.purpose in ('runtime','admin','worker'))) then
    raise exception using errcode='42501',message='source admission is closed or stale';
  end if;
  perform record_platform_internal.record_birth_launch_admit(s);
  if not pg_try_advisory_xact_lock_shared(1213154899,1)
    or not pg_try_advisory_xact_lock_shared(1213154899,81) then
    raise exception using errcode='40001',message='birth writer admission changed; restart transaction';
  end if;
  if source_present <> exists(select 1 from public.source_authority_admission where singleton) then
    raise exception using errcode='40001',message='birth source route changed; restart transaction';
  end if;
  for item in select reservation_id from public.deletion_reservations
    where project_id='default' and object_kind='record' and object_id=target
    order by reservation_id collate "C" for update nowait loop
    reservation_ids:=array_append(reservation_ids,item);
  end loop;
  select delivery_epoch into epoch from public.content_delivery_epochs
    where project_id='default' and object_kind='record' and object_id=target for update nowait;
  if not found then raise exception using errcode='55000',message='birth record epoch unavailable'; end if;
  if exists(select 1 from public.deletion_reservations r where r.project_id='default'
    and r.object_kind='record' and r.object_id=target and not (r.reservation_id=any(reservation_ids))) then
    raise exception using errcode='40001',message='birth reservation route changed; restart transaction';
  end if;
  select expires_at into lease_expiry from public.deletion_fence_leases
    where project_id='default' and object_kind='record' and object_id=target for update nowait;
  perform 1 from public.object_content_leases where project_id='default' and object_kind='record'
    and object_id=target for update nowait;
  perform 1 from public.record_deletion_gates where project_id='default' and record_id=target for share nowait;
  if found or coalesce(lease_expiry>clock_timestamp(),false) or exists (
    select 1 from public.deletion_reservations r where r.project_id='default' and r.object_kind='record'
      and r.object_id=target and r.state in ('fenced','committed')) then
    raise exception using errcode='55000',message='birth record gate is closed';
  end if;
  if not exists(select 1 from public.records r where r.project_id='default' and r.record_id=target)
    and exists(select 1 from record_platform_internal.record_birth_allocations a
      where a.project_id='default' and a.record_id=target and a.state in ('allocated','preparing','prepared')) then
    perform record_platform_internal.record_birth_continuity_guard();
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='birth earlier scope busy; restart transaction';
end $$;

create function public.record_birth_consume(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  b record_platform_internal.record_birth_bindings;
begin
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','actor_scope_digest','purpose','idempotency_key','request_fingerprint',
      'allocation_id','reservation_id','record_id','revision_id','canonical_hash','creation_request_fingerprint','prepare_receipt','continuity_proof'], '{}');
  perform record_platform_internal.record_birth_validate_request(v);
  if v->>'allocation_id' !~ '^rqa_[0-9a-f]{32}$' or v->>'reservation_id' !~ '^rba_[0-9a-f]{32}$'
    or v->>'record_id' !~ '^rec2_[0-9a-f]{32}$' or v->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$'
    or v->>'canonical_hash' !~ '^[0-9a-f]{64}$' or v->>'creation_request_fingerprint' !~ '^[0-9a-f]{64}$'
    or (v->>'prepare_receipt'<>'' and (length(v->>'prepare_receipt') not between 64 and 8192
      or length(v->>'prepare_receipt') % 2<>0 or v->>'prepare_receipt' !~ '^[0-9a-f]+$')) then
    raise exception using errcode='22023',message='invalid birth permit';
  end if;
  perform set_config('houfeng.birth_continuity_proof',v->>'continuity_proof',true);
  perform record_platform_internal.record_birth_writer_guard(v->>'record_id');
  perform record_platform_internal.record_birth_continuity_guard();
  a:=record_platform_internal.record_birth_request_row(v);
  if a.allocation_id is null or a.allocation_id<>v->>'allocation_id' then
    raise exception using errcode='23505',message='birth permit request conflict';
  end if;
  select * into strict a from record_platform_internal.record_birth_allocations
    where allocation_id=a.allocation_id for update nowait;
  if a.state<>'prepared' or a.reservation_id<>v->>'reservation_id' or a.record_id<>v->>'record_id'
    or a.revision_id<>v->>'revision_id' or a.canonical_hash<>decode(v->>'canonical_hash','hex')
    or a.creation_request_fingerprint<>decode(v->>'creation_request_fingerprint','hex')
    or coalesce(a.prepare_receipt,''::bytea)<>decode(v->>'prepare_receipt','hex')
    or a.initial_commitment<>record_platform_internal.record_birth_initial_commitment(a) then
    raise exception using errcode='23505',message='birth permit binding conflict';
  end if;
  if a.domain='certifiable' then
    b:=record_platform_internal.record_birth_binding();
    if b.generation is null or (b.generation,b.key_id,b.cutover_digest) is distinct from
      (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
      raise exception using errcode='55000',message='birth permit binding is no longer current';
    end if;
  end if;
  update record_platform_internal.record_birth_allocations set state='consumed' where allocation_id=a.allocation_id;
  insert into public.records(record_id,project_id,lifecycle) values(a.record_id,a.project_id,'active');
exception when lock_not_available then
  raise exception using errcode='40001',message='birth permit busy; restart transaction';
end $$;

create function public.record_birth_finish(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  v:=record_platform_internal.record_birth_command($1,
    array['allocation_id','reservation_id','record_id','revision_id','author_id','canonical_hash',
      'creation_request_fingerprint','prepare_receipt','continuity_proof'], '{}');
  if v->>'allocation_id' !~ '^rqa_[0-9a-f]{32}$' or v->>'reservation_id' !~ '^rba_[0-9a-f]{32}$'
    or v->>'record_id' !~ '^rec2_[0-9a-f]{32}$' or v->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$'
    or v->>'author_id' !~ '^[a-z0-9_]{1,128}$' or v->>'canonical_hash' !~ '^[0-9a-f]{64}$'
    or v->>'creation_request_fingerprint' !~ '^[0-9a-f]{64}$'
    or (v->>'prepare_receipt'<>'' and (length(v->>'prepare_receipt') not between 64 and 8192
      or length(v->>'prepare_receipt') % 2<>0 or v->>'prepare_receipt' !~ '^[0-9a-f]+$')) then
    raise exception using errcode='22023',message='invalid birth finish permit';
  end if;
  perform set_config('houfeng.birth_continuity_proof',v->>'continuity_proof',true);
  perform record_platform_internal.record_birth_writer_guard(v->>'record_id');
  perform record_platform_internal.record_birth_continuity_guard();
  select * into a from record_platform_internal.record_birth_allocations
    where allocation_id=v->>'allocation_id' for update nowait;
  if not found or a.state<>'consumed' or a.reservation_id<>v->>'reservation_id' or a.record_id<>v->>'record_id'
    or a.revision_id<>v->>'revision_id' or a.actor_id<>v->>'author_id'
    or a.canonical_hash<>decode(v->>'canonical_hash','hex')
    or a.creation_request_fingerprint<>decode(v->>'creation_request_fingerprint','hex')
    or coalesce(a.prepare_receipt,''::bytea)<>decode(v->>'prepare_receipt','hex')
    or not record_platform_internal.record_birth_actual_first(a)
    or not exists(select 1 from public.records r where r.project_id=a.project_id and r.record_id=a.record_id
      and r.current_revision_id=a.revision_id) then
    raise exception using errcode='23505',message='birth finish does not match first revision';
  end if;
  update record_platform_internal.record_birth_allocations set state='finished',finished_txid=txid_current()
    where allocation_id=a.allocation_id;
exception when lock_not_available then
  raise exception using errcode='40001',message='birth finish scope busy; restart transaction';
end $$;

create function public.record_birth_committed(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,array['record_id'],'{}');
  if v->>'record_id' !~ '^rec2_[0-9a-f]{32}$' then
    raise exception using errcode='22023',message='invalid birth record identity';
  end if;
  select * into a from record_platform_internal.record_birth_allocations where record_id=v->>'record_id';
  if not found or a.state not in ('finished','confirmed') or a.finished_txid is null
    or a.finished_txid=txid_current() or not record_platform_internal.record_birth_actual_first(a) then
    raise exception using errcode='55000',message='committed birth unavailable';
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

-- Reauthenticate every persisted W2 event on certification, including the
-- original binding and immutable request. The witness observation is compared
-- separately; stored authenticated bytes alone do not prove W2 is available.
create function record_platform_internal.record_birth_events_valid(a record_platform_internal.record_birth_allocations)
returns boolean language plpgsql stable security definer set search_path=pg_catalog as $$
declare e record; original record_platform_internal.record_birth_bindings;
begin
  select * into original from record_platform_internal.record_birth_bindings
    where (generation,key_id,cutover_digest)=(a.binding_generation,a.binding_key_id,a.binding_cutover_digest);
  if not found or a.reserve_sequence is null or a.prepare_sequence is null or a.created_sequence is null
    or not (a.reserve_sequence<a.prepare_sequence and a.prepare_sequence<a.created_sequence) then return false; end if;
  for e in select * from (values
    (a.reserve_event,a.reserve_receipt,a.reserve_sequence,'reserved'::text),
    (a.prepare_event,a.prepare_receipt,a.prepare_sequence,'prepared'::text),
    (a.created_event,a.created_receipt,a.created_sequence,'created'::text)
  ) as events(command,receipt,sequence,kind) loop
    if e.command is null or e.receipt is null or e.command->>'kind' is distinct from e.kind
      or (e.command->>'sequence')::bigint is distinct from e.sequence
      or e.command->>'authority_id' is distinct from original.authority_id
      or e.command->>'lineage_id' is distinct from original.lineage_id
      or e.command->>'project_id' is distinct from a.project_id
      or e.command->>'actor_id' is distinct from a.actor_id
      or e.command->>'actor_scope_digest' is distinct from encode(a.actor_scope_digest,'hex')
      or e.command->>'purpose' is distinct from a.purpose
      or e.command->>'idempotency_key' is distinct from a.idempotency_key
      or e.command->>'request_fingerprint' is distinct from encode(a.request_fingerprint,'hex')
      or e.command->>'reservation_id' is distinct from a.reservation_id
      or e.command->>'record_id' is distinct from a.record_id
      or e.command->>'initial_commitment' is distinct from (case when e.kind='reserved' then repeat('0',64)
        else encode(a.initial_commitment,'hex') end)
      or record_platform_internal.record_birth_receipt_check(e.command) is distinct from e.receipt then
      return false;
    end if;
  end loop;
  return true;
end $$;

create function public.record_birth_certification(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
  b record_platform_internal.record_birth_bindings; historical record_platform_internal.record_birth_bindings;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['record_id','authority_id','lineage_id','deployment_id','project_id','generation','key_id',
      'cutover_digest','head_sequence','head_hash','reserved','prepared','created'],array['generation','head_sequence']);
  if v->>'record_id' !~ '^rec2_[89a-f][0-9a-f]{31}$' or v->>'authority_id' !~ '^rd-[0-9a-f]{64}$'
    or v->>'lineage_id' !~ '^bl-[0-9a-f]{64}$' or v->>'deployment_id' !~ '^dp-[0-9a-f]{64}$'
    or v->>'project_id'<>'default' or v->>'key_id' !~ '^bk-[0-9a-f]{64}$'
    or (v->>'generation')::bigint<=0 or (v->>'head_sequence')::bigint<=0
    or v->>'cutover_digest' !~ '^[0-9a-f]{64}$' or v->>'head_hash' !~ '^[0-9a-f]{64}$'
    or v->>'cutover_digest'=repeat('0',64) or v->>'head_hash'=repeat('0',64)
    or exists (select 1 from unnest(array[v->>'reserved',v->>'prepared',v->>'created']) as receipts(value)
      where length(value) not between 64 and 8192 or length(value)%2<>0 or value !~ '^[0-9a-f]+$') then
    raise exception using errcode='22023',message='invalid birth observation';
  end if;
  b:=record_platform_internal.record_birth_binding();
  if b.generation is null or b.authority_id<>v->>'authority_id' or b.lineage_id<>v->>'lineage_id'
    or b.deployment_id<>v->>'deployment_id' or b.project_id<>v->>'project_id'
    or b.generation<>(v->>'generation')::bigint or b.key_id<>v->>'key_id'
    or b.cutover_digest<>decode(v->>'cutover_digest','hex') then
    raise exception using errcode='55000',message='birth observation is not current';
  end if;
  select * into a from record_platform_internal.record_birth_allocations where record_id=v->>'record_id';
  if not found or a.domain<>'certifiable' or a.state<>'confirmed' or a.finished_txid is null
    or a.finished_txid=txid_current() or a.reserve_receipt<>decode(v->>'reserved','hex')
    or a.prepare_receipt<>decode(v->>'prepared','hex') or a.created_receipt<>decode(v->>'created','hex')
    or a.created_sequence>(v->>'head_sequence')::bigint or not record_platform_internal.record_birth_actual_first(a)
    or not record_platform_internal.record_birth_events_valid(a)
    or (a.created_sequence=(v->>'head_sequence')::bigint and
      record_platform_internal.digest(a.created_receipt,'sha256')<>decode(v->>'head_hash','hex')) then
    raise exception using errcode='55000',message='birth is not confirmed';
  end if;
  select * into strict historical from record_platform_internal.record_birth_bindings
    where (generation,key_id,cutover_digest)=(a.binding_generation,a.binding_key_id,a.binding_cutover_digest);
  if historical.authority_id<>b.authority_id or historical.lineage_id<>b.lineage_id or historical.project_id<>b.project_id then
    raise exception using errcode='55000',message='birth lineage is not current';
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

create function record_platform_internal.record_birth_allocation_guard()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
  if tg_op='DELETE' then raise exception using errcode='55000',message='birth tombstones are permanent'; end if;
  if row(new.allocation_id,new.project_id,new.actor_id,new.actor_scope_digest,new.purpose,new.idempotency_key,
      new.request_fingerprint,new.domain,new.binding_generation,new.binding_key_id,new.binding_cutover_digest)
    is distinct from row(old.allocation_id,old.project_id,old.actor_id,old.actor_scope_digest,old.purpose,old.idempotency_key,
      old.request_fingerprint,old.domain,old.binding_generation,old.binding_key_id,old.binding_cutover_digest)
    or (old.reservation_id is not null and new.reservation_id is distinct from old.reservation_id)
    or (old.record_id is not null and new.record_id is distinct from old.record_id)
    or (old.initial_commitment is not null and row(new.revision_id,new.canonical_hash,new.creation_request_fingerprint,new.initial_commitment)
      is distinct from row(old.revision_id,old.canonical_hash,old.creation_request_fingerprint,old.initial_commitment))
    or (old.finished_txid is not null and new.finished_txid is distinct from old.finished_txid)
    or (old.publication_key is not null and row(new.publication_key,new.publication_digest)
      is distinct from row(old.publication_key,old.publication_digest))
    or (old.reserve_receipt is not null and row(new.reserve_receipt,new.reserve_sequence,new.reserve_event) is distinct from row(old.reserve_receipt,old.reserve_sequence,old.reserve_event))
    or (old.prepare_receipt is not null and row(new.prepare_receipt,new.prepare_sequence,new.prepare_event) is distinct from row(old.prepare_receipt,old.prepare_sequence,old.prepare_event))
    or (old.created_receipt is not null and row(new.created_receipt,new.created_sequence,new.created_event) is distinct from row(old.created_receipt,old.created_sequence,old.created_event))
    or not ((old.state='pending' and new.state='allocated') or (old.state='allocated' and new.state in ('preparing','prepared'))
      or (old.state='preparing' and new.state='prepared') or (old.state='prepared' and new.state='consumed')
      or (old.state='consumed' and new.state='finished') or (old.state='finished' and new.state in ('confirmed','tombstoned'))
      or (old.state='confirmed' and new.state='tombstoned')
      or (old.state=new.state and old.state in ('allocated','preparing','prepared')
        and old.publication_key is null and new.publication_key is not null)) then
    raise exception using errcode='55000',message='immutable birth transition';
  end if;
  return new;
end $$;
create trigger record_birth_allocation_guard before update or delete on record_platform_internal.record_birth_allocations
  for each row execute function record_platform_internal.record_birth_allocation_guard();
create trigger record_birth_allocation_no_truncate before truncate on record_platform_internal.record_birth_allocations
  for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger record_birth_lineage_immutable before update or delete or truncate on record_platform_internal.record_birth_lineage
  for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger record_birth_keys_immutable before update or delete or truncate on record_platform_internal.record_birth_keys
  for each statement execute function record_platform_internal.reject_source_retirement_mutation();
create trigger record_birth_bindings_immutable before update or delete or truncate on record_platform_internal.record_birth_bindings
  for each statement execute function record_platform_internal.reject_source_retirement_mutation();

-- Invoker context is intentional: only the named SECURITY DEFINER consume
-- command can insert roots for a constrained direct-login caller.
create function record_platform_internal.record_birth_root_insert_guard()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  if current_user=session_user or current_user <> (select pg_get_userbyid(relowner) from pg_class
    where oid='public.records'::regclass) or new.record_id !~ '^rec2_[0-9a-f]{32}$' then
    raise exception using errcode='42501',message='record root creation requires birth consume';
  end if;
  return new;
end $$;
create trigger record_birth_root_insert_guard before insert on public.records
  for each row execute function record_platform_internal.record_birth_root_insert_guard();
create function record_platform_internal.record_birth_root_identity_guard()
returns trigger language plpgsql set search_path=pg_catalog as $$
begin
  raise exception using errcode='42501',message='record root identity is immutable';
end $$;
create trigger record_birth_root_identity_guard before update of record_id,project_id on public.records
  for each row execute function record_platform_internal.record_birth_root_identity_guard();
create function record_platform_internal.record_birth_root_tombstone()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
  update record_platform_internal.record_birth_allocations set state='tombstoned' where record_id=old.record_id;
  return old;
end $$;
create trigger record_birth_root_tombstone before delete on public.records
  for each row execute function record_platform_internal.record_birth_root_tombstone();
create function record_platform_internal.record_birth_root_complete()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare a record_platform_internal.record_birth_allocations;
begin
  select * into a from record_platform_internal.record_birth_allocations where record_id=new.record_id;
  if not found or a.state not in ('finished','confirmed') or a.finished_txid is null
    or not record_platform_internal.record_birth_actual_first(a) then
    raise exception using errcode='23514',message='record root requires finished matching first revision';
  end if;
  return null;
end $$;
create constraint trigger record_birth_root_complete after insert on public.records
  deferrable initially deferred for each row execute function record_platform_internal.record_birth_root_complete();

-- Publication is a single immutable binding on the existing allocation, not a
-- lease or completion assertion. It survives consumed drafts and root purge.
create function public.record_birth_allocation_get(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,array['project_id','actor_id','allocation_id'],'{}');
  if v->>'project_id'<>'default' or v->>'actor_id' !~ '^[a-z0-9_]{1,128}$'
    or v->>'allocation_id' !~ '^rqa_[0-9a-f]{32}$' then
    raise exception using errcode='22023',message='invalid allocation lookup';
  end if;
  select * into a from record_platform_internal.record_birth_allocations
    where project_id=v->>'project_id' and actor_id=v->>'actor_id' and allocation_id=v->>'allocation_id';
  if not found then raise exception using errcode='55000',message='birth allocation unavailable'; end if;
  return record_platform_internal.record_birth_project(a);
end $$;

create function public.record_birth_publication_bind(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['allocation_id','actor_id','actor_scope_digest','publication_key','publication_digest','continuity_proof'],'{}');
  perform record_platform_internal.record_birth_continuity_check(decode(v->>'continuity_proof','hex'),false);
  if v->>'allocation_id' !~ '^rqa_[0-9a-f]{32}$' or v->>'actor_id' !~ '^[a-z0-9_]{1,128}$'
    or v->>'actor_scope_digest' !~ '^[0-9a-f]{64}$' or v->>'actor_scope_digest'=repeat('0',64)
    or v->>'publication_key' !~ '^[A-Za-z0-9._~-]{1,200}$'
    or v->>'publication_key' ~ 'drt1_[A-Za-z0-9_-]{43}'
    or v->>'publication_digest' !~ '^[0-9a-f]{64}$' or v->>'publication_digest'=repeat('0',64) then
    raise exception using errcode='22023',message='invalid publication binding';
  end if;
  select * into a from record_platform_internal.record_birth_allocations
    where allocation_id=v->>'allocation_id' and actor_id=v->>'actor_id' for update;
  if not found then raise exception using errcode='55000',message='birth allocation unavailable'; end if;
  if a.publication_key is not null then
    if a.publication_key<>v->>'publication_key' or a.publication_digest<>decode(v->>'publication_digest','hex') then
      raise exception using errcode='23505',message='publication binding conflict';
    end if;
  else
    if a.actor_scope_digest<>decode(v->>'actor_scope_digest','hex') then
      raise exception using errcode='23505',message='publication actor scope conflict';
    end if;
    if a.state not in ('allocated','preparing','prepared') then
      raise exception using errcode='55000',message='birth allocation cannot bind a new publication';
    end if;
    update record_platform_internal.record_birth_allocations
      set publication_key=v->>'publication_key',publication_digest=decode(v->>'publication_digest','hex')
      where allocation_id=a.allocation_id returning * into a;
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

create function public.record_birth_publication_lookup(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; a record_platform_internal.record_birth_allocations;
begin
  perform record_platform_internal.record_birth_admit();
  v:=record_platform_internal.record_birth_command($1,
    array['project_id','actor_id','publication_key','publication_digest'],'{}');
  if v->>'project_id'<>'default' or v->>'actor_id' !~ '^[a-z0-9_]{1,128}$'
    or v->>'publication_key' !~ '^[A-Za-z0-9._~-]{1,200}$'
    or v->>'publication_key' ~ 'drt1_[A-Za-z0-9_-]{43}'
    or v->>'publication_digest' !~ '^[0-9a-f]{64}$' or v->>'publication_digest'=repeat('0',64) then
    raise exception using errcode='22023',message='invalid publication lookup';
  end if;
  select * into a from record_platform_internal.record_birth_allocations
    where project_id=v->>'project_id' and actor_id=v->>'actor_id' and publication_key=v->>'publication_key';
  if not found then return null; end if;
  if a.publication_digest<>decode(v->>'publication_digest','hex') then
    raise exception using errcode='23505',message='publication request fingerprint conflict';
  end if;
  return record_platform_internal.record_birth_project(a);
end $$;

revoke all on function record_platform_internal.record_birth_command(bytea,text[],text[]),
  record_platform_internal.record_birth_validate_request(jsonb),record_platform_internal.record_birth_admit(),
  record_platform_internal.record_birth_binding(),
  record_platform_internal.record_birth_project(record_platform_internal.record_birth_allocations),
  record_platform_internal.record_birth_request_row(jsonb),
  record_platform_internal.record_birth_initial_commitment(record_platform_internal.record_birth_allocations),
  record_platform_internal.record_birth_receipt_check(jsonb),
  record_platform_internal.record_birth_actual_first(record_platform_internal.record_birth_allocations),
  record_platform_internal.record_birth_events_valid(record_platform_internal.record_birth_allocations),
  record_platform_internal.record_birth_writer_guard(text),record_platform_internal.record_birth_allocation_guard(),
  record_platform_internal.record_birth_root_insert_guard(),record_platform_internal.record_birth_root_identity_guard(),
  record_platform_internal.record_birth_root_tombstone(),record_platform_internal.record_birth_root_complete(),
  public.record_birth_allocation_find(bytea),public.record_birth_current_binding(),public.record_birth_allocation_begin(bytea),
  public.record_birth_receipt_register(bytea),public.record_birth_prepare_create(bytea),public.record_birth_committed(bytea),
  public.record_birth_certification(bytea),public.record_birth_consume(bytea),public.record_birth_finish(bytea),
  public.record_birth_allocation_get(bytea),public.record_birth_publication_bind(bytea),public.record_birth_publication_lookup(bytea) from public;

-- Evidence content may precede its root only through an exact, still-usable
-- birth allocation. The following checks never wait on an earlier-ranked lock.
create function record_platform_internal.evidence_current_actor(text,text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare actor alias for $1; expected alias for $2; body bytea; groups text[]; group_id text;
begin
  if actor !~ '^usr_[a-z0-9]{1,64}$' or expected !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='invalid evidence actor';
  end if;
  lock table public.users,public.record_access_groups,public.record_access_group_members in share mode nowait;
  if not exists(select 1 from public.users where user_id=actor and role='admin' and disabled_at is null) then
    raise exception using errcode='42501',message='evidence actor unavailable';
  end if;
  select coalesce(array_agg(g.group_id order by g.group_id collate "C"),'{}'::text[]) into groups
    from public.record_access_groups g join public.record_access_group_members m on m.group_id=g.group_id
    where g.project_id='default' and m.user_id=actor;
  body:=record_platform_internal.source_retirement_field(convert_to('recordauth.actor.v1','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to(actor,'UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to('project_admin','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to('default','UTF8'))||int4send(cardinality(groups));
  foreach group_id in array groups loop
    body:=body||record_platform_internal.source_retirement_field(convert_to(group_id,'UTF8'));
  end loop;
  if record_platform_internal.digest(body,'sha256')<>decode(expected,'hex') then
    raise exception using errcode='42501',message='evidence actor scope changed';
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='evidence membership busy; restart transaction';
end $$;

create function record_platform_internal.evidence_live_source(text,text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare kind alias for $1; source alias for $2; present boolean;
begin
  if kind='vps' then
    perform 1 from public.vps_assets where vps_id=source for share nowait; present:=found;
  elsif kind='monitoring_instance' then
    perform 1 from public.monitoring_instances where monitoring_instance_id=source for share nowait; present:=found;
  elsif kind='target' then
    perform 1 from public.targets where target_id=source for share nowait; present:=found;
  else
    raise exception using errcode='22023',message='invalid evidence source';
  end if;
  if not present or exists(select 1 from public.source_retirement_barriers b
    where (b.project_id,b.source_kind,b.source_id)=('default',kind,source))
    or exists(select 1 from public.source_retirement_coverage_unknown u
    where (u.project_id,u.source_kind,u.source_id)=('default',kind,source)) then
    raise exception using errcode='55000',message='evidence source unavailable';
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='evidence source busy; restart transaction';
end $$;

create function record_platform_internal.evidence_target_guard(text,text,text,text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v alias for $1; actor alias for $2; digest alias for $3; allocation_arg alias for $4;
  a record_platform_internal.record_birth_allocations; binding record; root_present boolean;
begin
  if v !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$' then
    raise exception using errcode='22023',message='invalid evidence target';
  end if;
  perform record_platform_internal.evidence_current_actor(actor,digest);
  perform record_platform_internal.record_birth_writer_guard(v);
  perform 1 from public.records where project_id='default' and record_id=v for share nowait;
  root_present:=found;
  if allocation_arg='' then
    if not root_present then raise exception using errcode='55000',message='evidence root unavailable'; end if;
    return;
  end if;
  select allocation.* into a from record_platform_internal.record_birth_allocations allocation
    where allocation.allocation_id=allocation_arg for update nowait;
  if not found or root_present or (a.project_id,a.record_id,a.actor_id,a.actor_scope_digest)
    is distinct from ('default'::text,v,actor,decode(digest,'hex'))
    or a.state not in ('allocated','preparing','prepared') then
    raise exception using errcode='55000',message='evidence allocation unavailable';
  end if;
  if a.domain='certifiable' then
    binding:=record_platform_internal.record_birth_binding();
    if binding.generation is null or (binding.generation,binding.key_id,binding.cutover_digest) is distinct from
      (a.binding_generation,a.binding_key_id,a.binding_cutover_digest) then
      raise exception using errcode='55000',message='evidence allocation binding is stale';
    end if;
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='evidence target busy; restart transaction';
end $$;

create function public.record_evidence_intent_insert(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; capture_selection jsonb; capture_preview jsonb; allocation record; preview_hash bytea;
  metadata_size bigint; selection_size bigint; selection_bytes bytea; preview_bytes bytea;
begin
  if $1 is null or octet_length($1)<10 then
    raise exception using errcode='22023',message='invalid evidence intent framing';
  end if;
  metadata_size:=(get_byte($1,0)::bigint<<24)|(get_byte($1,1)::bigint<<16)|(get_byte($1,2)::bigint<<8)|get_byte($1,3)::bigint;
  if metadata_size not between 1 and 32768 or octet_length($1)<8+metadata_size then
    raise exception using errcode='22023',message='invalid evidence intent metadata';
  end if;
  selection_size:=(get_byte($1,(4+metadata_size)::integer)::bigint<<24)|(get_byte($1,(5+metadata_size)::integer)::bigint<<16)
    |(get_byte($1,(6+metadata_size)::integer)::bigint<<8)|get_byte($1,(7+metadata_size)::integer)::bigint;
  if selection_size not between 1 and 5242880 or octet_length($1)-8-metadata_size-selection_size not between 1 and 5242880 then
    raise exception using errcode='22023',message='invalid evidence intent body';
  end if;
  selection_bytes:=substring($1 from (9+metadata_size)::integer for selection_size::integer);
  preview_bytes:=substring($1 from (9+metadata_size+selection_size)::integer);
  v:=record_platform_internal.record_birth_command(substring($1 from 5 for metadata_size::integer),array['actor_id','actor_scope_digest','allocation_id',
    'record_id','snapshot_id','intent_id','kind','schema_version','preview_digest','source_digest',
    'estimated_size_bytes','created_at','valid_until'],'{}');
  if v->>'snapshot_id' !~ '^evs_[a-z0-9]{1,64}$' or v->>'intent_id' !~ '^evi_[0-9a-f]{24}$'
    or v->>'kind' !~ '^[a-z0-9_.]{1,128}$' or v->>'schema_version' !~ '^[1-9][0-9]{0,4}$'
    or (v->>'schema_version')::bigint>65535 or v->>'estimated_size_bytes' !~ '^[1-9][0-9]{0,6}$'
    or (v->>'estimated_size_bytes')::bigint>5242880 or v->>'preview_digest' !~ '^[0-9a-f]{64}$'
    or v->>'source_digest' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='invalid evidence intent command';
  end if;
  capture_selection:=convert_from(selection_bytes,'UTF8')::jsonb; capture_preview:=convert_from(preview_bytes,'UTF8')::jsonb;
  preview_hash:=record_platform_internal.digest(int8send(octet_length(convert_to('houfeng.evidence.capture-preview.v1','UTF8'))::bigint)
    ||convert_to('houfeng.evidence.capture-preview.v1','UTF8')||int8send(octet_length(preview_bytes)::bigint)||preview_bytes,'sha256');
  if jsonb_typeof(capture_selection)<>'object' or jsonb_typeof(capture_preview)<>'object'
    or capture_preview->'Selection' is distinct from capture_selection or capture_preview->>'IntentID' is distinct from v->>'intent_id'
    or capture_selection->'Key'->>'Kind' is distinct from v->>'kind'
    or capture_selection->'Key'->>'SchemaVersion' is distinct from v->>'schema_version'
    or capture_preview->'Key' is distinct from capture_selection->'Key'
    or capture_preview->'SourceDigest' is distinct from (select jsonb_agg(get_byte(decode(v->>'source_digest','hex'),i) order by i) from generate_series(0,31) i)
    or capture_preview->>'EstimatedCanonicalBytes' is distinct from v->>'estimated_size_bytes'
    or (capture_preview->>'PreviewedAt')::timestamptz is distinct from (v->>'created_at')::timestamptz
    or (capture_preview->>'ValidUntil')::timestamptz is distinct from (v->>'valid_until')::timestamptz
    or (v->>'valid_until')::timestamptz<=(clock_timestamp())
    or preview_hash is distinct from decode(v->>'preview_digest','hex') then
    raise exception using errcode='22023',message='evidence preview binding conflict';
  end if;
  perform record_platform_internal.evidence_target_guard(v->>'record_id',v->>'actor_id',v->>'actor_scope_digest',v->>'allocation_id');
  perform record_platform_internal.evidence_live_source(capture_selection->>'SourceType',capture_selection->>'SourceID');
  if v->>'allocation_id'<>'' then
    select a.* into strict allocation from record_platform_internal.record_birth_allocations a where a.allocation_id=v->>'allocation_id';
    if allocation.purpose not in ('record_create','evidence_preview') then
      raise exception using errcode='55000',message='evidence allocation purpose mismatch';
    end if;
  end if;
  insert into public.evidence_capture_intents(intent_id,record_id,kind,schema_version,preview_digest,source_digest,
    selection,preview,snapshot_id,estimated_size_bytes,created_at,valid_until,birth_allocation_id,capture_actor_id,capture_actor_scope_digest)
  values(v->>'intent_id',v->>'record_id',v->>'kind',(v->>'schema_version')::bigint,preview_hash,
    decode(v->>'source_digest','hex'),capture_selection,capture_preview,v->>'snapshot_id',(v->>'estimated_size_bytes')::bigint,
    (v->>'created_at')::timestamptz,(v->>'valid_until')::timestamptz,nullif(v->>'allocation_id',''),v->>'actor_id',decode(v->>'actor_scope_digest','hex'));
end $$;
revoke all on function record_platform_internal.evidence_current_actor(text,text),
  record_platform_internal.evidence_live_source(text,text),record_platform_internal.evidence_target_guard(text,text,text,text),
  public.record_evidence_intent_insert(bytea) from public;

-- Canonical bytes determine the content address. The trusted Go caller has
-- validated the snapshot and produced the gzip; this command does not attest
-- that the compressed bytes decode to the supplied canonical bytes.
create function public.record_evidence_payload_insert(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; document jsonb; canonical bytea; compressed bytea; digest bytea;
  metadata_size bigint; canonical_size bigint; intent public.evidence_capture_intents;
  allocation record_platform_internal.record_birth_allocations; binding record;
  route record; item record; targets text[]; current_targets text[]; target text;
  inserted bigint; existing public.evidence_payloads;
begin
  perform record_platform_internal.local_blob_direct_login();
  if $1 is null or octet_length($1)<10 then
    raise exception using errcode='22023',message='invalid evidence payload framing';
  end if;
  metadata_size:=(get_byte($1,0)::bigint<<24)|(get_byte($1,1)::bigint<<16)|(get_byte($1,2)::bigint<<8)|get_byte($1,3)::bigint;
  if metadata_size not between 1 and 32768 or octet_length($1)<8+metadata_size then
    raise exception using errcode='22023',message='invalid evidence payload metadata';
  end if;
  canonical_size:=(get_byte($1,(4+metadata_size)::integer)::bigint<<24)|(get_byte($1,(5+metadata_size)::integer)::bigint<<16)
    |(get_byte($1,(6+metadata_size)::integer)::bigint<<8)|get_byte($1,(7+metadata_size)::integer)::bigint;
  if canonical_size not between 1 and 5242880 or octet_length($1)-8-metadata_size-canonical_size not between 1 and 6291456 then
    raise exception using errcode='22023',message='invalid evidence payload body';
  end if;
  v:=record_platform_internal.record_birth_command(substring($1 from 5 for metadata_size::integer),
    array['route','actor_id','actor_scope_digest','allocation_id','record_id','snapshot_id','intent_id',
      'source_kind','source_id','source_digest','kind','schema_version','payload_digest',
      'import_job_id','import_plan_id','revision_id'],'{}');
  canonical:=substring($1 from (9+metadata_size)::integer for canonical_size::integer);
  compressed:=substring($1 from (9+metadata_size+canonical_size)::integer);
  digest:=record_platform_internal.digest(convert_to('houfeng.evidence.canonical-payload.v1','UTF8')||decode('00','hex')||canonical,'sha256');
  document:=convert_from(canonical,'UTF8')::jsonb;
  if v->>'route' not in ('capture','comparison','import') or v->>'snapshot_id' !~ '^evs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'payload_digest' !~ '^[0-9a-f]{64}$' or digest<>decode(v->>'payload_digest','hex')
    or v->>'source_digest' !~ '^[0-9a-f]{64}$' or v->>'schema_version' !~ '^[1-9][0-9]{0,4}$'
    or document->>'canonicalization_version' is distinct from '1'
    or document->>'kind' is distinct from v->>'kind' or document->>'schema_version' is distinct from v->>'schema_version'
    or jsonb_typeof(document->'payload') is distinct from 'object' then
    raise exception using errcode='22023',message='invalid canonical evidence binding';
  end if;

  if v->>'route'='comparison' then
    if v->>'kind'<>'comparison.result' or v->>'schema_version'<>'1' or v->>'intent_id'<>''
      or v->>'import_job_id'<>'' or v->>'import_plan_id'<>'' or v->>'revision_id'<>''
      or document->'payload'->>'digest' is distinct from v->>'source_digest'
      or v->>'snapshot_id' is distinct from 'evs_'||substr(encode(record_platform_internal.digest(convert_to(
        'houfeng.evidence.comparison-result.v1:'||(v->>'record_id')||'|'||(v->>'source_digest'),'UTF8'),'sha256'),'hex'),1,32)
      or jsonb_typeof(document->'payload'->'items') is distinct from 'array'
      or jsonb_array_length(document->'payload'->'items') not between 2 and 6 then
      raise exception using errcode='22023',message='invalid comparison payload route';
    end if;
    -- Resolve every immediate owner from the canonical item itself, never a
    -- caller-supplied route list. Discover first, acquire each record rank in
    -- lexical order, then reread and lock the exact snapshot/revision rows.
    select array_agg(distinct x.owner collate "C" order by x.owner collate "C") into targets from (
      select v->>'record_id' as owner union all
      select coalesce(nullif(i.value->>'record_id',''),s.record_id,r.record_id)
      from jsonb_array_elements(document->'payload'->'items') i(value)
      left join public.evidence_snapshots s on s.snapshot_id=nullif(i.value->>'original_snapshot_id','')
      left join public.record_revisions r on r.revision_id=nullif(i.value->>'revision_id','')
    ) x where x.owner is not null;
    foreach target in array targets loop
      perform record_platform_internal.record_birth_writer_guard(target);
    end loop;
    foreach target in array targets loop
      perform 1 from public.records root where root.record_id=target for share nowait;
      if not found and target<>v->>'record_id' then
        raise exception using errcode='55000',message='comparison source root unavailable';
      end if;
    end loop;
    for item in select i.value from jsonb_array_elements(document->'payload'->'items') i(value) loop
      if jsonb_typeof(item.value)<>'object' or coalesce(item.value->>'hash','') !~ '^[0-9a-f]{64}$' then
        raise exception using errcode='22023',message='invalid comparison item';
      end if;
      if coalesce(item.value->>'original_snapshot_id','')<>'' then
        select s.record_id,s.payload_digest,s.kind,s.schema_version into route from public.evidence_snapshots s
          where s.snapshot_id=item.value->>'original_snapshot_id' for share nowait;
        if not found
          or route.payload_digest<>decode(item.value->>'hash','hex')
          or route.kind||'/v'||route.schema_version::text is distinct from item.value->>'kind'
          or item.value->>'copied_snapshot_id' is distinct from 'evs_'||substr(encode(record_platform_internal.digest(convert_to(
            'houfeng.evidence.comparison-copy.v1:'||(v->>'record_id')||'|'||(item.value->>'original_snapshot_id')||'|'||(v->>'source_digest'),
            'UTF8'),'sha256'),'hex'),1,32)
          or (coalesce(item.value->>'record_id','')<>'' and route.record_id<>item.value->>'record_id') then
          raise exception using errcode='55000',message='comparison snapshot owner unavailable';
        end if;
      elsif coalesce(item.value->>'revision_id','')='' then
        raise exception using errcode='55000',message='comparison item owner unavailable';
      end if;
      if coalesce(item.value->>'revision_id','')<>'' then
        perform 1 from public.record_revisions r where r.revision_id=item.value->>'revision_id'
          and r.record_id=item.value->>'record_id' for share nowait;
        if not found then raise exception using errcode='55000',message='comparison revision owner unavailable'; end if;
      end if;
    end loop;
    select array_agg(distinct x.owner collate "C" order by x.owner collate "C") into current_targets from (
      select v->>'record_id' as owner union all
      select coalesce(nullif(i.value->>'record_id',''),s.record_id,r.record_id)
      from jsonb_array_elements(document->'payload'->'items') i(value)
      left join public.evidence_snapshots s on s.snapshot_id=nullif(i.value->>'original_snapshot_id','')
      left join public.record_revisions r on r.revision_id=nullif(i.value->>'revision_id','')
    ) x where x.owner is not null;
    if targets is distinct from current_targets then
      raise exception using errcode='40001',message='comparison payload owner changed';
    end if;
    if not exists (
      select 1 from jsonb_array_elements(document->'payload'->'items') i(value)
      left join public.evidence_snapshots s on s.snapshot_id=nullif(i.value->>'original_snapshot_id','')
      left join public.records root on root.record_id=coalesce(nullif(i.value->>'record_id',''),s.record_id)
      left join public.record_revision_subjects subject on subject.revision_id=root.current_revision_id
      where (s.source_kind,s.source_id)=(v->>'source_kind',v->>'source_id')
        or (subject.subject_kind,subject.source_id)=(v->>'source_kind',v->>'source_id')
    ) then
      raise exception using errcode='55000',message='comparison source binding unavailable';
    end if;
    perform record_platform_internal.evidence_target_guard(v->>'record_id',v->>'actor_id',v->>'actor_scope_digest',v->>'allocation_id');
    if v->>'allocation_id'<>'' and not exists(select 1 from record_platform_internal.record_birth_allocations a
      where a.allocation_id=v->>'allocation_id' and a.purpose='comparison_save') then
      raise exception using errcode='55000',message='comparison allocation purpose mismatch';
    end if;
  elsif v->>'route'='capture' then
    if v->>'intent_id' !~ '^evi_[0-9a-f]{24}$' or v->>'import_job_id'<>'' or v->>'import_plan_id'<>'' or v->>'revision_id'<>'' then
      raise exception using errcode='22023',message='invalid capture payload route';
    end if;
    perform record_platform_internal.evidence_target_guard(v->>'record_id',v->>'actor_id',v->>'actor_scope_digest',v->>'allocation_id');
    perform record_platform_internal.evidence_live_source(v->>'source_kind',v->>'source_id');
    select * into intent from public.evidence_capture_intents where intent_id=v->>'intent_id' for update nowait;
    if not found or intent.valid_until<=clock_timestamp() or intent.estimated_size_bytes<>canonical_size
      or (intent.record_id,intent.snapshot_id,coalesce(intent.birth_allocation_id,''),intent.capture_actor_id,
        encode(intent.capture_actor_scope_digest,'hex'),intent.kind,intent.schema_version::text,encode(intent.source_digest,'hex'),
        intent.selection->>'SourceType',intent.selection->>'SourceID') is distinct from
        (v->>'record_id',v->>'snapshot_id',v->>'allocation_id',v->>'actor_id',v->>'actor_scope_digest',v->>'kind',
         v->>'schema_version',v->>'source_digest',v->>'source_kind',v->>'source_id') then
      raise exception using errcode='55000',message='capture intent binding unavailable';
    end if;
    if v->>'allocation_id'<>'' and not exists(select 1 from record_platform_internal.record_birth_allocations a
      where a.allocation_id=v->>'allocation_id' and a.purpose in ('record_create','evidence_preview')) then
      raise exception using errcode='55000',message='capture allocation purpose mismatch';
    end if;
  else
    if v->>'intent_id'<>'' or v->>'allocation_id'<>'' or v->>'actor_scope_digest'<>''
      or v->>'import_job_id' !~ '^rij_[a-z0-9]{1,64}$' or v->>'import_plan_id' !~ '^rip_[a-z0-9]{1,64}$'
      or v->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$' then
      raise exception using errcode='22023',message='invalid import payload route';
    end if;
    perform record_platform_internal.record_birth_writer_guard(v->>'record_id');
    select a.* into strict allocation from public.record_import_jobs j
      join public.record_import_plans p on p.import_job_id=j.import_job_id
      join public.record_import_entity_mappings e on e.import_plan_id=p.import_plan_id and e.entity_kind='evidence'
      join public.record_import_entity_mappings r on r.import_plan_id=p.import_plan_id and r.entity_kind='record'
        and r.target_id=e.owner_target_record_id
      join record_platform_internal.record_birth_allocations a on a.allocation_id=r.birth_allocation_id
      join public.record_revisions revision on revision.record_id=r.target_id and revision.revision_id=v->>'revision_id'
      where j.import_job_id=v->>'import_job_id' and p.import_plan_id=v->>'import_plan_id'
        and j.project_id='default' and j.actor_id=v->>'actor_id' and j.job_state='planned'
        and j.expires_at>clock_timestamp() and p.expires_at>clock_timestamp()
        and e.target_id=v->>'snapshot_id' and e.owner_target_record_id=v->>'record_id'
        and (a.project_id,a.actor_id,a.purpose,a.record_id,a.revision_id,a.state,a.finished_txid)
          =('default'::text,j.actor_id,'import'::text,r.target_id,v->>'revision_id','finished'::text,txid_current())
        and revision.author_id=j.actor_id
      for update of j,p,e,r,a nowait;
    perform record_platform_internal.evidence_current_actor(allocation.actor_id,encode(allocation.actor_scope_digest,'hex'));
    if allocation.domain='certifiable' then
      binding:=record_platform_internal.record_birth_binding();
      if binding.generation is null or (binding.generation,binding.key_id,binding.cutover_digest) is distinct from
        (allocation.binding_generation,allocation.binding_key_id,allocation.binding_cutover_digest) then
        raise exception using errcode='55000',message='import evidence birth binding is stale';
      end if;
    end if;
  end if;

  insert into public.evidence_payloads(payload_digest,canonical_size_bytes,compressed_size_bytes,compressed_payload)
    values(digest,canonical_size,octet_length(compressed),compressed) on conflict (payload_digest) do nothing;
  get diagnostics inserted=row_count;
  if inserted=0 then
    select * into strict existing from public.evidence_payloads where payload_digest=digest for update nowait;
    if (existing.payload_encoding,existing.canonical_size_bytes,existing.compressed_size_bytes,existing.compressed_payload)
      is distinct from ('canonical_json_gzip_v1'::text,canonical_size,octet_length(compressed)::bigint,compressed) then
      raise exception using errcode='23505',message='immutable evidence payload conflict';
    end if;
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='evidence payload route busy; restart transaction';
when no_data_found or too_many_rows then
  raise exception using errcode='55000',message='evidence payload binding unavailable or ambiguous';
end $$;
revoke all on function public.record_evidence_payload_insert(bytea) from public;

-- Comparison index publication and certified-copy repair are the only
-- runtime mutations of the dependency inventory. The command owns its locks:
-- neither a caller-supplied route nor a missing row is authority. A late call
-- never waits backwards for an earlier rank.
create function public.record_comparison_index_write(bytea, bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare
  raw json; command jsonb; document jsonb; dependency json; source record;
  admission public.source_authority_admission; admission_present boolean;
  target_ids text[]; current_ids text[]; reservation_ids text[] := '{}';
  target text; reservation record; epoch_count integer := 0; actual_digest bytea;
  owner_id text; inherited_owner text;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode='25000',message='comparison index requires read committed';
  end if;
  if $1 is null or octet_length($1) not between 1 and 32768
    or $2 is null or octet_length($2) not between 1 and 5242880 then
    raise exception using errcode='22023',message='invalid comparison index command size';
  end if;
  raw:=convert_from($1,'UTF8')::json;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw))<>5
    or (select count(distinct f.key) from json_each(raw) f)<>5
    or exists(select 1 from json_each(raw) f where f.key not in
      ('record_id','snapshot_id','payload_digest','inherited_from','dependencies')
      or case when f.key='dependencies' then json_typeof(f.value)<>'array'
        else json_typeof(f.value)<>'string' end) then
    raise exception using errcode='22023',message='invalid comparison index command fields';
  end if;
  if json_array_length(raw->'dependencies') not between 1 and 6 then
    raise exception using errcode='22023',message='invalid comparison dependency count';
  end if;
  for dependency in select value from json_array_elements(raw->'dependencies') loop
    if json_typeof(dependency) is distinct from 'object'
      or (select count(*) from json_each(dependency))<>3
      or (select count(distinct f.key) from json_each(dependency) f)<>3
      or exists(select 1 from json_each(dependency) f where f.key not in
        ('record_id','revision_id','snapshot_id') or json_typeof(f.value)<>'string')
      or dependency->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
      or (dependency->>'revision_id'<>'' and dependency->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$')
      or (dependency->>'snapshot_id'<>'' and dependency->>'snapshot_id' !~ '^evs_[a-z0-9]{1,64}$')
      or (dependency->>'revision_id'='' and dependency->>'snapshot_id'='') then
      raise exception using errcode='22023',message='invalid comparison dependency identity';
    end if;
  end loop;
  command:=raw::jsonb;
  if command->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or command->>'snapshot_id' !~ '^evs_[a-z0-9]{1,64}$'
    or command->>'payload_digest' !~ '^[0-9a-f]{64}$'
    or (command->>'inherited_from'<>'' and (command->>'inherited_from' !~ '^evs_[a-z0-9]{1,64}$'
      or command->>'inherited_from'=command->>'snapshot_id'))
    or exists(select 1 from jsonb_array_elements(command->'dependencies') d
      group by d->>'record_id',d->>'revision_id',d->>'snapshot_id' having count(*)<>1) then
    raise exception using errcode='22023',message='invalid comparison index identity';
  end if;
  actual_digest:=record_platform_internal.digest(convert_to('houfeng.evidence.canonical-payload.v1','UTF8')
    ||decode('00','hex')||$2,'sha256');
  document:=convert_from($2,'UTF8')::jsonb;
  if actual_digest<>decode(command->>'payload_digest','hex')
    or document->>'canonicalization_version' is distinct from '1'
    or document->>'kind' is distinct from 'comparison.result'
    or document->>'schema_version' is distinct from '1'
    or document->'payload'->>'version' is distinct from 'comparison_result/v1'
    or jsonb_typeof(document->'payload'->'items') is distinct from 'array'
    or jsonb_array_length(document->'payload'->'items') not between 2 and 6 then
    raise exception using errcode='22023',message='comparison canonical payload mismatch';
  end if;
  -- The caller cannot omit, add, or ambiguously bind an item. Snapshot-only
  -- items derive their owner from the persisted snapshot (or certified parent).
  if exists(select 1 from jsonb_array_elements(document->'payload'->'items') item
      where (select count(*) from jsonb_array_elements(command->'dependencies') d
        where coalesce(item->>'original_snapshot_id','')=d->>'snapshot_id'
          and coalesce(item->>'revision_id','')=d->>'revision_id'
          and (coalesce(item->>'record_id','')='' or item->>'record_id'=d->>'record_id'))<>1)
    or exists(select 1 from jsonb_array_elements(command->'dependencies') d
      where not exists(select 1 from jsonb_array_elements(document->'payload'->'items') item
        where coalesce(item->>'original_snapshot_id','')=d->>'snapshot_id'
          and coalesce(item->>'revision_id','')=d->>'revision_id'
          and (coalesce(item->>'record_id','')='' or item->>'record_id'=d->>'record_id'))) then
    raise exception using errcode='55000',message='comparison dependency coverage mismatch';
  end if;

  select * into admission from public.source_authority_admission where singleton for share nowait;
  admission_present:=found;
  if admission_present and (admission.mode<>'active' or not exists(
    select 1 from public.source_application_principals p where p.principal=session_user
      and p.generation=admission.generation and p.purpose='runtime')) then
    raise exception using errcode='42501',message='comparison source admission unavailable';
  end if;
  perform record_platform_internal.record_birth_launch_admit(admission);
  if not pg_try_advisory_xact_lock_shared(1213154899,1)
    or not pg_try_advisory_xact_lock_shared(1213154899,81) then
    raise exception using errcode='40001',message='comparison fence unavailable; restart transaction';
  end if;
  if admission_present<>exists(select 1 from public.source_authority_admission where singleton) then
    raise exception using errcode='40001',message='comparison source admission changed';
  end if;
  select s.record_id into owner_id from public.evidence_snapshots s where s.snapshot_id=command->>'snapshot_id';
  if owner_id is distinct from command->>'record_id' then
    raise exception using errcode='55000',message='comparison destination route unavailable';
  end if;
  if command->>'inherited_from'<>'' then
    select s.record_id into inherited_owner from public.evidence_snapshots s where s.snapshot_id=command->>'inherited_from';
    if inherited_owner is null then
      raise exception using errcode='55000',message='comparison inherited route unavailable';
    end if;
  end if;
  select array_agg(distinct x.id collate "C" order by x.id collate "C") into target_ids from (
    select owner_id as id union all select inherited_owner
    union all select d->>'record_id' from jsonb_array_elements(command->'dependencies') d
    union all select d.source_record_id from public.comparison_result_dependencies d
      where d.result_snapshot_id=command->>'snapshot_id'
  ) x where x.id is not null;

  for reservation in select r.reservation_id from public.deletion_reservations r
    where r.project_id='default' and r.object_kind='record' and r.object_id=any(target_ids)
    order by r.object_id collate "C",r.reservation_id collate "C" for update nowait loop
    reservation_ids:=array_append(reservation_ids,reservation.reservation_id);
  end loop;
  for target in select e.object_id from public.content_delivery_epochs e
    where e.project_id='default' and e.object_kind='record' and e.object_id=any(target_ids)
    order by e.object_id collate "C" for update nowait loop
    epoch_count:=epoch_count+1;
  end loop;
  if epoch_count<>cardinality(target_ids) or exists(select 1 from public.deletion_reservations r
      where r.project_id='default' and r.object_kind='record' and r.object_id=any(target_ids)
        and not (r.reservation_id=any(reservation_ids))) then
    raise exception using errcode='55000',message='comparison record scope unavailable';
  end if;
  perform 1 from public.deletion_fence_leases l where l.project_id='default' and l.object_kind='record'
    and l.object_id=any(target_ids) order by l.object_id collate "C" for update nowait;
  perform 1 from public.object_content_leases l where l.project_id='default' and l.object_kind='record'
    and l.object_id=any(target_ids) order by l.object_id collate "C" for update nowait;
  perform 1 from public.record_deletion_gates g where g.project_id='default' and g.record_id=any(target_ids)
    order by g.record_id collate "C" for share nowait;
  if exists(select 1 from public.record_deletion_gates g where g.project_id='default' and g.record_id=any(target_ids))
    or exists(select 1 from public.deletion_fence_leases l where l.project_id='default' and l.object_kind='record'
      and l.object_id=any(target_ids) and l.expires_at>clock_timestamp())
    or exists(select 1 from public.deletion_reservations r where r.project_id='default' and r.object_kind='record'
      and r.object_id=any(target_ids) and r.state in ('fenced','committed')) then
    raise exception using errcode='55000',message='comparison record gate is closed';
  end if;
  foreach target in array target_ids loop
    perform 1 from public.records r where r.project_id='default' and r.record_id=target for share nowait;
    if not found then raise exception using errcode='55000',message='comparison record root unavailable'; end if;
  end loop;
  select array_agg(distinct x.id collate "C" order by x.id collate "C") into current_ids from (
    select s.record_id as id from public.evidence_snapshots s where s.snapshot_id=command->>'snapshot_id'
    union all select s.record_id from public.evidence_snapshots s where s.snapshot_id=command->>'inherited_from'
    union all select d->>'record_id' from jsonb_array_elements(command->'dependencies') d
    union all select d.source_record_id from public.comparison_result_dependencies d
      where d.result_snapshot_id=command->>'snapshot_id'
  ) x;
  if target_ids is distinct from current_ids then
    raise exception using errcode='40001',message='comparison record route changed; restart transaction';
  end if;
  -- The target row lock also excludes a concurrent lineage INSERT through
  -- its foreign key, even when no lineage row exists yet.
  perform 1 from public.evidence_snapshots s where s.snapshot_id in
    (command->>'snapshot_id',command->>'inherited_from') order by s.snapshot_id collate "C" for update nowait;
  perform 1 from public.evidence_copy_lineage l where l.snapshot_id=command->>'snapshot_id' for share nowait;
  if not exists(select 1 from public.evidence_snapshots s join public.evidence_payloads p on p.payload_digest=s.payload_digest
      where s.snapshot_id=command->>'snapshot_id' and s.record_id=owner_id and s.kind='comparison.result'
        and s.schema_version=1 and s.payload_digest=actual_digest and s.canonical_hash=actual_digest
        and p.canonical_size_bytes=octet_length($2)) then
    raise exception using errcode='55000',message='comparison result binding unavailable';
  end if;
  perform 1 from public.comparison_result_dependency_index_completions c
    where c.result_snapshot_id in (command->>'snapshot_id',command->>'inherited_from')
    order by c.result_snapshot_id collate "C" for update nowait;
  perform 1 from public.comparison_result_dependencies d
    where d.result_snapshot_id in (command->>'snapshot_id',command->>'inherited_from')
    order by d.result_snapshot_id collate "C",d.source_record_id collate "C",
      d.source_revision_id collate "C" nulls first,d.source_snapshot_id collate "C" nulls first for update nowait;
  if command->>'inherited_from'='' then
    if coalesce(document->'payload'->>'digest','') !~ '^[0-9a-f]{64}$'
      or command->>'snapshot_id' is distinct from 'evs_'||substr(encode(record_platform_internal.digest(convert_to(
        'houfeng.evidence.comparison-result.v1:'||owner_id||'|'||(document->'payload'->>'digest'),'UTF8'),'sha256'),'hex'),1,32)
      or exists(select 1 from public.evidence_copy_lineage l where l.snapshot_id=command->>'snapshot_id') then
      raise exception using errcode='55000',message='comparison native result provenance unavailable';
    end if;
    -- Native provenance exists only while its result is being created by the
    -- revision transaction. Old or imported canonical IDs alone do not prove
    -- that they came from signed native comparison claims.
    if not exists(select 1 from public.evidence_snapshots s where s.snapshot_id=command->>'snapshot_id'
      and s.xmin::text::bigint=mod(txid_current(),4294967296::bigint)) then
      raise exception using errcode='55000',message='comparison native result is not new in this transaction';
    end if;
    if exists(select 1 from public.comparison_result_dependency_index_completions c where c.result_snapshot_id=command->>'snapshot_id')
      or exists(select 1 from public.comparison_result_dependencies d where d.result_snapshot_id=command->>'snapshot_id') then
      raise exception using errcode='55000',message='comparison native index already exists';
    end if;
    for source in select d->>'record_id' as record_id,d->>'revision_id' as revision_id,d->>'snapshot_id' as snapshot_id
      from jsonb_array_elements(command->'dependencies') d loop
      if source.snapshot_id<>'' then
        perform 1 from public.evidence_snapshots s where s.snapshot_id=source.snapshot_id and s.record_id=source.record_id for share nowait;
        if not found or exists(select 1 from jsonb_array_elements(document->'payload'->'items') item
            left join public.evidence_snapshots s on s.snapshot_id=source.snapshot_id
            where item->>'original_snapshot_id'=source.snapshot_id
              and (item->>'hash' is distinct from encode(s.payload_digest,'hex')
                or item->>'kind' is distinct from s.kind||'/v'||s.schema_version::text)) then
          raise exception using errcode='55000',message='comparison source snapshot route unavailable';
        end if;
      end if;
      if source.revision_id<>'' then
        perform 1 from public.record_revisions r where r.revision_id=source.revision_id and r.record_id=source.record_id for share nowait;
        if not found then raise exception using errcode='55000',message='comparison source revision route unavailable'; end if;
      end if;
    end loop;
  else
    if not exists(select 1 from public.evidence_copy_lineage l join public.evidence_snapshots s
        on s.snapshot_id=l.copied_from_snapshot_id join public.comparison_result_dependency_index_completions c
        on c.result_snapshot_id=s.snapshot_id and c.payload_digest=s.payload_digest
        where l.snapshot_id=command->>'snapshot_id' and l.copied_from_snapshot_id=command->>'inherited_from'
          and l.copy_reason='explicit comparison copy' and s.record_id=inherited_owner
          and s.kind='comparison.result' and s.schema_version=1 and s.payload_digest=actual_digest
          and s.canonical_hash=actual_digest)
      or exists((select d.source_record_id,coalesce(d.source_revision_id,''),coalesce(d.source_snapshot_id,'')
        from public.comparison_result_dependencies d where d.result_snapshot_id=command->>'inherited_from'
        except select d->>'record_id',d->>'revision_id',d->>'snapshot_id' from jsonb_array_elements(command->'dependencies') d)
        union all (select d->>'record_id',d->>'revision_id',d->>'snapshot_id' from jsonb_array_elements(command->'dependencies') d
        except select d.source_record_id,coalesce(d.source_revision_id,''),coalesce(d.source_snapshot_id,'')
          from public.comparison_result_dependencies d where d.result_snapshot_id=command->>'inherited_from')) then
      raise exception using errcode='55000',message='comparison inherited provenance unavailable';
    end if;
    if exists(select 1 from public.comparison_result_dependency_index_completions c
        where c.result_snapshot_id=command->>'snapshot_id' and c.payload_digest=actual_digest)
      and not exists((select d.source_record_id,coalesce(d.source_revision_id,''),coalesce(d.source_snapshot_id,'')
        from public.comparison_result_dependencies d where d.result_snapshot_id=command->>'snapshot_id'
        except select d->>'record_id',d->>'revision_id',d->>'snapshot_id' from jsonb_array_elements(command->'dependencies') d)
        union all (select d->>'record_id',d->>'revision_id',d->>'snapshot_id' from jsonb_array_elements(command->'dependencies') d
        except select d.source_record_id,coalesce(d.source_revision_id,''),coalesce(d.source_snapshot_id,'')
          from public.comparison_result_dependencies d where d.result_snapshot_id=command->>'snapshot_id')) then
      return;
    end if;
    delete from public.comparison_result_dependency_index_completions where result_snapshot_id=command->>'snapshot_id';
    delete from public.comparison_result_dependencies where result_snapshot_id=command->>'snapshot_id';
  end if;
  insert into public.comparison_result_dependencies(result_snapshot_id,source_record_id,source_revision_id,source_snapshot_id)
    select command->>'snapshot_id',d->>'record_id',nullif(d->>'revision_id',''),nullif(d->>'snapshot_id','')
    from jsonb_array_elements(command->'dependencies') d;
  insert into public.comparison_result_dependency_index_completions(result_snapshot_id,payload_digest)
    values(command->>'snapshot_id',actual_digest);
exception when lock_not_available then
  raise exception using errcode='40001',message='comparison route busy; restart transaction';
end $$;
revoke all on function public.record_comparison_index_write(bytea,bytea) from public;
revoke all on public.comparison_result_dependencies,public.comparison_result_dependency_index_completions,
  public.comparison_client_workbenches,public.comparison_client_save_attempts from public;

-- These fixed row guards cover the other mutable inputs read by the
-- comparison decision. DML reaches them after a table/row lock, so every
-- earlier admission and record scope is reacquired without waiting.
create function record_platform_internal.comparison_input_admit()
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare admission public.source_authority_admission; present boolean;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='comparison input requires read committed';
  end if;
  select * into admission from public.source_authority_admission where singleton for share nowait;
  present:=found;
  if present and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
    where p.principal=session_user and p.generation=admission.generation and p.purpose in ('runtime','admin','worker'))) then
    raise exception using errcode='42501',message='comparison input source admission unavailable';
  end if;
  perform record_platform_internal.record_birth_launch_admit(admission);
  if not pg_try_advisory_xact_lock_shared(1213154899,1)
    or not pg_try_advisory_xact_lock_shared(1213154899,81) then
    raise exception using errcode='40001',message='comparison input fence unavailable; restart transaction';
  end if;
  if present<>exists(select 1 from public.source_authority_admission where singleton) then
    raise exception using errcode='40001',message='comparison input admission changed';
  end if;
exception when lock_not_available then
  raise exception using errcode='40001',message='comparison input admission busy; restart transaction';
end $$;

-- Older standalone draft callers do not touch a record root or a named
-- content command. Enforce the same launch admission on their actual DML.
create function record_platform_internal.record_draft_launch_guard()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare target text;
begin
  if exists(select 1 from pg_roles r where r.rolname=session_user and r.rolsuper) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='DELETE' then
    if tg_table_name='record_drafts' then
      target:=old.record_id;
    else
      select d.record_id into target from public.record_drafts d where d.draft_id=old.draft_id;
    end if;
    -- Closed recovery and core purge already authenticate this exact record
    -- through their private transaction-local effect scope.
    if target is not null and record_platform_internal.record_deletion_effect_scope(target,array['core','recovery']) then
      return old;
    end if;
  end if;
  perform record_platform_internal.comparison_input_admit();
  if tg_op='DELETE' then return old; else return new; end if;
end $$;
create trigger record_draft_launch_guard before insert or update or delete on public.record_drafts
  for each row execute function record_platform_internal.record_draft_launch_guard();
create trigger record_draft_checkpoint_launch_guard before insert or delete on public.record_draft_checkpoints
  for each row execute function record_platform_internal.record_draft_launch_guard();
revoke all on function record_platform_internal.record_draft_launch_guard() from public;

-- A persisted operation owner is data, not caller authority. Only authenticated
-- online/recovery commands create the transaction-local effects scope.
create function record_platform_internal.comparison_v1_cleanup_guard(target text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  if not record_platform_internal.record_deletion_effect_scope(target,array['core','evidence','recovery']) then
    raise exception using errcode='42501',message='comparison cleanup transaction authority unavailable';
  end if;
end $$;

create function record_platform_internal.comparison_evidence_row_guard()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare target text; origin text; target_digest bytea; origin_digest bytea; target_kind text; origin_kind text;
  target_schema bigint; origin_schema bigint; item text;
begin
  -- Superusers are outside the constrained application role boundary and are
  -- used by isolated corruption/restore fixtures and database maintenance.
  if exists(select 1 from pg_roles r where r.rolname=session_user and r.rolsuper) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  perform record_platform_internal.comparison_input_admit();
  if tg_table_name='evidence_payloads' then
    if exists(select 1 from public.evidence_snapshots s where s.payload_digest=old.payload_digest) then
      raise exception using errcode='55000',message='referenced evidence payload cannot be collected';
    end if;
    return old;
  end if;
  if tg_table_name='evidence_snapshots' then
    if tg_op='DELETE' then
      perform record_platform_internal.comparison_v1_cleanup_guard(old.record_id);
      return old;
    end if;
    perform record_platform_internal.record_birth_writer_guard(new.record_id);
    perform 1 from public.records r where r.project_id='default' and r.record_id=new.record_id for share nowait;
    if not found then raise exception using errcode='55000',message='evidence snapshot owner unavailable'; end if;
    perform 1 from public.evidence_payloads p where p.payload_digest=new.payload_digest
      and p.canonical_size_bytes=new.logical_size_bytes for share nowait;
    if not found or new.canonical_hash is distinct from new.payload_digest then
      raise exception using errcode='55000',message='evidence snapshot payload unavailable';
    end if;
    return new;
  end if;
  if tg_table_name='record_revision_evidence' then
    if tg_op='DELETE' then
      perform record_platform_internal.comparison_v1_cleanup_guard(old.record_id);
      return old;
    end if;
    perform record_platform_internal.record_birth_writer_guard(new.record_id);
    perform 1 from public.records r where r.project_id='default' and r.record_id=new.record_id for share nowait;
    if not found then raise exception using errcode='55000',message='evidence reference owner unavailable'; end if;
    perform 1 from public.record_revisions r where r.revision_id=new.revision_id and r.record_id=new.record_id for share nowait;
    if not found then raise exception using errcode='55000',message='evidence reference revision unavailable'; end if;
    perform 1 from public.evidence_snapshots s where s.snapshot_id=new.snapshot_id and s.record_id=new.record_id for share nowait;
    if not found then raise exception using errcode='55000',message='evidence reference snapshot unavailable'; end if;
    return new;
  end if;
  if tg_op='DELETE' then
    select s.record_id into target from public.evidence_snapshots s where s.snapshot_id=old.snapshot_id;
    if target is null then raise exception using errcode='55000',message='evidence lineage owner unavailable'; end if;
    perform record_platform_internal.comparison_v1_cleanup_guard(target);
    perform 1 from public.evidence_snapshots s where s.snapshot_id=old.snapshot_id and s.record_id=target for share nowait;
    if not found then raise exception using errcode='40001',message='evidence lineage route changed'; end if;
    return old;
  end if;
  select s.record_id,s.payload_digest,s.kind,s.schema_version into target,target_digest,target_kind,target_schema
    from public.evidence_snapshots s where s.snapshot_id=new.snapshot_id;
  select s.record_id,s.payload_digest,s.kind,s.schema_version into origin,origin_digest,origin_kind,origin_schema
    from public.evidence_snapshots s where s.snapshot_id=new.copied_from_snapshot_id;
  if target is null or origin is null or new.copy_reason<>'explicit comparison copy'
    or (target_digest,target_kind,target_schema) is distinct from (origin_digest,origin_kind,origin_schema) then
    raise exception using errcode='55000',message='evidence lineage route unavailable';
  end if;
  for item in select distinct id collate "C" from unnest(array[target,origin]) id order by id collate "C" loop
    perform record_platform_internal.record_birth_writer_guard(item);
  end loop;
  for item in select distinct id collate "C" from unnest(array[target,origin]) id order by id collate "C" loop
    perform 1 from public.records r where r.project_id='default' and r.record_id=item for share nowait;
    if not found then raise exception using errcode='55000',message='evidence lineage record unavailable'; end if;
  end loop;
  perform 1 from public.evidence_snapshots s where s.snapshot_id=new.snapshot_id and s.record_id=target
    and s.payload_digest=target_digest and s.kind=target_kind and s.schema_version=target_schema for share nowait;
  if not found then raise exception using errcode='40001',message='evidence lineage destination changed'; end if;
  perform 1 from public.evidence_snapshots s where s.snapshot_id=new.copied_from_snapshot_id and s.record_id=origin
    and s.payload_digest=origin_digest and s.kind=origin_kind and s.schema_version=origin_schema for share nowait;
  if not found then raise exception using errcode='40001',message='evidence lineage source changed'; end if;
  return new;
exception when lock_not_available then
  raise exception using errcode='40001',message='comparison evidence route busy; restart transaction';
end $$;

create trigger comparison_snapshot_writer_guard before insert or delete on public.evidence_snapshots
  for each row execute function record_platform_internal.comparison_evidence_row_guard();
create trigger comparison_lineage_writer_guard before insert or delete on public.evidence_copy_lineage
  for each row execute function record_platform_internal.comparison_evidence_row_guard();
create trigger comparison_reference_writer_guard before insert or delete on public.record_revision_evidence
  for each row execute function record_platform_internal.comparison_evidence_row_guard();
create trigger comparison_payload_cleanup_guard before delete on public.evidence_payloads
  for each row execute function record_platform_internal.comparison_evidence_row_guard();

create function record_platform_internal.comparison_root_epoch_guard()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
declare target text; is_record boolean;
begin
  if exists(select 1 from pg_roles r where r.rolname=session_user and r.rolsuper) then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_table_name='records' then
    target:=old.record_id;
    if (tg_op='DELETE' or (old.current_revision_id is not null and new.current_revision_id is null))
      and record_platform_internal.record_deletion_effect_scope(target,array['core','recovery']) then
      if tg_op='DELETE' then return old; else return new; end if;
    end if;
    perform record_platform_internal.comparison_input_admit();
    if tg_op='DELETE' or (old.current_revision_id is not null and new.current_revision_id is null) then
      perform record_platform_internal.comparison_v1_cleanup_guard(target);
    else
      perform record_platform_internal.record_birth_writer_guard(target);
    end if;
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='INSERT' then
    is_record:=new.object_kind='record'; target:=new.object_id;
  else
    is_record:=old.object_kind='record'; target:=old.object_id;
    if tg_op='UPDATE' and (new.project_id,new.object_kind,new.object_id) is distinct from
      (old.project_id,old.object_kind,old.object_id) and (is_record or new.object_kind='record') then
      raise exception using errcode='55000',message='record epoch identity is immutable';
    end if;
  end if;
  if not is_record then
    if tg_op='DELETE' then return old; else return new; end if;
  end if;
  if tg_op='DELETE' and record_platform_internal.record_deletion_effect_scope(target,array['core','recovery']) then
    return old;
  end if;
  perform record_platform_internal.comparison_input_admit();
  if tg_op='DELETE' then
    perform record_platform_internal.comparison_v1_cleanup_guard(target);
    return old;
  end if;
  if tg_op='UPDATE' then
    perform record_platform_internal.record_birth_writer_guard(target);
    if new.delivery_epoch<>old.delivery_epoch+1 then
      raise exception using errcode='55000',message='record epoch transition unavailable';
    end if;
    return new;
  end if;
  if new.project_id<>'default' or new.delivery_epoch<>0 then
    raise exception using errcode='55000',message='record epoch creation route unavailable';
  end if;
  -- INSERT ... ON CONFLICT DO NOTHING is an existing-scope acquisition, not
  -- a new effect. Pin the existing epoch so it cannot disappear before the
  -- conflict is resolved; any ON CONFLICT UPDATE has its own guarded trigger.
  perform 1 from public.content_delivery_epochs e where e.project_id='default'
    and e.object_kind='record' and e.object_id=target for update nowait;
  if found then return new; end if;
  if exists(select 1 from public.record_deletion_gates g where g.project_id='default' and g.record_id=target)
    or exists(select 1 from public.deletion_reservations r where r.project_id='default' and r.object_kind='record'
      and r.object_id=target and r.state in ('fenced','committed'))
    or exists(select 1 from public.deletion_fence_leases l where l.project_id='default' and l.object_kind='record'
      and l.object_id=target and l.expires_at>clock_timestamp())
    or not (exists(select 1 from public.records r where r.project_id='default' and r.record_id=target)
      or exists(select 1 from record_platform_internal.record_birth_allocations a where a.project_id='default'
        and a.record_id=target and a.state in ('allocated','preparing','prepared','consumed','finished','confirmed'))) then
    raise exception using errcode='55000',message='record epoch creation route unavailable';
  end if;
  if not exists(select 1 from public.records r where r.project_id='default' and r.record_id=target) then
    perform record_platform_internal.record_birth_continuity_validate(
      decode(coalesce(current_setting('houfeng.birth_continuity_proof',true),''),'hex'));
  end if;
  return new;
exception when lock_not_available then
  raise exception using errcode='40001',message='comparison root or epoch busy; restart transaction';
end $$;

create trigger comparison_record_update_guard before update
  on public.records for each row execute function record_platform_internal.comparison_root_epoch_guard();
create trigger comparison_record_delete_guard before delete on public.records
  for each row execute function record_platform_internal.comparison_root_epoch_guard();
create trigger comparison_epoch_insert_delete_guard before insert or delete on public.content_delivery_epochs
  for each row execute function record_platform_internal.comparison_root_epoch_guard();
create trigger comparison_epoch_update_guard before update of project_id,object_kind,object_id,delivery_epoch on public.content_delivery_epochs
  for each row execute function record_platform_internal.comparison_root_epoch_guard();
revoke all on function record_platform_internal.comparison_input_admit(),
  record_platform_internal.comparison_v1_cleanup_guard(text),record_platform_internal.comparison_evidence_row_guard(),
  record_platform_internal.comparison_root_epoch_guard() from public;

-- Export creation and advancement use the persisted job route and recheck the
-- same record scope after admission. Failed staging is an exact late fact; it
-- does not authorize a new export, artifact publication or revived owner.
create function record_platform_internal.record_export_job_write(bytea,text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; fields text[]; job public.record_export_jobs; observed public.record_export_jobs;
  reservation public.deletion_reservations; epoch bigint; expiry timestamptz; created timestamptz;
  updated timestamptz; expected_version bigint; record_version bigint; expected_auth_epoch bigint;
  terminal boolean:=false; reservation_ids text[]:='{}';
begin
  perform record_platform_internal.local_blob_direct_login();
  fields:=array['export_job_id','project_id','actor_id','idempotency_key','export_kind','export_mode',
    'request_fingerprint','inventory_digest','authorization_epoch','record_id','revision_id','expires_at','record_lock_version'];
  if $2='claim' then
    fields:=fields||array['created_at','updated_at'];
  elsif $2='advance' then
    fields:=fields||array['expected_state','expected_lock_version','new_state','failure_code'];
  else
    raise exception using errcode='22023',message='invalid export job command';
  end if;
  v:=record_platform_internal.record_birth_command($1,fields,'{}');
  if v->>'project_id'<>'default' or v->>'export_job_id' !~ '^rej_[a-z0-9]{1,64}$'
    or v->>'actor_id' !~ '^usr_[a-z0-9]{1,64}$' or v->>'idempotency_key' !~ '^[a-z0-9._:-]{1,128}$'
    or v->>'export_kind' not in ('markdown','comparison_json','evidence_json','archive','pdf')
    or v->>'export_mode' not in ('safe','sensitive_topology')
    or v->>'request_fingerprint' !~ '^[0-9a-f]{64}$' or v->>'request_fingerprint'=repeat('0',64)
    or v->>'inventory_digest' !~ '^[0-9a-f]{64}$' or v->>'inventory_digest'=repeat('0',64)
    or v->>'authorization_epoch' !~ '^[1-9][0-9]{0,18}$'
    or (v->>'authorization_epoch')::numeric>9223372036854775807
    or v->>'record_lock_version' !~ '^(0|[1-9][0-9]{0,18})$'
    or (v->>'record_lock_version')::numeric>9223372036854775807
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'revision_id' !~ '^rrv_[a-z0-9]{1,64}$'
    or v->>'expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' then
    raise exception using errcode='22023',message='invalid export job identity';
  end if;
  expected_auth_epoch:=(v->>'authorization_epoch')::bigint;
  record_version:=(v->>'record_lock_version')::bigint;
  expiry:=(v->>'expires_at')::timestamptz;
  if $2='claim' then
    if record_version=0 or v->>'created_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$'
      or v->>'updated_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' then
      raise exception using errcode='22023',message='invalid export job creation';
    end if;
    created:=(v->>'created_at')::timestamptz;
    updated:=(v->>'updated_at')::timestamptz;
  else
    if v->>'expected_lock_version' !~ '^[1-9][0-9]{0,18}$'
      or (v->>'expected_lock_version')::numeric>=9223372036854775807 then
      raise exception using errcode='22023',message='invalid export job version';
    end if;
    expected_version:=(v->>'expected_lock_version')::bigint;
    terminal:=v->>'expected_state'='staging' and v->>'new_state'='failed' and v->>'failure_code'='staging_failed';
    if (terminal and record_version<>0) or (not terminal and (record_version=0 or v->>'failure_code'<>''
      or not ((v->>'expected_state'='previewed' and v->>'new_state'='staging')
        or (v->>'expected_state'='staging' and v->>'new_state'='published')))) then
      raise exception using errcode='22023',message='invalid export job transition';
    end if;
  end if;

  perform record_platform_internal.comparison_input_admit();
  if $2='advance' then
    select * into observed from public.record_export_jobs j where j.export_job_id=v->>'export_job_id';
    if not found or (observed.project_id,observed.actor_id,observed.idempotency_key,observed.export_kind,
        observed.export_mode,observed.request_fingerprint,observed.inventory_digest,observed.authorization_epoch,
        observed.record_id,observed.revision_id,observed.expires_at,observed.job_state,observed.failure_code,observed.lock_version,
        observed.owner_id,observed.owner_generation,observed.lease_expires_at) is distinct from
      (v->>'project_id',v->>'actor_id',v->>'idempotency_key',v->>'export_kind',v->>'export_mode',
        decode(v->>'request_fingerprint','hex'),decode(v->>'inventory_digest','hex'),expected_auth_epoch,
        v->>'record_id',v->>'revision_id',expiry,v->>'expected_state',''::text,expected_version,''::text,0::bigint,null::timestamptz) then
      raise exception using errcode='55000',message='export job route or version unavailable';
    end if;
  end if;
  if terminal then
    -- A late failure does not require the actor, record root or gate to remain
    -- live. It still pins the actual epoch and exact persisted job identity.
    for reservation in select r.* from public.deletion_reservations r where r.project_id='default'
      and r.object_kind='record' and r.object_id=observed.record_id
      order by r.reservation_id collate "C" for update nowait loop
      reservation_ids:=array_append(reservation_ids,reservation.reservation_id);
    end loop;
    select e.delivery_epoch into epoch from public.content_delivery_epochs e where e.project_id='default'
      and e.object_kind='record' and e.object_id=observed.record_id for update nowait;
    if not found or exists(select 1 from public.deletion_reservations r where r.project_id='default'
        and r.object_kind='record' and r.object_id=observed.record_id and not (r.reservation_id=any(reservation_ids))) then
      raise exception using errcode='55000',message='export terminal scope unavailable';
    end if;
    perform 1 from public.deletion_fence_leases l where l.project_id='default' and l.object_kind='record'
      and l.object_id=observed.record_id for update nowait;
    perform 1 from public.object_content_leases l where l.project_id='default' and l.object_kind='record'
      and l.object_id=observed.record_id for update nowait;
    perform 1 from public.record_deletion_gates g where g.project_id='default' and g.record_id=observed.record_id for share nowait;
  else
    perform 1 from public.users u where u.user_id=v->>'actor_id' and u.disabled_at is null
      and u.role='admin' for update nowait;
    if not found then raise exception using errcode='55000',message='export actor unavailable'; end if;
    perform record_platform_internal.record_birth_writer_guard(v->>'record_id');
    perform 1 from public.records r where r.project_id='default' and r.record_id=v->>'record_id'
      and r.current_revision_id is not null and r.authorization_epoch=expected_auth_epoch and r.lock_version=record_version for share nowait;
    if not found then raise exception using errcode='55000',message='export record route unavailable'; end if;
    perform 1 from public.record_revisions r where r.record_id=v->>'record_id' and r.revision_id=v->>'revision_id' for share nowait;
    if not found or expiry<=clock_timestamp() then
      raise exception using errcode='55000',message='export revision or expiry unavailable';
    end if;
  end if;
  if $2='claim' then
    insert into public.record_export_jobs(export_job_id,project_id,actor_id,idempotency_key,export_kind,export_mode,
      job_state,lock_version,request_fingerprint,inventory_digest,authorization_epoch,record_id,revision_id,expires_at,created_at,updated_at)
      values(v->>'export_job_id',v->>'project_id',v->>'actor_id',v->>'idempotency_key',v->>'export_kind',v->>'export_mode',
        'previewed',1,decode(v->>'request_fingerprint','hex'),decode(v->>'inventory_digest','hex'),expected_auth_epoch,
        v->>'record_id',v->>'revision_id',expiry,created,updated);
    return;
  end if;
  select * into job from public.record_export_jobs j where j.export_job_id=observed.export_job_id for update nowait;
  if not found or job is distinct from observed then
    raise exception using errcode='40001',message='export job route changed; restart transaction';
  end if;
  if not terminal and (job.expires_at<=clock_timestamp() or not exists(select 1 from public.users u
      where u.user_id=job.actor_id and u.disabled_at is null and u.role='admin')) then
    raise exception using errcode='55000',message='export job authorization changed';
  end if;
  update public.record_export_jobs set job_state=v->>'new_state',failure_code=v->>'failure_code',
    lock_version=lock_version+1,updated_at=clock_timestamp() where export_job_id=job.export_job_id;
exception when lock_not_available then
  raise exception using errcode='40001',message='export job route busy; restart transaction';
when invalid_datetime_format or datetime_field_overflow then
  raise exception using errcode='22023',message='invalid export job timestamp';
end $$;
create function public.record_export_job_claim(bytea) returns void language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_export_job_write($1,'claim') $$;
create function public.record_export_job_advance(bytea) returns void language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_export_job_write($1,'advance') $$;
revoke all on function record_platform_internal.record_export_job_write(bytea,text),
  public.record_export_job_claim(bytea),public.record_export_job_advance(bytea) from public;

-- Independent record ledger authority is installed only by the constrained
-- management LOGIN after direct primary/full-witness verification. Runtime and
-- workers never receive table mutation or installer privileges.
create table record_platform_internal.record_deletion_verified_entries (
  ledger_domain bytea not null check (octet_length(ledger_domain)=32),
  ledger_sequence bigint not null check (ledger_sequence>0),
  ledger_entry_hash bytea not null check (octet_length(ledger_entry_hash)=32),
  previous_hash bytea not null check (octet_length(previous_hash)=32),
  canonical_entry bytea not null check (octet_length(canonical_entry) between 1 and 65536),
  entry_type text not null check (entry_type in ('delete_commit','attempt_not_committed')),
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  project_id text not null check (project_id='default'),
  operation_id text not null check (operation_id ~ '^rpo_[a-z0-9]{1,64}$'),
  actor_id text not null check (actor_id ~ '^usr_[a-z0-9]{1,64}$'),
  route text not null check (route='record_permanent_delete'),
  object_kind text not null check (object_kind='record'),
  object_id text not null check (object_id ~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'),
  token_commitment bytea not null check (octet_length(token_commitment)=32),
  request_fingerprint bytea not null check (octet_length(request_fingerprint)=32),
  reason_code text not null check (reason_code='user_confirmed'),
  deletion_contract_version bigint not null,
  release_epoch bigint not null,
  confirmed_at_unix_microseconds bigint not null check (confirmed_at_unix_microseconds>0),
  primary_head_sequence bigint not null,
  primary_head_hash bytea not null check (octet_length(primary_head_hash)=32),
  witness_head_sequence bigint not null,
  witness_head_hash bytea not null check (octet_length(witness_head_hash)=32),
  witness_proof_digest bytea not null check (octet_length(witness_proof_digest)=32),
  maintenance_rid text not null,
  maintenance_generation bigint not null check (maintenance_generation>=0),
  primary key (ledger_domain,ledger_sequence),
  unique (deployment_id,project_id,operation_id),
  check (primary_head_sequence>=witness_head_sequence and witness_head_sequence>=ledger_sequence),
  check ((entry_type='delete_commit' and deletion_contract_version=1 and release_epoch=0)
    or (entry_type='attempt_not_committed' and deletion_contract_version=0 and release_epoch>0)),
  check (ledger_entry_hash=record_platform_internal.digest(canonical_entry,'sha256'))
);
create trigger record_deletion_verified_entry_immutable before update or delete
  on record_platform_internal.record_deletion_verified_entries
  for each row execute function record_platform_internal.enforce_client_purge_receipt_immutable();

-- Scopes exist only during an authenticated definer call. They cannot be set
-- through a GUC, a temporary table, a caller boolean or a runtime DML grant.
create table record_platform_internal.record_deletion_effect_scopes (
  transaction_id xid8 not null,
  backend_pid integer not null,
  record_id text not null,
  operation_id text not null,
  authority_kind text not null check (authority_kind in ('online_v1','online_v2','recovery_v1')),
  authority_digest bytea not null check (octet_length(authority_digest)=32),
  effect_kind text not null check (effect_kind in ('core','evidence','attachment','recovery')),
  primary key (transaction_id,backend_pid,record_id,operation_id,effect_kind)
);
create function record_platform_internal.record_deletion_effect_scope(target text, kinds text[])
returns boolean language sql stable security definer set search_path=pg_catalog as $$
  select exists(select 1 from record_platform_internal.record_deletion_effect_scopes s
    where s.transaction_id=pg_current_xact_id() and s.backend_pid=pg_backend_pid()
      and s.record_id=target and s.effect_kind=any(kinds))
$$;

create function record_platform_internal.record_deletion_command(body bytea, fields text[], numbers text[])
returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare raw json;
begin
  if body is null or octet_length(body) not between 1 and 262144 then
    raise exception using errcode='22023',message='invalid record deletion command size';
  end if;
  raw:=convert_from(body,'UTF8')::json;
  if json_typeof(raw) is distinct from 'object'
    or (select count(*) from json_each(raw))<>cardinality(fields)
    or (select count(distinct f.key) from json_each(raw) f)<>cardinality(fields)
    or exists(select 1 from json_each(raw) f where not(f.key=any(fields))
      or case when f.key=any(numbers) then json_typeof(f.value)<>'number' or f.value::text !~ '^(0|[1-9][0-9]*)$'
        else json_typeof(f.value)<>'string' end) then
    raise exception using errcode='22023',message='invalid record deletion command fields';
  end if;
  return raw::jsonb;
end $$;

create function record_platform_internal.record_deletion_canonical(v jsonb)
returns bytea language plpgsql immutable set search_path=pg_catalog as $$
declare material bytea; item text;
begin
  material:=record_platform_internal.source_retirement_field(convert_to('HOUFENG-RECORD-DELETION-V1','UTF8'))
    ||int8send(1::bigint)
    ||record_platform_internal.source_retirement_field(decode(v->>'ledger_domain','hex'))
    ||int8send((v->>'ledger_sequence')::bigint)
    ||record_platform_internal.source_retirement_field(decode(v->>'previous_hash','hex'));
  foreach item in array array['entry_type','deployment_id','project_id','operation_id','actor_id','route','object_kind','object_id'] loop
    material:=material||record_platform_internal.source_retirement_field(convert_to(v->>item,'UTF8'));
  end loop;
  return material
    ||record_platform_internal.source_retirement_field(decode(v->>'token_commitment','hex'))
    ||record_platform_internal.source_retirement_field(decode(v->>'request_fingerprint','hex'))
    ||record_platform_internal.source_retirement_field(convert_to(v->>'reason_code','UTF8'))
    ||int8send((v->>'deletion_contract_version')::bigint)
    ||int8send((v->>'release_epoch')::bigint)
    ||int8send((v->>'confirmed_at_unix_microseconds')::bigint);
end $$;

create function public.record_deletion_verify_legacy_entry(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; existing record_platform_internal.record_deletion_verified_entries;
  admission public.source_authority_admission; item text; material bytea;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='ledger installation requires read committed';
  end if;
  v:=record_platform_internal.record_deletion_command($1,array[
    'ledger_domain','ledger_sequence','ledger_entry_hash','previous_hash','canonical_entry','entry_type',
    'deployment_id','project_id','operation_id','actor_id','route','object_kind','object_id','token_commitment',
    'request_fingerprint','reason_code','deletion_contract_version','release_epoch','confirmed_at_unix_microseconds',
    'primary_head_sequence','primary_head_hash','witness_head_sequence','witness_head_hash','witness_proof_digest',
    'maintenance_rid','maintenance_generation'],array['ledger_sequence','deletion_contract_version','release_epoch',
    'confirmed_at_unix_microseconds','primary_head_sequence','witness_head_sequence','maintenance_generation']);
  foreach item in array array['ledger_domain','ledger_entry_hash','previous_hash','token_commitment',
    'request_fingerprint','primary_head_hash','witness_head_hash','witness_proof_digest'] loop
    if v->>item !~ '^[0-9a-f]{64}$' or (item<>'previous_hash' and v->>item=repeat('0',64)) then
      raise exception using errcode='22023',message='invalid verified entry digest';
    end if;
  end loop;
  if v->>'canonical_entry' !~ '^([0-9a-f]{2})+$'
    or ((v->>'ledger_sequence')::bigint=1)<>(v->>'previous_hash'=repeat('0',64)) then
    raise exception using errcode='22023',message='invalid verified entry canonical identity';
  end if;
  material:=record_platform_internal.record_deletion_canonical(v);
  if material<>decode(v->>'canonical_entry','hex')
    or record_platform_internal.digest(material,'sha256')<>decode(v->>'ledger_entry_hash','hex') then
    raise exception using errcode='22023',message='verified entry canonical projection mismatch';
  end if;
  perform 1 from public.deployment_contract_state d where d.project_id=v->>'project_id'
    and d.deployment_id=v->>'deployment_id' and d.active_profile is not null for share;
  if not found then raise exception using errcode='42501',message='verified entry APP deployment mismatch'; end if;
  select * into admission from public.source_authority_admission where singleton for share;
  if found then
    if admission.deployment_id<>v->>'deployment_id' or not exists(select 1 from public.source_application_principals p
      where p.generation=admission.generation and p.principal=session_user and p.purpose='admin') then
      raise exception using errcode='42501',message='verified entry management admission mismatch';
    end if;
    if v->>'maintenance_rid'='' then
      if admission.mode<>'active' or (v->>'maintenance_generation')::bigint<>0 then
        raise exception using errcode='42501',message='online ledger installation admission unavailable';
      end if;
    elsif admission.mode not in ('closed','ready_closed')
      or admission.recovery_id is distinct from v->>'maintenance_rid'
      or admission.generation<>(v->>'maintenance_generation')::bigint then
      raise exception using errcode='42501',message='recovery ledger installation admission unavailable';
    end if;
  elsif v->>'maintenance_rid'<>'' and (v->>'maintenance_generation')::bigint<>0 then
    raise exception using errcode='42501',message='never-enrolled generation mismatch';
  end if;
  if v->>'maintenance_rid'='' and not exists(select 1 from public.record_purge_operations o
    join public.deletion_reservations r on r.reservation_id=o.reservation_id
    where o.operation_id=v->>'operation_id' and o.deletion_contract_version=1
      and (o.deployment_id,o.project_id,o.actor_id,o.reason_code,r.object_kind,r.object_id)
        =(v->>'deployment_id',v->>'project_id',v->>'actor_id',v->>'reason_code',v->>'object_kind',v->>'object_id')
      and r.deletion_token_commitment=decode(v->>'token_commitment','hex')
      and r.request_fingerprint=decode(v->>'request_fingerprint','hex')) then
    raise exception using errcode='42501',message='legacy operation identity unavailable';
  end if;
  insert into record_platform_internal.record_deletion_verified_entries
    select decode(v->>'ledger_domain','hex'),(v->>'ledger_sequence')::bigint,decode(v->>'ledger_entry_hash','hex'),
      decode(v->>'previous_hash','hex'),material,v->>'entry_type',v->>'deployment_id',v->>'project_id',
      v->>'operation_id',v->>'actor_id',v->>'route',v->>'object_kind',v->>'object_id',
      decode(v->>'token_commitment','hex'),decode(v->>'request_fingerprint','hex'),v->>'reason_code',
      (v->>'deletion_contract_version')::bigint,(v->>'release_epoch')::bigint,(v->>'confirmed_at_unix_microseconds')::bigint,
      (v->>'primary_head_sequence')::bigint,decode(v->>'primary_head_hash','hex'),
      (v->>'witness_head_sequence')::bigint,decode(v->>'witness_head_hash','hex'),decode(v->>'witness_proof_digest','hex'),
      v->>'maintenance_rid',(v->>'maintenance_generation')::bigint
    on conflict (ledger_domain,ledger_sequence) do nothing;
  select * into strict existing from record_platform_internal.record_deletion_verified_entries e
    where e.ledger_domain=decode(v->>'ledger_domain','hex') and e.ledger_sequence=(v->>'ledger_sequence')::bigint;
  if existing.canonical_entry<>material or existing.witness_proof_digest<>decode(v->>'witness_proof_digest','hex')
    or existing.primary_head_sequence>(v->>'primary_head_sequence')::bigint
    or existing.witness_head_sequence>(v->>'witness_head_sequence')::bigint
    or (existing.primary_head_sequence=(v->>'primary_head_sequence')::bigint and existing.primary_head_hash<>decode(v->>'primary_head_hash','hex'))
    or (existing.witness_head_sequence=(v->>'witness_head_sequence')::bigint and existing.witness_head_hash<>decode(v->>'witness_head_hash','hex')) then
    raise exception using errcode='23505',message='verified ledger entry conflict';
  end if;
end $$;

create function public.record_deletion_verified_binding(bytea)
returns table(ledger_domain bytea,witness_proof_digest bytea)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb;
begin
  perform record_platform_internal.local_blob_direct_login();
  perform public.source_application_admit();
  v:=record_platform_internal.record_deletion_command($1,
    array['operation_id','project_id','ledger_sequence','ledger_entry_hash'],array['ledger_sequence']);
  return query select e.ledger_domain,e.witness_proof_digest
    from record_platform_internal.record_deletion_verified_entries e
    where e.operation_id=v->>'operation_id' and e.project_id=v->>'project_id'
      and e.ledger_sequence=(v->>'ledger_sequence')::bigint
      and e.ledger_entry_hash=decode(v->>'ledger_entry_hash','hex') and e.entry_type='delete_commit';
end $$;
revoke all on table record_platform_internal.record_deletion_verified_entries,
  record_platform_internal.record_deletion_effect_scopes from public;
revoke all on function record_platform_internal.record_deletion_effect_scope(text,text[]),
  record_platform_internal.record_deletion_command(bytea,text[],text[]),
  record_platform_internal.record_deletion_canonical(jsonb),
  public.record_deletion_verify_legacy_entry(bytea),public.record_deletion_verified_binding(bytea) from public;

create function record_platform_internal.record_core_surface_digest()
returns bytea language plpgsql immutable set search_path=pg_catalog as $$
declare body bytea; item text;
begin
  body:=record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.adapter-surfaces.v1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to('record_core','UTF8'))||int8send(10::bigint);
  foreach item in array array['content_delivery_epochs','record_core_purge_receipts','record_domain_activities',
    'record_draft_checkpoints','record_drafts','record_revision_participants','record_revision_subjects',
    'record_revision_tags','record_revisions','records'] loop
    body:=body||record_platform_internal.client_purge_field(convert_to(item,'UTF8'));
  end loop;
  return record_platform_internal.digest(body,'sha256');
end $$;

create function record_platform_internal.record_core_purge_effects(op text, target text, project text, verify_only boolean)
returns public.record_core_purge_receipts language plpgsql security definer set search_path=pg_catalog as $$
declare receipt public.record_core_purge_receipts; present boolean; removed bigint:=0; affected bigint;
  surface bytea:=record_platform_internal.record_core_surface_digest(); expected bytea;
begin
  if not record_platform_internal.record_deletion_effect_scope(target,array['core','recovery'])
    or not exists(select 1 from record_platform_internal.record_deletion_effect_scopes s
      where s.transaction_id=pg_current_xact_id() and s.backend_pid=pg_backend_pid()
        and s.record_id=target and s.operation_id=op and s.effect_kind in ('core','recovery')) then
    raise exception using errcode='42501',message='core purge transaction authority unavailable';
  end if;
  select * into receipt from public.record_core_purge_receipts r where r.operation_id=op for update;
  if not found then
    if verify_only then raise exception using errcode='55000',message='core receipt unavailable'; end if;
    update public.records set current_revision_id=null,current_title=null,current_record_type=null,
      current_business_status=null,current_status_group=null,current_impact_level=null,current_occurred_at=null,
      current_completed_at=null,current_visibility_scope=null,current_visibility_digest=null,current_owner_id=null,
      current_follow_up_at=null,updated_at=clock_timestamp() where record_id=target and project_id=project;
    get diagnostics affected=row_count;
    if affected<>1 and exists(select 1 from record_platform_internal.record_deletion_effect_scopes s
      where s.transaction_id=pg_current_xact_id() and s.backend_pid=pg_backend_pid()
        and s.operation_id=op and s.record_id=target and s.authority_kind in ('online_v1','online_v2')) then
      raise exception using errcode='55000',message='online core root unavailable without receipt';
    end if;
    delete from public.record_draft_checkpoints where draft_id in(select draft_id from public.record_drafts where record_id=target);
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_drafts where record_id=target;
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_domain_activities where record_id=target;
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_revision_participants where revision_id in(select revision_id from public.record_revisions where record_id=target);
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_revision_tags where revision_id in(select revision_id from public.record_revisions where record_id=target);
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_revision_subjects where revision_id in(select revision_id from public.record_revisions where record_id=target);
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.record_revisions where record_id=target;
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.records where record_id=target and project_id=project;
    get diagnostics affected=row_count; removed:=removed+affected;
    delete from public.content_delivery_epochs where project_id=project and object_kind='record' and object_id=target;
    get diagnostics affected=row_count; removed:=removed+affected;
    expected:=record_platform_internal.digest(
      record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.core-purge-receipt.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||surface||int8send(removed),'sha256');
    insert into public.record_core_purge_receipts(operation_id,adapter_name,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
      values(op,'record_core',surface,expected,removed,clock_timestamp()) returning * into receipt;
  end if;
  select exists(select 1 from public.records where record_id=target
    union all select 1 from public.record_revisions where record_id=target
    union all select 1 from public.record_revision_participants p join public.record_revisions r using(revision_id) where r.record_id=target
    union all select 1 from public.record_revision_tags p join public.record_revisions r using(revision_id) where r.record_id=target
    union all select 1 from public.record_revision_subjects p join public.record_revisions r using(revision_id) where r.record_id=target
    union all select 1 from public.record_drafts where record_id=target
    union all select 1 from public.record_draft_checkpoints c join public.record_drafts d using(draft_id) where d.record_id=target
    union all select 1 from public.record_domain_activities where record_id=target
    union all select 1 from public.content_delivery_epochs where project_id=project and object_kind='record' and object_id=target) into present;
  expected:=record_platform_internal.digest(
    record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.core-purge-receipt.v1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))
    ||surface||int8send(receipt.removed_row_count),'sha256');
  if present or receipt.adapter_name<>'record_core' or receipt.removed_surface_digest<>surface
    or receipt.receipt_digest<>expected then
    raise exception using errcode='55000',message='core purge absence or receipt mismatch';
  end if;
  return receipt;
end $$;

create function record_platform_internal.record_core_purge(bytea, bigint, boolean)
returns public.record_core_purge_receipts language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; fields text[]; numbers text[]; reservation public.deletion_reservations;
  operation public.record_purge_operations; gate public.record_deletion_gates; fence public.deletion_fence_leases;
  entry record_platform_internal.record_deletion_verified_entries; receipt public.record_core_purge_receipts;
  epoch bigint; authority bytea; expiry timestamptz; discovered text;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='core purge requires read committed';
  end if;
  perform public.source_application_admit();
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  fields:=array['operation_id','record_id','reservation_id','fence_epoch','owner_id','owner_generation','owner_expires_at','surface_digest'];
  numbers:=array['fence_epoch','owner_generation'];
  if $2=1 then
    fields:=fields||array['ledger_domain','ledger_sequence','ledger_entry_hash','witness_proof_digest'];
    numbers:=numbers||array['ledger_sequence'];
  elsif $2<>2 then raise exception using errcode='22023',message='unsupported core purge version'; end if;
  v:=record_platform_internal.record_deletion_command($1,fields,numbers);
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or (v->>'owner_generation')::bigint<1
    or (v->>'fence_epoch')::bigint<1 or v->>'surface_digest' !~ '^[0-9a-f]{64}$'
    or v->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or decode(v->>'surface_digest','hex')<>record_platform_internal.record_core_surface_digest() then
    raise exception using errcode='22023',message='invalid core purge identity';
  end if;
  expiry:=(v->>'owner_expires_at')::timestamptz;
  select o.reservation_id into strict discovered from public.record_purge_operations o where o.operation_id=v->>'operation_id';
  select r.* into strict reservation from public.deletion_reservations r where r.reservation_id=discovered for update;
  if reservation.reservation_id<>v->>'reservation_id' or reservation.project_id<>'default'
    or reservation.object_kind<>'record' or reservation.object_id<>v->>'record_id'
    or reservation.deletion_contract_version<>$2 or reservation.fence_epoch<>(v->>'fence_epoch')::bigint
    or reservation.state not in ('fenced','committed') or ($2=1 and reservation.state<>'committed') then
    raise exception using errcode='42501',message='core purge reservation mismatch';
  end if;
  if exists(select 1 from public.deletion_reservations other
    where other.project_id=reservation.project_id and other.object_kind=reservation.object_kind
      and other.object_id=reservation.object_id and other.reservation_id<>reservation.reservation_id
      and other.state in ('fenced','committed')) then
    raise exception using errcode='42501',message='core purge conflicts with another reservation';
  end if;
  select e.delivery_epoch into epoch from public.content_delivery_epochs e where e.project_id=reservation.project_id
    and e.object_kind='record' and e.object_id=reservation.object_id for update;
  if found and epoch<>reservation.fence_epoch then
    raise exception using errcode='42501',message='core purge epoch mismatch';
  end if;
  select l.* into fence from public.deletion_fence_leases l where l.project_id=reservation.project_id
    and l.object_kind='record' and l.object_id=reservation.object_id for update;
  select g.* into gate from public.record_deletion_gates g
    where g.project_id=reservation.project_id and g.record_id=reservation.object_id for share;
  if $2=2 then
    if not found or (gate.operation_id,gate.record_id,gate.project_id,gate.fence_epoch)
      is distinct from (v->>'operation_id',reservation.object_id,reservation.project_id,reservation.fence_epoch) then
      raise exception using errcode='42501',message='core purge gate unavailable';
    end if;
    authority:=gate.binding_digest;
  elsif found then raise exception using errcode='42501',message='V2 gate cannot authorize legacy purge'; end if;
  select o.* into strict operation from public.record_purge_operations o where o.operation_id=v->>'operation_id' for update;
  if operation.reservation_id<>reservation.reservation_id or operation.project_id<>reservation.project_id
    or operation.deletion_contract_version<>$2 or operation.operation_state<>'online_purging'
    or (operation.owner_id,operation.owner_generation,operation.owner_expires_at)
      is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry) or expiry<=clock_timestamp() then
    raise exception using errcode='42501',message='core purge caller owner unavailable';
  end if;
  if $2=2 and (reservation.state<>'fenced'
      or (reservation.owner_id,reservation.owner_generation,reservation.owner_expires_at)
        is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
      or (fence.owner_id,fence.owner_generation,fence.expires_at)
        is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
      or (gate.binding_digest,gate.request_fingerprint,gate.actor_scope_digest,gate.actor_id)
        is distinct from (reservation.preview_binding_digest,reservation.request_fingerprint,reservation.actor_scope_digest,operation.actor_id)) then
    raise exception using errcode='42501',message='deletion owner lease lost';
  end if;
  if $2=1 then
    select e.* into strict entry from record_platform_internal.record_deletion_verified_entries e
      where e.ledger_domain=decode(v->>'ledger_domain','hex') and e.ledger_sequence=(v->>'ledger_sequence')::bigint
        and e.ledger_entry_hash=decode(v->>'ledger_entry_hash','hex') and e.witness_proof_digest=decode(v->>'witness_proof_digest','hex');
    if entry.entry_type<>'delete_commit' or entry.deletion_contract_version<>1
      or (entry.operation_id,entry.deployment_id,entry.project_id,entry.actor_id,entry.reason_code,entry.object_kind,entry.object_id)
        is distinct from (operation.operation_id,operation.deployment_id,operation.project_id,operation.actor_id,operation.reason_code,reservation.object_kind,reservation.object_id)
      or (entry.token_commitment,entry.request_fingerprint) is distinct from (reservation.deletion_token_commitment,reservation.request_fingerprint)
      or (entry.ledger_sequence,entry.ledger_entry_hash,entry.witness_proof_digest,entry.entry_type)
        is distinct from (operation.ledger_sequence,operation.ledger_entry_hash,operation.witness_proof_digest,operation.ledger_entry_type) then
      raise exception using errcode='42501',message='core purge verified ledger identity mismatch';
    end if;
    authority:=entry.ledger_entry_hash;
  end if;
  perform 1 from public.records r where r.project_id=reservation.project_id and r.record_id=reservation.object_id for update;
  if $2=2 and not $3 then
    -- Resolve routes while drafts and other original owners still exist.
    -- Completed obligations retain their operation after those rows disappear;
    -- a shared live archive remains with its other owner instead.
    perform 1 from public.attachment_quota_accounts q where q.project_id=reservation.project_id for update;
    lock table public.blob_objects in share row exclusive mode;
    lock table public.attachment_upload_parts in share row exclusive mode;
    lock table public.record_write_obligations,public.record_write_obligation_targets,
      public.blob_gc_deletions,public.attachment_purge_preparations,public.attachment_purge_targets,
      public.attachment_purge_workspace_targets,public.record_portability_cleanup_preparations,
      public.record_portability_cleanup_targets in share row exclusive mode;
    if not record_platform_internal.record_deletion_responsibilities_v2(operation.operation_id,reservation.project_id,reservation.object_id) then
      raise exception using errcode='55000',message='record purge responsibility remains outstanding';
    end if;
    update public.record_write_obligations w set operation_id=operation.operation_id,handed_off_at=coalesce(w.handed_off_at,clock_timestamp())
      where w.project_id=reservation.project_id and w.operation_id is null and w.cleanup_completed_at is not null
        and (w.record_id=reservation.object_id
          or exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=w.obligation_id and t.record_id=reservation.object_id)
          or (w.origin_kind in ('upload','processor_preview') and exists(select 1 from public.record_drafts d
            where d.record_id=reservation.object_id and d.draft_id=(convert_from(w.registration_command,'UTF8')::jsonb)->>'draft_id'))
          or (w.origin_kind='upload' and exists(select 1 from public.attachment_uploads u
            join public.record_attachments a on a.attachment_id=u.attachment_id left join public.record_drafts d on d.draft_id=a.draft_id
            where u.upload_id=w.origin_id and (a.record_id=reservation.object_id or d.record_id=reservation.object_id)))
          or (w.origin_kind='processor_preview' and exists(select 1 from public.attachment_processor_jobs j
            join public.record_attachments a on a.attachment_id=j.attachment_id left join public.record_drafts d on d.draft_id=a.draft_id
            where j.processor_job_id=w.origin_id and (a.record_id=reservation.object_id or d.record_id=reservation.object_id)))
          or (w.origin_kind='export_artifact' and exists(select 1 from public.record_export_jobs j
            where j.export_job_id=w.origin_id and j.record_id=reservation.object_id))
          or (w.origin_kind in ('import_archive','import_attachment') and exists(select 1 from public.record_import_plans p
            join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
            where p.import_job_id=w.origin_id and m.entity_kind='record' and m.target_id=reservation.object_id)));
  end if;
  if expiry<=clock_timestamp() then raise exception using errcode='42501',message='core purge owner expired after locks'; end if;
  insert into record_platform_internal.record_deletion_effect_scopes values(pg_current_xact_id(),pg_backend_pid(),
    reservation.object_id,operation.operation_id,case when $2=1 then 'online_v1' else 'online_v2' end,authority,'core');
  receipt:=record_platform_internal.record_core_purge_effects(operation.operation_id,reservation.object_id,reservation.project_id,$3);
  if $2=1 and not exists(select 1 from public.record_purge_operations o where o.operation_id=operation.operation_id
    and o.owner_id=v->>'owner_id' and o.owner_generation=(v->>'owner_generation')::bigint
    and o.owner_expires_at=expiry and o.owner_expires_at>clock_timestamp() and o.operation_state='online_purging') then
    raise exception using errcode='42501',message='core purge owner expired before receipt completion';
  end if;
  delete from record_platform_internal.record_deletion_effect_scopes s where s.transaction_id=pg_current_xact_id()
    and s.backend_pid=pg_backend_pid() and s.operation_id=operation.operation_id and s.effect_kind='core';
  if $2=1 then
    perform record_platform_internal.record_deletion_queue_owner_commit_check(
      operation.operation_id,v->>'owner_id',(v->>'owner_generation')::bigint,expiry);
  else
    perform record_platform_internal.local_blob_cleanup_operation(operation.operation_id,v->>'owner_id',
      (v->>'owner_generation')::bigint,expiry,v->>'record_id');
  end if;
  return receipt;
end $$;
create function public.record_core_purge_v1(bytea)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
    from record_platform_internal.record_core_purge($1,1,false) r $$;
create function public.record_core_purge_verify_v1(bytea)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
    from record_platform_internal.record_core_purge($1,1,true) r $$;
create function public.record_core_purge_v2(bytea)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
    from record_platform_internal.record_core_purge($1,2,false) r $$;
create function public.record_core_purge_verify_v2(bytea)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
    from record_platform_internal.record_core_purge($1,2,true) r $$;
revoke all on function record_platform_internal.record_core_surface_digest(),
  record_platform_internal.record_core_purge_effects(text,text,text,boolean),
  record_platform_internal.record_core_purge(bytea,bigint,boolean),public.record_core_purge_v1(bytea),
  public.record_core_purge_verify_v1(bytea),public.record_core_purge_v2(bytea),public.record_core_purge_verify_v2(bytea) from public;

create table record_platform_internal.record_deletion_recovery_sessions (
  transaction_id xid8 not null,
  backend_pid integer not null,
  ledger_domain bytea not null,
  ledger_sequence bigint not null,
  ledger_entry_hash bytea not null,
  deployment_id text not null,
  maintenance_rid text not null check (maintenance_rid<>''),
  maintenance_generation bigint not null check (maintenance_generation>=0),
  primary key(transaction_id,backend_pid),
  foreign key(ledger_domain,ledger_sequence)
    references record_platform_internal.record_deletion_verified_entries(ledger_domain,ledger_sequence)
);

create function record_platform_internal.record_deletion_management_admit(deployment text, rid text, generation bigint)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare admission public.source_authority_admission;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='deletion management requires read committed';
  end if;
  perform 1 from public.deployment_contract_state d where d.project_id='default'
    and d.deployment_id=deployment and d.active_profile is not null for share;
  if not found then raise exception using errcode='42501',message='recovery APP deployment mismatch'; end if;
  select * into admission from public.source_authority_admission where singleton for share;
  if found then
    if admission.deployment_id<>deployment or not exists(select 1 from public.source_application_principals p
      where p.generation=admission.generation and p.principal=session_user and p.purpose='admin') then
      raise exception using errcode='42501',message='deletion management principal mismatch';
    end if;
    if rid='' then
      if admission.mode<>'active' or generation<>0 then
        raise exception using errcode='42501',message='online deletion management unavailable';
      end if;
    elsif admission.mode not in ('closed','ready_closed') or admission.recovery_id is distinct from rid
      or admission.generation<>generation then
      raise exception using errcode='42501',message='deletion recovery management unavailable';
    end if;
  elsif generation<>0 then
    raise exception using errcode='42501',message='never-enrolled deletion generation mismatch';
  end if;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
end $$;

create function public.record_deletion_legacy_identity(bytea)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; discovered text; reservation public.deletion_reservations; operation public.record_purge_operations;
begin
  v:=record_platform_internal.record_deletion_command($1,
    array['deployment_id','project_id','operation_id','maintenance_rid','maintenance_generation'],array['maintenance_generation']);
  perform record_platform_internal.record_deletion_management_admit(v->>'deployment_id',v->>'maintenance_rid',
    (v->>'maintenance_generation')::bigint);
  select o.reservation_id into strict discovered from public.record_purge_operations o where o.operation_id=v->>'operation_id';
  select r.* into strict reservation from public.deletion_reservations r where r.reservation_id=discovered for share;
  select o.* into strict operation from public.record_purge_operations o where o.operation_id=v->>'operation_id' for share;
  if operation.deletion_contract_version<>1 or reservation.deletion_contract_version<>1
    or operation.deployment_id<>v->>'deployment_id' or operation.project_id<>v->>'project_id'
    or reservation.project_id<>operation.project_id or operation.reservation_id<>reservation.reservation_id
    or reservation.object_kind<>'record' then
    raise exception using errcode='42501',message='legacy operation identity mismatch';
  end if;
  return jsonb_build_object('deployment_id',operation.deployment_id,'project_id',operation.project_id,
    'operation_id',operation.operation_id,'actor_id',operation.actor_id,'reason_code',operation.reason_code,
    'deletion_contract_version',operation.deletion_contract_version,'operation_state',operation.operation_state,
    'ledger_entry_type',coalesce(operation.ledger_entry_type,''),'ledger_sequence',coalesce(operation.ledger_sequence,0),
    'ledger_entry_hash',coalesce(encode(operation.ledger_entry_hash,'hex'),''),'release_epoch',coalesce(operation.release_epoch,0),
    'object_kind',reservation.object_kind,'object_id',reservation.object_id,
    'token_commitment',encode(reservation.deletion_token_commitment,'hex'),'request_fingerprint',encode(reservation.request_fingerprint,'hex'));
end $$;

create function public.record_deletion_recovery_begin(bytea)
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; entry record_platform_internal.record_deletion_verified_entries;
begin
  v:=record_platform_internal.record_deletion_command($1,
    array['ledger_domain','ledger_sequence','ledger_entry_hash','maintenance_rid','maintenance_generation'],
    array['ledger_sequence','maintenance_generation']);
  if v->>'maintenance_rid'='' then raise exception using errcode='42501',message='explicit recovery identity required'; end if;
  select * into strict entry from record_platform_internal.record_deletion_verified_entries e
    where e.ledger_domain=decode(v->>'ledger_domain','hex') and e.ledger_sequence=(v->>'ledger_sequence')::bigint
      and e.ledger_entry_hash=decode(v->>'ledger_entry_hash','hex');
  perform record_platform_internal.record_deletion_management_admit(entry.deployment_id,v->>'maintenance_rid',
    (v->>'maintenance_generation')::bigint);
  insert into record_platform_internal.record_deletion_recovery_sessions
    values(pg_current_xact_id(),pg_backend_pid(),entry.ledger_domain,entry.ledger_sequence,entry.ledger_entry_hash,
      entry.deployment_id,v->>'maintenance_rid',(v->>'maintenance_generation')::bigint);
end $$;
revoke all on table record_platform_internal.record_deletion_recovery_sessions from public;
revoke all on function record_platform_internal.record_deletion_management_admit(text,text,bigint),
  public.record_deletion_legacy_identity(bytea),public.record_deletion_recovery_begin(bytea) from public;

-- Candidate discovery is only a hint; mutation happens after ordered locks
-- and revalidation in the same statement.
create function public.record_deletion_claim_v1(bytea)
returns table (
  operation_id text, reservation_id text, project_id text, operation_state text,
  deployment_id text, actor_id text, reason_code text, deletion_contract_version bigint,
  ledger_entry_type text, ledger_sequence bigint, ledger_entry_hash bytea, release_epoch bigint,
  receipt_digest bytea, retry_from text, owner_id text, owner_generation bigint, owner_expires_at timestamptz,
  reservation_state text, object_kind text, object_id text, deletion_token_commitment bytea,
  request_fingerprint bytea, fence_epoch bigint, reservation_owner_id text,
  reservation_owner_generation bigint, reservation_owner_expires_at timestamptz, observed_at timestamptz
) language plpgsql security definer set search_path=pg_catalog as $$
declare
  v jsonb; candidate text; discovered_reservation text;
  r public.deletion_reservations; o public.record_purge_operations; f public.deletion_fence_leases;
  admission public.source_authority_admission; epoch bigint; compound boolean;
  claimed_at timestamptz; new_expiry timestamptz; new_generation bigint; micros bigint;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception using errcode='25000',message='legacy deletion claim requires read committed';
  end if;
  perform public.source_application_admit();
  select s.* into admission from public.source_authority_admission s where s.singleton for share;
  if found and (admission.mode <> 'active' or not exists (
      select 1 from public.source_application_principals p where p.principal=session_user
        and p.generation=admission.generation and p.purpose='worker')) then
    raise exception using errcode='42501',message='legacy deletion worker admission unavailable';
  end if;
  v:=record_platform_internal.record_deletion_command($1,array['owner_id','owner_lease_microseconds'],array['owner_lease_microseconds']);
  micros:=(v->>'owner_lease_microseconds')::bigint;
  if v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or micros<1 or micros>9223372036854775 then
    raise exception using errcode='22023',message='invalid legacy claim';
  end if;
  select op.operation_id,op.reservation_id into candidate,discovered_reservation
  from public.record_purge_operations op join public.deletion_reservations res
    on res.reservation_id=op.reservation_id and res.project_id=op.project_id
  where op.deletion_contract_version=1 and res.deletion_contract_version=1
    and op.operation_state not in ('online_purged','not_committed')
    and (op.owner_id=v->>'owner_id' or op.owner_expires_at<=clock_timestamp())
    and (op.operation_state<>'provisional_fenced' or not exists (
      select 1 from public.object_content_leases l where l.project_id=res.project_id
        and l.object_kind=res.object_kind and l.object_id=res.object_id and l.expires_at>clock_timestamp()))
  order by op.started_at,op.operation_id limit 1;
  if candidate is null then return; end if;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select res.* into r from public.deletion_reservations res where res.reservation_id=discovered_reservation for update;
  if not found then raise exception using errcode='40001',message='legacy claim reservation changed'; end if;
  select e.delivery_epoch into epoch from public.content_delivery_epochs e
    where e.project_id=r.project_id and e.object_kind=r.object_kind and e.object_id=r.object_id for update;
  if found and epoch<>r.fence_epoch then raise exception using errcode='40001',message='legacy claim epoch changed'; end if;
  select l.* into f from public.deletion_fence_leases l
    where l.project_id=r.project_id and l.object_kind=r.object_kind and l.object_id=r.object_id for update;
  select op.* into o from public.record_purge_operations op where op.operation_id=candidate for update;
  if not found or o.reservation_id<>r.reservation_id or o.project_id<>r.project_id
    or o.deletion_contract_version<>1 or r.deletion_contract_version<>1
    or o.operation_state in ('online_purged','not_committed') or r.object_kind<>'record' then
    raise exception using errcode='40001',message='legacy claim candidate changed';
  end if;
  claimed_at:=clock_timestamp();
  if o.owner_id<>v->>'owner_id' and o.owner_expires_at>claimed_at then
    raise exception using errcode='40001',message='legacy claim owner changed';
  end if;
  if o.operation_state='provisional_fenced' and exists (
      select 1 from public.object_content_leases l where l.project_id=r.project_id
        and l.object_kind=r.object_kind and l.object_id=r.object_id and l.expires_at>claimed_at) then
    raise exception using errcode='40001',message='legacy content lease is live';
  end if;
  compound:=o.operation_state in ('provisional_fenced','ledger_commit_unknown','witness_pending','delete_requested','release_pending')
    or (o.operation_state='retry_required' and o.retry_from='promote_permanent_fence');
  if (compound and (r.state<>'fenced' or (r.owner_id,r.owner_generation,r.owner_expires_at)
      is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at) or
      (f.owner_id,f.owner_generation,f.expires_at) is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at)))
    or (not compound and r.state<>'committed') then
    raise exception using errcode='42501',message='legacy claim fence unavailable';
  end if;
  if o.owner_generation<1 or (o.owner_generation=9223372036854775807
      and (o.owner_id<>v->>'owner_id' or o.owner_expires_at<=claimed_at)) then
    raise exception using errcode='55000',message='legacy claim generation exhausted';
  end if;
  new_generation:=o.owner_generation+case when o.owner_id<>v->>'owner_id' or o.owner_expires_at<=claimed_at then 1 else 0 end;
  new_expiry:=claimed_at+(micros*interval '1 microsecond');
  if compound then
    update public.deletion_reservations x set owner_id=v->>'owner_id',owner_generation=new_generation,owner_expires_at=new_expiry
      where x.reservation_id=r.reservation_id returning x.* into r;
    update public.deletion_fence_leases x set owner_id=v->>'owner_id',owner_generation=new_generation,expires_at=new_expiry
      where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id;
  end if;
  update public.record_purge_operations x set owner_id=v->>'owner_id',owner_generation=new_generation,
    owner_expires_at=new_expiry,updated_at=claimed_at where x.operation_id=o.operation_id returning x.* into o;
  if new_expiry<=clock_timestamp() then raise exception using errcode='42501',message='legacy claim expired before commit'; end if;
  return query select o.operation_id,o.reservation_id,o.project_id,o.operation_state,o.deployment_id,o.actor_id,o.reason_code,
    o.deletion_contract_version,coalesce(o.ledger_entry_type,''),coalesce(o.ledger_sequence,0),coalesce(o.ledger_entry_hash,''::bytea),
    o.release_epoch,coalesce(o.receipt_digest,''::bytea),coalesce(o.retry_from,''),o.owner_id,o.owner_generation,o.owner_expires_at,
    r.state,r.object_kind,r.object_id,r.deletion_token_commitment,r.request_fingerprint,r.fence_epoch,
    r.owner_id,r.owner_generation,r.owner_expires_at,claimed_at;
end $$;
revoke all on function public.record_deletion_claim_v1(bytea) from public;

create function record_platform_internal.record_deletion_worker_admit_v2()
returns void language plpgsql security definer set search_path=pg_catalog as $$
declare admission public.source_authority_admission;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='V2 deletion requires read committed';
  end if;
  perform public.source_application_admit();
  select s.* into admission from public.source_authority_admission s where s.singleton for share;
  if found and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=admission.generation and p.purpose='worker')) then
    raise exception using errcode='42501',message='V2 deletion worker admission unavailable';
  end if;
end $$;

create function public.record_deletion_claim_v2(bytea)
returns table(operation_id text,reservation_id text,project_id text,operation_state text,record_id text,
  fence_epoch bigint,deployment_id text,actor_id text,reason_code text,deletion_contract_version bigint,
  owner_id text,owner_generation bigint,owner_expires_at timestamptz,
  reservation_owner_id text,reservation_owner_generation bigint,reservation_owner_expires_at timestamptz,
  fence_owner_id text,fence_owner_generation bigint,fence_expires_at timestamptz,observed_at timestamptz)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; c record; r public.deletion_reservations; o public.record_purge_operations;
  f public.deletion_fence_leases; g public.record_deletion_gates; epoch bigint;
  now_at timestamptz; expires timestamptz; generation bigint; micros bigint;
begin
  perform record_platform_internal.record_deletion_worker_admit_v2();
  v:=record_platform_internal.record_deletion_command($1,array['owner_id','owner_lease_microseconds'],array['owner_lease_microseconds']);
  micros:=(v->>'owner_lease_microseconds')::bigint;
  if v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or micros<1000 or micros>86400000000 then
    raise exception using errcode='22023',message='invalid V2 deletion claim';
  end if;
  for c in select x.operation_id,x.reservation_id from public.record_purge_operations x
    where x.deletion_contract_version=2 and x.operation_state='online_purging'
      and x.owner_expires_at<=clock_timestamp()
    order by x.started_at,x.operation_id collate "C"
  loop
    perform pg_advisory_xact_lock_shared(1213154899,1);
    perform pg_advisory_xact_lock(1213154899,81);
    select x.* into r from public.deletion_reservations x where x.reservation_id=c.reservation_id for update;
    if not found then continue; end if;
    epoch:=null;
    select x.delivery_epoch into epoch from public.content_delivery_epochs x
      where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
    select x.* into f from public.deletion_fence_leases x
      where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
    if not found then continue; end if;
    select x.* into g from public.record_deletion_gates x
      where x.project_id=r.project_id and x.record_id=r.object_id for share;
    if not found then continue; end if;
    select x.* into o from public.record_purge_operations x where x.operation_id=c.operation_id for update;
    if not found then continue; end if;
    perform 1 from public.records x where x.project_id=r.project_id and x.record_id=r.object_id for update;
    if found and epoch is null then continue; end if;
    now_at:=clock_timestamp();
    if r.deletion_contract_version<>2 or r.state<>'fenced' or r.object_kind<>'record'
      or (epoch is not null and epoch<>r.fence_epoch)
      or (o.reservation_id,o.project_id,o.deletion_contract_version,o.operation_state)
        is distinct from (r.reservation_id,r.project_id,2::bigint,'online_purging')
      or (g.operation_id,g.project_id,g.record_id,g.fence_epoch,g.binding_digest,g.request_fingerprint,g.actor_scope_digest,g.actor_id)
        is distinct from (o.operation_id,r.project_id,r.object_id,r.fence_epoch,r.preview_binding_digest,r.request_fingerprint,r.actor_scope_digest,o.actor_id)
      or (r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at)
      or (f.owner_id,f.owner_generation,f.expires_at) is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at)
      or o.owner_expires_at is null or o.owner_expires_at>now_at then continue; end if;
    generation:=greatest(r.owner_generation,o.owner_generation,f.owner_generation);
    if generation=9223372036854775807 then raise exception using errcode='22003',message='deletion owner generation exhausted'; end if;
    generation:=generation+1; expires:=now_at+micros*interval '1 microsecond';
    update public.deletion_reservations x set owner_id=v->>'owner_id',owner_generation=generation,owner_expires_at=expires
      where x.reservation_id=r.reservation_id returning x.* into r;
    update public.deletion_fence_leases x set owner_id=v->>'owner_id',owner_generation=generation,expires_at=expires
      where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id returning x.* into f;
    update public.record_purge_operations x set owner_id=v->>'owner_id',owner_generation=generation,owner_expires_at=expires,updated_at=now_at
      where x.operation_id=o.operation_id returning x.* into o;
    perform record_platform_internal.local_blob_cleanup_operation(o.operation_id,v->>'owner_id',generation,expires,r.object_id);
    return query select o.operation_id,o.reservation_id,o.project_id,o.operation_state,r.object_id,r.fence_epoch,
      o.deployment_id,o.actor_id,o.reason_code,o.deletion_contract_version,o.owner_id,o.owner_generation,o.owner_expires_at,
      r.owner_id,r.owner_generation,r.owner_expires_at,f.owner_id,f.owner_generation,f.expires_at,now_at;
    return;
  end loop;
end $$;
revoke all on function record_platform_internal.record_deletion_worker_admit_v2(),public.record_deletion_claim_v2(bytea) from public;

create function public.record_deletion_renew_v2(bytea)
returns table(owner_id text,owner_generation bigint,owner_expires_at timestamptz,observed_at timestamptz)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; r public.deletion_reservations; o public.record_purge_operations;
  f public.deletion_fence_leases; g public.record_deletion_gates; epoch bigint;
  old_expiry timestamptz; new_expiry timestamptz; now_at timestamptz; micros bigint;
begin
  perform record_platform_internal.record_deletion_worker_admit_v2();
  v:=record_platform_internal.record_deletion_command($1,
    array['operation_id','reservation_id','record_id','fence_epoch','owner_id','owner_generation','observed_owner_expires_at','owner_lease_microseconds'],
    array['fence_epoch','owner_generation','owner_lease_microseconds']);
  micros:=(v->>'owner_lease_microseconds')::bigint;
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or (v->>'owner_generation')::bigint<1
    or (v->>'fence_epoch')::bigint<1 or micros<1000 or micros>86400000000
    or v->>'observed_owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception using errcode='22023',message='invalid V2 deletion renewal';
  end if;
  old_expiry:=(v->>'observed_owner_expires_at')::timestamptz;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select x.* into r from public.deletion_reservations x where x.reservation_id=v->>'reservation_id' for update;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  select x.delivery_epoch into epoch from public.content_delivery_epochs x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  select x.* into f from public.deletion_fence_leases x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  select x.* into g from public.record_deletion_gates x where x.project_id=r.project_id and x.record_id=r.object_id for share;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  select x.* into o from public.record_purge_operations x where x.operation_id=v->>'operation_id' for update;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  perform 1 from public.records x where x.project_id=r.project_id and x.record_id=r.object_id for update;
  if found and epoch is null then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  now_at:=clock_timestamp();
  if (r.deletion_contract_version,r.state,r.object_kind,r.object_id,r.fence_epoch)
      is distinct from (2::bigint,'fenced','record',v->>'record_id',(v->>'fence_epoch')::bigint)
    or (epoch is not null and epoch<>r.fence_epoch)
    or (o.reservation_id,o.project_id,o.deletion_contract_version,o.operation_state)
      is distinct from (r.reservation_id,r.project_id,2::bigint,'online_purging')
    or (g.operation_id,g.project_id,g.record_id,g.fence_epoch,g.binding_digest,g.request_fingerprint,g.actor_scope_digest,g.actor_id)
      is distinct from (o.operation_id,r.project_id,r.object_id,r.fence_epoch,r.preview_binding_digest,r.request_fingerprint,r.actor_scope_digest,o.actor_id)
    or (r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,old_expiry)
    or (o.owner_id,o.owner_generation,o.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,old_expiry)
    or (f.owner_id,f.owner_generation,f.expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,old_expiry)
    or old_expiry<=now_at then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  new_expiry:=now_at+micros*interval '1 microsecond';
  update public.deletion_reservations x set owner_expires_at=new_expiry where x.reservation_id=r.reservation_id;
  update public.deletion_fence_leases x set expires_at=new_expiry
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id;
  update public.record_purge_operations x set owner_expires_at=new_expiry,updated_at=now_at where x.operation_id=o.operation_id;
  if old_expiry<=clock_timestamp() then
    raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  perform record_platform_internal.local_blob_cleanup_operation(o.operation_id,v->>'owner_id',
    (v->>'owner_generation')::bigint,new_expiry,r.object_id);
  return query select o.owner_id,o.owner_generation,new_expiry,now_at;
end $$;
revoke all on function public.record_deletion_renew_v2(bytea) from public;

-- Restricted fixed V1 continuations. The internal dispatch argument is never
-- exposed to a login: each PUBLIC entry point fixes its own literal below.
-- The complete branch calls the full nine-adapter receipt verifier that the
-- integration owner supplies when those adapters are cut over.
create function record_platform_internal.record_deletion_v1_continue(body bytea, kind text)
returns boolean language plpgsql security definer set search_path=pg_catalog as $$
declare
  v jsonb; fields text[]:=array['operation_id','reservation_id','project_id','record_id','fence_epoch','owner_id','owner_generation','owner_expires_at'];
  numbers text[]:=array['fence_epoch','owner_generation'];
  r public.deletion_reservations; o public.record_purge_operations; f public.deletion_fence_leases;
  e record_platform_internal.record_deletion_verified_entries; s public.source_authority_admission;
  expiry timestamptz; seq bigint; hash bytea; epoch bigint; result_count bigint;
  target_state text; terminal boolean:=false; release bigint:=0;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='legacy continuation requires read committed';
  end if;
  perform public.source_application_admit();
  select a.* into s from public.source_authority_admission a where a.singleton for share;
  if found and (s.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=s.generation and p.purpose='worker')) then
    raise exception using errcode='42501',message='legacy worker admission unavailable';
  end if;
  if kind in ('delete_entry','witness','outcome_entry','finalize','promote','read_fenced','begin_purge','complete','retry','resume') then
    fields:=fields||array['ledger_sequence','ledger_entry_hash']; numbers:=numbers||array['ledger_sequence'];
  end if;
  if kind in ('witness','finalize') then fields:=fields||array['witness_proof_digest']; end if;
  if kind in ('outcome_unknown','outcome_entry','finalize') then
    fields:=fields||array['release_epoch']; numbers:=numbers||array['release_epoch'];
  end if;
  if kind in ('finalize','promote') then fields:=fields||array['audit_id']; end if;
  if kind='complete' then fields:=fields||array['receipt_digest']; end if;
  if kind in ('retry','resume') then fields:=fields||array['retry_stage']; end if;
  if kind not in ('delete_unknown','delete_entry','witness','outcome_unknown','outcome_entry','finalize','promote',
                  'read_fenced','begin_purge','complete','retry','resume') then
    raise exception using errcode='22023',message='invalid private continuation kind';
  end if;
  v:=record_platform_internal.record_deletion_command(body,fields,numbers);
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'project_id'<>'default' or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or (v->>'owner_generation')::bigint<1 or (v->>'fence_epoch')::bigint<1
    or v->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or (v ? 'ledger_entry_hash' and (v->>'ledger_entry_hash' !~ '^[0-9a-f]{64}$' or (v->>'ledger_sequence')::bigint<1))
    or (v ? 'witness_proof_digest' and v->>'witness_proof_digest' !~ '^[0-9a-f]{64}$')
    or (v ? 'receipt_digest' and v->>'receipt_digest' !~ '^[0-9a-f]{64}$')
    or (v ? 'audit_id' and v->>'audit_id' !~ '^rda_[a-z0-9]{1,64}$')
    or (v ? 'release_epoch' and (v->>'release_epoch')::bigint<1) then
    raise exception using errcode='22023',message='invalid legacy continuation identity';
  end if;
  expiry:=(v->>'owner_expires_at')::timestamptz;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select x.* into r from public.deletion_reservations x where x.reservation_id=v->>'reservation_id' for update;
  if not found or r.project_id<>v->>'project_id' or r.object_kind<>'record' or r.object_id<>v->>'record_id'
    or r.deletion_contract_version<>1 or r.fence_epoch<>(v->>'fence_epoch')::bigint then
    raise exception using errcode='42501',message='legacy continuation reservation mismatch';
  end if;
  select x.delivery_epoch into epoch from public.content_delivery_epochs x where x.project_id=r.project_id
    and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  if found and epoch<>r.fence_epoch then raise exception using errcode='42501',message='legacy continuation epoch mismatch'; end if;
  select x.* into f from public.deletion_fence_leases x where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  select x.* into o from public.record_purge_operations x where x.operation_id=v->>'operation_id' for update;
  if not found or o.reservation_id<>r.reservation_id or o.project_id<>r.project_id or o.deletion_contract_version<>1
    or (o.owner_id,o.owner_generation,o.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or expiry<=clock_timestamp() then
    raise exception using errcode='42501',message='legacy continuation caller owner unavailable';
  end if;
  if r.state='fenced' and ((r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at)
      or (f.owner_id,f.owner_generation,f.expires_at) is distinct from (o.owner_id,o.owner_generation,o.owner_expires_at)) then
    raise exception using errcode='42501',message='legacy continuation compound fence mismatch';
  end if;
  if v ? 'ledger_sequence' then
    seq:=(v->>'ledger_sequence')::bigint; hash:=decode(v->>'ledger_entry_hash','hex');
    select x.* into e from record_platform_internal.record_deletion_verified_entries x
      where x.operation_id=o.operation_id and x.deployment_id=o.deployment_id and x.project_id=o.project_id
        and x.ledger_sequence=seq and x.ledger_entry_hash=hash;
    if not found or (e.actor_id,e.reason_code,e.object_kind,e.object_id,e.token_commitment,e.request_fingerprint)
       is distinct from (o.actor_id,o.reason_code,r.object_kind,r.object_id,r.deletion_token_commitment,r.request_fingerprint)
       or (v ? 'witness_proof_digest' and e.witness_proof_digest<>decode(v->>'witness_proof_digest','hex')) then
      raise exception using errcode='42501',message='legacy continuation verified entry unavailable';
    end if;
  elsif kind='outcome_unknown' then
    select x.* into e from record_platform_internal.record_deletion_verified_entries x
      where x.operation_id=o.operation_id and x.deployment_id=o.deployment_id and x.project_id=o.project_id
        and x.entry_type='attempt_not_committed' and x.release_epoch=(v->>'release_epoch')::bigint;
    if not found or (e.actor_id,e.reason_code,e.object_kind,e.object_id,e.token_commitment,e.request_fingerprint)
      is distinct from (o.actor_id,o.reason_code,r.object_kind,r.object_id,r.deletion_token_commitment,r.request_fingerprint) then
      raise exception using errcode='42501',message='witnessed absence outcome unavailable';
    end if;
  end if;
  case kind
  when 'delete_unknown' then
    if o.operation_state<>'provisional_fenced' or r.state<>'fenced' then raise exception using errcode='42501',message='legacy state mismatch'; end if;
    update public.record_purge_operations x set operation_state='ledger_commit_unknown',updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'delete_entry' then
    if o.operation_state not in ('provisional_fenced','ledger_commit_unknown') or r.state<>'fenced'
      or o.ledger_sequence is not null or e.entry_type<>'delete_commit' or e.deletion_contract_version<>1 then
      raise exception using errcode='42501',message='legacy delete entry mismatch'; end if;
    update public.record_purge_operations x set operation_state='witness_pending',ledger_entry_type='delete_commit',
      ledger_sequence=seq,ledger_entry_hash=hash,updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'witness' then
    if o.operation_state<>'witness_pending' or r.state<>'fenced' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.ledger_entry_type) is distinct from (seq,hash,'delete_commit'::text) then
      raise exception using errcode='42501',message='legacy witness mismatch'; end if;
    update public.record_purge_operations x set operation_state='delete_requested',witness_proof_digest=e.witness_proof_digest,
      updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'outcome_unknown' then
    if o.operation_state<>'ledger_commit_unknown' or r.state<>'fenced' or o.ledger_sequence is not null or o.release_epoch<>0 then
      raise exception using errcode='42501',message='legacy outcome state mismatch'; end if;
    update public.record_purge_operations x set operation_state='release_pending',release_epoch=e.release_epoch,
      updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'outcome_entry' then
    release:=(v->>'release_epoch')::bigint;
    if o.operation_state not in ('ledger_commit_unknown','release_pending') or r.state<>'fenced' or o.ledger_sequence is not null
      or e.entry_type<>'attempt_not_committed' or e.release_epoch<>release
      or (o.operation_state='release_pending' and o.release_epoch<>release) then
      raise exception using errcode='42501',message='legacy outcome entry mismatch'; end if;
    update public.record_purge_operations x set operation_state='release_pending',ledger_entry_type='attempt_not_committed',
      ledger_sequence=seq,ledger_entry_hash=hash,release_epoch=release,updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'finalize' then
    release:=(v->>'release_epoch')::bigint;
    if o.operation_state<>'release_pending' or r.state<>'fenced' or e.entry_type<>'attempt_not_committed'
      or e.release_epoch<>release or o.release_epoch<>release or (o.ledger_sequence,o.ledger_entry_hash) is distinct from (seq,hash) then
      raise exception using errcode='42501',message='legacy outcome finalization mismatch'; end if;
    update public.deletion_reservations x set state='not_committed',release_epoch=release,owner_id='',owner_generation=0,
      owner_expires_at=null,completed_at=clock_timestamp() where x.reservation_id=r.reservation_id;
    update public.deletion_fence_leases x set expires_at=clock_timestamp() where x.project_id=r.project_id and x.object_kind=r.object_kind
      and x.object_id=r.object_id and (x.owner_id,x.owner_generation,x.expires_at)=(o.owner_id,o.owner_generation,o.owner_expires_at);
    get diagnostics result_count=row_count;
    if result_count<>1 then raise exception using errcode='42501',message='legacy exact fence lost'; end if;
    update public.record_purge_operations x set operation_state='not_committed',witness_proof_digest=e.witness_proof_digest,
      owner_id='',owner_generation=0,owner_expires_at=null,completed_at=clock_timestamp(),updated_at=clock_timestamp() where x.operation_id=o.operation_id;
    insert into public.record_deletion_audits(audit_id,operation_id,project_id,event_kind,reason_code,occurred_at)
      values(v->>'audit_id',o.operation_id,o.project_id,'not_committed',o.reason_code,clock_timestamp());
    terminal:=true;
  when 'promote' then
    if o.operation_state<>'delete_requested' or r.state<>'fenced' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest) then
      raise exception using errcode='42501',message='legacy permanent fence mismatch'; end if;
    update public.deletion_reservations x set state='committed',owner_id='',owner_generation=0,owner_expires_at=null,
      completed_at=clock_timestamp() where x.reservation_id=r.reservation_id;
    update public.deletion_fence_leases x set expires_at=clock_timestamp() where x.project_id=r.project_id and x.object_kind=r.object_kind
      and x.object_id=r.object_id and (x.owner_id,x.owner_generation,x.expires_at)=(o.owner_id,o.owner_generation,o.owner_expires_at);
    get diagnostics result_count=row_count;
    if result_count<>1 then raise exception using errcode='42501',message='legacy exact fence lost'; end if;
    update public.record_purge_operations x set operation_state='fence_propagating',updated_at=clock_timestamp() where x.operation_id=o.operation_id;
    insert into public.record_deletion_audits(audit_id,operation_id,project_id,event_kind,reason_code,occurred_at)
      values(v->>'audit_id',o.operation_id,o.project_id,'committed',o.reason_code,clock_timestamp());
  when 'read_fenced' then
    if o.operation_state<>'fence_propagating' or r.state<>'committed' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest)
      or exists(select 1 from public.deletion_fence_leases x where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id and x.expires_at>clock_timestamp())
      or exists(select 1 from public.object_content_leases x where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id and x.expires_at>clock_timestamp()) then
      raise exception using errcode='42501',message='legacy read fence not propagated'; end if;
    update public.record_purge_operations x set operation_state='read_fenced',updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'begin_purge' then
    if o.operation_state<>'read_fenced' or r.state<>'committed' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest) then
      raise exception using errcode='42501',message='legacy purge admission mismatch'; end if;
    update public.record_purge_operations x set operation_state='online_purging',updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'complete' then
    if o.operation_state<>'online_purging' or r.state<>'committed' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest)
      or not record_platform_internal.record_deletion_verify_online_receipts_v1(o.operation_id,decode(v->>'receipt_digest','hex')) then
      raise exception using errcode='42501',message='legacy purge closure unavailable'; end if;
    update public.record_purge_operations x set operation_state='online_purged',receipt_digest=decode(v->>'receipt_digest','hex'),
      owner_id='',owner_generation=0,owner_expires_at=null,completed_at=clock_timestamp(),updated_at=clock_timestamp() where x.operation_id=o.operation_id;
    terminal:=true;
  when 'retry' then
    target_state:=case v->>'retry_stage' when 'promote_permanent_fence' then 'delete_requested' when 'propagate_permanent_fence' then 'fence_propagating'
      when 'begin_online_purge' then 'read_fenced' when 'purge_online' then 'online_purging' else null end;
    if target_state is null or o.operation_state<>target_state or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest) then
      raise exception using errcode='42501',message='legacy retry mismatch'; end if;
    update public.record_purge_operations x set operation_state='retry_required',retry_from=v->>'retry_stage',updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  when 'resume' then
    target_state:=case v->>'retry_stage' when 'promote_permanent_fence' then 'delete_requested' when 'propagate_permanent_fence' then 'fence_propagating'
      when 'begin_online_purge' then 'read_fenced' when 'purge_online' then 'online_purging' else null end;
    if target_state is null or o.operation_state<>'retry_required' or o.retry_from<>v->>'retry_stage' or e.entry_type<>'delete_commit'
      or (o.ledger_sequence,o.ledger_entry_hash,o.witness_proof_digest) is distinct from (seq,hash,e.witness_proof_digest) then
      raise exception using errcode='42501',message='legacy retry resume mismatch'; end if;
    update public.record_purge_operations x set operation_state=target_state,retry_from=null,updated_at=clock_timestamp() where x.operation_id=o.operation_id;
  end case;
  -- A time check after any potentially blocking receipt/audit operation is
  -- mandatory even when the terminal transition has intentionally cleared owner.
  if expiry<=clock_timestamp() or (not terminal and not exists(select 1 from public.record_purge_operations x
      where x.operation_id=o.operation_id and (x.owner_id,x.owner_generation,x.owner_expires_at)=(o.owner_id,o.owner_generation,o.owner_expires_at))) then
    raise exception using errcode='42501',message='legacy owner expired before commit';
  end if;
  return true;
end $$;

create function public.record_deletion_mark_delete_commit_unknown_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'delete_unknown') $$;
create function public.record_deletion_record_delete_entry_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'delete_entry') $$;
create function public.record_deletion_mark_delete_witnessed_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'witness') $$;
create function public.record_deletion_mark_outcome_commit_unknown_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'outcome_unknown') $$;
create function public.record_deletion_record_outcome_entry_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'outcome_entry') $$;
create function public.record_deletion_finalize_not_committed_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'finalize') $$;
create function public.record_deletion_promote_permanent_fence_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'promote') $$;
create function public.record_deletion_mark_read_fenced_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'read_fenced') $$;
create function public.record_deletion_begin_online_purge_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'begin_purge') $$;
create function public.record_deletion_complete_online_purge_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'complete') $$;
create function public.record_deletion_mark_retry_required_v1(bytea) returns boolean language sql security definer set search_path=pg_catalog as $$ select record_platform_internal.record_deletion_v1_continue($1,'retry') $$;
