-- Revoke PUBLIC and grant only to the constrained worker for each public wrapper.

revoke all on function public.record_deletion_mark_delete_commit_unknown_v1(bytea),
  public.record_deletion_record_delete_entry_v1(bytea),
  public.record_deletion_mark_delete_witnessed_v1(bytea),
  public.record_deletion_mark_outcome_commit_unknown_v1(bytea),
  public.record_deletion_record_outcome_entry_v1(bytea),
  public.record_deletion_finalize_not_committed_v1(bytea),
  public.record_deletion_promote_permanent_fence_v1(bytea),
  public.record_deletion_mark_read_fenced_v1(bytea),
  public.record_deletion_begin_online_purge_v1(bytea),
  public.record_deletion_complete_online_purge_v1(bytea),
