alter table public.record_core_purge_receipts alter constraint record_core_purge_receipts_operation_id_fkey deferrable initially immediate;
-- Older per-obligation cleanup receipts are opaque immutable facts because
-- their completion command was not retained. GC-linked completions must
-- match their actual command and receipt, including the physical target.
create function record_platform_internal.record_deletion_completed_obligation_v2(id text)
returns boolean language sql security definer set search_path=pg_catalog as $$
  select exists(select 1 from public.record_write_obligations w where w.obligation_id=id
    and w.backend_kind='local' and w.cleanup_completed_at is not null and w.handed_off_at is not null
    and w.cleanup_receipt is not null and octet_length(w.cleanup_receipt)=32
    and ((w.cleanup_outcome in ('deleted','already_absent') and w.quota_settled_at is not null)
      or (w.cleanup_outcome='retained_referenced' and w.quota_settled_at is null))
    and (exists(select 1 from public.local_blob_gc_obligations link
      join public.blob_gc_deletions gc on gc.deletion_id=link.deletion_id
      where link.obligation_id=w.obligation_id and link.seal_obligation
        and gc.local_contract_version=2 and gc.deletion_state='completed' and gc.completed_at is not null
        and (gc.namespace_id,gc.incarnation_id,gc.blob_key,gc.physical_delete_result,gc.receipt_digest)
          is not distinct from (w.namespace_id,w.incarnation_id,w.canonical_key,w.cleanup_outcome,w.cleanup_receipt)
        and gc.final_identity_bound and gc.inventory_digest is not null and gc.completion_command is not null
        and gc.receipt_digest=record_platform_internal.digest(convert_to('HOUFENG-LOCAL-GC-V2','UTF8')||gc.completion_command,'sha256')
        and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'deletion_id'=gc.deletion_id
        and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'inventory_digest'=encode(gc.inventory_digest,'hex')
        and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'outcome'=gc.physical_delete_result)
      or (not exists(select 1 from public.local_blob_gc_obligations link where link.obligation_id=w.obligation_id and link.seal_obligation)
        and w.cleanup_owner_id is not null and w.cleanup_generation>0 and w.cleanup_expires_at is not null and w.cleanup_dispatch_id is not null))
    and (not exists(select 1 from public.blob_objects b where b.namespace_id=w.namespace_id and b.blob_key=w.canonical_key)
      or record_platform_internal.local_blob_key_referenced(w.namespace_id,w.canonical_key))
    and (w.cleanup_outcome<>'retained_referenced' or record_platform_internal.local_blob_key_referenced(w.namespace_id,w.canonical_key)
      or (not exists(select 1 from public.blob_objects b where b.namespace_id=w.namespace_id and b.blob_key=w.canonical_key)
        and exists(select 1 from public.blob_gc_deletions gc where gc.namespace_id=w.namespace_id and gc.incarnation_id=w.incarnation_id
          and gc.blob_key=w.canonical_key and gc.local_contract_version=2 and gc.deletion_state='completed'
          and gc.physical_delete_result in ('deleted','already_absent') and gc.completed_at>=w.cleanup_completed_at
          and gc.final_identity_bound and gc.inventory_digest is not null and gc.completion_command is not null
          and gc.receipt_digest=record_platform_internal.digest(convert_to('HOUFENG-LOCAL-GC-V2','UTF8')||gc.completion_command,'sha256')
          and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'deletion_id'=gc.deletion_id
          and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'inventory_digest'=encode(gc.inventory_digest,'hex')
          and (convert_from(gc.completion_command,'UTF8')::jsonb)->>'outcome'=gc.physical_delete_result))))
$$;
revoke all on function record_platform_internal.record_deletion_completed_obligation_v2(text) from public;

-- Re-discover all inventory-lock routes, including root-independent operation
-- handoffs. Shared archives remain owned only while another target and its
-- real import job/artifact continue to exist.
create function record_platform_internal.record_deletion_responsibilities_v2(op text, project text, target text)
returns boolean language sql security definer set search_path=pg_catalog as $$
  select not exists (
    select 1 from public.record_write_obligations w where w.project_id=project and (
      w.operation_id=op or w.record_id=target
      or exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=w.obligation_id and t.record_id=target)
      or (w.origin_kind in ('upload','processor_preview') and exists(select 1 from public.record_drafts d
        where d.record_id=target and d.draft_id=(convert_from(w.registration_command,'UTF8')::jsonb)->>'draft_id'))
      or (w.origin_kind='upload' and exists(select 1 from public.attachment_uploads u
        join public.record_attachments a on a.attachment_id=u.attachment_id left join public.record_drafts d on d.draft_id=a.draft_id
        where u.upload_id=w.origin_id and (a.record_id=target or d.record_id=target)))
      or (w.origin_kind='processor_preview' and exists(select 1 from public.attachment_processor_jobs j
        join public.record_attachments a on a.attachment_id=j.attachment_id left join public.record_drafts d on d.draft_id=a.draft_id
        where j.processor_job_id=w.origin_id and (a.record_id=target or d.record_id=target)))
      or (w.origin_kind='export_artifact' and exists(select 1 from public.record_export_jobs j
        where j.export_job_id=w.origin_id and j.record_id=target))
      or (w.origin_kind in ('import_archive','import_attachment') and exists(select 1 from public.record_import_plans p
        join public.record_import_entity_mappings m on m.import_plan_id=p.import_plan_id
        where p.import_job_id=w.origin_id and m.entity_kind='record' and m.target_id=target))
    ) and not record_platform_internal.record_deletion_completed_obligation_v2(w.obligation_id) and not (
      w.cleanup_completed_at is null and w.origin_kind='import_archive' and w.operation_id is null
      and exists(select 1 from public.record_write_obligation_targets own where own.obligation_id=w.obligation_id
        and own.record_id=target and own.handed_off_at is not null)
      and exists(select 1 from public.record_write_obligation_targets other
        join public.records live on live.project_id=w.project_id and live.record_id=other.record_id
        join public.record_import_jobs job on job.import_job_id=w.origin_id and job.project_id=w.project_id
        join public.record_import_artifacts artifact on artifact.import_job_id=job.import_job_id
          and artifact.artifact_role='archive' and artifact.obligation_id=w.obligation_id
        where other.obligation_id=w.obligation_id and other.record_id<>target and other.handed_off_at is null)))
    and not exists(select 1 from public.blob_gc_deletions gc where gc.operation_id=op and (
      gc.deletion_state<>'completed' or gc.completed_at is null or gc.retry_at is not null or gc.receipt_digest is null
      or (not exists(select 1 from public.attachment_purge_targets t where t.operation_id=op and t.deletion_id=gc.deletion_id)
        and not exists(select 1 from public.record_portability_cleanup_targets t where t.operation_id=op and t.deletion_id=gc.deletion_id))))
$$;
revoke all on function record_platform_internal.record_deletion_responsibilities_v2(text,text,text) from public;

-- Reconstructs the V1 RegistryPurger receipt from immutable per-adapter data.
-- Invoke only from the already owner-fenced V1 completion command. Receipt
-- INSERT rights must be restricted to the corresponding purge commands.
create function record_platform_internal.record_deletion_verify_online_receipts(op text, expected bytea, version bigint)
returns boolean language plpgsql security definer set search_path=pg_catalog as $$
declare
  r public.deletion_reservations; names text[]:=array['record_core','record_attachments','record_evidence',
    'record_markdown_client','record_search','record_activity_projection','record_comparison','record_collaboration','record_portability'];
  name text; surfaces text[]; item text; surface bytea; receipt bytea; stored_surface bytea; computed bytea;
  content bytea; aggregate bytea; count_removed bigint; verified_at timestamptz; rowcount bigint;
  marker bytea; counts bigint[]:='{}'; part public.attachment_purge_receipts; expected_gc bigint;
  attachment_manifest public.attachment_purge_preparations; portability_manifest public.record_portability_cleanup_preparations;
  material jsonb; physical_rows bigint; removed_rows bigint;
begin
  select res.* into strict r from public.record_purge_operations o join public.deletion_reservations res
    on res.reservation_id=o.reservation_id and res.project_id=o.project_id
    where o.operation_id=op and o.deletion_contract_version=version and res.deletion_contract_version=version;
  if octet_length(expected)<>32 then return false; end if;
  -- Pending physical obligations remain independent of a SQL receipt. The
  -- planned collaboration drain must additionally establish its durable handoff.
  if (version=1 and (exists(select 1 from public.record_write_obligations w where (w.operation_id=op or (w.project_id=r.project_id and w.record_id=r.object_id))
        and w.cleanup_completed_at is null)
    or exists(select 1 from public.record_write_obligation_targets t join public.record_write_obligations w using(obligation_id)
        where t.record_id=r.object_id and w.cleanup_completed_at is null)))
    or (version=2 and not record_platform_internal.record_deletion_responsibilities_v2(op,r.project_id,r.object_id))
    or not record_platform_internal.record_outbox_handoff_complete(op,r.object_id) then
    return false;
  end if;
  aggregate:=record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.online-purge.v1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'));
  foreach name in array names loop
    surfaces:=case name
      when 'record_core' then array['content_delivery_epochs','record_core_purge_receipts','record_domain_activities','record_draft_checkpoints','record_drafts','record_revision_participants','record_revision_subjects','record_revision_tags','record_revisions','records']
      when 'record_attachments' then array['attachment_processor_jobs','attachment_purge_receipts','attachment_quota_accounts','attachment_upload_parts','attachment_uploads','blob_gc_deletions','blob_gc_pins','blob_objects','blob_publication_intents','content_processor_workspaces','content_workspace_purge_receipts','record_attachments','record_revision_attachments']
      when 'record_evidence' then array['evidence_capture_intents','evidence_copy_lineage','evidence_payload_gc_receipts','evidence_payloads','evidence_purge_receipts','evidence_snapshots','record_revision_evidence']
      when 'record_markdown_client' then array['browser_record_cleanup_events','browser_record_cleanup_receipts','browser_record_cleanup_targets','markdown_client_draft_buffers','markdown_client_workspaces','record_markdown_client_purge_receipts']
      when 'record_search' then array['record_search_documents','record_search_purge_receipts','record_search_subjects']
      when 'record_activity_projection' then array['record_activity_projection','record_activity_purge_receipts','record_activity_revision_intervals','record_activity_subjects']
      when 'record_comparison' then array['comparison_client_save_attempts','comparison_client_workbenches','comparison_result_dependencies','record_comparison_purge_receipts']
      when 'record_collaboration' then array['record_action_events','record_actions','record_collaboration_purge_receipts','record_comment_mentions','record_comment_replies','record_comment_revisions','record_comment_tombstones','record_comments','record_followers','record_notification_audit_summaries','record_notification_deliveries','record_notification_delivery_attempts','record_notification_delivery_starts','record_notification_recipients','record_notifications']
      when 'record_portability' then array['record_export_artifacts','record_export_jobs','record_import_artifacts','record_import_entity_mappings','record_import_jobs','record_import_plans','record_origin_tombstones','record_origins','record_portability_purge_receipts']
    end;
    content:=record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.adapter-surfaces.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(name,'UTF8'))||int8send(cardinality(surfaces)::bigint);
    foreach item in array surfaces loop content:=content||record_platform_internal.client_purge_field(convert_to(item,'UTF8')); end loop;
    surface:=record_platform_internal.digest(content,'sha256');
    stored_surface:=null; receipt:=null; count_removed:=null; verified_at:=null;
    case name
      when 'record_core' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at
          into stored_surface,receipt,count_removed,verified_at from public.record_core_purge_receipts x where x.operation_id=op and x.adapter_name=name;
        computed:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.core-purge-receipt.v1','UTF8'))
          ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||surface||int8send(count_removed),'sha256');
      when 'record_attachments' then
        select count(*) into rowcount from public.attachment_purge_receipts x where x.operation_id=op and x.adapter_name=name;
        if rowcount<>3 then return false; end if;
        if version=2 then
          select p.* into strict attachment_manifest from public.attachment_purge_preparations p where p.operation_id=op;
          if attachment_manifest.record_id<>r.object_id or attachment_manifest.surface_digest<>surface then return false; end if;
          if not record_platform_internal.workspace_purge_manifest_valid(op) then return false; end if;
          if exists(select 1 from public.attachment_purge_targets t left join public.blob_gc_deletions g using(deletion_id)
            where t.operation_id=op and (g.deletion_id is null or g.operation_id is distinct from op
              or g.namespace_id is distinct from attachment_manifest.namespace_id or g.incarnation_id is distinct from attachment_manifest.incarnation_id
              or g.blob_key is distinct from t.blob_key or g.local_contract_version<>2 or g.deletion_state<>'completed'
              or g.physical_delete_result not in ('deleted','already_absent','retained_referenced') or g.physical_delete_result is null
              or g.completed_at is null or not g.final_identity_bound or g.inventory_digest is null or g.completion_command is null
              or g.receipt_digest is distinct from record_platform_internal.digest(convert_to('HOUFENG-LOCAL-GC-V2','UTF8')||g.completion_command,'sha256')
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'deletion_id' is distinct from g.deletion_id
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'namespace_id' is distinct from g.namespace_id::text
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'incarnation_id' is distinct from g.incarnation_id::text
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_owner_id' is distinct from g.owner_id
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_generation')::bigint is distinct from g.owner_generation
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_expires_at')::timestamptz is distinct from g.lease_expires_at
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_dispatch_id')::uuid is distinct from g.cleanup_dispatch_id
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'operation_id' is distinct from op
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'outcome' is distinct from g.physical_delete_result
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'inventory_digest' is distinct from encode(g.inventory_digest,'hex'))) then return false; end if;
          select coalesce(jsonb_agg(jsonb_build_array(t.blob_key,t.deletion_id,t.metadata_present,g.physical_delete_result,encode(g.receipt_digest,'hex'))
              order by t.blob_key),'[]'::jsonb),count(*) filter(where t.metadata_present and g.physical_delete_result in ('deleted','already_absent'))
            into material,physical_rows from public.attachment_purge_targets t join public.blob_gc_deletions g using(deletion_id) where t.operation_id=op;
          receipt:=sha256(convert_to(jsonb_build_array('HOUFENG-ATTACHMENT-PURGE-V2',op,encode(surface,'hex'),
            attachment_manifest.logical_rows,attachment_manifest.upload_part_rows,physical_rows,material)::text,'UTF8'));
          foreach item in array array['logical_attachment','upload_part','blob_object'] loop
            marker:=sha256(convert_to(jsonb_build_array('HOUFENG-ATTACHMENT-PURGE-V2',op,item)::text,'UTF8'));
            removed_rows:=case item when 'logical_attachment' then attachment_manifest.logical_rows
              when 'upload_part' then attachment_manifest.upload_part_rows else physical_rows end;
            if not exists(select 1 from public.attachment_purge_receipts x where x.operation_id=op and x.adapter_name=name
                and x.surface_kind=item and x.object_version_digest=marker and x.removed_surface_digest=surface
                and x.receipt_digest=sha256(receipt||marker) and x.removed_row_count=removed_rows and x.verified_absent_at is not null) then return false; end if;
          end loop;
          computed:=receipt; stored_surface:=surface; verified_at:=attachment_manifest.prepared_at; count_removed:=0;
        else
        content:=record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-receipt.v1','UTF8'))
          ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||surface;
        foreach item in array array['logical_attachment','upload_part','blob_object'] loop
          marker:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-marker.v1','UTF8'))
            ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))
            ||record_platform_internal.client_purge_field(convert_to(item,'UTF8')),'sha256');
          select x.* into part from public.attachment_purge_receipts x
            where x.operation_id=op and x.adapter_name=name and x.surface_kind=item and x.object_version_digest=marker;
          if not found or part.verified_absent_at is null or part.removed_surface_digest<>surface or part.removed_row_count<0 then return false; end if;
          computed:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-receipt.v1','UTF8'))
            ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))
            ||record_platform_internal.client_purge_field(convert_to(item,'UTF8'))||marker||surface||int8send(part.removed_row_count),'sha256');
          if part.receipt_digest<>computed then return false; end if;
          content:=content||record_platform_internal.client_purge_field(convert_to(item,'UTF8'))||marker||int8send(part.removed_row_count);
          if item='blob_object' then expected_gc:=part.removed_row_count; end if;
        end loop;
        select count(*) into rowcount from public.blob_gc_deletions g where g.project_id=r.project_id and g.purge_mode='permanent'
          and (g.operation_id=op or (g.operation_id is null and g.owner_id=op and g.local_contract_version=1));
        if rowcount<>expected_gc or exists(select 1 from public.blob_gc_deletions g where g.project_id=r.project_id and g.purge_mode='permanent'
          and (g.operation_id=op or (g.operation_id is null and g.owner_id=op and g.local_contract_version=1))
          and (g.deletion_state<>'completed' or g.retry_at is not null or g.physical_delete_result not in ('deleted','already_absent')
            or g.receipt_digest is null or g.completed_at is null or g.sha256_digest is null or g.size_bytes is null or g.size_bytes<=0)) then return false; end if;
        receipt:=record_platform_internal.digest(content,'sha256'); computed:=receipt; stored_surface:=surface; verified_at:=part.verified_absent_at; count_removed:=0;
        end if;
      when 'record_evidence' then
        select x.receipt_digest,x.completed_at into receipt,verified_at from public.evidence_purge_receipts x where x.operation_id=op and x.surface_kind=name;
        stored_surface:=surface; count_removed:=0;
        computed:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.evidence.deletion-receipt.v1','UTF8'))
          ||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||record_platform_internal.client_purge_field(convert_to(r.project_id,'UTF8'))
          ||record_platform_internal.client_purge_field(convert_to(r.object_id,'UTF8'))||record_platform_internal.client_purge_field(surface)||int8send(0::bigint),'sha256');
      when 'record_markdown_client' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_markdown_client_purge_receipts x where x.operation_id=op and x.adapter_name=name;
      when 'record_search' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_search_purge_receipts x where x.operation_id=op and x.adapter_name=name;
      when 'record_activity_projection' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_activity_purge_receipts x where x.operation_id=op and x.adapter_name=name;
      when 'record_comparison' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_comparison_purge_receipts x where x.operation_id=op and x.adapter_name=name;
      when 'record_collaboration' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_collaboration_purge_receipts x where x.operation_id=op and x.adapter_name=name;
      when 'record_portability' then
        select x.removed_surface_digest,x.receipt_digest,x.removed_row_count,x.verified_absent_at into stored_surface,receipt,count_removed,verified_at
          from public.record_portability_purge_receipts x where x.operation_id=op and x.adapter_name=name;
        if version=2 then
          select p.* into strict portability_manifest from public.record_portability_cleanup_preparations p where p.operation_id=op;
          if portability_manifest.record_id<>r.object_id or portability_manifest.surface_digest<>surface then return false; end if;
          if exists(select 1 from public.record_portability_cleanup_targets t left join public.blob_gc_deletions g using(deletion_id)
            where t.operation_id=op and (g.deletion_id is null or g.operation_id is distinct from op
              or g.namespace_id is distinct from portability_manifest.namespace_id or g.incarnation_id is distinct from portability_manifest.incarnation_id
              or g.blob_key is distinct from t.blob_key or g.local_contract_version<>2 or g.deletion_state<>'completed'
              or g.physical_delete_result not in ('deleted','already_absent','retained_referenced') or g.physical_delete_result is null
              or g.completed_at is null or not g.final_identity_bound or g.inventory_digest is null or g.completion_command is null
              or g.receipt_digest is distinct from record_platform_internal.digest(convert_to('HOUFENG-LOCAL-GC-V2','UTF8')||g.completion_command,'sha256')
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'deletion_id' is distinct from g.deletion_id
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'namespace_id' is distinct from g.namespace_id::text
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'incarnation_id' is distinct from g.incarnation_id::text
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_owner_id' is distinct from g.owner_id
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_generation')::bigint is distinct from g.owner_generation
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_expires_at')::timestamptz is distinct from g.lease_expires_at
              or ((convert_from(g.completion_command,'UTF8')::jsonb)->>'cleanup_dispatch_id')::uuid is distinct from g.cleanup_dispatch_id
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'operation_id' is distinct from op
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'outcome' is distinct from g.physical_delete_result
              or (convert_from(g.completion_command,'UTF8')::jsonb)->>'inventory_digest' is distinct from encode(g.inventory_digest,'hex'))) then return false; end if;
          select coalesce(jsonb_agg(jsonb_build_array(t.blob_key,t.deletion_id,g.physical_delete_result,encode(g.receipt_digest,'hex'))
            order by t.blob_key),'[]'::jsonb) into material from public.record_portability_cleanup_targets t
            join public.blob_gc_deletions g using(deletion_id) where t.operation_id=op;
          computed:=sha256(convert_to(jsonb_build_array('HOUFENG-PORTABILITY-PURGE-V2',op,encode(surface,'hex'),
            portability_manifest.removed_rows,material)::text,'UTF8'));
          if count_removed is distinct from portability_manifest.removed_rows then return false; end if;
        end if;
    end case;
    if name in ('record_markdown_client','record_comparison','record_collaboration') then
      computed:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.client-purge.v1','UTF8'))
        ||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||record_platform_internal.client_purge_field(convert_to(r.object_id,'UTF8'))
        ||record_platform_internal.client_purge_field(convert_to(name,'UTF8'))||record_platform_internal.client_purge_field(surface)
        ||record_platform_internal.client_purge_field(int8send(count_removed)),'sha256');
    elsif name in ('record_search','record_activity_projection') or (name='record_portability' and version=1) then
      item:=case name when 'record_search' then 'houfeng.record-search.deletion-receipt.v1'
        when 'record_activity_projection' then 'houfeng.record-activity.deletion-receipt.v1' else 'houfeng.record-portability.deletion-receipt.v1' end;
      computed:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to(item,'UTF8'))
        ||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))||record_platform_internal.client_purge_field(convert_to(r.project_id,'UTF8'))
        ||record_platform_internal.client_purge_field(convert_to(r.object_id,'UTF8'))||record_platform_internal.client_purge_field(surface)
        ||record_platform_internal.client_purge_field(int8send(count_removed)),'sha256');
    end if;
    if verified_at is null or count_removed is null or count_removed<0 or stored_surface is distinct from surface
      or receipt is null or octet_length(receipt)<>32 or receipt is distinct from computed then return false; end if;
    aggregate:=aggregate||record_platform_internal.client_purge_field(convert_to(name,'UTF8'))||surface||receipt;
  end loop;
  -- Recheck surviving record-specific projections. Shared evidence payloads,
  -- origins/tombstones and provider facts are not owned record content.
  if exists(select 1 from public.records where record_id=r.object_id)
    or exists(select 1 from public.record_revisions where record_id=r.object_id)
    or exists(select 1 from public.record_drafts where record_id=r.object_id)
    or exists(select 1 from public.record_domain_activities where record_id=r.object_id)
    or exists(select 1 from public.content_delivery_epochs x where x.project_id=r.project_id and x.object_kind='record' and x.object_id=r.object_id)
    or exists(select 1 from public.record_attachments x where x.project_id=r.project_id and x.record_id=r.object_id)
    or exists(select 1 from public.record_revision_attachments where record_id=r.object_id)
    or exists(select 1 from public.evidence_capture_intents where record_id=r.object_id)
    or exists(select 1 from public.evidence_snapshots where record_id=r.object_id)
    or exists(select 1 from public.record_revision_evidence where record_id=r.object_id)
    or exists(select 1 from public.record_search_subjects where record_id=r.object_id)
    or exists(select 1 from public.record_search_documents where record_id=r.object_id)
    or exists(select 1 from public.record_activity_subjects where record_id=r.object_id)
    or exists(select 1 from public.record_activity_projection where record_id=r.object_id)
    or exists(select 1 from public.record_activity_revision_intervals where record_id=r.object_id)
    or exists(select 1 from public.record_export_jobs where record_id=r.object_id)
    or exists(select 1 from public.record_origins where source_record_id=r.object_id)
    or exists(select 1 from public.record_import_entity_mappings where entity_kind='record' and target_id=r.object_id)
    or exists(select 1 from public.markdown_client_draft_buffers b where b.project_id=r.project_id and b.record_id=r.object_id)
    or exists(select 1 from public.markdown_client_workspaces w where w.project_id=r.project_id and w.record_id=r.object_id)
    or exists(select 1 from public.comparison_client_save_attempts a where a.project_id=r.project_id and
      (a.destination_record_id=r.object_id or r.object_id=any(a.source_record_ids)))
    or exists(select 1 from public.comparison_client_workbenches w where w.project_id=r.project_id and
      (w.destination_record_id=r.object_id or r.object_id=any(w.source_record_ids)))
    or exists(select 1 from public.record_action_events where record_id=r.object_id)
    or exists(select 1 from public.record_actions where record_id=r.object_id)
    or exists(select 1 from public.record_comment_mentions where record_id=r.object_id)
    or exists(select 1 from public.record_comment_replies where record_id=r.object_id)
    or exists(select 1 from public.record_comment_revisions where record_id=r.object_id)
    or exists(select 1 from public.record_comment_tombstones where record_id=r.object_id)
    or exists(select 1 from public.record_comments where record_id=r.object_id)
    or exists(select 1 from public.record_followers where record_id=r.object_id)
    or exists(select 1 from public.record_notification_audit_summaries where record_id=r.object_id)
    or exists(select 1 from public.record_notification_deliveries where record_id=r.object_id)
    or exists(select 1 from public.record_notification_delivery_attempts where record_id=r.object_id)
    or exists(select 1 from public.record_notification_recipients where record_id=r.object_id)
    or exists(select 1 from public.record_notifications where record_id=r.object_id) then
    return false;
  end if;
  return record_platform_internal.digest(aggregate,'sha256')=expected;
exception when no_data_found then return false;
end $$;
create function record_platform_internal.record_deletion_verify_online_receipts_v1(op text, expected bytea)
returns boolean language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.record_deletion_verify_online_receipts(op,expected,1) $$;
create function record_platform_internal.record_deletion_verify_online_receipts_v2(op text, expected bytea)
returns boolean language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.record_deletion_verify_online_receipts(op,expected,2) $$;
revoke all on function record_platform_internal.record_deletion_verify_online_receipts(text,bytea,bigint),
  record_platform_internal.record_deletion_verify_online_receipts_v1(text,bytea),
  record_platform_internal.record_deletion_verify_online_receipts_v2(text,bytea) from public;

-- V1 recovery replay. Install after the recovery session/management helpers and
-- after making record_core_purge_receipts_operation_id_fkey DEFERRABLE INITIALLY
-- IMMEDIATE. The single deferred FK allows the real core receipt to precede a
-- terminal operation projection when no predecessor projection exists.
create function record_platform_internal.record_deletion_recovery_surface_digest(kind text)
returns bytea language plpgsql immutable set search_path=pg_catalog as $$
declare surfaces text[]; item text; material bytea;
begin
  if kind='delete_commit' then
    surfaces:=array['content_delivery_epochs','deletion_fence_leases','deletion_replay_state','deletion_reservations',
      'record_core_purge_receipts','record_deletion_audits','record_domain_activities','record_draft_checkpoints','record_drafts',
      'record_purge_operations','record_revision_participants','record_revision_subjects','record_revision_tags','record_revisions','records'];
  elsif kind='attempt_not_committed' then
    surfaces:=array['deletion_fence_leases','deletion_replay_state','deletion_reservations','record_deletion_audits','record_purge_operations'];
  else raise exception using errcode='22023',message='unknown record recovery entry'; end if;
  material:=record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.recovery-surfaces.v1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(kind,'UTF8'))||int8send(cardinality(surfaces)::bigint);
  foreach item in array surfaces loop material:=material||record_platform_internal.client_purge_field(convert_to(item,'UTF8')); end loop;
  return record_platform_internal.digest(material,'sha256');
end $$;

create function record_platform_internal.record_deletion_recovery_id(prefix text, domain text,
  deployment text, project text, operation text, kind text)
returns text language sql immutable strict set search_path=pg_catalog as $$
  select prefix||encode(record_platform_internal.digest(
    record_platform_internal.client_purge_field(convert_to(domain,'UTF8'))||int8send(1::bigint)
    ||record_platform_internal.client_purge_field(convert_to(deployment,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(project,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(operation,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(kind,'UTF8')),'sha256'),'hex')
$$;

create function public.record_deletion_replay_v1(bytea)
returns table(sequence bigint,entry_hash bytea,surface_digest bytea,content_purged boolean)
language plpgsql security definer set search_path=pg_catalog as $$
#variable_conflict use_variable
declare
  v jsonb; entry record_platform_internal.record_deletion_verified_entries;
  session_scope record_platform_internal.record_deletion_recovery_sessions;
  reservation public.deletion_reservations; operation public.record_purge_operations; lease public.deletion_fence_leases;
  receipt public.record_core_purge_receipts; cursor_row public.deletion_replay_state;
  reservation_id text; by_operation text; by_token text; competing text; audit_id text;
  have_reservation boolean:=false; have_operation boolean:=false; have_lease boolean:=false;
  delete_content boolean; existing_receipt boolean; terminal_projection boolean; desired_state text; desired_reservation text; audit_kind text;
  proof bytea; digest bytea; old_cursor_sequence bigint; old_cursor_hash bytea; found_cursor boolean;
  current_epoch bigint; requested_sequence bigint; previous_sequence bigint;
begin
  v:=record_platform_internal.record_deletion_command($1,array['ledger_domain','ledger_sequence','ledger_entry_hash',
    'previous_sequence','previous_hash','request_fingerprint','surface_digest','maintenance_rid','maintenance_generation'],
    array['ledger_sequence','previous_sequence','maintenance_generation']);
  if v->>'ledger_domain' !~ '^[0-9a-f]{64}$' or v->>'ledger_entry_hash' !~ '^[0-9a-f]{64}$'
    or v->>'previous_hash' !~ '^[0-9a-f]{64}$' or v->>'request_fingerprint' !~ '^[0-9a-f]{64}$'
    or v->>'surface_digest' !~ '^[0-9a-f]{64}$' or v->>'maintenance_rid' !~ '^[a-z0-9_-]{1,128}$'
    or (v->>'ledger_sequence')::bigint<1 then
    raise exception using errcode='22023',message='invalid record recovery replay identity';
  end if;
  requested_sequence:=(v->>'ledger_sequence')::bigint; previous_sequence:=(v->>'previous_sequence')::bigint;
  if previous_sequence<>requested_sequence-1 then raise exception using errcode='42501',message='recovery predecessor sequence mismatch'; end if;
  select x.* into strict entry from record_platform_internal.record_deletion_verified_entries x
    where x.ledger_domain=decode(v->>'ledger_domain','hex') and x.ledger_sequence=requested_sequence
      and x.ledger_entry_hash=decode(v->>'ledger_entry_hash','hex');
  select x.* into strict session_scope from record_platform_internal.record_deletion_recovery_sessions x
    where x.transaction_id=pg_current_xact_id() and x.backend_pid=pg_backend_pid() for update;
  if (session_scope.ledger_domain,session_scope.ledger_sequence,session_scope.ledger_entry_hash,session_scope.deployment_id,
      session_scope.maintenance_rid,session_scope.maintenance_generation)
      is distinct from (entry.ledger_domain,entry.ledger_sequence,entry.ledger_entry_hash,entry.deployment_id,
        v->>'maintenance_rid',(v->>'maintenance_generation')::bigint) then
    raise exception using errcode='42501',message='record recovery session mismatch';
  end if;
  perform record_platform_internal.record_deletion_management_admit(entry.deployment_id,v->>'maintenance_rid',(v->>'maintenance_generation')::bigint);
  digest:=record_platform_internal.record_deletion_recovery_surface_digest(entry.entry_type);
  if entry.previous_hash<>decode(v->>'previous_hash','hex') or entry.request_fingerprint<>decode(v->>'request_fingerprint','hex')
    or digest<>decode(v->>'surface_digest','hex') or entry.object_kind<>'record'
    or (entry.entry_type='delete_commit' and (entry.deletion_contract_version<>1 or entry.release_epoch<>0))
    or (entry.entry_type='attempt_not_committed' and (entry.deletion_contract_version<>0 or entry.release_epoch<1)) then
    raise exception using errcode='42501',message='record recovery verified binding mismatch';
  end if;
  -- Discovery only. Do not lock or create the cursor until every affected
  -- reservation, epoch, fence, operation, root, dependent row and receipt.
  select x.applied_ledger_sequence,x.applied_ledger_hash into old_cursor_sequence,old_cursor_hash
    from public.deletion_replay_state x where x.project_id=entry.project_id;
  found_cursor:=found;
  if not found_cursor then old_cursor_sequence:=0; old_cursor_hash:=decode(repeat('00',32),'hex'); end if;
  if (old_cursor_sequence,old_cursor_hash) is distinct from (previous_sequence,entry.previous_hash)
    and (old_cursor_sequence,old_cursor_hash) is distinct from (entry.ledger_sequence,entry.ledger_entry_hash) then
    raise exception using errcode='40001',message='record recovery predecessor changed';
  end if;
  select x.reservation_id into by_operation from public.record_purge_operations x where x.operation_id=entry.operation_id;
  select x.reservation_id into by_token from public.deletion_reservations x where x.deletion_token_commitment=entry.token_commitment;
  if by_operation is not null and by_token is not null and by_operation<>by_token then
    raise exception using errcode='42501',message='record recovery reservation conflict';
  end if;
  reservation_id:=coalesce(by_operation,by_token,record_platform_internal.record_deletion_recovery_id('drs_',
    'houfeng.record-deletion.recovery-reservation-id.v1',entry.deployment_id,entry.project_id,entry.operation_id,entry.entry_type));
  select x.* into reservation from public.deletion_reservations x where x.reservation_id=reservation_id for update;
  have_reservation:=found;
  if have_reservation and ((reservation.project_id,reservation.object_kind,reservation.object_id,
      reservation.deletion_token_commitment,reservation.request_fingerprint,reservation.deletion_contract_version)
      is distinct from (entry.project_id,entry.object_kind,entry.object_id,entry.token_commitment,entry.request_fingerprint,1::bigint)) then
    raise exception using errcode='42501',message='record recovery reservation binding mismatch';
  end if;
  select x.delivery_epoch into current_epoch from public.content_delivery_epochs x
    where x.project_id=entry.project_id and x.object_kind='record' and x.object_id=entry.object_id for update;
  select x.* into lease from public.deletion_fence_leases x where x.project_id=entry.project_id
    and x.object_kind='record' and x.object_id=entry.object_id for update;
  have_lease:=found;
  select x.* into operation from public.record_purge_operations x where x.operation_id=entry.operation_id for update;
  have_operation:=found;
  if have_operation and (not have_reservation or operation.reservation_id<>reservation_id or operation.deletion_contract_version<>1
      or (operation.deployment_id,operation.project_id,operation.actor_id,operation.reason_code)
        is distinct from (entry.deployment_id,entry.project_id,entry.actor_id,entry.reason_code)
      or (operation.ledger_sequence is not null and (operation.ledger_sequence,operation.ledger_entry_hash,operation.ledger_entry_type)
        is distinct from (entry.ledger_sequence,entry.ledger_entry_hash,entry.entry_type))
      or (operation.witness_proof_digest is not null and operation.witness_proof_digest<>entry.witness_proof_digest)) then
    raise exception using errcode='42501',message='record recovery operation binding mismatch';
  end if;
  if not have_operation and have_reservation then
    select x.operation_id into competing from public.record_purge_operations x where x.reservation_id=reservation_id for update;
    if competing is not null then raise exception using errcode='42501',message='record recovery reservation already used'; end if;
  end if;
  delete_content:=entry.entry_type='delete_commit';
  if delete_content then
    desired_state:='online_purged'; desired_reservation:='committed'; audit_kind:='committed';
    if (have_reservation and reservation.state in ('not_committed','released'))
      or (have_operation and (operation.operation_state='not_committed' or operation.release_epoch<>0))
      or exists(select 1 from public.record_deletion_gates g where g.project_id=entry.project_id and g.record_id=entry.object_id)
      or exists(select 1 from public.deletion_reservations x where x.project_id=entry.project_id and x.object_kind='record'
        and x.object_id=entry.object_id and x.reservation_id<>reservation_id and x.state='fenced') then
      raise exception using errcode='42501',message='record recovery delete conflicts with later authority';
    end if;
  else
    desired_state:='not_committed'; desired_reservation:='not_committed'; audit_kind:='not_committed';
    if (have_reservation and (reservation.state='committed' or reservation.release_epoch not in (0,entry.release_epoch)))
      or (have_operation and (operation.operation_state='online_purged' or operation.release_epoch not in (0,entry.release_epoch))) then
      raise exception using errcode='42501',message='record recovery outcome conflicts with delete';
    end if;
  end if;
  if have_reservation and not have_operation and reservation.state<>'previewed' then
    raise exception using errcode='42501',message='record recovery cannot adopt unowned reservation';
  end if;
  terminal_projection:=have_operation and operation.operation_state in ('online_purged','not_committed');
  if terminal_projection and (operation.operation_state<>desired_state or reservation.state<>desired_reservation
    or reservation.release_epoch<>entry.release_epoch or operation.release_epoch<>entry.release_epoch
    or (operation.ledger_sequence,operation.ledger_entry_hash,operation.ledger_entry_type,operation.witness_proof_digest)
      is distinct from (entry.ledger_sequence,entry.ledger_entry_hash,entry.entry_type,entry.witness_proof_digest)
    or operation.owner_id<>'' or operation.owner_generation<>0 or operation.owner_expires_at is not null
    or reservation.owner_id<>'' or reservation.owner_generation<>0 or reservation.owner_expires_at is not null
    or operation.completed_at is null or reservation.completed_at is null) then
    raise exception using errcode='42501',message='record recovery terminal projection mismatch';
  end if;
  if (old_cursor_sequence,old_cursor_hash)=(entry.ledger_sequence,entry.ledger_entry_hash) and not terminal_projection then
    raise exception using errcode='42501',message='record recovery cursor lacks terminal projection';
  end if;
  perform 1 from public.records x where x.project_id=entry.project_id and x.record_id=entry.object_id for update;
  if delete_content then
    insert into record_platform_internal.record_deletion_effect_scopes(transaction_id,backend_pid,record_id,operation_id,authority_kind,authority_digest,effect_kind)
      values(pg_current_xact_id(),pg_backend_pid(),entry.object_id,entry.operation_id,'recovery_v1',entry.ledger_entry_hash,'recovery');
    set constraints public.record_core_purge_receipts_operation_id_fkey deferred;
    select exists(select 1 from public.record_core_purge_receipts x where x.operation_id=entry.operation_id) into existing_receipt;
    receipt:=record_platform_internal.record_core_purge_effects(entry.operation_id,entry.object_id,entry.project_id,existing_receipt or terminal_projection);
    proof:=receipt.receipt_digest;
  else
    if exists(select 1 from public.record_core_purge_receipts x where x.operation_id=entry.operation_id) then
      raise exception using errcode='42501',message='not-committed recovery has a core receipt';
    end if;
    proof:=null;
  end if;
  if terminal_projection and operation.receipt_digest is distinct from proof then
    raise exception using errcode='42501',message='record recovery terminal receipt mismatch';
  end if;
  if not terminal_projection then
  if have_reservation then
    update public.deletion_reservations x set state=desired_reservation,fence_epoch=greatest(x.fence_epoch,1),
      release_epoch=entry.release_epoch,owner_id='',owner_generation=0,owner_expires_at=null,
      completed_at=coalesce(x.completed_at,clock_timestamp()) where x.reservation_id=reservation_id;
  else
    insert into public.deletion_reservations(reservation_id,project_id,object_kind,object_id,deletion_token_commitment,
      request_fingerprint,state,fence_epoch,owner_id,owner_generation,owner_expires_at,created_at,expires_at,completed_at,
      release_epoch,recovery_replayed,deletion_contract_version)
      values(reservation_id,entry.project_id,'record',entry.object_id,entry.token_commitment,entry.request_fingerprint,
        desired_reservation,greatest(coalesce(current_epoch,0),1),'',0,null,clock_timestamp(),'infinity'::timestamptz,
        clock_timestamp(),entry.release_epoch,true,1);
  end if;
  if have_operation then
    update public.record_purge_operations x set operation_state=desired_state,ledger_sequence=entry.ledger_sequence,
      ledger_entry_hash=entry.ledger_entry_hash,ledger_entry_type=entry.entry_type,witness_proof_digest=entry.witness_proof_digest,
      release_epoch=entry.release_epoch,receipt_digest=proof,retry_from=null,owner_id='',owner_generation=0,owner_expires_at=null,
      completed_at=coalesce(x.completed_at,clock_timestamp()),updated_at=clock_timestamp() where x.operation_id=entry.operation_id;
  else
    insert into public.record_purge_operations(operation_id,reservation_id,project_id,operation_state,ledger_sequence,ledger_entry_hash,
      started_at,completed_at,deployment_id,actor_id,reason_code,deletion_contract_version,ledger_entry_type,witness_proof_digest,
      release_epoch,receipt_digest,owner_id,owner_generation,owner_expires_at,updated_at)
      values(entry.operation_id,reservation_id,entry.project_id,desired_state,entry.ledger_sequence,entry.ledger_entry_hash,
        clock_timestamp(),clock_timestamp(),entry.deployment_id,entry.actor_id,entry.reason_code,1,entry.entry_type,
        entry.witness_proof_digest,entry.release_epoch,proof,'',0,null,clock_timestamp());
  end if;
  -- A fence belongs to the old projection only if its full observed tuple
  -- matches and no other still-fenced reservation carries that same tuple.
  if have_reservation and reservation.state='fenced' and have_lease
    and (lease.owner_id,lease.owner_generation,lease.expires_at)
      is not distinct from (reservation.owner_id,reservation.owner_generation,reservation.owner_expires_at)
    and not exists(select 1 from public.deletion_reservations x where x.project_id=entry.project_id and x.object_kind='record'
      and x.object_id=entry.object_id and x.reservation_id<>reservation_id and x.state='fenced'
      and (x.owner_id,x.owner_generation,x.owner_expires_at)=(lease.owner_id,lease.owner_generation,lease.expires_at)) then
    update public.deletion_fence_leases x set created_at=least(x.created_at,clock_timestamp()-interval '1 microsecond'),expires_at=clock_timestamp()
      where x.project_id=entry.project_id and x.object_kind='record' and x.object_id=entry.object_id
        and (x.owner_id,x.owner_generation,x.expires_at)=(lease.owner_id,lease.owner_generation,lease.expires_at);
  end if;
  audit_id:=record_platform_internal.record_deletion_recovery_id('rda_','houfeng.record-deletion.recovery-audit-id.v1',
    entry.deployment_id,entry.project_id,entry.operation_id,entry.entry_type);
  insert into public.record_deletion_audits(audit_id,operation_id,project_id,event_kind,reason_code,occurred_at)
    values(audit_id,entry.operation_id,entry.project_id,audit_kind,entry.reason_code,clock_timestamp())
    on conflict(operation_id,event_kind) do nothing;
  end if;
  if not exists(select 1 from public.record_deletion_audits a where a.operation_id=entry.operation_id and a.project_id=entry.project_id
      and a.event_kind=audit_kind and a.reason_code=entry.reason_code) then
    raise exception using errcode='42501',message='record recovery audit mismatch';
  end if;
  if delete_content then
    set constraints public.record_core_purge_receipts_operation_id_fkey immediate;
    if not exists(select 1 from public.record_core_purge_receipts x where x.operation_id=entry.operation_id and x.receipt_digest=proof) then
      raise exception using errcode='42501',message='record recovery receipt mismatch';
    end if;
  end if;
  -- Cursor creation/locking is last. A race with a different predecessor
  -- aborts the entire transaction including the core receipt and content.
  insert into public.deletion_replay_state(project_id,applied_ledger_sequence,applied_ledger_hash,updated_at)
    values(entry.project_id,0,decode(repeat('00',32),'hex'),clock_timestamp()) on conflict(project_id) do nothing;
  select x.* into strict cursor_row from public.deletion_replay_state x where x.project_id=entry.project_id for update;
  if (cursor_row.applied_ledger_sequence,cursor_row.applied_ledger_hash)=(previous_sequence,entry.previous_hash) then
    update public.deletion_replay_state x set applied_ledger_sequence=entry.ledger_sequence,
      applied_ledger_hash=entry.ledger_entry_hash,updated_at=clock_timestamp() where x.project_id=entry.project_id;
  elsif (cursor_row.applied_ledger_sequence,cursor_row.applied_ledger_hash) is distinct from (entry.ledger_sequence,entry.ledger_entry_hash) then
    raise exception using errcode='40001',message='record recovery cursor changed';
  end if;
  delete from record_platform_internal.record_deletion_effect_scopes x where x.transaction_id=pg_current_xact_id()
    and x.backend_pid=pg_backend_pid() and x.record_id=entry.object_id and x.operation_id=entry.operation_id and x.effect_kind='recovery';
  delete from record_platform_internal.record_deletion_recovery_sessions x where x.transaction_id=pg_current_xact_id() and x.backend_pid=pg_backend_pid();
  return query select entry.ledger_sequence,entry.ledger_entry_hash,digest,delete_content;
end $$;
revoke all on function record_platform_internal.record_deletion_recovery_surface_digest(text),
  record_platform_internal.record_deletion_recovery_id(text,text,text,text,text,text),public.record_deletion_replay_v1(bytea) from public;

-- The fixed kind comes only from the wrappers below. Preserve the descriptor
-- ordering and framing used by recorddeletion.digestAdapterSurfaces.
create function record_platform_internal.legacy_adapter_surface(kind text)
returns bytea language plpgsql immutable set search_path=pg_catalog as $$
declare names text[]; name text; body bytea;
begin
  case kind
    when 'record_activity_projection' then
      names:=array['record_activity_projection','record_activity_purge_receipts',
        'record_activity_revision_intervals','record_activity_subjects'];
    when 'record_search' then
      names:=array['record_search_documents','record_search_purge_receipts','record_search_subjects'];
    when 'record_evidence' then
      names:=array['evidence_capture_intents','evidence_copy_lineage','evidence_payload_gc_receipts',
        'evidence_payloads','evidence_purge_receipts','evidence_snapshots','record_revision_evidence'];
    when 'record_attachments' then
      names:=array['attachment_processor_jobs','attachment_purge_receipts','attachment_quota_accounts',
        'attachment_upload_parts','attachment_uploads','blob_gc_deletions','blob_gc_pins','blob_objects',
        'blob_publication_intents','content_processor_workspaces','content_workspace_purge_receipts',
        'record_attachments','record_revision_attachments'];
    else raise exception using errcode='22023',message='invalid legacy adapter';
  end case;
  body:=record_platform_internal.client_purge_field(convert_to('houfeng.record-deletion.adapter-surfaces.v1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(kind,'UTF8'))
    ||int8send(cardinality(names)::bigint);
  foreach name in array names loop
    body:=body||record_platform_internal.client_purge_field(convert_to(name,'UTF8'));
  end loop;
  return record_platform_internal.digest(body,'sha256');
end $$;

-- Activity/search frame the eight-byte count as a byte field. Evidence's
-- predecessor receipt wrote the count directly, and its immutable table has
-- no count column, so its replay count remains exactly zero.
create function record_platform_internal.legacy_adapter_receipt_digest(
  kind text, op text, project text, target text, surface bytea, removed bigint)
returns bytea language plpgsql immutable set search_path=pg_catalog as $$
declare domain text; body bytea;
begin
  if removed is null or removed<0 or octet_length(surface)<>32 then
    raise exception using errcode='22023',message='invalid legacy adapter receipt';
  end if;
  case kind
    when 'record_activity_projection' then domain:='houfeng.record-activity.deletion-receipt.v1';
    when 'record_search' then domain:='houfeng.record-search.deletion-receipt.v1';
    when 'record_evidence' then
      if removed<>0 then raise exception using errcode='22023',message='invalid evidence receipt count'; end if;
      domain:='houfeng.evidence.deletion-receipt.v1';
    else raise exception using errcode='22023',message='invalid legacy adapter';
  end case;
  body:=record_platform_internal.client_purge_field(convert_to(domain,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(project,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(target,'UTF8'))
    ||record_platform_internal.client_purge_field(surface);
  if kind='record_evidence' then body:=body||int8send(removed);
  else body:=body||record_platform_internal.client_purge_field(int8send(removed)); end if;
  return record_platform_internal.digest(body,'sha256');
end $$;

-- A pending assertion only: no command may use this table to authorize an
-- effect. Its deferred trigger rechecks the captured caller tuple at COMMIT and
-- removes the row; rollback also removes it. Scope rows remain separate and
-- are cleared by the authenticated effect entry point before it returns.
create table record_platform_internal.record_deletion_owner_commit_checks (
  transaction_id xid8 not null,
  backend_pid integer not null,
  operation_id text not null,
  owner_id text not null,
  owner_generation bigint not null,
  owner_expires_at timestamptz not null,
  primary key(transaction_id,backend_pid,operation_id)
);

create function record_platform_internal.record_deletion_owner_commit_trigger()
returns trigger language plpgsql security definer set search_path=pg_catalog as $$
begin
  if new.transaction_id<>pg_current_xact_id() or new.backend_pid<>pg_backend_pid()
    or not exists(select 1 from public.record_purge_operations o where o.operation_id=new.operation_id
      and o.owner_id=new.owner_id and o.owner_generation=new.owner_generation
      and o.owner_expires_at=new.owner_expires_at and o.owner_expires_at>clock_timestamp()
      and o.operation_state='online_purging') then
    raise exception using errcode='42501',message='deletion owner expired before transaction commit';
  end if;
  delete from record_platform_internal.record_deletion_owner_commit_checks c
    where c.transaction_id=new.transaction_id and c.backend_pid=new.backend_pid
      and c.operation_id=new.operation_id;
  return null;
end $$;
create constraint trigger record_deletion_owner_commit_check
  after insert on record_platform_internal.record_deletion_owner_commit_checks
  deferrable initially deferred for each row
  execute function record_platform_internal.record_deletion_owner_commit_trigger();

-- Only authenticated V1 commands use the legacy deferred owner check.
create function record_platform_internal.record_deletion_queue_owner_commit_check(
  op text, caller text, generation bigint, expires timestamptz)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  if op is null or caller is null or generation is null or generation<1 or expires is null then
    raise exception using errcode='22023',message='invalid deletion owner commit check';
  end if;
  if exists(select 1 from public.record_purge_operations o where o.operation_id=op and o.deletion_contract_version=2) then
    raise exception using errcode='42501',message='V2 deletion cannot queue a legacy commit check';
  end if;
  if not exists(select 1 from public.record_purge_operations o where o.operation_id=op and o.deletion_contract_version=1) then
    raise exception using errcode='42501',message='legacy deletion operation unavailable';
  end if;
  insert into record_platform_internal.record_deletion_owner_commit_checks
    (transaction_id,backend_pid,operation_id,owner_id,owner_generation,owner_expires_at)
    values(pg_current_xact_id(),pg_backend_pid(),op,caller,generation,expires)
    on conflict(transaction_id,backend_pid,operation_id) do nothing;
  if not exists(select 1 from record_platform_internal.record_deletion_owner_commit_checks c
    where c.transaction_id=pg_current_xact_id() and c.backend_pid=pg_backend_pid() and c.operation_id=op
      and (c.owner_id,c.owner_generation,c.owner_expires_at) is not distinct from (caller,generation,expires)) then
    raise exception using errcode='42501',message='deletion owner commit check conflict';
  end if;
end $$;
revoke all on table record_platform_internal.record_deletion_owner_commit_checks from public;
revoke all on function record_platform_internal.record_deletion_owner_commit_trigger(),
  record_platform_internal.record_deletion_queue_owner_commit_check(text,text,bigint,timestamptz) from public;


create function public.record_deletion_finish_v2(bytea)
returns boolean language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; r public.deletion_reservations; o public.record_purge_operations;
  f public.deletion_fence_leases; g public.record_deletion_gates; epoch bigint; expiry timestamptz; digest bytea;
  have_fence boolean;
begin
  perform record_platform_internal.record_deletion_worker_admit_v2();
  v:=record_platform_internal.record_deletion_command($1,
    array['operation_id','reservation_id','record_id','fence_epoch','owner_id','owner_generation','observed_owner_expires_at','receipt_digest'],
    array['fence_epoch','owner_generation']);
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or (v->>'owner_generation')::bigint<1
    or (v->>'fence_epoch')::bigint<1 or v->>'receipt_digest' !~ '^[0-9a-f]{64}$'
    or v->>'observed_owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception using errcode='22023',message='invalid V2 deletion completion';
  end if;
  expiry:=(v->>'observed_owner_expires_at')::timestamptz; digest:=decode(v->>'receipt_digest','hex');
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select x.* into r from public.deletion_reservations x where x.reservation_id=v->>'reservation_id' for update;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  select x.delivery_epoch into epoch from public.content_delivery_epochs x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  select x.* into f from public.deletion_fence_leases x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  have_fence:=found;
  select x.* into g from public.record_deletion_gates x where x.project_id=r.project_id and x.record_id=r.object_id for share;
  if not found then raise exception using errcode='42501',message='deletion gate unavailable'; end if;
  select x.* into o from public.record_purge_operations x where x.operation_id=v->>'operation_id' for update;
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  perform 1 from public.records x where x.project_id=r.project_id and x.record_id=r.object_id for update;
  if (r.deletion_contract_version,r.object_kind,r.object_id,r.fence_epoch)
      is distinct from (2::bigint,'record',v->>'record_id',(v->>'fence_epoch')::bigint)
    or (epoch is not null and epoch<>r.fence_epoch)
    or (o.reservation_id,o.project_id,o.deletion_contract_version) is distinct from (r.reservation_id,r.project_id,2::bigint)
    or (g.operation_id,g.project_id,g.record_id,g.fence_epoch,g.binding_digest,g.request_fingerprint,g.actor_scope_digest,g.actor_id)
      is distinct from (o.operation_id,r.project_id,r.object_id,r.fence_epoch,r.preview_binding_digest,r.request_fingerprint,r.actor_scope_digest,o.actor_id) then
    raise exception using errcode='42501',message='V2 deletion identity mismatch'; end if;
  if o.operation_state='online_purged' then
    if r.state<>'committed' or have_fence or o.completed_at is null or o.receipt_digest is distinct from digest
      or (o.owner_id,o.owner_generation,o.owner_expires_at) is distinct from ('',0::bigint,null::timestamptz)
      or (r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from ('',0::bigint,null::timestamptz) then
      raise exception using errcode='42501',message='V2 deletion completion replay conflict'; end if;
    return true;
  end if;
  if r.state<>'fenced' or o.operation_state<>'online_purging' or not have_fence
    or (r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or (o.owner_id,o.owner_generation,o.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or (f.owner_id,f.owner_generation,f.expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or expiry<=clock_timestamp() then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  lock table public.record_outbox in share row exclusive mode;
  begin
    lock table public.record_actions,public.record_comments,public.record_notification_deliveries,
      public.record_notification_delivery_attempts,public.record_notifications in share mode nowait;
  exception when lock_not_available then
    raise exception using errcode='40001',message='outbox closure route changed; restart transaction';
  end;
  perform 1 from public.attachment_quota_accounts q where q.project_id=r.project_id for update;
  lock table public.blob_objects in share row exclusive mode;
  lock table public.attachment_upload_parts in share row exclusive mode;
  lock table public.record_write_obligations,public.record_write_obligation_targets,
    public.blob_gc_deletions,public.attachment_purge_preparations,public.attachment_purge_targets,
    public.attachment_purge_workspace_targets,public.record_portability_cleanup_preparations,
    public.record_portability_cleanup_targets in share row exclusive mode;
  if not record_platform_internal.record_deletion_verify_online_receipts_v2(o.operation_id,digest) then
    raise exception using errcode='42501',message='V2 deletion receipt closure unavailable'; end if;
  perform record_platform_internal.local_blob_cleanup_operation(o.operation_id,v->>'owner_id',
    (v->>'owner_generation')::bigint,expiry,r.object_id);
  update public.deletion_reservations x set state='committed',owner_id='',owner_generation=0,owner_expires_at=null,completed_at=clock_timestamp()
    where x.reservation_id=r.reservation_id;
  update public.record_purge_operations x set operation_state='online_purged',receipt_digest=digest,completed_at=clock_timestamp(),updated_at=clock_timestamp(),
    owner_id='',owner_generation=0,owner_expires_at=null where x.operation_id=o.operation_id;
  delete from public.deletion_fence_leases x where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id
    and (x.owner_id,x.owner_generation,x.expires_at) is not distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry);
  if not found then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  if not exists(
    select 1 from public.record_purge_operations x join public.deletion_reservations y on y.reservation_id=x.reservation_id
    join public.record_deletion_gates z on z.operation_id=x.operation_id
    where x.operation_id=o.operation_id and x.reservation_id=r.reservation_id and x.project_id=r.project_id
      and x.deletion_contract_version=2 and x.operation_state='online_purged' and x.completed_at is not null
      and x.receipt_digest=digest and (x.owner_id,x.owner_generation,x.owner_expires_at) is not distinct from ('',0::bigint,null::timestamptz)
      and (y.project_id,y.object_kind,y.object_id,y.fence_epoch,y.deletion_contract_version,y.state)
        is not distinct from (r.project_id,'record',r.object_id,r.fence_epoch,2::bigint,'committed')
      and (y.owner_id,y.owner_generation,y.owner_expires_at) is not distinct from ('',0::bigint,null::timestamptz)
      and (z.operation_id,z.project_id,z.record_id,z.fence_epoch,z.binding_digest,z.request_fingerprint,z.actor_scope_digest,z.actor_id)
        is not distinct from (x.operation_id,y.project_id,y.object_id,y.fence_epoch,y.preview_binding_digest,y.request_fingerprint,y.actor_scope_digest,x.actor_id)
      and not exists(select 1 from public.deletion_fence_leases l where l.project_id=y.project_id and l.object_kind='record' and l.object_id=y.object_id)) then
    raise exception using errcode='42501',message='V2 deletion terminal invariant unavailable';
  end if;
  if expiry<=clock_timestamp() then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  return true;
end $$;
revoke all on function public.record_deletion_finish_v2(bytea) from public;

-- Lock/revalidate only; returning the parsed envelope does not grant permission
-- to mutate. Each fixed purge wrapper calls this helper again. The locks remain
-- transaction-local and follow admission -> graph/comparison -> reservation ->
-- epoch/fence -> gate -> operation/ledger -> root -> affected tables.
create function record_platform_internal.legacy_adapter_lock(body bytea, kind text)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; reservation public.deletion_reservations; operation public.record_purge_operations;
  entry record_platform_internal.record_deletion_verified_entries;
  admission public.source_authority_admission; epoch bigint; expiry timestamptz;
  discovered text; root_exists boolean;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='legacy adapter requires read committed';
  end if;
  perform public.source_application_admit();
  select s.* into admission from public.source_authority_admission s where s.singleton for share;
  if found and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=admission.generation and p.purpose='worker')) then
    raise exception using errcode='42501',message='legacy adapter worker admission unavailable';
  end if;
  v:=record_platform_internal.record_deletion_command(body,
    array['operation_id','record_id','reservation_id','fence_epoch','owner_id','owner_generation',
      'owner_expires_at','surface_digest','ledger_domain','ledger_sequence','ledger_entry_hash','witness_proof_digest'],
    array['fence_epoch','owner_generation','ledger_sequence']);
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$'
    or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$'
    or (v->>'owner_generation')::bigint<1 or (v->>'fence_epoch')::bigint<1
    or (v->>'ledger_sequence')::bigint<1
    or v->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or v->>'surface_digest' !~ '^[0-9a-f]{64}$'
    or v->>'ledger_domain' !~ '^[0-9a-f]{64}$'
    or v->>'ledger_entry_hash' !~ '^[0-9a-f]{64}$'
    or v->>'witness_proof_digest' !~ '^[0-9a-f]{64}$'
    or decode(v->>'surface_digest','hex')<>record_platform_internal.legacy_adapter_surface(kind) then
    raise exception using errcode='22023',message='invalid legacy adapter identity';
  end if;
  expiry:=(v->>'owner_expires_at')::timestamptz;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select o.reservation_id into strict discovered from public.record_purge_operations o
    where o.operation_id=v->>'operation_id';
  select r.* into strict reservation from public.deletion_reservations r
    where r.reservation_id=discovered for update;
  if reservation.reservation_id<>v->>'reservation_id' or reservation.project_id<>'default'
    or reservation.object_kind<>'record' or reservation.object_id<>v->>'record_id'
    or reservation.deletion_contract_version<>1 or reservation.state<>'committed'
    or reservation.fence_epoch<>(v->>'fence_epoch')::bigint then
    raise exception using errcode='42501',message='legacy adapter reservation mismatch';
  end if;
  if exists(select 1 from public.deletion_reservations other
    where other.project_id=reservation.project_id and other.object_kind=reservation.object_kind
      and other.object_id=reservation.object_id and other.reservation_id<>reservation.reservation_id
      and other.state in ('fenced','committed')) then
    raise exception using errcode='42501',message='legacy adapter conflicts with another reservation';
  end if;
  select e.delivery_epoch into epoch from public.content_delivery_epochs e
    where e.project_id=reservation.project_id and e.object_kind='record' and e.object_id=reservation.object_id for update;
  if found and epoch<>reservation.fence_epoch then
    raise exception using errcode='42501',message='legacy adapter epoch mismatch';
  end if;
  perform 1 from public.deletion_fence_leases l where l.project_id=reservation.project_id
    and l.object_kind='record' and l.object_id=reservation.object_id for update;
  perform 1 from public.record_deletion_gates g
    where g.project_id=reservation.project_id and g.record_id=reservation.object_id for share;
  if found then raise exception using errcode='42501',message='V2 gate conflicts with legacy adapter'; end if;
  select o.* into strict operation from public.record_purge_operations o where o.operation_id=v->>'operation_id' for update;
  if operation.reservation_id<>reservation.reservation_id or operation.project_id<>reservation.project_id
    or operation.deletion_contract_version<>1
    or not ((operation.operation_state='online_purging'
      and (operation.owner_id,operation.owner_generation,operation.owner_expires_at)
        is not distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
      and expiry>clock_timestamp())
      or (kind='record_attachments' and operation.operation_state='online_purged')) then
    raise exception using errcode='42501',message='legacy adapter caller owner unavailable';
  end if;
  select e.* into strict entry from record_platform_internal.record_deletion_verified_entries e
    where e.ledger_domain=decode(v->>'ledger_domain','hex') and e.ledger_sequence=(v->>'ledger_sequence')::bigint
      and e.ledger_entry_hash=decode(v->>'ledger_entry_hash','hex')
      and e.witness_proof_digest=decode(v->>'witness_proof_digest','hex');
  if entry.entry_type<>'delete_commit' or entry.deletion_contract_version<>1
    or (entry.operation_id,entry.deployment_id,entry.project_id,entry.actor_id,entry.reason_code,entry.object_kind,entry.object_id)
      is distinct from (operation.operation_id,operation.deployment_id,operation.project_id,operation.actor_id,
        operation.reason_code,reservation.object_kind,reservation.object_id)
    or (entry.token_commitment,entry.request_fingerprint)
      is distinct from (reservation.deletion_token_commitment,reservation.request_fingerprint)
    or (entry.ledger_sequence,entry.ledger_entry_hash,entry.witness_proof_digest,entry.entry_type)
      is distinct from (operation.ledger_sequence,operation.ledger_entry_hash,operation.witness_proof_digest,operation.ledger_entry_type) then
    raise exception using errcode='42501',message='legacy adapter verified ledger mismatch';
  end if;
  perform 1 from public.records r where r.project_id=reservation.project_id and r.record_id=reservation.object_id for update;
  root_exists:=found;
  if root_exists and epoch is null then
    raise exception using errcode='42501',message='legacy adapter root lacks deletion epoch';
  end if;
  case kind
    when 'record_activity_projection' then
      lock table public.record_activity_projection,public.record_activity_revision_intervals,
        public.record_activity_subjects in share row exclusive mode;
    when 'record_search' then
      lock table public.record_search_documents,public.record_search_subjects in share row exclusive mode;
    when 'record_evidence' then
      lock table public.evidence_capture_intents,public.evidence_payloads,public.evidence_snapshots,
        public.evidence_copy_lineage,public.record_revision_evidence in share row exclusive mode;
    when 'record_attachments' then
      perform 1 from public.attachment_quota_accounts q where q.project_id=reservation.project_id for update;
      lock table public.blob_objects in share row exclusive mode;
      lock table public.attachment_upload_parts in share row exclusive mode;
      lock table public.record_attachments,public.record_revision_attachments,public.attachment_uploads,
        public.attachment_processor_jobs,public.content_processor_workspaces,public.blob_gc_pins,
        public.blob_publication_intents,public.record_write_obligations,public.record_write_obligation_targets,
        public.attachment_purge_receipts in share row exclusive mode;
    else raise exception using errcode='22023',message='invalid legacy adapter';
  end case;
  if operation.operation_state='online_purging' and expiry<=clock_timestamp() then
    raise exception using errcode='42501',message='legacy adapter owner expired after locks';
  end if;
  return v;
end $$;

-- V2 uses the compound lease and gate, independently of the legacy ledger.
create function record_platform_internal.adapter_lock_v2(body bytea, kind text)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; r public.deletion_reservations; o public.record_purge_operations;
  f public.deletion_fence_leases; g public.record_deletion_gates;
  admission public.source_authority_admission; epoch bigint; expiry timestamptz; discovered text;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='V2 adapter requires read committed';
  end if;
  perform public.source_application_admit();
  select s.* into admission from public.source_authority_admission s where s.singleton for share;
  if found and (admission.mode<>'active' or not exists(select 1 from public.source_application_principals p
      where p.principal=session_user and p.generation=admission.generation and p.purpose='worker')) then
    raise exception using errcode='42501',message='V2 adapter worker admission unavailable';
  end if;
  if kind not in ('record_evidence','record_search','record_activity_projection') then
    raise exception using errcode='22023',message='invalid V2 adapter';
  end if;
  v:=record_platform_internal.record_deletion_command(body,
    array['operation_id','record_id','reservation_id','fence_epoch','owner_id','owner_generation','owner_expires_at','surface_digest'],
    array['fence_epoch','owner_generation']);
  if v->>'operation_id' !~ '^rpo_[a-z0-9]{1,64}$' or v->>'reservation_id' !~ '^drs_[a-z0-9]{1,64}$'
    or v->>'record_id' !~ '^(rec_[a-z0-9]{1,64}|rec2_[0-9a-f]{32})$'
    or v->>'owner_id' !~ '^[a-z0-9_-]{1,128}$' or (v->>'owner_generation')::bigint<1
    or (v->>'fence_epoch')::bigint<1 or v->>'surface_digest' !~ '^[0-9a-f]{64}$'
    or v->>'owner_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
    or decode(v->>'surface_digest','hex')<>record_platform_internal.legacy_adapter_surface(kind) then
    raise exception using errcode='22023',message='invalid V2 adapter identity';
  end if;
  expiry:=(v->>'owner_expires_at')::timestamptz;
  perform pg_advisory_xact_lock_shared(1213154899,1);
  perform pg_advisory_xact_lock(1213154899,81);
  select x.reservation_id into strict discovered from public.record_purge_operations x where x.operation_id=v->>'operation_id';
  select x.* into strict r from public.deletion_reservations x where x.reservation_id=discovered for update;
  if (r.reservation_id,r.project_id,r.object_kind,r.object_id,r.fence_epoch,r.deletion_contract_version,r.state)
      is distinct from (v->>'reservation_id','default','record',v->>'record_id',(v->>'fence_epoch')::bigint,2::bigint,'fenced') then
    raise exception using errcode='42501',message='V2 adapter reservation mismatch';
  end if;
  select x.delivery_epoch into epoch from public.content_delivery_epochs x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  if found and epoch<>r.fence_epoch then raise exception using errcode='42501',message='V2 adapter epoch mismatch'; end if;
  select x.* into strict f from public.deletion_fence_leases x
    where x.project_id=r.project_id and x.object_kind=r.object_kind and x.object_id=r.object_id for update;
  select x.* into strict g from public.record_deletion_gates x where x.project_id=r.project_id and x.record_id=r.object_id for share;
  select x.* into strict o from public.record_purge_operations x where x.operation_id=v->>'operation_id' for update;
  if (g.operation_id,g.project_id,g.record_id,g.fence_epoch) is distinct from (o.operation_id,r.project_id,r.object_id,r.fence_epoch)
    or (g.binding_digest,g.request_fingerprint,g.actor_scope_digest,g.actor_id)
      is distinct from (r.preview_binding_digest,r.request_fingerprint,r.actor_scope_digest,o.actor_id)
    or (o.reservation_id,o.project_id,o.deletion_contract_version,o.operation_state)
      is distinct from (r.reservation_id,r.project_id,2::bigint,'online_purging')
    or (r.owner_id,r.owner_generation,r.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or (f.owner_id,f.owner_generation,f.expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or (o.owner_id,o.owner_generation,o.owner_expires_at) is distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,expiry)
    or expiry<=clock_timestamp() then
    raise exception using errcode='42501',message='deletion owner lease lost';
  end if;
  perform 1 from public.records x where x.project_id=r.project_id and x.record_id=r.object_id for update;
  if found and epoch is null then raise exception using errcode='42501',message='V2 adapter root lacks epoch'; end if;
  case kind
    when 'record_activity_projection' then
      lock table public.record_activity_projection,public.record_activity_revision_intervals,public.record_activity_subjects in share row exclusive mode;
    when 'record_search' then
      lock table public.record_search_documents,public.record_search_subjects in share row exclusive mode;
    when 'record_evidence' then
      lock table public.evidence_capture_intents,public.evidence_payloads,public.evidence_snapshots,
        public.evidence_copy_lineage,public.record_revision_evidence in share row exclusive mode;
  end case;
  if expiry<=clock_timestamp() then raise exception using errcode='42501',message='deletion owner lease lost'; end if;
  return v;
end $$;
revoke all on function record_platform_internal.adapter_lock_v2(bytea,text) from public;

-- Checks SQL-visible metadata only; the Go caller independently validates the
-- compressed bytes returned below while these same table/graph locks are held.
create function record_platform_internal.legacy_evidence_metadata(target text)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  if exists(select 1 from public.evidence_snapshots s left join public.evidence_payloads p on p.payload_digest=s.payload_digest
      where s.record_id=target and (p.payload_digest is null or s.canonical_hash is distinct from s.payload_digest
        or p.payload_encoding is distinct from 'canonical_json_gzip_v1'
        or p.canonical_size_bytes is distinct from s.logical_size_bytes
        or p.canonical_size_bytes not between 1 and 5242880
        or p.compressed_size_bytes not between 1 and 6291456
        or octet_length(p.compressed_payload) is distinct from p.compressed_size_bytes)) then
    raise exception using errcode='55000',message='legacy evidence payload metadata mismatch';
  end if;
end $$;

create function record_platform_internal.evidence_purge_prepare(body bytea, version bigint)
returns table(snapshot_id text,payload_digest bytea,canonical_hash bytea,logical_size_bytes bigint,
  payload_encoding text,canonical_size_bytes bigint,compressed_size_bytes bigint)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb;
begin
  if version=1 then v:=record_platform_internal.legacy_adapter_lock(body,'record_evidence');
  elsif version=2 then v:=record_platform_internal.adapter_lock_v2(body,'record_evidence');
  else raise exception using errcode='22023',message='invalid evidence version'; end if;
  perform record_platform_internal.legacy_evidence_metadata(v->>'record_id');
  return query select s.snapshot_id,s.payload_digest,s.canonical_hash,s.logical_size_bytes,
    p.payload_encoding,p.canonical_size_bytes,p.compressed_size_bytes
    from public.evidence_snapshots s left join public.evidence_payloads p on p.payload_digest=s.payload_digest
    where s.record_id=v->>'record_id' order by s.snapshot_id;
  if version=2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'owner_id',
      (v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz,v->>'record_id');
  elsif not exists(select 1 from public.record_purge_operations o where o.operation_id=v->>'operation_id'
    and o.owner_id=v->>'owner_id' and o.owner_generation=(v->>'owner_generation')::bigint
    and o.owner_expires_at=(v->>'owner_expires_at')::timestamptz
    and o.owner_expires_at>clock_timestamp() and o.operation_state='online_purging') then
    raise exception using errcode='42501',message='legacy evidence owner expired before payload read';
  end if;
end $$;

-- The scalar return avoids a content-bearing tuplestore. The bytea command is
-- exact JSON {"authority": base64(original owner/ledger envelope),
-- "snapshot_id": exact id}; the nested envelope is fully authenticated again.
create function record_platform_internal.evidence_purge_payload(body bytea, version bigint)
returns bytea language plpgsql security definer set search_path=pg_catalog as $$
declare request jsonb; v jsonb; compressed bytea;
begin
  request:=record_platform_internal.record_deletion_command($1,array['authority','snapshot_id'],array[]::text[]);
  if request->>'snapshot_id' !~ '^evs_[a-z0-9]{1,64}$' then
    raise exception using errcode='22023',message='invalid evidence snapshot identity';
  end if;
  if version=1 then v:=record_platform_internal.legacy_adapter_lock(decode(request->>'authority','base64'),'record_evidence');
  elsif version=2 then v:=record_platform_internal.adapter_lock_v2(decode(request->>'authority','base64'),'record_evidence');
  else raise exception using errcode='22023',message='invalid evidence version'; end if;
  select p.compressed_payload into compressed
    from public.evidence_snapshots s join public.evidence_payloads p on p.payload_digest=s.payload_digest
    where s.record_id=v->>'record_id' and s.snapshot_id=request->>'snapshot_id'
      and s.canonical_hash=s.payload_digest and p.payload_encoding='canonical_json_gzip_v1'
      and p.canonical_size_bytes=s.logical_size_bytes and p.canonical_size_bytes between 1 and 5242880
      and p.compressed_size_bytes between 1 and 6291456
      and octet_length(p.compressed_payload)=p.compressed_size_bytes;
  if not found then raise exception using errcode='55000',message='legacy evidence payload unavailable'; end if;
  if version=2 then
    -- byteacat detoasts its inputs and copies the full value into a new bytea.
    -- A SELECT INTO or octet_length alone can leave an external TOAST pointer.
    compressed:=compressed || '\x'::bytea;
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'owner_id',
      (v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz,v->>'record_id');
  elsif not exists(select 1 from public.record_purge_operations o where o.operation_id=v->>'operation_id'
    and o.owner_id=v->>'owner_id' and o.owner_generation=(v->>'owner_generation')::bigint
    and o.owner_expires_at=(v->>'owner_expires_at')::timestamptz
    and o.owner_expires_at>clock_timestamp() and o.operation_state='online_purging') then
    raise exception using errcode='42501',message='legacy evidence owner expired before payload read';
  end if;
  return compressed;
end $$;

create function record_platform_internal.adapter_purge(body bytea, kind text, verify_only boolean, version bigint)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; expected_surface bytea; expected_receipt bytea; stored_surface bytea; stored_receipt bytea;
  stored_count bigint; stored_at timestamptz; has_receipt boolean; remaining boolean;
  removed bigint:=0; affected bigint; payload_digests bytea[]; expiry timestamptz;
begin
  if version=1 then v:=record_platform_internal.legacy_adapter_lock(body,kind);
  elsif version=2 then v:=record_platform_internal.adapter_lock_v2(body,kind);
  else raise exception using errcode='22023',message='invalid adapter version'; end if;
  expected_surface:=record_platform_internal.legacy_adapter_surface(kind);
  expiry:=(v->>'owner_expires_at')::timestamptz;
  if kind='record_evidence' then
    perform record_platform_internal.legacy_evidence_metadata(v->>'record_id');
    select expected_surface,r.receipt_digest,0::bigint,r.completed_at
      into stored_surface,stored_receipt,stored_count,stored_at
      from public.evidence_purge_receipts r where r.operation_id=v->>'operation_id'
        and r.surface_kind='record_evidence' for update;
  elsif kind='record_search' then
    select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
      into stored_surface,stored_receipt,stored_count,stored_at
      from public.record_search_purge_receipts r where r.operation_id=v->>'operation_id' and r.adapter_name='record_search' for update;
  elsif kind='record_activity_projection' then
    select r.removed_surface_digest,r.receipt_digest,r.removed_row_count,r.verified_absent_at
      into stored_surface,stored_receipt,stored_count,stored_at
      from public.record_activity_purge_receipts r where r.operation_id=v->>'operation_id'
        and r.adapter_name='record_activity_projection' for update;
  else raise exception using errcode='22023',message='invalid legacy adapter'; end if;
  has_receipt:=found;
  if verify_only and not has_receipt then
    raise exception using errcode='55000',message='legacy adapter receipt unavailable';
  end if;
  if not has_receipt then
    if kind='record_activity_projection' then
      delete from public.record_activity_subjects where record_id=v->>'record_id'
        or activity_id in(select activity_id from public.record_activity_projection where record_id=v->>'record_id');
      get diagnostics affected=row_count; removed:=removed+affected;
      delete from public.record_activity_projection where record_id=v->>'record_id';
      get diagnostics affected=row_count; removed:=removed+affected;
      delete from public.record_activity_revision_intervals where record_id=v->>'record_id';
      get diagnostics affected=row_count; removed:=removed+affected;
    elsif kind='record_search' then
      delete from public.record_search_subjects where record_id=v->>'record_id';
      get diagnostics affected=row_count; removed:=removed+affected;
      delete from public.record_search_documents where record_id=v->>'record_id';
      get diagnostics affected=row_count; removed:=removed+affected;
    else
      -- This is the only evidence scope. Caller owner/proof and all common
      -- locks were just revalidated. It disappears before returning and rolls
      -- back with the entire statement if any effect fails.
      insert into record_platform_internal.record_deletion_effect_scopes
        (transaction_id,backend_pid,record_id,operation_id,authority_kind,authority_digest,effect_kind)
        select pg_current_xact_id(),pg_backend_pid(),v->>'record_id',v->>'operation_id',
          case when version=1 then 'online_v1' else 'online_v2' end,
          case when version=1 then decode(v->>'ledger_entry_hash','hex') else g.binding_digest end,'evidence'
        from (select 1) singleton left join public.record_deletion_gates g on g.operation_id=v->>'operation_id';
      select coalesce(array_agg(distinct s.payload_digest),array[]::bytea[]) into payload_digests
        from public.evidence_snapshots s where s.record_id=v->>'record_id';
      delete from public.record_revision_evidence where record_id=v->>'record_id';
      delete from public.evidence_capture_intents where record_id=v->>'record_id';
      delete from public.evidence_copy_lineage where snapshot_id in
        (select snapshot_id from public.evidence_snapshots where record_id=v->>'record_id');
      delete from public.evidence_snapshots where record_id=v->>'record_id';
      delete from public.evidence_payloads p where p.payload_digest=any(payload_digests)
        and not exists(select 1 from public.evidence_snapshots s where s.payload_digest=p.payload_digest);
      delete from record_platform_internal.record_deletion_effect_scopes s
        where s.transaction_id=pg_current_xact_id() and s.backend_pid=pg_backend_pid()
          and s.record_id=v->>'record_id' and s.operation_id=v->>'operation_id' and s.effect_kind='evidence';
      -- The legacy evidence receipt has no persisted count.
      removed:=0;
    end if;
  end if;
  if kind='record_activity_projection' then
    select exists(select 1 from public.record_activity_subjects where record_id=v->>'record_id'
      union all select 1 from public.record_activity_projection where record_id=v->>'record_id'
      union all select 1 from public.record_activity_revision_intervals where record_id=v->>'record_id') into remaining;
  elsif kind='record_search' then
    select exists(select 1 from public.record_search_subjects where record_id=v->>'record_id'
      union all select 1 from public.record_search_documents where record_id=v->>'record_id') into remaining;
  else
    select exists(select 1 from public.record_revision_evidence where record_id=v->>'record_id'
      union all select 1 from public.evidence_capture_intents where record_id=v->>'record_id'
      union all select 1 from public.evidence_snapshots where record_id=v->>'record_id'
      union all select 1 from public.evidence_copy_lineage l join public.evidence_snapshots s on s.snapshot_id=l.snapshot_id
        where s.record_id=v->>'record_id') into remaining;
  end if;
  if remaining then raise exception using errcode='55000',message='legacy adapter surfaces remain'; end if;
  if not has_receipt then
    expected_receipt:=record_platform_internal.legacy_adapter_receipt_digest(
      kind,v->>'operation_id','default',v->>'record_id',expected_surface,removed);
    if kind='record_activity_projection' then
      insert into public.record_activity_purge_receipts
        (operation_id,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
        values(v->>'operation_id',expected_surface,expected_receipt,removed,transaction_timestamp())
        returning record_activity_purge_receipts.verified_absent_at into stored_at;
    elsif kind='record_search' then
      insert into public.record_search_purge_receipts
        (operation_id,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
        values(v->>'operation_id',expected_surface,expected_receipt,removed,transaction_timestamp())
        returning record_search_purge_receipts.verified_absent_at into stored_at;
    else
      insert into public.evidence_purge_receipts(operation_id,surface_kind,receipt_digest,completed_at)
        values(v->>'operation_id','record_evidence',expected_receipt,transaction_timestamp())
        returning evidence_purge_receipts.completed_at into stored_at;
    end if;
    stored_surface:=expected_surface; stored_receipt:=expected_receipt; stored_count:=removed;
  end if;
  if stored_surface is distinct from expected_surface or stored_count is null or stored_count<0 or stored_at is null
    or stored_receipt is distinct from record_platform_internal.legacy_adapter_receipt_digest(
      kind,v->>'operation_id','default',v->>'record_id',expected_surface,stored_count) then
    raise exception using errcode='55000',message='legacy adapter receipt mismatch';
  end if;
  if version=2 then
    perform record_platform_internal.local_blob_cleanup_operation(v->>'operation_id',v->>'owner_id',
      (v->>'owner_generation')::bigint,expiry,v->>'record_id');
  else
    if not exists(select 1 from public.record_purge_operations o where o.operation_id=v->>'operation_id'
      and o.owner_id=v->>'owner_id' and o.owner_generation=(v->>'owner_generation')::bigint
      and o.owner_expires_at=expiry and o.owner_expires_at>clock_timestamp() and o.operation_state='online_purging') then
      raise exception using errcode='42501',message='legacy adapter owner expired before completion';
    end if;
    perform record_platform_internal.record_deletion_queue_owner_commit_check(
      v->>'operation_id',v->>'owner_id',(v->>'owner_generation')::bigint,expiry);
  end if;
  return query select stored_surface,stored_receipt,stored_count,stored_at;
end $$;

create function record_platform_internal.legacy_adapter_purge(body bytea, kind text, verify_only boolean)
returns table(removed_surface_digest bytea,receipt_digest bytea,removed_row_count bigint,verified_absent_at timestamptz)
language sql security definer set search_path=pg_catalog as $$
  select * from record_platform_internal.adapter_purge(body,kind,verify_only,1) $$;

