-- Legacy source retirement remains a mutation prohibition after the C80 APP
-- converges. These rows are not W2 terminal pins and never invent a generation.
-- Only the direct management verifier installs them after actual W1/full-W2
-- reads under its live external fence. SQL independently checks the projection.
create table public.source_legacy_retirement_bindings (
  deployment_id text not null check (deployment_id ~ '^dp-[0-9a-f]{64}$'),
  project_id text not null check (project_id = 'default'),
  source_kind text not null check (source_kind in ('vps','monitoring_instance','target')),
  source_id text not null,
  operation_id text not null check (operation_id ~ '^[a-z0-9_-]{1,128}$'),
  ledger_domain bytea not null check (octet_length(ledger_domain)=32),
  ledger_sequence bigint not null check (ledger_sequence>0),
  ledger_entry_hash bytea not null check (octet_length(ledger_entry_hash)=32),
  canonical_entry bytea not null,
  witness_proof_digest bytea not null check (octet_length(witness_proof_digest)=32),
  first_installation_rid text not null check (first_installation_rid ~ '^[a-z0-9_-]{1,128}$'),
  installation jsonb not null check (jsonb_typeof(installation)='object'),
  primary key (deployment_id,project_id,source_kind,source_id),
  unique (deployment_id,project_id,operation_id),
  unique (ledger_domain,ledger_sequence)
);
create trigger source_legacy_retirement_immutable
  before update or delete on public.source_legacy_retirement_bindings
  for each row execute function record_platform_internal.reject_immutable_mutation();

create function record_platform_internal.source_legacy_retirement_command(body bytea)
returns jsonb language plpgsql immutable set search_path=pg_catalog as $$
declare v jsonb; item text; origin bytea; fingerprint bytea; material bytea;
  live bytea; floor bytea; witness_domain bytea; proof bytea;
begin
  v:=record_platform_internal.record_deletion_command(body,array[
    'deployment_id','project_id','source_kind','source_id','operation_id','actor_id',
    'app_domain_id','app_system_identifier','app_database_oid','app_database_name','app_epoch',
    'source_revision','last_live_scope','final_floor_scope','tombstone_unix_microseconds',
    'ledger_domain','ledger_sequence','ledger_entry_hash','previous_hash','canonical_entry',
    'token_commitment','request_fingerprint','confirmed_at_unix_microseconds',
    'witness_domain_id','witness_proof_digest','primary_head_sequence','primary_head_hash',
    'witness_head_sequence','witness_head_hash','maintenance_rid','maintenance_generation'],array[
    'app_database_oid','app_epoch','tombstone_unix_microseconds','ledger_sequence',
    'confirmed_at_unix_microseconds','primary_head_sequence','witness_head_sequence','maintenance_generation']);
  if v->>'deployment_id' !~ '^dp-[0-9a-f]{64}$' or v->>'project_id'<>'default'
    or v->>'source_kind' not in ('vps','monitoring_instance','target')
    or v->>'source_id' !~ (case v->>'source_kind' when 'vps' then '^vps_[0-9a-f]{16}$'
      when 'monitoring_instance' then '^mi_[0-9a-f]{16}$' else '^tg_[0-9a-f]{16}$' end)
    or v->>'operation_id' !~ '^[a-z0-9_-]{1,128}$' or v->>'actor_id' !~ '^usr_[a-z0-9]{1,64}$'
    or v->>'app_domain_id' !~ '^rd-[0-9a-f]{64}$' or v->>'witness_domain_id' !~ '^rd-[0-9a-f]{64}$'
    or v->>'app_system_identifier' !~ '^[1-9][0-9]{0,19}$'
    or v->>'app_database_name' !~ '^[a-z][a-z0-9_]{0,62}$'
    or (v->>'app_database_oid')::bigint not between 1 and 4294967295
    or (v->>'app_epoch')::bigint<=0 or (v->>'ledger_sequence')::bigint<=0
    or v->>'maintenance_rid' !~ '^[a-z0-9_-]{1,128}$'
    or (v->>'primary_head_sequence')::bigint<(v->>'witness_head_sequence')::bigint
    or (v->>'witness_head_sequence')::bigint<(v->>'ledger_sequence')::bigint then
    raise exception using errcode='22023',message='invalid legacy source installation identity';
  end if;
  foreach item in array array['source_revision','ledger_domain','ledger_entry_hash','previous_hash',
    'token_commitment','request_fingerprint','witness_proof_digest','primary_head_hash','witness_head_hash'] loop
    if v->>item !~ '^[0-9a-f]{64}$' or (item<>'previous_hash' and v->>item=repeat('0',64)) then
      raise exception using errcode='22023',message='invalid legacy source installation digest';
    end if;
  end loop;
  foreach item in array array['last_live_scope','final_floor_scope','canonical_entry'] loop
    if v->>item !~ '^([0-9a-f]{2})+$' then
      raise exception using errcode='22023',message='invalid legacy source canonical bytes';
    end if;
  end loop;
  if ((v->>'ledger_sequence')::bigint=1)<>(v->>'previous_hash'=repeat('0',64)) then
    raise exception using errcode='22023',message='invalid legacy source previous hash';
  end if;
  live:=decode(v->>'last_live_scope','hex'); floor:=decode(v->>'final_floor_scope','hex');
  if octet_length(live)>4096 or octet_length(floor)>4096 then
    raise exception using errcode='22023',message='legacy source scope exceeds limit';
  end if;
  origin:=record_platform_internal.source_retirement_field(convert_to('HOUFENG-SOURCE-RETIREMENT-ORIGIN-V1','UTF8'))
    ||int8send(1::bigint)
    ||record_platform_internal.source_retirement_field(convert_to(v->>'app_domain_id','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to(v->>'app_system_identifier','UTF8'))
    ||int8send((v->>'app_database_oid')::bigint)
    ||record_platform_internal.source_retirement_field(convert_to(v->>'app_database_name','UTF8'))
    ||int8send((v->>'app_epoch')::bigint)
    ||record_platform_internal.source_retirement_field(convert_to('retire_source_authorization','UTF8'));
  foreach item in array array['deployment_id','project_id','source_kind','source_id'] loop
    origin:=origin||record_platform_internal.source_retirement_field(convert_to(v->>item,'UTF8'));
  end loop;
  origin:=origin||record_platform_internal.source_retirement_field(decode(v->>'source_revision','hex'))
    ||record_platform_internal.source_retirement_field(live)||int8send((v->>'tombstone_unix_microseconds')::bigint);
  if octet_length(origin)>4096 then
    raise exception using errcode='22023',message='legacy source origin exceeds limit';
  end if;
  fingerprint:=record_platform_internal.source_retirement_field(convert_to('HOUFENG-SOURCE-RETIREMENT-REQUEST-V1','UTF8'));
  foreach item in array array['deployment_id','project_id','operation_id','actor_id','source_kind','source_id'] loop
    fingerprint:=fingerprint||record_platform_internal.source_retirement_field(convert_to(v->>item,'UTF8'));
  end loop;
  fingerprint:=fingerprint||record_platform_internal.source_retirement_field(decode(v->>'token_commitment','hex'))
    ||record_platform_internal.source_retirement_field(origin)||record_platform_internal.source_retirement_field(live)
    ||record_platform_internal.source_retirement_field(floor)||int8send(2::bigint);
  if record_platform_internal.digest(fingerprint,'sha256')<>decode(v->>'request_fingerprint','hex') then
    raise exception using errcode='22023',message='legacy source request fingerprint mismatch';
  end if;
  material:=record_platform_internal.source_retirement_field(convert_to('HOUFENG-SOURCE-RETIREMENT-LEDGER-V1','UTF8'))
    ||int8send(1::bigint)||record_platform_internal.source_retirement_field(decode(v->>'ledger_domain','hex'))
    ||int8send((v->>'ledger_sequence')::bigint)||record_platform_internal.source_retirement_field(decode(v->>'previous_hash','hex'))
    ||record_platform_internal.source_retirement_field(convert_to('delete_commit','UTF8'));
  foreach item in array array['deployment_id','project_id','operation_id','actor_id'] loop
    material:=material||record_platform_internal.source_retirement_field(convert_to(v->>item,'UTF8'));
  end loop;
  material:=material||record_platform_internal.source_retirement_field(convert_to('source_permanent_delete','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to(v->>'source_kind','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to(v->>'source_id','UTF8'))
    ||record_platform_internal.source_retirement_field(origin)||record_platform_internal.source_retirement_field(floor)
    ||record_platform_internal.source_retirement_field(record_platform_internal.digest(floor,'sha256'))
    ||record_platform_internal.source_retirement_field(decode(v->>'token_commitment','hex'))
    ||record_platform_internal.source_retirement_field(decode(v->>'request_fingerprint','hex'))
    ||record_platform_internal.source_retirement_field(convert_to('user_confirmed','UTF8'))
    ||int8send(2::bigint)||int8send(0::bigint)||int8send((v->>'confirmed_at_unix_microseconds')::bigint);
  if material<>decode(v->>'canonical_entry','hex')
    or record_platform_internal.digest(material,'sha256')<>decode(v->>'ledger_entry_hash','hex') then
    raise exception using errcode='22023',message='legacy source canonical projection mismatch';
  end if;
  witness_domain:=record_platform_internal.digest(
    record_platform_internal.source_retirement_field(convert_to('HOUFENG-RECORD-LEDGER-DOMAIN-V1','UTF8'))
    ||record_platform_internal.source_retirement_field(convert_to(v->>'witness_domain_id','UTF8')),'sha256');
  proof:=record_platform_internal.source_retirement_field(convert_to('HOUFENG-RECORD-LEDGER-WITNESS-V1','UTF8'))
    ||record_platform_internal.source_retirement_field(decode(v->>'ledger_domain','hex'))
    ||int8send((v->>'ledger_sequence')::bigint)||record_platform_internal.source_retirement_field(decode(v->>'ledger_entry_hash','hex'))
    ||record_platform_internal.source_retirement_field(witness_domain);
  if record_platform_internal.digest(proof,'sha256')<>decode(v->>'witness_proof_digest','hex') then
    raise exception using errcode='22023',message='legacy source full-witness binding mismatch';
  end if;
  return v;
end $$;

create function record_platform_internal.source_legacy_retirement_binding(body bytea, install boolean)
returns bytea language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; stored jsonb; admission public.source_authority_admission; candidate jsonb; item text;
  changing text[]:=array['primary_head_sequence','primary_head_hash','witness_head_sequence','witness_head_hash'];
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='source installation requires read committed';
  end if;
  v:=record_platform_internal.source_legacy_retirement_command(body);
  -- pg_control_system remains bootstrap-only. The live external verifier checks
  -- it independently; this command must not broaden that privilege boundary.
  perform 1 from public.record_platform_domain_identity d join pg_database db on db.datname=current_database()
    where d.domain_kind='application' and d.identity_mode='postgres_system'
      and d.domain_id=v->>'app_domain_id' and d.postgres_system_identifier=v->>'app_system_identifier'
      and d.database_oid=db.oid and d.database_oid=(v->>'app_database_oid')::oid
      and d.database_name=db.datname and d.database_name=v->>'app_database_name'
      and d.identity_epoch=(v->>'app_epoch')::bigint for share of d;
  if not found then raise exception using errcode='42501',message='source installation APP identity mismatch'; end if;
  perform 1 from public.source_deletion_tombstones t join public.deployment_contract_state d using(project_id)
    where t.project_id=v->>'project_id' and t.source_kind=v->>'source_kind' and t.source_id=v->>'source_id'
      and d.deployment_id=v->>'deployment_id' and d.activation_sequence=1
      and d.active_profile in ('postgres_sync','s3_worm') and d.minimum_fence_contract_version>0
      and t.authorization_floor_digest=record_platform_internal.digest(decode(v->>'final_floor_scope','hex'),'sha256')
      and extract(epoch from t.deleted_at)*1000000=(v->>'tombstone_unix_microseconds')::bigint for share of t,d;
  if not found then raise exception using errcode='42501',message='source installation tombstone mismatch'; end if;
  select * into admission from public.source_authority_admission where singleton for share;
  if found then
    if admission.mode<>'closed' or admission.recovery_id is distinct from v->>'maintenance_rid'
      or admission.generation<>(v->>'maintenance_generation')::bigint
      or admission.deployment_id<>v->>'deployment_id' or admission.witness_domain_id<>v->>'witness_domain_id'
      or not exists(select 1 from public.source_application_principals p where p.generation=admission.generation
        and p.purpose='admin' and p.principal=session_user) then
      raise exception using errcode='42501',message='source installation live recovery admission mismatch';
    end if;
  elsif (v->>'maintenance_generation')::bigint<>0 then
    raise exception using errcode='42501',message='source installation unenrolled generation mismatch';
  end if;
  candidate:=(v-array['maintenance_rid','maintenance_generation'])||jsonb_build_object(
    'first_installation_rid',v->>'maintenance_rid','first_installation_generation',(v->>'maintenance_generation')::bigint);
  if install then
    insert into public.source_legacy_retirement_bindings values (
      v->>'deployment_id',v->>'project_id',v->>'source_kind',v->>'source_id',v->>'operation_id',
      decode(v->>'ledger_domain','hex'),(v->>'ledger_sequence')::bigint,decode(v->>'ledger_entry_hash','hex'),
      decode(v->>'canonical_entry','hex'),decode(v->>'witness_proof_digest','hex'),v->>'maintenance_rid',candidate)
      on conflict (deployment_id,project_id,source_kind,source_id) do nothing;
  end if;
  select installation into strict stored from public.source_legacy_retirement_bindings
    where deployment_id=v->>'deployment_id' and project_id=v->>'project_id'
      and source_kind=v->>'source_kind' and source_id=v->>'source_id' for share;
  if (stored-changing-array['first_installation_rid','first_installation_generation'])
    is distinct from (v-changing-array['maintenance_rid','maintenance_generation']) then
    raise exception using errcode='23505',message='legacy source immutable installation conflict';
  end if;
  foreach item in array array['primary','witness'] loop
    if (stored->>(item||'_head_sequence'))::bigint>(v->>(item||'_head_sequence'))::bigint
      or ((stored->>(item||'_head_sequence'))::bigint=(v->>(item||'_head_sequence'))::bigint
        and stored->>(item||'_head_hash')<>v->>(item||'_head_hash')) then
      raise exception using errcode='23505',message='legacy source installation head rollback';
    end if;
  end loop;
  return convert_to(stored::text,'UTF8');
end $$;
create function public.source_legacy_retirement_install(bytea)
returns bytea language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.source_legacy_retirement_binding($1,true) $$;
create function public.source_legacy_retirement_verify(bytea)
returns bytea language sql security definer set search_path=pg_catalog as $$
  select record_platform_internal.source_legacy_retirement_binding($1,false) $$;
create function public.source_legacy_retirement_blocked(text,text)
returns boolean language sql stable security definer set search_path=pg_catalog as $$
  select exists(select 1 from public.source_legacy_retirement_bindings
    where project_id='default' and source_kind=$1 and source_id=$2) $$;
revoke all on table public.source_legacy_retirement_bindings from public;
revoke all on function record_platform_internal.source_legacy_retirement_command(bytea),
  record_platform_internal.source_legacy_retirement_binding(bytea,boolean),
  public.source_legacy_retirement_install(bytea),public.source_legacy_retirement_verify(bytea),
  public.source_legacy_retirement_blocked(text,text) from public;

-- The deferred primary-subject validator keeps its identity, body and trigger
-- timing. Only its execution authority changes in this successor.
alter function record_platform_internal.validate_record_revision_primary_subject() security definer;

-- Generic serving callers already hold the epoch. Re-locking that same row
-- preserves epoch -> fence order without a comparison advisory dependency.
create function public.record_serving_deletion_fence_lock(bytea)
returns table(owner_id text,owner_generation bigint,expires_at timestamptz,live boolean)
language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; fence public.deletion_fence_leases;
begin
  perform record_platform_internal.local_blob_direct_login();
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception using errcode='25000',message='serving fence requires read committed';
  end if;
  perform public.source_application_admit();
  v:=record_platform_internal.record_deletion_command($1,
    array['project_id','object_kind','object_id'],array[]::text[]);
  if v->>'project_id'<>'default'
    or v->>'object_kind' !~ '^[a-z0-9_]{1,64}$'
    or v->>'object_id' !~ '^[a-z0-9_]{1,128}$'
    or v->>'object_kind' ~ 'drt1_[a-z0-9_]{43}'
    or v->>'object_id' ~ 'drt1_[a-z0-9_]{43}' then
    raise exception using errcode='22023',message='invalid serving object';
  end if;
  perform 1 from public.content_delivery_epochs e where e.project_id=v->>'project_id'
    and e.object_kind=v->>'object_kind' and e.object_id=v->>'object_id' for update;
  if not found then
    raise exception using errcode='P0002',message='content delivery epoch missing';
  end if;
  select l.* into fence from public.deletion_fence_leases l where l.project_id=v->>'project_id'
    and l.object_kind=v->>'object_kind' and l.object_id=v->>'object_id' for update;
  if found then
    return query select fence.owner_id,fence.owner_generation,fence.expires_at,
      fence.expires_at>clock_timestamp();
  end if;
end $$;
revoke all on function public.record_serving_deletion_fence_lock(bytea) from public;

create function record_platform_internal.attachment_v1_time(t timestamptz)
returns text language sql immutable strict security definer set search_path=pg_catalog
as $$ select to_char(t at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') $$;

create function record_platform_internal.attachment_v1_deletion_id(op text,backend text,key text,version text)
returns text language sql immutable strict security definer set search_path=pg_catalog as $$
  select 'bgd_'||encode(record_platform_internal.digest(
    record_platform_internal.client_purge_field(convert_to('houfeng.attachments.purge-claim.v1','UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(op,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(backend,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(key,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(version,'UTF8')),'sha256'),'hex')
$$;

create function record_platform_internal.attachment_v1_gc_digest(g public.blob_gc_deletions, result text)
returns bytea language sql immutable strict security definer set search_path=pg_catalog as $$
  select record_platform_internal.digest(
    record_platform_internal.client_purge_field(convert_to('houfeng.attachments.blob-gc-receipt.v1','UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(g.deletion_id,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(g.project_id,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to('permanent','UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(g.blob_key,'UTF8'))
    ||record_platform_internal.client_purge_field(g.sha256_digest)
    ||record_platform_internal.client_purge_field(convert_to(g.object_version,'UTF8'))
    ||record_platform_internal.client_purge_field(int8send(g.size_bytes))
    ||record_platform_internal.client_purge_field(convert_to(g.backend_kind,'UTF8'))
    ||record_platform_internal.client_purge_field(convert_to(result,'UTF8')),'sha256')
$$;

create function record_platform_internal.attachment_v1_gc_document(g public.blob_gc_deletions)
returns jsonb language plpgsql stable strict security definer set search_path=pg_catalog as $$
begin
  if g.operation_id is null or g.project_id<>'default' or g.backend_kind<>'s3'
    or g.deletion_id<>record_platform_internal.attachment_v1_deletion_id(g.operation_id,g.backend_kind,g.blob_key,g.object_version)
    or g.purge_mode<>'permanent' or g.local_contract_version<>1 or g.namespace_id is not null
    or g.incarnation_id is not null or g.cleanup_dispatch_id is not null or g.inventory_digest is not null
    or g.final_identity_bound or g.final_was_present is not null or g.final_device is not null
    or g.final_inode is not null or g.completion_command is not null
    or g.blob_key<>'sha256/'||encode(g.sha256_digest,'hex') or octet_length(g.sha256_digest)<>32
    or octet_length(g.object_version) not between 1 and 1024 or g.size_bytes<=0
    or g.owner_generation<1 or g.attempt<1 or not isfinite(g.blob_created_at)
    or not isfinite(g.lease_expires_at) then
    raise exception using errcode='55000',message='attachment GC identity conflict';
  end if;
  if not ((g.deletion_state='claimed' and g.retry_at is null and g.receipt_digest is null
       and g.physical_delete_result is null and g.completed_at is null)
    or (g.deletion_state='retry_wait' and g.retry_at is not null and isfinite(g.retry_at)
       and g.receipt_digest is null and g.physical_delete_result is null and g.completed_at is null)
    or (g.deletion_state='completed' and g.retry_at is null and g.completed_at is not null
       and isfinite(g.completed_at) and g.physical_delete_result in ('deleted','already_absent')
       and g.receipt_digest=record_platform_internal.attachment_v1_gc_digest(g,g.physical_delete_result))) then
    raise exception using errcode='55000',message='attachment GC proof conflict';
  end if;
  return jsonb_build_object('claim',jsonb_build_object(
    'operation_id',g.operation_id,'deletion_id',g.deletion_id,'project_id',g.project_id,
    'backend_kind',g.backend_kind,'key',g.blob_key,'version_id',g.object_version,
    'sha256',encode(g.sha256_digest,'hex'),'size_bytes',g.size_bytes,
    'blob_created_at',record_platform_internal.attachment_v1_time(g.blob_created_at),
    'cleanup_owner_id',g.owner_id,'cleanup_owner_generation',g.owner_generation,'attempt',g.attempt,
    'cleanup_expires_at',record_platform_internal.attachment_v1_time(g.lease_expires_at)),
    'state',g.deletion_state,'retry_at',record_platform_internal.attachment_v1_time(g.retry_at),
    'physical_delete_result',g.physical_delete_result,'receipt_digest',encode(g.receipt_digest,'hex'),
    'completed_at',record_platform_internal.attachment_v1_time(g.completed_at));
end $$;

create function record_platform_internal.attachment_v1_live(v jsonb)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  if not exists(select 1 from public.record_purge_operations o where o.operation_id=v->>'operation_id'
    and o.operation_state='online_purging' and (o.owner_id,o.owner_generation,o.owner_expires_at)
      is not distinct from (v->>'owner_id',(v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz)
    and o.owner_expires_at>clock_timestamp()) then
    raise exception using errcode='42501',message='attachment operation owner unavailable';
  end if;
end $$;

create function record_platform_internal.attachment_v1_queue(v jsonb)
returns void language plpgsql security definer set search_path=pg_catalog as $$
begin
  perform record_platform_internal.attachment_v1_live(v);
  perform record_platform_internal.record_deletion_queue_owner_commit_check(v->>'operation_id',v->>'owner_id',
    (v->>'owner_generation')::bigint,(v->>'owner_expires_at')::timestamptz);
end $$;

-- Checks the three immutable V1 receipts and all associated GC proofs. Pending
-- claims remain visible so recovery can resolve them; this function mints none.
create function record_platform_internal.attachment_v1_projection(v jsonb)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare n bigint; name text; marker bytea; expected bytea; r public.attachment_purge_receipts;
  counts jsonb:='{}'::jsonb; latest timestamptz; docs jsonb; gc_count bigint;
  g public.blob_gc_deletions; operation_state text;
begin
  select count(*) into n from public.attachment_purge_receipts where operation_id=v->>'operation_id';
  if n=0 then
    if exists(select 1 from public.record_purge_operations o where o.operation_id=v->>'operation_id' and o.operation_state='online_purged') then
      raise exception using errcode='55000',message='terminal attachment proof unavailable';
    end if;
    return 'null'::jsonb;
  end if;
  if n<>3 then raise exception using errcode='55000',message='attachment receipt set conflict'; end if;
  foreach name in array array['logical_attachment','upload_part','blob_object'] loop
    marker:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-marker.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(v->>'operation_id','UTF8'))
      ||record_platform_internal.client_purge_field(convert_to(name,'UTF8')),'sha256');
    select * into r from public.attachment_purge_receipts x where x.operation_id=v->>'operation_id'
      and x.adapter_name='record_attachments' and x.surface_kind=name and x.object_version_digest=marker;
    if not found then raise exception using errcode='55000',message='attachment receipt missing'; end if;
    expected:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-receipt.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(v->>'operation_id','UTF8'))
      ||record_platform_internal.client_purge_field(convert_to(name,'UTF8'))||marker
      ||decode(v->>'surface_digest','hex')||int8send(r.removed_row_count),'sha256');
    if r.removed_surface_digest<>decode(v->>'surface_digest','hex') or r.receipt_digest<>expected
      or r.removed_row_count<0 or not isfinite(r.verified_absent_at) then
      raise exception using errcode='55000',message='attachment receipt proof conflict';
    end if;
    counts:=counts||jsonb_build_object(name,r.removed_row_count);
    latest:=greatest(latest,r.verified_absent_at);
  end loop;
  if exists(select 1 from public.record_attachments a where a.project_id='default' and
      (a.record_id=v->>'record_id' or a.draft_id in (select d.draft_id from public.record_drafts d where d.record_id=v->>'record_id')))
    or exists(select 1 from public.record_revision_attachments x where x.record_id=v->>'record_id')
    or exists(select 1 from public.record_write_obligations w where w.cleanup_completed_at is null and w.published_at is null
      and (w.operation_id=v->>'operation_id' or w.record_id=v->>'record_id'
        or exists(select 1 from public.record_write_obligation_targets t
          where t.obligation_id=w.obligation_id and t.record_id=v->>'record_id'))) then
    raise exception using errcode='55000',message='attachment purge absence conflict';
  end if;
  -- Historical claims are exclusively checked by the old nine-adapter oracle;
  -- they cannot authorize new remote IO through this protocol.
  if exists(select 1 from public.blob_gc_deletions x where x.operation_id is null
      and x.local_contract_version=1 and x.purge_mode='permanent' and x.owner_id=v->>'operation_id') then
    raise exception using errcode='55000',message='historical attachment claim requires legacy proof';
  end if;
  docs:='[]'::jsonb; gc_count:=0;
  for g in select x.* from public.blob_gc_deletions x where x.operation_id=v->>'operation_id'
      order by x.backend_kind collate "C",x.blob_key collate "C",x.object_version collate "C",x.deletion_id collate "C" loop
    docs:=docs||jsonb_build_array(record_platform_internal.attachment_v1_gc_document(g));
    gc_count:=gc_count+1;
  end loop;
  if gc_count<>(counts->>'blob_object')::bigint then
    raise exception using errcode='55000',message='attachment GC count conflict';
  end if;
  select o.operation_state into strict operation_state from public.record_purge_operations o where o.operation_id=v->>'operation_id';
  if operation_state='online_purged' and exists(select 1 from public.blob_gc_deletions x
      where x.operation_id=v->>'operation_id' and x.deletion_state<>'completed') then
    raise exception using errcode='55000',message='terminal attachment proof incomplete';
  end if;
  return jsonb_build_object('counts',counts,'verified_at',record_platform_internal.attachment_v1_time(latest),
    'claims',docs,'required_backends','[]'::jsonb);
end $$;

create function record_platform_internal.record_attachment_purge_v1(body bytea,verify_only boolean)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare v jsonb; projection jsonb; ids text[]; objects public.blob_objects[]; b public.blob_objects;
  released_logical bigint; logical_rows bigint:=0; part_rows bigint:=0; n bigint; gc_count bigint:=0;
  name text; marker bytea; proof bytea; deletion text; stamp timestamptz:=transaction_timestamp();
begin
  v:=record_platform_internal.legacy_adapter_lock(body,'record_attachments');
  projection:=record_platform_internal.attachment_v1_projection(v);
  if verify_only then return projection; end if;
  perform record_platform_internal.attachment_v1_live(v);
  if projection<>'null'::jsonb then return projection; end if;
  if exists(select 1 from public.blob_gc_deletions g where g.operation_id=v->>'operation_id'
      or (g.operation_id is null and g.local_contract_version=1 and g.purge_mode='permanent' and g.owner_id=v->>'operation_id')) then
    raise exception using errcode='55000',message='attachment claim without preparation';
  end if;
  select coalesce(array_agg(a.attachment_id order by a.attachment_id),'{}'::text[]),
    coalesce(sum(a.logical_size_bytes) filter(where a.attachment_state='available'),0)
    into ids,released_logical from public.record_attachments a where a.project_id='default'
      and (a.record_id=v->>'record_id' or a.draft_id in (select d.draft_id from public.record_drafts d where d.record_id=v->>'record_id'));
  if exists(select 1 from public.record_attachments a where a.attachment_id=any(ids)
      and a.attachment_state not in ('available','rejected','expired'))
    or exists(select 1 from public.attachment_uploads u where u.attachment_id=any(ids)
      and (u.upload_state not in ('available','rejected','expired')
        or (u.temporary_object_key is not null and u.temporary_object_deleted_at is null)))
    or exists(select 1 from public.attachment_processor_jobs j where j.attachment_id=any(ids)
      and j.processor_state not in ('succeeded','rejected','expired'))
    or exists(select 1 from public.content_processor_workspaces w join public.attachment_processor_jobs j using(processor_job_id)
      where j.attachment_id=any(ids) and w.workspace_state<>'purged')
    or exists(select 1 from public.blob_publication_intents p where p.publication_state<>'completed' and
      ((p.owner_kind='upload' and p.owner_id in (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(ids)))
       or (p.owner_kind='processor_preview' and p.owner_id in (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(ids)))))
    or exists(select 1 from public.record_write_obligations w where w.cleanup_completed_at is null and w.published_at is null
      and (w.operation_id=v->>'operation_id' or w.record_id=v->>'record_id'
        or exists(select 1 from public.record_write_obligation_targets t where t.obligation_id=w.obligation_id and t.record_id=v->>'record_id')
        or (w.origin_kind='upload' and w.origin_id in (select u.upload_id from public.attachment_uploads u where u.attachment_id=any(ids)))
        or (w.origin_kind='processor_preview' and w.origin_id in (select j.processor_job_id from public.attachment_processor_jobs j where j.attachment_id=any(ids))))) then
    raise exception using errcode='55000',message='attachment purge has active publication responsibility';
  end if;
  select coalesce(array_agg(candidate order by candidate.backend_kind collate "C",candidate.blob_key collate "C",candidate.object_version collate "C"),'{}'::public.blob_objects[])
    into objects from public.blob_objects candidate where exists(select 1 from public.record_attachments a where a.attachment_id=any(ids)
      and ((a.blob_key,a.blob_object_version)=(candidate.blob_key,candidate.object_version)
        or (a.preview_blob_key,a.preview_blob_object_version)=(candidate.blob_key,candidate.object_version)));
  -- Configuration is checked by the coordinator before this transaction commits,
  -- including backends whose objects remain shared and produce no GC claim.
  foreach b in array objects loop
    if b.backend_kind is distinct from 's3' or b.namespace_id is not null then
      raise exception using errcode='55000',message='attachment backend requires another authority';
    end if;
  end loop;
  insert into record_platform_internal.record_deletion_effect_scopes
    (transaction_id,backend_pid,record_id,operation_id,authority_kind,authority_digest,effect_kind)
    values(pg_current_xact_id(),pg_backend_pid(),v->>'record_id',v->>'operation_id','online_v1',decode(v->>'ledger_entry_hash','hex'),'attachment');
  delete from public.content_processor_workspaces w using public.attachment_processor_jobs j where w.processor_job_id=j.processor_job_id and j.attachment_id=any(ids);
  get diagnostics n=row_count; logical_rows:=logical_rows+n;
  delete from public.attachment_processor_jobs where attachment_id=any(ids);
  get diagnostics n=row_count; logical_rows:=logical_rows+n;
  delete from public.attachment_upload_parts p using public.attachment_uploads u where p.upload_id=u.upload_id and u.attachment_id=any(ids);
  get diagnostics part_rows=row_count;
  delete from public.attachment_uploads where attachment_id=any(ids);
  get diagnostics n=row_count; logical_rows:=logical_rows+n;
  delete from public.record_revision_attachments where attachment_id=any(ids);
  get diagnostics n=row_count; logical_rows:=logical_rows+n;
  delete from public.record_attachments where attachment_id=any(ids);
  get diagnostics n=row_count; logical_rows:=logical_rows+n;
  if n<>cardinality(ids) then raise exception using errcode='55000',message='attachment target changed'; end if;
  if cardinality(ids)>0 then
    update public.attachment_quota_accounts q set logical_bytes=q.logical_bytes-released_logical,
      quota_version=q.quota_version+1,updated_at=clock_timestamp()
      where q.project_id='default' and q.logical_bytes>=released_logical;
    if not found then raise exception using errcode='55000',message='attachment quota conflict'; end if;
  end if;
  foreach b in array objects loop
    if exists(select 1 from public.record_attachments a where (a.blob_key,a.blob_object_version)=(b.blob_key,b.object_version)
       or (a.preview_blob_key,a.preview_blob_object_version)=(b.blob_key,b.object_version)) then continue; end if;
    if exists(select 1 from public.blob_gc_pins p where p.blob_key=b.blob_key and p.blob_object_version=b.object_version and p.expires_at>clock_timestamp())
      or exists(select 1 from public.attachment_upload_parts p where p.sha256_digest=b.sha256_digest and p.object_version=b.object_version)
      or exists(select 1 from public.blob_publication_intents p where p.blob_key=b.blob_key and p.publication_state<>'completed')
      or exists(select 1 from public.record_write_obligations w where w.canonical_key=b.blob_key and w.cleanup_completed_at is null and w.published_at is null)
      or exists(select 1 from public.blob_gc_deletions g where g.blob_key=b.blob_key and g.object_version=b.object_version and g.deletion_state<>'completed') then
      raise exception using errcode='55000',message='attachment purge has active publication responsibility';
    end if;
    delete from public.blob_gc_pins p where p.blob_key=b.blob_key and p.blob_object_version=b.object_version and p.expires_at<=clock_timestamp();
    deletion:=record_platform_internal.attachment_v1_deletion_id(v->>'operation_id',b.backend_kind,b.blob_key,b.object_version);
    insert into public.blob_gc_deletions(deletion_id,project_id,purge_mode,blob_key,sha256_digest,object_version,size_bytes,
      backend_kind,blob_created_at,deletion_state,owner_id,owner_generation,attempt,lease_expires_at,operation_id,local_contract_version)
      values(deletion,'default','permanent',b.blob_key,b.sha256_digest,b.object_version,b.size_bytes,'s3',b.created_at,
        'claimed',v->>'owner_id',1,1,clock_timestamp()+interval '1 minute',v->>'operation_id',1);
    delete from public.blob_objects x where (x.blob_key,x.object_version,x.sha256_digest,x.size_bytes,x.backend_kind)
      =(b.blob_key,b.object_version,b.sha256_digest,b.size_bytes,b.backend_kind);
    if not found then raise exception using errcode='55000',message='attachment blob identity changed'; end if;
    gc_count:=gc_count+1;
  end loop;
  foreach name in array array['logical_attachment','upload_part','blob_object'] loop
    n:=case name when 'logical_attachment' then logical_rows when 'upload_part' then part_rows else gc_count end;
    marker:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-marker.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(v->>'operation_id','UTF8'))
      ||record_platform_internal.client_purge_field(convert_to(name,'UTF8')),'sha256');
    proof:=record_platform_internal.digest(record_platform_internal.client_purge_field(convert_to('houfeng.attachments.deletion-receipt.v1','UTF8'))
      ||int8send(1::bigint)||record_platform_internal.client_purge_field(convert_to(v->>'operation_id','UTF8'))
      ||record_platform_internal.client_purge_field(convert_to(name,'UTF8'))||marker||decode(v->>'surface_digest','hex')||int8send(n),'sha256');
    insert into public.attachment_purge_receipts(operation_id,surface_kind,object_version_digest,removed_surface_digest,receipt_digest,removed_row_count,verified_absent_at)
      values(v->>'operation_id',name,marker,decode(v->>'surface_digest','hex'),proof,n,stamp);
  end loop;
  delete from record_platform_internal.record_deletion_effect_scopes s where s.transaction_id=pg_current_xact_id()
    and s.backend_pid=pg_backend_pid() and s.operation_id=v->>'operation_id' and s.effect_kind='attachment';
  perform record_platform_internal.attachment_v1_queue(v);
  return record_platform_internal.attachment_v1_projection(v)||jsonb_build_object(
    'required_backends',case when cardinality(objects)>0 then '["s3"]'::jsonb else '[]'::jsonb end);
end $$;

-- Parse raw JSON before any jsonb conversion. Nested authority and claim use
-- the existing scalar exact-field parser, which rejects duplicate names.
create function record_platform_internal.record_attachment_gc_v1(body bytea,kind text)
returns jsonb language plpgsql security definer set search_path=pg_catalog as $$
declare raw json; auth json; claim_raw json; receipt_raw json; v jsonb; c jsonb; receipt jsonb;
  fields text[]; g public.blob_gc_deletions; doc jsonb; result text; digest bytea;
  deletion text; cleanup_owner text; lease_ms bigint; retry_time timestamptz; state text;
begin
  if kind not in ('claim','complete','retry','resolve') or body is null or octet_length(body) not between 1 and 262144 then
    raise exception using errcode='22023',message='invalid attachment GC command';
  end if;
  raw:=convert_from(body,'UTF8')::json;
  fields:=case kind when 'claim' then array['authority','deletion_id','cleanup_owner_id','cleanup_lease_ms']
    when 'retry' then array['authority','claim','retry_at'] else array['authority','claim','receipt'] end;
  if json_typeof(raw) is distinct from 'object' or (select count(*) from json_each(raw))<>cardinality(fields)
    or (select count(distinct x.key) from json_each(raw) x)<>cardinality(fields)
    or exists(select 1 from json_each(raw) x where not(x.key=any(fields)) or json_typeof(x.value)='null') then
    raise exception using errcode='22023',message='invalid attachment GC fields';
  end if;
  auth:=raw->'authority';
  if json_typeof(auth) is distinct from 'object' then raise exception using errcode='22023',message='invalid attachment authority'; end if;
  if (select count(*) from json_each(auth))<>(select count(distinct x.key) from json_each(auth) x) then
    raise exception using errcode='22023',message='duplicate attachment authority field';
  end if;
  if kind<>'claim' then
    claim_raw:=raw->'claim';
    if json_typeof(claim_raw) is distinct from 'object' then
      raise exception using errcode='22023',message='invalid attachment GC tuple';
    end if;
    if (select count(*) from json_each(claim_raw))<>(select count(distinct x.key) from json_each(claim_raw) x) then
      raise exception using errcode='22023',message='duplicate attachment GC tuple field';
    end if;
    if kind in ('complete','resolve') then
      receipt_raw:=raw->'receipt';
      if json_typeof(receipt_raw) is distinct from 'object' then
        raise exception using errcode='22023',message='invalid attachment GC receipt';
      end if;
      if (select count(*) from json_each(receipt_raw))<>(select count(distinct x.key) from json_each(receipt_raw) x) then
        raise exception using errcode='22023',message='duplicate attachment GC receipt field';
      end if;
    end if;
  end if;
  -- legacy_adapter_lock validates the original authority JSON, including duplicates.
  v:=record_platform_internal.legacy_adapter_lock(convert_to(auth::text,'UTF8'),'record_attachments');
  if kind='claim' then
    if json_typeof(raw->'deletion_id')<>'string' or json_typeof(raw->'cleanup_owner_id')<>'string'
      or json_typeof(raw->'cleanup_lease_ms')<>'number' or (raw->'cleanup_lease_ms')::text !~ '^(0|[1-9][0-9]*)$' then
      raise exception using errcode='22023',message='invalid attachment GC claim fields';
    end if;
    deletion:=raw->>'deletion_id'; cleanup_owner:=raw->>'cleanup_owner_id'; lease_ms:=(raw->>'cleanup_lease_ms')::bigint;
    if deletion !~ '^bgd_[a-z0-9]{1,64}$' or cleanup_owner !~ '^[a-z0-9_-]{1,128}$' or lease_ms<>60000 then
      raise exception using errcode='22023',message='invalid attachment GC claim';
    end if;
  else
    claim_raw:=raw->'claim';
    c:=record_platform_internal.record_deletion_command(convert_to(claim_raw::text,'UTF8'),
      array['operation_id','deletion_id','project_id','backend_kind','key','version_id','sha256','size_bytes',
        'blob_created_at','cleanup_owner_id','cleanup_owner_generation','attempt','cleanup_expires_at'],
      array['size_bytes','cleanup_owner_generation','attempt']);
    deletion:=c->>'deletion_id';
    if c->>'operation_id'<>v->>'operation_id' or deletion !~ '^bgd_[a-z0-9]{1,64}$'
      or c->>'project_id'<>'default' or c->>'backend_kind'<>'s3'
      or c->>'sha256' !~ '^[0-9a-f]{64}$' or c->>'key'<>'sha256/'||(c->>'sha256')
      or octet_length(c->>'version_id') not between 1 and 1024 or (c->>'size_bytes')::bigint<1
      or c->>'cleanup_owner_id' !~ '^[a-z0-9_-]{1,128}$' or (c->>'cleanup_owner_generation')::bigint<1
      or (c->>'attempt')::bigint<1
      or c->>'blob_created_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'
      or c->>'cleanup_expires_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
      raise exception using errcode='22023',message='invalid attachment GC tuple';
    end if;
    if kind='retry' then
      if json_typeof(raw->'retry_at')<>'string' or raw->>'retry_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then
        raise exception using errcode='22023',message='invalid attachment retry time';
      end if;
      retry_time:=(raw->>'retry_at')::timestamptz;
    else
      receipt_raw:=raw->'receipt';
      if json_typeof(receipt_raw) is distinct from 'object' or (select count(*) from json_each(receipt_raw))<>5
        or (select count(distinct x.key) from json_each(receipt_raw) x)<>5
        or exists(select 1 from json_each(receipt_raw) x where not(x.key=any(array['key','version_id','sha256','size_bytes','deleted']))
          or case when x.key='deleted' then json_typeof(x.value)<>'boolean'
            when x.key='size_bytes' then json_typeof(x.value)<>'number' or x.value::text !~ '^(0|[1-9][0-9]*)$'
            else json_typeof(x.value)<>'string' end) then
        raise exception using errcode='22023',message='invalid attachment GC receipt';
      end if;
      receipt:=receipt_raw::jsonb;
      if receipt->>'key'<>c->>'key' or receipt->>'version_id'<>c->>'version_id'
        or receipt->>'sha256'<>c->>'sha256' or (receipt->>'size_bytes')::bigint<>(c->>'size_bytes')::bigint then
        raise exception using errcode='22023',message='attachment GC receipt tuple mismatch';
      end if;
      result:=case when (receipt->>'deleted')::boolean then 'deleted' else 'already_absent' end;
    end if;
  end if;
  if kind<>'resolve' then perform record_platform_internal.attachment_v1_live(v); end if;
  -- legacy_adapter_lock takes quota before any GC row lock.
  if kind='resolve' then
    select * into g from public.blob_gc_deletions x where x.deletion_id=deletion and x.operation_id=v->>'operation_id';
  else
    select * into g from public.blob_gc_deletions x where x.deletion_id=deletion and x.operation_id=v->>'operation_id' for update;
  end if;
  if not found then return 'null'::jsonb; end if;
  doc:=record_platform_internal.attachment_v1_gc_document(g);
  select o.operation_state into strict state from public.record_purge_operations o where o.operation_id=v->>'operation_id';
  if state='online_purged' and (kind<>'resolve' or g.deletion_state<>'completed') then
    raise exception using errcode='42501',message='terminal operation cannot dispatch attachment GC';
  end if;
  if state='online_purged' then
    perform record_platform_internal.attachment_v1_projection(v);
  end if;
  if kind='claim' then
    if g.deletion_state='completed' then return doc; end if;
    if g.deletion_state='claimed' and g.owner_id=cleanup_owner and g.lease_expires_at>clock_timestamp() then
      perform record_platform_internal.attachment_v1_queue(v);
      return doc;
    end if;
    if g.lease_expires_at>clock_timestamp() or (g.deletion_state='retry_wait' and g.retry_at>clock_timestamp()) then return 'null'::jsonb; end if;
    update public.blob_gc_deletions x set owner_id=cleanup_owner,owner_generation=x.owner_generation+1,attempt=x.attempt+1,
      lease_expires_at=clock_timestamp()+interval '1 minute',deletion_state='claimed',retry_at=null,updated_at=clock_timestamp()
      where x.deletion_id=deletion returning x.* into g;
    perform record_platform_internal.attachment_v1_queue(v);
    return record_platform_internal.attachment_v1_gc_document(g);
  end if;
  if row(g.operation_id,g.deletion_id,g.project_id,g.backend_kind,g.blob_key,g.object_version,encode(g.sha256_digest,'hex'),
      g.size_bytes,g.blob_created_at,g.owner_id,g.owner_generation,g.attempt,g.lease_expires_at)
    is distinct from row(c->>'operation_id',c->>'deletion_id',c->>'project_id',c->>'backend_kind',c->>'key',c->>'version_id',c->>'sha256',
      (c->>'size_bytes')::bigint,(c->>'blob_created_at')::timestamptz,c->>'cleanup_owner_id',
      (c->>'cleanup_owner_generation')::bigint,(c->>'attempt')::bigint,(c->>'cleanup_expires_at')::timestamptz) then
    raise exception using errcode='42501',message='attachment GC tuple unavailable';
  end if;
  if kind in ('complete','resolve') then
    digest:=record_platform_internal.attachment_v1_gc_digest(g,result);
    if g.deletion_state='completed' then
      if g.physical_delete_result<>result or g.receipt_digest<>digest then
        raise exception using errcode='55000',message='attachment GC receipt conflict';
      end if;
      return doc;
    end if;
    if kind='resolve' then return 'null'::jsonb; end if;
  end if;
  if g.deletion_state<>'claimed' or g.lease_expires_at<=clock_timestamp() then
    raise exception using errcode='42501',message='attachment GC cleanup owner expired';
  end if;
  if kind='retry' then
    update public.blob_gc_deletions x set deletion_state='retry_wait',retry_at=retry_time,updated_at=clock_timestamp()
      where x.deletion_id=deletion returning x.* into g;
  else
    update public.attachment_quota_accounts q set physical_bytes=q.physical_bytes-g.size_bytes,
      quota_version=q.quota_version+1,updated_at=clock_timestamp()
      where q.project_id=g.project_id and q.physical_bytes>=g.size_bytes;
    if not found then raise exception using errcode='55000',message='attachment physical quota conflict'; end if;
    update public.blob_gc_deletions x set deletion_state='completed',retry_at=null,physical_delete_result=result,
      receipt_digest=digest,completed_at=clock_timestamp(),updated_at=clock_timestamp()
      where x.deletion_id=deletion returning x.* into g;
  end if;
  perform record_platform_internal.attachment_v1_queue(v);
  return record_platform_internal.attachment_v1_gc_document(g);
exception when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow or invalid_datetime_format then
  raise exception using errcode='22023',message='invalid attachment GC value';
end $$;

create function public.record_attachment_purge_prepare_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_purge_v1($1,false) $$;
create function public.record_attachment_purge_verify_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_purge_v1($1,true) $$;
create function public.record_attachment_gc_claim_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_gc_v1($1,'claim') $$;
create function public.record_attachment_gc_complete_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_gc_v1($1,'complete') $$;
create function public.record_attachment_gc_retry_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_gc_v1($1,'retry') $$;
create function public.record_attachment_gc_resolve_v1(bytea) returns jsonb language sql security definer set search_path=pg_catalog
  as $$ select record_platform_internal.record_attachment_gc_v1($1,'resolve') $$;

revoke all on function record_platform_internal.attachment_v1_time(timestamptz),
  record_platform_internal.attachment_v1_deletion_id(text,text,text,text),
  record_platform_internal.attachment_v1_gc_digest(public.blob_gc_deletions,text),
  record_platform_internal.attachment_v1_gc_document(public.blob_gc_deletions),
  record_platform_internal.attachment_v1_live(jsonb),record_platform_internal.attachment_v1_queue(jsonb),
  record_platform_internal.attachment_v1_projection(jsonb),
  record_platform_internal.record_attachment_purge_v1(bytea,boolean),record_platform_internal.record_attachment_gc_v1(bytea,text),
  public.record_attachment_purge_prepare_v1(bytea),public.record_attachment_purge_verify_v1(bytea),
  public.record_attachment_gc_claim_v1(bytea),public.record_attachment_gc_complete_v1(bytea),
  public.record_attachment_gc_retry_v1(bytea),public.record_attachment_gc_resolve_v1(bytea) from public;
